(window.__APPSRC=window.__APPSRC||{})["xmvkq53re"]="<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Pharmaco INFAS — Mon parcours de révision</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<meta name=\"theme-color\" content=\"#5B3FF0\">\n<style>\n:root{\n  --bg:#EEF0FB; --bg2:#E6E4FB;\n  --white:#FFFFFF;\n  --violet:#5B3FF0; --violet2:#7C62FF; --violet-deep:#3B23C9; --lav:#ECE8FF; --lav2:#F4F1FF;\n  --navy:#141A3D; --navy2:#232B5C;\n  --green:#2FA84F; --green-l:#E5F6EA; --green-soft:#C9EBD2;\n  --yellow:#F6B81A; --yellow-l:#FFF4D6;\n  --sky:#E2F0FD; --blue:#2F7BF6;\n  --coral:#F0566A; --coral-l:#FDE8EB;\n  --ink:#151A33; --ink2:#5D6382; --ink3:#9AA0BC;\n  --line:#E3E5F3;\n  /* compat anciens noms */\n  --txt:var(--ink); --txt-dim:var(--ink2); --txt-faint:var(--ink3); --panel-brd:var(--line);\n  --teal:var(--violet); --amber:var(--yellow); --r0:#F0566A; --r1:#F59A3A; --r2:#F6B81A; --r3:#2FA84F; --r4:#2F7BF6;\n  --radius:24px;\n  --shadow:0 10px 30px rgba(59,35,201,.10);\n  --font:'Poppins','Segoe UI',system-ui,-apple-system,Roboto,Helvetica,Arial,sans-serif;\n}\n*{box-sizing:border-box;}\nhtml,body{margin:0;padding:0;}\nbody{\n  font-family:var(--font);color:var(--ink);min-height:100vh;\n  background:\n    radial-gradient(900px 500px at 100% -10%, #DCD5FF 0%, transparent 60%),\n    radial-gradient(700px 500px at -20% 30%, #E4ECFF 0%, transparent 60%),\n    var(--bg);\n  -webkit-font-smoothing:antialiased;\n}\nbutton,input,textarea{font-family:inherit;}\n.wrap{max-width:560px;margin:0 auto;padding:10px 16px 130px;}\n\n/* ---------- barre du haut ---------- */\n.brandline{text-align:center;padding:4px 2px 12px;}\n.brandline .app{font-size:12px;color:var(--ink3);margin-bottom:6px;}\n.brandline .app b{color:var(--violet);font-weight:700;}\n.brandline .author{display:inline-block;background:linear-gradient(135deg,#5B3FF0,#8E6CFF);color:#fff;border-radius:999px;padding:7px 18px;box-shadow:0 6px 16px rgba(91,63,240,.3);font-size:14px;}\n.brandline .author strong{font-weight:700;}\n.brandline .author span{opacity:.9;}\n.topbar{display:flex;align-items:center;gap:12px;background:var(--white);border-radius:22px;padding:10px 12px;box-shadow:var(--shadow);margin-bottom:16px;}\n.avatar{width:46px;height:46px;flex:0 0 46px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:26px;\n  background:linear-gradient(145deg,#FFE3B3,#FFC27A);box-shadow:inset 0 0 0 3px #fff,0 0 0 2px var(--violet2);cursor:pointer;}\n.who{flex:1;min-width:0;}\n.who .nm{font-weight:700;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.who .lv{font-size:12px;color:var(--ink2);margin-top:1px;}\n.who .lv i{font-style:normal;color:var(--yellow);}\n.bell{position:relative;width:42px;height:42px;border-radius:50%;border:1px solid var(--line);background:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;}\n.bell svg{width:20px;height:20px;}\n.bell .dot{position:absolute;top:8px;right:9px;width:9px;height:9px;border-radius:50%;background:var(--coral);box-shadow:0 0 0 2px #fff;}\n\n/* ---------- cartes ---------- */\n.card{background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:18px;margin-bottom:14px;box-shadow:var(--shadow);}\nh2.section-title{font-size:15px;font-weight:700;color:var(--ink);margin:0 0 12px;letter-spacing:0;}\n.h-row{display:flex;justify-content:space-between;align-items:center;margin:6px 2px 10px;}\n.h-row h3{margin:0;font-size:18px;font-weight:700;}\n.h-row a{font-size:12.5px;color:var(--violet);font-weight:600;cursor:pointer;}\n\n/* hero */\n.hero{position:relative;overflow:hidden;border-radius:28px;padding:22px 20px;margin-bottom:14px;color:#fff;\n  background:radial-gradient(400px 220px at 85% 30%,rgba(255,255,255,.18),transparent 60%),linear-gradient(140deg,var(--violet2),var(--violet) 45%,var(--violet-deep));\n  box-shadow:0 18px 40px rgba(91,63,240,.35);min-height:190px;}\n.hero h2{font-size:24px;line-height:1.18;margin:0 0 8px;font-weight:800;max-width:62%;}\n.hero p{font-size:12.5px;opacity:.88;margin:0 0 16px;max-width:60%;line-height:1.5;}\n.hero .go{width:50px;height:50px;border-radius:50%;background:var(--navy);border:2px solid rgba(255,255,255,.5);color:#fff;font-size:20px;display:flex;align-items:center;justify-content:center;cursor:pointer;}\n.hero .rocket{position:absolute;right:-6px;bottom:-4px;width:46%;max-width:210px;}\n.hero .spark{position:absolute;color:#FFD54A;font-size:16px;}\n\n/* stats duo */\n.duo{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px;}\n.mini{border-radius:22px;padding:14px;position:relative;}\n.mini.lav{background:var(--lav);} .mini.sky{background:var(--sky);}\n.mini .ic{width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:17px;color:#fff;}\n.mini.lav .ic{background:var(--violet);} .mini.sky .ic{background:var(--blue);}\n.mini .t{font-size:12px;color:var(--ink2);margin-top:8px;}\n.mini .v{font-size:28px;font-weight:800;line-height:1.1;}\n.mini .top{display:flex;align-items:center;gap:8px;}\n.mini .top .t{margin:0;}\n\n/* progression segmentée */\n.segbar{display:flex;height:16px;border-radius:10px;overflow:hidden;background:#EDEEF6;gap:3px;margin:8px 0 10px;}\n.segbar span{display:block;height:100%;}\n.seglegend{display:flex;justify-content:space-around;font-size:12px;}\n.seglegend div{text-align:center;}\n.seglegend small{display:block;color:var(--ink3);font-size:10.5px;}\n.seglegend i{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:4px;}\n\n/* tuiles */\n.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:14px;}\n.tile{background:#fff;border:1px solid var(--line);border-radius:20px;padding:14px 6px;text-align:center;cursor:pointer;box-shadow:var(--shadow);}\n.tile .e{font-size:26px;line-height:1;}\n.tile .l{font-size:11.5px;font-weight:600;color:var(--ink2);margin-top:7px;}\n.tile:active{transform:scale(.97);}\n\n/* boutons */\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 18px;border-radius:16px;border:1px solid var(--line);\n  background:#fff;color:var(--ink);font-size:14px;font-weight:600;cursor:pointer;-webkit-tap-highlight-color:transparent;}\n.btn:active{transform:scale(.98);}\n.btn.primary{background:var(--violet);border-color:var(--violet);color:#fff;box-shadow:0 8px 20px rgba(91,63,240,.3);}\n.btn.navy{background:var(--navy);border-color:var(--navy);color:#fff;}\n.btn.green{background:var(--green);border-color:var(--green);color:#fff;}\n.btn.ghost{background:transparent;}\n.btn.full{width:100%;}\n.btn.small{padding:8px 12px;font-size:12.5px;border-radius:12px;}\n.btn:disabled{opacity:.4;cursor:not-allowed;}\n.btn:focus-visible,.chip:focus-visible,.tile:focus-visible{outline:3px solid var(--violet2);outline-offset:2px;}\n.row{display:flex;gap:10px;flex-wrap:wrap;}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px;}\n\n/* chips */\n.chip{padding:9px 14px;border-radius:999px;border:1px solid var(--line);background:#fff;font-size:12.5px;cursor:pointer;user-select:none;color:var(--ink2);font-weight:500;white-space:nowrap;}\n.chip.active{background:var(--violet);border-color:var(--violet);color:#fff;font-weight:600;}\n.chip.compact{padding:6px 10px;font-size:11.5px;}\n.chip small{opacity:.75;}\n.scroller{display:flex;gap:8px;overflow-x:auto;padding:2px 2px 6px;scrollbar-width:none;}\n.scroller::-webkit-scrollbar{display:none;}\n.pill{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:999px;font-size:12.5px;font-weight:600;}\n.pill.navy{background:var(--navy);color:#fff;} .pill.white{background:#fff;border:1px solid var(--line);}\n\n/* badges */\n.badge{display:inline-block;padding:4px 10px;border-radius:999px;font-size:10.5px;font-weight:700;}\n.badge.qcm{background:var(--lav);color:var(--violet);}\n.badge.qcd{background:var(--sky);color:var(--blue);}\n.badge.libre{background:var(--yellow-l);color:#B07D00;}\n.badge.association{background:var(--green-l);color:var(--green);}\n.badge.ouverte{background:#FFE9F5;color:#C2187A;}\n.badge.facile{background:var(--green-l);color:var(--green);}\n.badge.moyen{background:var(--yellow-l);color:#B07D00;}\n.badge.difficile{background:var(--coral-l);color:var(--coral);}\n.badge.chap{background:#F1F2F8;color:var(--ink2);}\n\n/* cartes chapitre (parcours) */\n.ccard{position:relative;border-radius:26px;padding:16px 16px 14px;margin-bottom:12px;color:#fff;overflow:hidden;cursor:pointer;}\n.ccard.navy{background:linear-gradient(135deg,#1B2350,var(--navy));}\n.ccard.green{background:linear-gradient(135deg,#3CB75C,#278C42);}\n.ccard.yellow{background:linear-gradient(135deg,#FFC93A,#F2A900);color:#2A1E00;}\n.ccard.violet{background:linear-gradient(135deg,var(--violet2),var(--violet-deep));}\n.ccard .blob{position:absolute;right:-30px;bottom:-40px;width:150px;height:150px;border-radius:50%;background:rgba(255,255,255,.08);}\n.ccard .cat{font-size:10px;font-weight:700;letter-spacing:.8px;text-transform:uppercase;opacity:.85;}\n.ccard .ttl{font-size:17px;font-weight:700;line-height:1.25;margin:4px 104px 12px 0;}\n.ccard .emo{position:absolute;right:62px;top:14px;font-size:30px;opacity:.95;}\n.ccard .bm{position:absolute;right:14px;top:12px;width:34px;height:34px;border-radius:10px;border:1.5px solid currentColor;display:flex;align-items:center;justify-content:center;font-size:14px;opacity:.9;background:transparent;color:inherit;cursor:pointer;}\n.ccard .bm.on{background:#fff;color:var(--violet);border-color:#fff;}\n.ccard .foot{display:flex;align-items:center;justify-content:space-between;}\n.stack{display:flex;align-items:center;}\n.stack span{width:28px;height:28px;border-radius:50%;background:#fff;display:flex;align-items:center;justify-content:center;font-size:14px;margin-right:-8px;box-shadow:0 0 0 2px rgba(0,0,0,.08);}\n.stack b{margin-left:14px;font-size:12px;font-weight:600;}\n.ccard .arrow{width:42px;height:42px;border-radius:50%;background:#fff;color:var(--ink);display:flex;align-items:center;justify-content:center;font-size:18px;}\n.ccard .cprog{height:5px;border-radius:5px;background:rgba(255,255,255,.25);margin-top:12px;overflow:hidden;}\n.ccard.yellow .cprog{background:rgba(0,0,0,.12);}\n.ccard .cprog span{display:block;height:100%;background:#fff;border-radius:5px;}\n.ccard.yellow .cprog span{background:var(--navy);}\n.ccard .done{position:absolute;left:14px;top:-1px;}\n\n/* écran parcours en-tête */\n.pheader{display:flex;align-items:center;justify-content:space-between;margin:2px 0 12px;}\n.pheader h1{font-size:30px;line-height:1.05;margin:0;font-weight:800;}\n.pheader .fig{font-size:58px;line-height:1;filter:drop-shadow(0 8px 10px rgba(91,63,240,.25));}\n\n/* stats */\n.toggle{display:inline-flex;background:#F1F2F8;border-radius:999px;padding:4px;}\n.toggle span{padding:7px 14px;border-radius:999px;font-size:12px;font-weight:600;color:var(--ink2);cursor:pointer;}\n.toggle span.on{background:var(--green);color:#fff;}\n.bars{display:flex;align-items:flex-end;justify-content:space-between;height:170px;padding:22px 4px 0;gap:6px;}\n.bars .b{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;}\n.bars .b em{font-style:normal;font-size:11.5px;font-weight:700;margin-bottom:5px;}\n.bars .b i{display:block;width:12px;border-radius:8px;background:var(--green-soft);min-height:6px;}\n.bars .b.max i{background:var(--green);width:14px;}\n.bars .b small{font-size:11px;color:var(--ink3);margin-top:7px;}\n.kpi{display:flex;gap:10px;align-items:center;}\n.kpi .ic{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;font-size:13px;background:var(--green);}\n.kpi .v{font-size:22px;font-weight:800;line-height:1;}\n.kpi small{display:block;font-size:11px;color:var(--ink3);}\n.cta{display:flex;align-items:center;gap:12px;border-radius:22px;padding:14px;margin-bottom:12px;cursor:pointer;}\n.cta.y{background:var(--yellow-l);} .cta.b{background:var(--sky);} .cta.v{background:var(--lav);} .cta.g{background:var(--green-l);}\n.cta .e{font-size:30px;}\n.cta .t{flex:1;} .cta .t b{display:block;font-size:14.5px;} .cta .t small{color:var(--ink2);font-size:12px;}\n.cta .go{width:36px;height:36px;border-radius:50%;background:#fff;display:flex;align-items:center;justify-content:center;}\n\n/* navigation basse */\n.bottomnav{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(14px + env(safe-area-inset-bottom,0px));width:min(520px,calc(100% - 28px));\n  background:var(--navy);border-radius:26px;display:flex;justify-content:space-around;align-items:stretch;padding:7px 6px;gap:2px;z-index:30;box-shadow:0 14px 34px rgba(20,26,61,.35);}\n.bottomnav button{flex:1;min-width:0;border-radius:18px;border:none;background:transparent;color:#AEB3D3;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:7px 2px;cursor:pointer;font-family:inherit;}\n.bottomnav button .lbl{font-size:10.5px;font-weight:600;line-height:1;white-space:nowrap;}\n.bottomnav button svg{width:22px;height:22px;}\n.bottomnav button.on{background:var(--violet);color:#fff;box-shadow:0 6px 16px rgba(91,63,240,.5);}\n.bottomnav button.on.stats{background:var(--green);box-shadow:0 6px 16px rgba(47,168,79,.5);}\n.bottomnav.hide{display:none;}\n\n/* quiz */\n.progress-outer{height:8px;border-radius:8px;background:#E3E1F8;overflow:hidden;margin:10px 0 4px;}\n.progress-inner{height:100%;background:linear-gradient(90deg,var(--violet2),var(--violet));border-radius:8px;transition:width .3s;}\n.qtop{display:flex;justify-content:space-between;align-items:center;gap:10px;}\n.rbtn{width:42px;height:42px;border-radius:50%;background:#fff;border:1px solid var(--line);display:flex;align-items:center;justify-content:center;font-size:16px;cursor:pointer;color:var(--ink);}\n.rbtn.on{background:var(--violet);color:#fff;border-color:var(--violet);}\n.qlabel{flex:1;text-align:center;font-size:12.5px;color:var(--ink2);font-weight:600;}\n.q-meta{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap;}\n.q-meta .tags{display:flex;gap:6px;flex-wrap:wrap;}\n.q-page{font-size:11px;color:var(--ink3);}\n.q-text{font-size:17.5px;line-height:1.45;margin:6px 0 16px;font-weight:700;}\n.opt{display:flex;align-items:center;gap:12px;padding:13px 14px;margin-bottom:10px;border-radius:18px;border:1.5px solid var(--line);background:#fff;cursor:pointer;font-size:14.5px;}\n.opt .letter{width:28px;height:28px;flex:0 0 28px;border-radius:50%;background:var(--lav2);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:var(--violet);}\n.opt.selected{border-color:var(--violet);background:var(--lav2);}\n.opt.selected .letter{background:var(--violet);color:#fff;}\n.opt.correct{border-color:var(--green);background:var(--green-l);}\n.opt.correct .letter{background:var(--green);color:#fff;}\n.opt.incorrect{border-color:var(--coral);background:var(--coral-l);}\n.opt.incorrect .letter{background:var(--coral);color:#fff;}\n.opt.disabled{cursor:default;}\ntextarea.free{width:100%;min-height:110px;border-radius:18px;border:1.5px solid var(--line);background:var(--lav2);color:var(--ink);padding:14px;font-size:14.5px;resize:vertical;}\ntextarea.free:focus{outline:none;border-color:var(--violet);}\n.react{display:flex;align-items:flex-end;gap:10px;margin:14px 0 4px;}\n.react svg{width:64px;height:76px;flex:0 0 64px;}\n.bubble{position:relative;background:var(--lav);border-radius:18px 18px 18px 4px;padding:10px 14px;font-size:13.5px;font-weight:600;}\n.bubble.ok{background:var(--green-l);color:#1E6E34;} .bubble.ko{background:var(--coral-l);color:#A3253A;} .bubble.mid{background:var(--yellow-l);color:#7A5600;}\n.model{background:var(--lav2);border-radius:18px;padding:14px;font-size:14px;line-height:1.6;border:1px dashed var(--violet2);}\nmark.hit{background:var(--green-soft);border-radius:4px;padding:0 2px;}\nmark.miss{background:#FFE7A8;border-radius:4px;padding:0 2px;}\n.kwrow{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0;}\n.kw{font-size:11.5px;padding:4px 9px;border-radius:999px;background:#F1F2F8;color:var(--ink2);}\n.kw.hit{background:var(--green-l);color:var(--green);font-weight:600;}\n.selfeval{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-top:12px;}\n.selfeval button{border-radius:16px;padding:12px 6px;border:1.5px solid var(--line);background:#fff;font-weight:600;font-size:12.5px;cursor:pointer;}\n.selfeval .k{border-color:var(--coral);color:var(--coral);} .selfeval .m{border-color:var(--yellow);color:#9A6C00;} .selfeval .o{border-color:var(--green);color:var(--green);}\n\n.correction{margin-top:16px;padding-top:14px;border-top:1px dashed var(--line);}\n.correction .block{margin-bottom:12px;}\n.correction .label{font-size:12px;color:var(--ink2);margin-bottom:5px;font-weight:700;}\n.correction .content{font-size:14px;line-height:1.6;}\n.correction .content.kid{background:var(--yellow-l);border-radius:16px;padding:11px 13px;}\n.correction .content.trap{background:var(--coral-l);border-radius:16px;padding:11px 13px;}\n.correction .content.tip{background:var(--lav);border-radius:16px;padding:11px 13px;}\n.navrow{display:flex;justify-content:space-between;align-items:center;margin-top:16px;gap:10px;}\n.arrow-btn{width:48px;height:48px;border-radius:50%;flex:0 0 48px;padding:0;font-size:18px;}\n.qcounter{font-size:12.5px;color:var(--ink2);text-align:center;flex:1;}\n\n/* anciens composants */\n.dash-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px;}\n.stat{background:var(--lav2);border-radius:18px;padding:12px;text-align:center;}\n.stat .num{font-size:22px;font-weight:800;}\n.stat .lbl{font-size:11px;color:var(--ink2);margin-top:2px;}\n.chapter-row{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--line);}\n.chapter-row:last-child{border-bottom:none;}\n.chapter-row .cname{flex:1;font-size:13.5px;}\n.chapter-row .cbar{width:80px;height:7px;border-radius:7px;background:#EDEEF6;overflow:hidden;}\n.chapter-row .cbar span{display:block;height:100%;background:linear-gradient(90deg,var(--violet2),var(--violet));}\n.chapter-row .cpct{width:38px;text-align:right;font-size:12px;color:var(--ink2);font-weight:600;}\n.mastery-dot{width:9px;height:9px;border-radius:50%;display:inline-block;margin-right:5px;flex:0 0 9px;}\n.m0{background:var(--r0);} .m1{background:var(--r1);} .m2{background:var(--r2);} .m3{background:var(--r3);} .m4{background:var(--r4);}\n.hint{font-size:12px;color:var(--ink3);margin-top:6px;}\n.center{text-align:center;} .mb8{margin-bottom:8px;} .mb14{margin-bottom:14px;} .mt14{margin-top:14px;}\ninput[type=text]{font-family:inherit;}\n#globalSearch,#medsFilter,.inp{background:#fff!important;border:1.5px solid var(--line)!important;border-radius:16px!important;color:var(--ink)!important;}\n\n/* profil / badges */\n.lvlbar{height:12px;border-radius:12px;background:#EDEEF6;overflow:hidden;margin:8px 0 4px;}\n.lvlbar span{display:block;height:100%;background:linear-gradient(90deg,var(--yellow),#FF8A3D);border-radius:12px;}\n.badges{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;}\n.bdg{text-align:center;border-radius:18px;padding:12px 4px;background:var(--lav2);}\n.bdg .e{font-size:26px;} .bdg small{display:block;font-size:10.5px;margin-top:5px;color:var(--ink2);line-height:1.2;}\n.bdg.off{filter:grayscale(1);opacity:.45;}\n.avgrid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;}\n.avgrid span{font-size:26px;text-align:center;padding:8px 0;border-radius:14px;cursor:pointer;background:var(--lav2);}\n.avgrid span.on{background:var(--violet);box-shadow:0 6px 14px rgba(91,63,240,.35);}\n\n/* résultat */\n.ring{width:150px;height:150px;margin:0 auto;position:relative;}\n.ring svg{width:100%;height:100%;transform:rotate(-90deg);}\n.ring .val{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:800;font-size:32px;}\n.ring .val small{font-size:12px;color:var(--ink3);font-weight:600;}\n\n/* overlays */\n.toast{position:fixed;left:50%;top:18px;white-space:nowrap;max-width:92vw;overflow:hidden;text-overflow:ellipsis;transform:translateX(-50%);background:var(--navy);color:#fff;padding:10px 18px;border-radius:999px;font-weight:700;font-size:14px;z-index:60;animation:toast 1.6s ease forwards;}\n@keyframes toast{0%{opacity:0;transform:translate(-50%,-10px)}15%{opacity:1;transform:translate(-50%,0)}80%{opacity:1}100%{opacity:0;transform:translate(-50%,-14px)}}\n.confetti{position:fixed;inset:0;pointer-events:none;z-index:55;overflow:hidden;}\n.confetti i{position:absolute;top:-12px;width:9px;height:14px;border-radius:3px;animation:fall 1.3s ease-in forwards;}\n@keyframes fall{to{transform:translateY(105vh) rotate(540deg);opacity:.7}}\n.overlay{position:fixed;inset:0;background:rgba(20,26,61,.45);backdrop-filter:blur(4px);z-index:70;display:flex;align-items:flex-end;justify-content:center;}\n.sheet{background:#fff;width:min(560px,100%);border-radius:28px 28px 0 0;padding:20px 18px calc(24px + env(safe-area-inset-bottom,0px));max-height:85vh;overflow:auto;}\n.sheet.centered{border-radius:28px;margin:auto 16px;text-align:center;}\n.overlay.center{align-items:center;}\n.notif{display:flex;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--line);cursor:pointer;}\n.notif:last-child{border-bottom:none;}\n.notif .e{font-size:24px;width:42px;height:42px;border-radius:14px;background:var(--lav2);display:flex;align-items:center;justify-content:center;}\n.notif b{font-size:14px;display:block;} .notif small{color:var(--ink2);font-size:12px;}\nfooter.sig{text-align:center;color:var(--ink3);font-size:11px;line-height:1.7;margin-top:22px;}\nfooter.sig b{color:var(--violet);}\n@media (prefers-reduced-motion:reduce){.toast,.confetti i{animation:none!important;}.confetti{display:none;}}\n@media(max-width:380px){.hero h2{font-size:21px}.pheader h1{font-size:26px}.tile .e{font-size:22px}}\n\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"brandline\"><div class=\"app\">💊 <b>Pharmaco INFAS</b> · Licence 2</div><div class=\"author\">✨ Créé par <strong>Daniel Noufe</strong> <span>· INFAS Daloa</span></div></div>\n  <header class=\"topbar\" id=\"topbar\"></header>\n  <div id=\"app\"></div>\n  <footer class=\"sig\">Supports : COURS PHARMACOLOGIE L2 INFAS 2025 &amp; INFAS 2022 — Dr Anzan Koimé, Pharmacien<br><b>Créé par Daniel Noufe · INFAS Daloa</b></footer>\n</div>\n<nav class=\"bottomnav\" id=\"bottomnav\" aria-label=\"Navigation principale\"></nav>\n<script>\n/* =========================================================\n   BANQUE DE QUESTIONS — issue de COURS PHARMACOLOGIE L2 INFAS 2025\n   ========================================================= */\nconst CHAPTERS = [\n  \"Généralités\",\n  \"Antalgiques & fièvre\",\n  \"Anti-inflammatoires & anesthésiques\",\n  \"Anti-infectieux\",\n  \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n  \"Antidiabétiques\",\n  \"Appareil respiratoire\",\n  \"Antihistaminiques\",\n  \"Appareil digestif\",\n  \"Médicaments du SNC (Psychotropes)\",\n  \"Hormonaux gynécologiques\",\n  \"Appareil cardio-vasculaire\",\n  \"Vitamines & Oligo-éléments\",\n  \"Antiseptiques, désinfectants & détergents\"\n];\n\nconst Q = [\n// ---------------- GENERALITES (p.4-17) ----------------\n{id:\"g001\",chapter:\"Généralités\",page:5,type:\"qcm\",difficulty:\"facile\",\n question:\"Quelle est la composante d'un médicament qui possède l'effet thérapeutique ?\",\n options:[\"L'excipient\",\"Le principe actif\",\"Le conservateur\",\"La galénique\"],correctAnswer:\"Le principe actif\",\n explanation:\"Le principe actif (PA) est la molécule qui, dans un médicament, possède un effet thérapeutique. Il est en général en très faible proportion par rapport aux excipients.\",\n simpleExplanation:\"Imagine un gâteau : le principe actif est la petite pincée d'ingrédient magique qui soigne, l'excipient est toute la pâte autour qui donne juste la forme.\",\n memoryTip:\"PA = Puissance Active.\",examTrap:\"Ne pas confondre principe actif (effet thérapeutique) et excipient (juste le support).\"},\n{id:\"g002\",chapter:\"Généralités\",page:6,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le rôle principal de l'excipient dans un médicament ?\",\n options:[\"Produire l'effet thérapeutique\",\"Donner une consistance et faciliter l'administration\",\"Détruire le principe actif\",\"Remplacer le principe actif en cas de rupture\"],\n correctAnswer:\"Donner une consistance et faciliter l'administration\",\n explanation:\"L'excipient confère une consistance donnée ou d'autres caractéristiques physiques/gustatives au produit final, tout en évitant toute interaction avec le principe actif.\",\n simpleExplanation:\"L'excipient, c'est l'emballage confortable qui transporte le vrai médicament jusqu'à ton corps.\",\n memoryTip:\"EX-cipient = EX-térieur, l'enveloppe.\",examTrap:\"L'excipient n'a pas de composition chimique fixe, il est défini par son usage.\"},\n{id:\"g003\",chapter:\"Généralités\",page:6,type:\"qcm\",difficulty:\"facile\",\n question:\"Combien de voies principales d'administration sont décrites dans le cours ?\",\n options:[\"Trois\",\"Quatre\",\"Cinq\",\"Six\"],correctAnswer:\"Cinq\",\n explanation:\"Cinq voies principales : orale, parentérale, transmuqueuse, percutanée, pulmonaire.\",\n simpleExplanation:\"Cinq portes d'entrée différentes pour faire rentrer le médicament dans le corps.\",\n memoryTip:\"O-P-T-P-P : Orale, Parentérale, Transmuqueuse, Percutanée, Pulmonaire.\",examTrap:\"La voie sublinguale est une sous-catégorie de la voie transmuqueuse, pas une voie à part.\"},\n{id:\"g004\",chapter:\"Généralités\",page:7,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel est l'avantage principal de la voie intraveineuse ?\",\n options:[\"Coût très faible\",\"Rapidité d'action et précision de la posologie\",\"Absence totale de risque infectieux\",\"Action toujours locale\"],\n correctAnswer:\"Rapidité d'action et précision de la posologie\",\n explanation:\"La voie intraveineuse est une voie d'urgence caractérisée par la rapidité des effets et la précision du contrôle de la posologie.\",\n simpleExplanation:\"C'est comme jeter directement le médicament dans la rivière sanguine : il part vite partout dans le corps.\",\n memoryTip:\"IV = Immédiat et Vite.\",examTrap:\"La voie IV comporte aussi un risque de surdosage plus important que la voie orale.\"},\n{id:\"g005\",chapter:\"Généralités\",page:8,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quelle voie d'administration permet une action directe dans la circulation générale en évitant le premier passage hépatique, en plus de la voie parentérale ?\",\n options:[\"Voie orale classique\",\"Voie sublinguale\",\"Voie rectale à visée locale uniquement\",\"Voie orale avec forme gastro-résistante\"],\n correctAnswer:\"Voie sublinguale\",\n explanation:\"La voie sublinguale permet une pénétration directe du médicament dans la circulation sans passer par le foie, avec une action rapide.\",\n simpleExplanation:\"Sous la langue, il y a plein de petits vaisseaux qui aspirent le médicament directement, sans passer par l'usine du foie.\",\n memoryTip:\"Sub-linguale = sous la langue = shortcut vers le sang.\",examTrap:\"La voie orale classique, elle, passe obligatoirement par le foie (premier passage hépatique).\"},\n{id:\"g006\",chapter:\"Généralités\",page:9,type:\"libre\",difficulty:\"moyen\",\n question:\"Citez trois inconvénients de la voie orale d'administration des médicaments.\",\n keywords:[\"altération sucs digestifs\",\"hépatotoxicité\",\"irritation tube digestif\",\"trouble déglutition\",\"délai avant effet\",\"dégradation foie\"],\n explanation:\"Inconvénients de la voie orale : risque d'altération par les sucs digestifs, risque d'hépatotoxicité, irritation du tube digestif, impossibilité en cas de trouble de déglutition, délai avant l'apparition de l'effet.\",\n simpleExplanation:\"Avaler un médicament, c'est un long voyage plein d'obstacles : l'acide de l'estomac peut l'abîmer, le foie peut le fatiguer, et ça prend du temps avant d'agir.\",\n memoryTip:\"5 ennemis de la voie orale : sucs, foie, irritation, déglutition, délai.\",examTrap:\"Ne pas confondre avec les avantages (facilité, coût faible).\"},\n{id:\"g007\",chapter:\"Généralités\",page:12,type:\"qcd\",difficulty:\"moyen\",\n question:\"Parmi les propositions suivantes, lesquelles définissent correctement un médicament princeps ? (plusieurs réponses possibles)\",\n options:[\"Il incorpore pour la première fois un principe actif isolé/synthétisé\",\"Il est protégé par un brevet\",\"Il copie un principe actif déjà connu\",\"Il est toujours vendu moins cher qu'un générique\"],\n correctAnswer:[\"Il incorpore pour la première fois un principe actif isolé/synthétisé\",\"Il est protégé par un brevet\"],\n explanation:\"Un princeps est le médicament « original » qui incorpore pour la première fois un principe actif, protégé par un brevet d'environ 10 ans (prolongeable de 5 ans par CCP).\",\n simpleExplanation:\"Le princeps, c'est comme la toute première recette d'un plat, protégée par le cuisinier qui l'a inventée.\",\n memoryTip:\"PRINCEPS = PREMIER.\",examTrap:\"C'est le générique qui copie le principe actif une fois le brevet expiré, pas l'inverse.\"},\n{id:\"g008\",chapter:\"Généralités\",page:13,type:\"qcm\",difficulty:\"facile\",\n question:\"Que signifie l'abréviation DCI ?\",\n options:[\"Dénomination Chimique Internationale\",\"Dénomination Commune Internationale\",\"Dispensation Contrôlée Individuelle\",\"Dose Curative Initiale\"],\n correctAnswer:\"Dénomination Commune Internationale\",\n explanation:\"DCI = Dénomination Commune Internationale, retenue par l'OMS pour désigner le principe actif indépendamment du nom commercial.\",\n simpleExplanation:\"La DCI, c'est le vrai prénom scientifique du médicament, le même partout dans le monde.\",\n memoryTip:\"DCI = même partout, un seul nom universel.\",examTrap:\"Ne pas confondre DCI (nom scientifique unique) et nom commercial (peut varier selon le pays/laboratoire).\"},\n{id:\"g009\",chapter:\"Généralités\",page:13,type:\"libre\",difficulty:\"moyen\",\n question:\"Citez deux objectifs de la prescription en DCI selon le cours.\",\n keywords:[\"identification rapide interactions\",\"limiter confusions noms\",\"réduire risque prendre plusieurs médicaments même principe actif\",\"limiter allergie\",\"réduire erreur délivrance étranger\",\"indépendance stratégies commerciales\"],\n explanation:\"La prescription en DCI permet notamment une identification plus rapide des interactions médicamenteuses, limite les confusions entre noms commerciaux et réduit le risque de prendre plusieurs médicaments contenant le même principe actif (ex : paracétamol).\",\n simpleExplanation:\"Utiliser le vrai nom du médicament évite de se tromper, un peu comme appeler quelqu'un par son vrai prénom plutôt que par plusieurs surnoms différents.\",\n memoryTip:\"DCI = Sécurité du patient.\",examTrap:\"La DCI ne change pas les propriétés du médicament, elle sert à la clarté et la sécurité.\"},\n{id:\"g010\",chapter:\"Généralités\",page:13,type:\"association\",difficulty:\"difficile\",\n question:\"Associez le type d'interaction médicamenteuse à sa définition : Addition, Synergie, Antagonisme.\",\n pairs:[[\"Addition\",\"A + B = A et B\"],[\"Synergie\",\"A + B > A et B\"],[\"Antagonisme\",\"A + B < A et B\"]],\n explanation:\"Lorsqu'on administre 2 médicaments A et B : Addition (effet = somme simple), Synergie (effet supérieur à la somme), Antagonisme (effet inférieur, un médicament diminue l'autre).\",\n simpleExplanation:\"Synergie, c'est comme deux amis qui poussent une voiture ensemble et vont plus vite que la somme de leurs forces. L'antagonisme, c'est un ami qui pousse la voiture dans l'autre sens.\",\n memoryTip:\"Synergie = Super effet. Antagonisme = Anti-effet.\",examTrap:\"La synergie n'est pas juste 'addition', elle est supérieure à la somme des effets individuels.\"},\n{id:\"g011\",chapter:\"Généralités\",page:14,type:\"qcm\",difficulty:\"moyen\",\n question:\"Selon l'OMS (1972), comment définit-on un effet indésirable ?\",\n options:[\"Toute amélioration inattendue de l'état du patient\",\"Une réaction nocive et non voulue se produisant aux posologies normalement utilisées\",\"Un surdosage volontaire par le patient\",\"Une allergie uniquement liée à l'excipient\"],\n correctAnswer:\"Une réaction nocive et non voulue se produisant aux posologies normalement utilisées\",\n explanation:\"C'est une réaction nocive et non voulue, se produisant aux posologies normalement utilisées chez l'homme pour la prophylaxie, le diagnostic ou le traitement d'une maladie.\",\n simpleExplanation:\"Même en prenant la bonne dose comme prévu, le corps peut parfois mal réagir : c'est ça, un effet indésirable.\",\n memoryTip:\"Effet indésirable = surprise désagréable même à dose normale.\",examTrap:\"L'effet indésirable n'implique pas forcément un mésusage : il peut survenir à dose normale.\"},\n{id:\"g012\",chapter:\"Généralités\",page:15,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel stade de gravité d'un effet indésirable est défini comme nécessitant l'arrêt du médicament ET des soins supplémentaires, sans mettre la vie en danger ?\",\n options:[\"Effet indésirable grave\",\"Effet indésirable sévère\",\"Effet indésirable modéré\",\"Effet indésirable létal\"],\n correctAnswer:\"Effet indésirable sévère\",\n explanation:\"L'effet indésirable sévère nécessite, en plus de l'arrêt du médicament, des soins supplémentaires (à distinguer du grave qui menace la vie).\",\n simpleExplanation:\"Sévère, c'est du sérieux mais pas mortel : il faut arrêter le médicament et soigner un peu plus.\",\n memoryTip:\"Grave = danger de mort. Sévère = soins en plus. Modéré = banal.\",examTrap:\"Grave et sévère sont souvent confondus à l'examen : grave implique une menace vitale ou une hospitalisation.\"},\n{id:\"g013\",chapter:\"Généralités\",page:16,type:\"libre\",difficulty:\"facile\",\n question:\"Quelle est la durée maximale de validité d'une ordonnance médicale après sa date de rédaction ?\",\n keywords:[\"trois mois\",\"3 mois\"],\n explanation:\"Vous disposez de trois mois après la date de prescription pour vous faire délivrer vos médicaments en pharmacie.\",\n simpleExplanation:\"Une ordonnance, c'est comme un ticket qui expire après 3 mois : passé ce délai, le pharmacien ne peut plus rien donner avec ce papier.\",\n memoryTip:\"Ordonnance = 3 mois. Traitement = 1 an maximum.\",examTrap:\"Ne pas confondre validité de l'ordonnance (3 mois) et durée maximale du traitement (1 an, sauf anxiolytiques limités à 12 semaines).\"},\n\n// ---------------- ANTALGIQUES / FIEVRE (p.18-22) ----------------\n{id:\"a001\",chapter:\"Antalgiques & fièvre\",page:20,type:\"qcm\",difficulty:\"facile\",\n question:\"Selon la classification de l'OMS, à quel niveau appartient le paracétamol ?\",\n options:[\"Niveau 1\",\"Niveau 2\",\"Niveau 3\",\"Niveau 4\"],correctAnswer:\"Niveau 1\",\n explanation:\"Niveau 1 : analgésiques non opioïdes, représentés par le paracétamol et les AINS.\",\n simpleExplanation:\"Le paracétamol, c'est le premier niveau, pour les douleurs légères, comme la première marche d'un escalier.\",\n memoryTip:\"PARA = calme la douleur et la température, niveau 1.\",examTrap:\"Ne pas classer le paracétamol comme AINS : ce sont deux catégories distinctes du niveau 1.\"},\n{id:\"a002\",chapter:\"Antalgiques & fièvre\",page:20,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le chef de file des antalgiques opioïdes forts de niveau 3 ?\",\n options:[\"Codéine\",\"Tramadol\",\"Morphine\",\"Paracétamol\"],correctAnswer:\"Morphine\",\n explanation:\"Niveau 3 : analgésiques opioïdes forts, dont le chef de file est la morphine, pour les douleurs très sévères et rebelles.\",\n simpleExplanation:\"La morphine est la reine des antalgiques puissants, réservée aux douleurs très fortes.\",\n memoryTip:\"Morphine = Maximum, niveau 3.\",examTrap:\"Le tramadol et la codéine sont niveau 2 (opioïdes faibles), pas niveau 3.\"},\n{id:\"a003\",chapter:\"Antalgiques & fièvre\",page:20,type:\"qcd\",difficulty:\"moyen\",\n question:\"Quels antalgiques appartiennent au niveau 2 de l'OMS (opioïdes faibles) ?\",\n options:[\"Codéine\",\"Tramadol\",\"Morphine\",\"Paracétamol\"],correctAnswer:[\"Codéine\",\"Tramadol\"],\n explanation:\"Niveau 2 : analgésiques opioïdes faibles, représentés par la codéine et le tramadol, souvent associés à un antalgique de niveau 1.\",\n simpleExplanation:\"La codéine et le tramadol sont dans la classe intermédiaire, entre le paracétamol et la morphine.\",\n memoryTip:\"Niveau 2 = Co-Tra (Codéine-Tramadol).\",examTrap:\"Leur association avec un antalgique de niveau 1 est recommandée, pas remplacée.\"},\n{id:\"a004\",chapter:\"Antalgiques & fièvre\",page:21,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel est le mécanisme d'action commun des médicaments qui font baisser la fièvre selon le cours ?\",\n options:[\"Blocage des récepteurs à l'histamine\",\"Inhibition de la voie de la cyclo-oxygénase\",\"Stimulation de la sécrétion gastrique\",\"Blocage des canaux calciques\"],\n correctAnswer:\"Inhibition de la voie de la cyclo-oxygénase\",\n explanation:\"Le mécanisme commun des antipyrétiques (paracétamol, aspirine, ibuprofène, métamizole) est l'inhibition de la voie de la cyclo-oxygénase.\",\n simpleExplanation:\"La cyclo-oxygénase est comme une usine qui fabrique la fièvre. Ces médicaments ferment un peu l'usine.\",\n memoryTip:\"COX bloquée = fièvre baissée.\",examTrap:\"Ne pas confondre avec les antihistaminiques, dont le mécanisme est différent.\"},\n{id:\"a005\",chapter:\"Antalgiques & fièvre\",page:21,type:\"qcm\",difficulty:\"difficile\",\n question:\"Le métamizole (Noramidopyrine) est contre-indiqué à quel moment de la grossesse selon le cours ?\",\n options:[\"Premier trimestre uniquement\",\"Deuxième trimestre uniquement\",\"Troisième trimestre\",\"Il n'est jamais contre-indiqué\"],\n correctAnswer:\"Troisième trimestre\",\n explanation:\"Le métamizole est contre-indiqué pendant le 3e trimestre de la grossesse (diminution de la fonction rénale et constriction du canal artériel chez l'enfant) et contre-indiqué pendant l'allaitement.\",\n simpleExplanation:\"En fin de grossesse, ce médicament peut abîmer un petit canal important chez le bébé, donc on l'évite.\",\n memoryTip:\"Métamizole = Contre-indiqué au 3e trimestre + allaitement.\",examTrap:\"Un effet indésirable grave possible est l'agranulocytose, indépendante de la dose.\"},\n{id:\"a006\",chapter:\"Antalgiques & fièvre\",page:22,type:\"qcm\",difficulty:\"moyen\",\n question:\"À quelle classe appartiennent le Buscopan (butyl hyoscine) et le Spasmodex (dihexyvérine) ?\",\n options:[\"Antispasmodiques musculotropes\",\"Antispasmodiques neurotropes anticholinergiques\",\"Myorelaxants centraux\",\"Anti-inflammatoires stéroïdiens\"],\n correctAnswer:\"Antispasmodiques neurotropes anticholinergiques\",\n explanation:\"Ce sont des anti-muscariniques (antispasmodiques neurotropes) qui inhibent le spasme induit par l'acétylcholine.\",\n simpleExplanation:\"Ces médicaments bloquent le signal chimique (acétylcholine) qui déclenche les crampes.\",\n memoryTip:\"Anticholinergique = bloque l'acétylcholine.\",examTrap:\"Le Spasfon (phloroglucinol) agit lui directement sur le muscle : c'est un musculotrope, pas un neurotrope.\"},\n{id:\"a007\",chapter:\"Antalgiques & fièvre\",page:23,type:\"association\",difficulty:\"moyen\",\n question:\"Associez le DCI de l'antispasmodique musculotrope à son nom commercial.\",\n pairs:[[\"Phloroglucinol\",\"SPASFON\"],[\"Trimébutine\",\"DEBRIDAT\"],[\"Alvérine\",\"METEOSPASMYL\"]],\n explanation:\"Les antispasmodiques musculotropes agissent directement sur la fibre musculaire lisse : Phloroglucinol (SPASFON), Trimébutine (DEBRIDAT), Alvérine (METEOSPASMYL).\",\n simpleExplanation:\"Ces médicaments vont directement détendre le muscle, comme un massage chimique.\",\n memoryTip:\"Musculotrope = agit direct sur le muscle.\",examTrap:\"Ne pas confondre avec les anticholinergiques qui bloquent un messager chimique.\"},\n{id:\"a008\",chapter:\"Anti-inflammatoires & anesthésiques\",page:25,type:\"qcm\",difficulty:\"facile\",\n question:\"Que provoque, sur le plan pharmacologique, tout anti-inflammatoire (stéroïdien ou non) ?\",\n options:[\"Une augmentation de la synthèse des prostaglandines\",\"Une inhibition de la synthèse des prostaglandines\",\"Une stimulation de la coagulation\",\"Une augmentation de la sécrétion d'histamine\"],\n correctAnswer:\"Une inhibition de la synthèse des prostaglandines\",\n explanation:\"Tous les anti-inflammatoires, y compris les non stéroïdiens, inhibent la synthèse des prostaglandines.\",\n simpleExplanation:\"Les prostaglandines sont comme des messagers qui allument le feu de l'inflammation ; ces médicaments coupent le message.\",\n memoryTip:\"Anti-inflammatoire = anti-prostaglandines.\",examTrap:\"Cette inhibition explique aussi l'effet secondaire commun : lésion de la muqueuse gastroduodénale.\"},\n{id:\"a009\",chapter:\"Anti-inflammatoires & anesthésiques\",page:25,type:\"qcm\",difficulty:\"moyen\",\n question:\"À quelle classe d'AINS appartient le Célécoxib (CELEBREX) ?\",\n options:[\"Arylcarboxyliques\",\"Coxibs\",\"Oxicams\",\"Indoliques\"],correctAnswer:\"Coxibs\",\n explanation:\"Les coxibs comprennent Célécoxib (CELEBREX), Etoricoxib (ARCOXIA), Parécoxib (DYNASTAT), rofécoxib (Vioxx®).\",\n simpleExplanation:\"Les coxibs sont une famille spéciale d'AINS, un peu plus douce pour l'estomac.\",\n memoryTip:\"CoXib = Célécoxib.\",examTrap:\"Ne pas confondre avec les arylcarboxyliques (Diclofénac, Ibuprofène...).\"},\n{id:\"a010\",chapter:\"Anti-inflammatoires & anesthésiques\",page:26,type:\"libre\",difficulty:\"difficile\",\n question:\"Pourquoi les AINS sont-ils formellement contre-indiqués à partir du sixième mois de grossesse ?\",\n keywords:[\"fermeture prématurée canal artériel\",\"hypertension pulmonaire\",\"insuffisance rénale\",\"oligoamnios\",\"toxicité rénale cardiaque foetale\"],\n explanation:\"À partir de 24 semaines d'aménorrhée, les AINS peuvent entraîner une fermeture prématurée du canal artériel, une hypertension pulmonaire, une insuffisance rénale ou un oligohydramnios chez le fœtus.\",\n simpleExplanation:\"En fin de grossesse, ces médicaments peuvent fermer trop tôt un petit tuyau essentiel du cœur du bébé.\",\n memoryTip:\"AINS + 6e mois = danger pour le canal artériel du bébé.\",examTrap:\"Le seul antipyrétique autorisé pendant toute la grossesse est le paracétamol.\"},\n{id:\"a011\",chapter:\"Anti-inflammatoires & anesthésiques\",page:26,type:\"qcm\",difficulty:\"difficile\",\n question:\"Quel AINS est considéré comme le plus adapté et compatible avec l'allaitement selon le cours ?\",\n options:[\"Le kétoprofène\",\"L'ibuprofène\",\"L'indométacine\",\"Le piroxicam\"],correctAnswer:\"L'ibuprofène\",\n explanation:\"L'ibuprofène et ses dérivés sont de loin les plus adaptés en cas de besoin chez la femme allaitante, sans risque pour le bébé.\",\n simpleExplanation:\"Parmi tous les AINS, l'ibuprofène est celui qu'on autorise le plus facilement pendant l'allaitement.\",\n memoryTip:\"Allaitement + douleur légère = Ibuprofène en premier choix.\",examTrap:\"Les AINS en général passent dans le lait maternel et doivent être évités sauf exception documentée.\"},\n{id:\"a012\",chapter:\"Anti-inflammatoires & anesthésiques\",page:27,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quelle est la contre-indication absolue des neuroleptiques rappelée dans le chapitre des myorelaxants et confirmée au chapitre SNC ?\",\n options:[\"L'hypotension\",\"L'hyperthermie, même légère\",\"L'hypoglycémie\",\"La constipation\"],correctAnswer:\"L'hyperthermie, même légère\",\n explanation:\"La contre-indication absolue aux neuroleptiques est l'hyperthermie : même une fièvre légère (38°) peut causer un syndrome malin pouvant entraîner le décès.\",\n simpleExplanation:\"Donner un neuroleptique à quelqu'un qui a de la fièvre, c'est comme jeter de l'huile sur un feu déjà allumé : très dangereux.\",\n memoryTip:\"Neuroleptique + fièvre = syndrome malin = urgence.\",examTrap:\"Même une fièvre modérée (38°C) suffit à poser cette contre-indication absolue.\"},\n{id:\"a013\",chapter:\"Anti-inflammatoires & anesthésiques\",page:28,type:\"association\",difficulty:\"moyen\",\n question:\"Associez le DCI de l'anesthésique local à son nom commercial.\",\n pairs:[[\"Lidocaïne\",\"XYLOCAINE\"],[\"Mépivacaïne\",\"CARBOCAINE\"],[\"Ropivacaïne\",\"NAROPEINE\"]],\n explanation:\"Anesthésiques locaux : Lidocaïne (XYLOCAINE), Mépivacaïne (CARBOCAINE), Ropivacaïne (NAROPEINE), Procaïne, Articaïne.\",\n simpleExplanation:\"Ces médicaments endorment localement une petite zone, comme chez le dentiste.\",\n memoryTip:\"XYLO = Lidocaïne, la star des anesthésiques locaux.\",examTrap:\"Ne pas confondre anesthésiques locaux et anesthésiques généraux (halothane, kétamine...).\"},\n\n// ---------------- ANTI-INFECTIEUX (p.29-49) ----------------\n{id:\"i001\",chapter:\"Anti-infectieux\",page:30,type:\"qcm\",difficulty:\"facile\",\n question:\"Quelle action décrit un antibiotique qui inhibe la multiplication des micro-organismes sans les tuer ?\",\n options:[\"Action bactéricide\",\"Action bactériostatique\",\"Action virucide\",\"Action fongicide\"],correctAnswer:\"Action bactériostatique\",\n explanation:\"L'action bactériostatique inhibe la multiplication des micro-organismes, tandis que l'action bactéricide les tue.\",\n simpleExplanation:\"Bactériostatique, c'est mettre les bactéries en pause. Bactéricide, c'est les éliminer complètement.\",\n memoryTip:\"STATIQUE = ça s'arrête (pause). CIDE = ça meurt (comme homicide).\",examTrap:\"Un piège classique d'examen : confondre les deux termes qui se ressemblent.\"},\n{id:\"i002\",chapter:\"Anti-infectieux\",page:32,type:\"qcm\",difficulty:\"moyen\",\n question:\"À quoi sert un antibiogramme ?\",\n options:[\"À diagnostiquer une allergie médicamenteuse\",\"À définir les antibiotiques auxquels la souche bactérienne isolée est sensible\",\"À mesurer la fièvre du patient\",\"À remplacer la culture bactérienne\"],\n correctAnswer:\"À définir les antibiotiques auxquels la souche bactérienne isolée est sensible\",\n explanation:\"L'antibiogramme permet de définir les ATB vis-à-vis desquels la souche bactérienne isolée est sensible, guidant la prescription et surveillant les résistances.\",\n simpleExplanation:\"C'est un test qui montre quelles armes (antibiotiques) fonctionnent vraiment contre le microbe précis du patient.\",\n memoryTip:\"Antibiogramme = carte d'identité de sensibilité du microbe.\",examTrap:\"Il doit être pratiqué avant le début de l'antibiothérapie, sur des prélèvements préalables.\"},\n{id:\"i003\",chapter:\"Anti-infectieux\",page:32,type:\"qcm\",difficulty:\"difficile\",\n question:\"Comment appelle-t-on la résistance qui existe d'emblée quand le germe n'appartient pas au spectre naturel de l'antibiotique ?\",\n options:[\"Résistance acquise\",\"Résistance naturelle\",\"Résistance croisée\",\"Résistance nosocomiale\"],correctAnswer:\"Résistance naturelle\",\n explanation:\"La résistance naturelle existe d'emblée si le germe n'appartient pas au spectre de l'ATB, contrairement à la résistance acquise due à l'emploi abusif d'ATB.\",\n simpleExplanation:\"Certaines bactéries n'ont jamais été sensibles à un antibiotique donné, dès le départ, comme une serrure qui n'a jamais eu cette clé.\",\n memoryTip:\"Naturelle = de naissance. Acquise = développée avec le temps (mauvais usage).\",examTrap:\"La résistance acquise est croisée dans une même famille d'antibiotiques.\"},\n{id:\"i004\",chapter:\"Anti-infectieux\",page:33,type:\"qcd\",difficulty:\"moyen\",\n question:\"Quelles sont les principales cibles d'action des antibiotiques citées dans le cours ?\",\n options:[\"La paroi bactérienne\",\"La membrane cytoplasmique\",\"L'ARN des ribosomes\",\"Le noyau des cellules humaines\"],\n correctAnswer:[\"La paroi bactérienne\",\"La membrane cytoplasmique\",\"L'ARN des ribosomes\"],\n explanation:\"Les ATB agissent sur la paroi bactérienne (pénicillines), la membrane cytoplasmique (polymyxines), l'ARN des ribosomes (macrolides, tétracyclines) et l'ADN bactérien (quinolones).\",\n simpleExplanation:\"Les antibiotiques attaquent des points précis de la bactérie, comme un tireur qui vise des cibles différentes selon l'arme utilisée.\",\n memoryTip:\"4 cibles : Paroi, Membrane, ARN, ADN.\",examTrap:\"Le noyau des cellules humaines n'est jamais une cible : les ATB ne doivent pas toucher les cellules humaines.\"},\n{id:\"i005\",chapter:\"Anti-infectieux\",page:33,type:\"qcm\",difficulty:\"facile\",\n question:\"Quelle famille de bêta-lactamines regroupe l'Amoxicilline (CLAMOXYL) ?\",\n options:[\"Pénicilline G\",\"Pénicilline M antistaphylococcique\",\"Aminopénicilline (Pénicilline A)\",\"Carboxypénicilline\"],correctAnswer:\"Aminopénicilline (Pénicilline A)\",\n explanation:\"L'Amoxicilline (CLAMOXYL) appartient aux aminopénicillines (Pénicilline A), à spectre large.\",\n simpleExplanation:\"L'amoxicilline, c'est l'antibiotique le plus connu de toute une famille, avec un large spectre d'action.\",\n memoryTip:\"CLAMOXYL = Amoxicilline = Pénicilline A.\",examTrap:\"L'association amoxicilline-acide clavulanique élargit encore le spectre par rapport à l'amoxicilline seule.\"},\n{id:\"i006\",chapter:\"Anti-infectieux\",page:36,type:\"qcm\",difficulty:\"moyen\",\n question:\"À quelle génération de céphalosporines appartient la Ceftriaxone (ROCEPHINE) ?\",\n options:[\"1ère génération\",\"2ème génération\",\"3ème génération\",\"4ème génération\"],correctAnswer:\"3ème génération\",\n explanation:\"Ceftriaxone (ROCEPHINE) et Céfotaxime (CLAFORAN) appartiennent aux céphalosporines de 3ème génération.\",\n simpleExplanation:\"Plus le numéro de génération augmente, plus l'antibiotique couvre large et est utilisé pour des infections plus sérieuses.\",\n memoryTip:\"ROCEPHINE = 3ème génération, injectable, très utilisée à l'hôpital.\",examTrap:\"La Ceftriaxone est contre-indiquée chez les nourrissons (précipitation de bilirubine, calculs biliaires).\"},\n{id:\"i007\",chapter:\"Anti-infectieux\",page:41,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quelle classe d'antibiotiques regroupe la Doxycycline (DOXY) ?\",\n options:[\"Tétracyclines (cyclines)\",\"Macrolides\",\"Aminosides\",\"Quinolones\"],correctAnswer:\"Tétracyclines (cyclines)\",\n explanation:\"La Doxycycline (DOXY) appartient aux tétracyclines ou cyclines, bactériostatiques.\",\n simpleExplanation:\"La doxycycline fait partie de la famille des cyclines, souvent utilisée pour l'acné ou le paludisme.\",\n memoryTip:\"DOXY = cycline.\",examTrap:\"Les cyclines sont contre-indiquées pendant la grossesse (coloration des dents/squelette du fœtus) et chez le nourrisson.\"},\n{id:\"i008\",chapter:\"Anti-infectieux\",page:45,type:\"qcd\",difficulty:\"difficile\",\n question:\"Quelles familles d'antibiotiques sont contre-indiquées pendant la grossesse selon le cours ?\",\n options:[\"Les cyclines\",\"Les aminosides\",\"Les quinolones\",\"Les pénicillines\"],\n correctAnswer:[\"Les cyclines\",\"Les aminosides\",\"Les quinolones\"],\n explanation:\"Cyclines (coloration des dents/squelette), aminosides (toxicité auditive/rénale fœtale), tétracyclines et quinolones (cartilage fœtal) sont contre-indiquées pendant la grossesse. Les pénicillines peuvent être utilisées avec précaution.\",\n simpleExplanation:\"Certains antibiotiques peuvent abîmer les dents, les os ou les articulations du bébé avant même sa naissance.\",\n memoryTip:\"3 familles à éviter en grossesse : Cyclines, Aminosides, Quinolones (CAQ).\",examTrap:\"Les pénicillines, céphalosporines et macrolides restent utilisables avec précaution, contrairement aux 3 familles ci-dessus.\"},\n{id:\"i009\",chapter:\"Anti-infectieux\",page:45,type:\"qcd\",difficulty:\"difficile\",\n question:\"Quels antibiotiques sont contre-indiqués chez le nourrisson selon le cours ?\",\n options:[\"Les sulfamides\",\"La ceftriaxone\",\"Les fluoroquinolones\",\"Les pénicillines\"],\n correctAnswer:[\"Les sulfamides\",\"La ceftriaxone\",\"Les fluoroquinolones\"],\n explanation:\"Sulfamides (compétition avec la bilirubine, jaunisse), ceftriaxone (précipitation de bilirubine, calculs biliaires), fluoroquinolones (cartilage et tendons) et tétracyclines sont contre-indiqués chez le nourrisson.\",\n simpleExplanation:\"Le corps du nourrisson est très fragile : certains antibiotiques peuvent abîmer ses os, son foie ou provoquer une jaunisse.\",\n memoryTip:\"Nourrisson fragile : pas de Sulfamides, Ceftriaxone, Fluoroquinolones, Tétracyclines.\",examTrap:\"Les pénicillines, céphalosporines (sauf ceftriaxone), macrolides, aminosides et glycopeptides restent utilisables avec précaution.\"},\n{id:\"i010\",chapter:\"Anti-infectieux\",page:46,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le chef de file des inhibiteurs de la dihydrofolate réductase utilisés en traitement antipaludéen ?\",\n options:[\"Quinine\",\"Chloroquine\",\"Sulfadoxine-Pyriméthamine (FANSIDAR)\",\"Artémisinine\"],correctAnswer:\"Sulfadoxine-Pyriméthamine (FANSIDAR)\",\n explanation:\"Les inhibiteurs de la dihydrofolate réductase comprennent Sulfadoxine + Pyriméthamine (FANSIDAR) et Proguanil (PALUDRINE).\",\n simpleExplanation:\"Ces médicaments bloquent une enzyme dont le parasite du paludisme a besoin pour se reproduire.\",\n memoryTip:\"FANSIDAR = inhibiteur DHFR.\",examTrap:\"La Quinine et la Chloroquine sont des antipaludéens à effet intra-érythrocytaire, mécanisme différent.\"},\n{id:\"i011\",chapter:\"Anti-infectieux\",page:46,type:\"libre\",difficulty:\"moyen\",\n question:\"Citez deux combinaisons thérapeutiques (ACT) recommandées actuellement par l'OMS pour traiter le paludisme.\",\n keywords:[\"artéméther luméfantrine\",\"artésunate amodiaquine\",\"dihydroartemisinine pipéraquine\",\"artésunate méfloquine\",\"artésunate sulfadoxine pyriméthamine\"],\n explanation:\"L'OMS recommande notamment : Artéméther+luméfantrine, Artésunate+amodiaquine, Dihydroartémisinine+Pipéraquine, Artésunate+méfloquine, Artésunate+sulfadoxine-pyriméthamine.\",\n simpleExplanation:\"Ce sont des équipes de deux médicaments qui travaillent ensemble contre le paludisme, plus efficaces qu'un seul médicament seul.\",\n memoryTip:\"ACT = Artemisinin-based Combination Therapy.\",examTrap:\"L'amodiaquine + sulfadoxine-pyriméthamine n'est qu'une option provisoire, pas un premier choix.\"},\n{id:\"i012\",chapter:\"Anti-infectieux\",page:47,type:\"qcm\",difficulty:\"moyen\",\n question:\"L'ivermectine (STROMECTOL-MECTIZAN) est indiquée dans le traitement de :\",\n options:[\"Le paludisme\",\"L'onchocercose, la gale, l'anguillulose\",\"La tuberculose\",\"L'hépatite B\"],correctAnswer:\"L'onchocercose, la gale, l'anguillulose\",\n explanation:\"L'Ivermectine (STROMECTOL-MECTIZAN) est un anthelminthique utilisé dans le traitement de l'onchocercose, la gale et l'anguillulose.\",\n simpleExplanation:\"Ce médicament chasse plusieurs parasites différents, dont ceux responsables de la cécité des rivières.\",\n memoryTip:\"Ivermectine = Onchocercose + Gale + Anguillulose.\",examTrap:\"Ne pas confondre avec le Praziquantel (BILTRICIDE), antibilharzien et taenicide.\"},\n{id:\"i013\",chapter:\"Anti-infectieux\",page:48,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le médicament de référence pour traiter les dysenteries amibiennes selon le cours ?\",\n options:[\"Le métronidazole (FLAGYL)\",\"L'albendazole (ZENTEL)\",\"La colistine (COLIMYCINE)\",\"La griséofulvine\"],correctAnswer:\"Le métronidazole (FLAGYL)\",\n explanation:\"Le métronidazole (FLAGYL, METRONYL) fait partie des anti-amibiens, traitant les dysenteries amibiennes et affections génitales comme la trichomonose.\",\n simpleExplanation:\"Le Flagyl est un peu le couteau suisse contre les amibes et certaines infections génitales.\",\n memoryTip:\"FLAGYL = amibes + trichomonose.\",examTrap:\"Le métronidazole appartient aussi à la classe des nitro-imidazoles, anti-anaérobies.\"},\n{id:\"i014\",chapter:\"Anti-infectieux\",page:49,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quelle est l'action antifongique du Fluconazole (FLUCAZOLE) ?\",\n options:[\"Traitement des candidoses et cryptococcoses neuroméningées\",\"Traitement des infections virales\",\"Traitement du paludisme\",\"Traitement de l'hypertension\"],\n correctAnswer:\"Traitement des candidoses et cryptococcoses neuroméningées\",\n explanation:\"Le Fluconazole (FLUCAZOLE, suspension et comprimés) est indiqué dans le traitement des candidoses et des cryptococcoses neuroméningées.\",\n simpleExplanation:\"C'est un antifongique par voie orale qui combat les champignons, y compris dans le cerveau.\",\n memoryTip:\"FLUCAZOLE = Champignon + méninges.\",examTrap:\"Ne pas confondre avec la Terbinafine (LAMISIL), plutôt utilisée pour les dermatophyties cutanées et unguéales.\"},\n\n// ---------------- RESPIRATOIRE (p.50-53) ----------------\n{id:\"r001\",chapter:\"Appareil respiratoire\",page:50,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel type de toux est traité par des expectorants (mucolytiques) ?\",\n options:[\"Toux sèche\",\"Toux productive (grasse)\",\"Toux nerveuse\",\"Toux allergique uniquement\"],correctAnswer:\"Toux productive (grasse)\",\n explanation:\"Les toux productives ou grasses (avec expectorations) sont traitées avec des expectorants, visant à produire et expulser le mucus.\",\n simpleExplanation:\"Quand la toux ramène du mucus, on aide le corps à mieux l'évacuer plutôt que de le bloquer.\",\n memoryTip:\"Toux grasse = expectorant (aide à cracher). Toux sèche = antitussif (stoppe le réflexe).\",examTrap:\"Ne jamais donner un antitussif vrai en cas de toux grasse : cela peut provoquer une inondation bronchique.\"},\n{id:\"r002\",chapter:\"Appareil respiratoire\",page:50,type:\"qcm\",difficulty:\"moyen\",\n question:\"À quelle catégorie d'antitussifs appartient la Codéine (NEO CODION) ?\",\n options:[\"Antitussifs opiacés\",\"Antitussifs antihistaminiques\",\"Antitussifs homéopathiques\",\"Antitussifs phytothérapiques\"],correctAnswer:\"Antitussifs opiacés\",\n explanation:\"La Codéine (NEO CODION) fait partie des antitussifs opiacés, avec la Noscapine et le Dextrométhorphane.\",\n simpleExplanation:\"La codéine calme la toux en agissant sur le centre de la toux dans le cerveau, comme un opiacé léger.\",\n memoryTip:\"Codéine = opiacé antitussif.\",examTrap:\"Les expectorants n'agissent pas sur le cerveau mais sur la viscosité du mucus lui-même.\"},\n{id:\"r003\",chapter:\"Appareil respiratoire\",page:52,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le mode d'action des bêta-2-stimulants comme le Salbutamol (VENTOLINE) ?\",\n options:[\"Bronchodilatation par relâchement de la musculature bronchique\",\"Blocage des récepteurs H1\",\"Inhibition de la pompe à protons\",\"Diminution de la sécrétion acide gastrique\"],\n correctAnswer:\"Bronchodilatation par relâchement de la musculature bronchique\",\n explanation:\"Les bêta-2-stimulants agissent par relâchement de la musculature bronchique (bronchodilatation) en agissant sur les récepteurs bêta-2 du système sympathique.\",\n simpleExplanation:\"La Ventoline ouvre les petits tuyaux des bronches pour laisser mieux passer l'air.\",\n memoryTip:\"VENTOLINE = ouvre le VENT(o).\",examTrap:\"Ne pas confondre avec les corticoïdes inhalés qui, eux, réduisent l'inflammation mais n'ouvrent pas rapidement les bronches.\"},\n{id:\"r004\",chapter:\"Appareil respiratoire\",page:53,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quels médicaments sont des médicaments d'entretien de l'asthme, à utiliser régulièrement, et ne doivent pas être utilisés pour soulager une crise ?\",\n options:[\"Les bêta-2-stimulants d'action rapide\",\"Les antagonistes des récepteurs des leucotriènes (montélukast)\",\"L'oxygène\",\"Le MEOPA\"],\n correctAnswer:\"Les antagonistes des récepteurs des leucotriènes (montélukast)\",\n explanation:\"Le Montélukast (SINGULAIR) est un médicament d'entretien à utiliser régulièrement ; il n'ouvre pas les voies respiratoires et ne doit pas être employé pour soulager les crises.\",\n simpleExplanation:\"C'est un traitement de fond, pas un traitement de secours : il prévient, il ne soigne pas la crise en cours.\",\n memoryTip:\"Montélukast = tous les jours, jamais en urgence.\",examTrap:\"Le Salbutamol, lui, est un traitement de crise à action rapide.\"},\n\n// ---------------- ANTIHISTAMINIQUES (p.54-55) ----------------\n{id:\"h001\",chapter:\"Antihistaminiques\",page:54,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel médiateur chimique est bloqué par les antihistaminiques anti-H1 ?\",\n options:[\"L'histamine\",\"La sérotonine\",\"L'acétylcholine\",\"La dopamine\"],correctAnswer:\"L'histamine\",\n explanation:\"Un antihistaminique sert à réduire ou éliminer les effets de l'histamine, médiateur chimique libéré notamment au cours des réactions allergiques.\",\n simpleExplanation:\"L'histamine, c'est le signal d'alarme du corps qui déclenche les démangeaisons et éternuements ; les antihistaminiques coupent cette alarme.\",\n memoryTip:\"Anti-H1 = anti-histamine.\",examTrap:\"Il existe aussi des antihistaminiques atypiques qui bloquent la transformation de l'histidine en histamine.\"},\n{id:\"h002\",chapter:\"Antihistaminiques\",page:55,type:\"qcm\",difficulty:\"moyen\",\n question:\"Pourquoi préfère-t-on les antihistaminiques de deuxième génération (cétirizine, loratadine) chez le nourrisson ?\",\n options:[\"Ils sont moins chers\",\"Ils traversent moins la barrière hémato-encéphalique, donc moins sédatifs\",\"Ils agissent plus vite\",\"Ils n'ont aucun effet secondaire\"],\n correctAnswer:\"Ils traversent moins la barrière hémato-encéphalique, donc moins sédatifs\",\n explanation:\"Les antihistaminiques de 2ème génération ont un effet moins sédatif et traversent moins la barrière hémato-encéphalique, donc moins d'effets secondaires chez le nourrisson.\",\n simpleExplanation:\"Les anciens antihistaminiques endorment beaucoup le cerveau du bébé ; les nouveaux sont plus doux et évitent cela.\",\n memoryTip:\"2ème génération = moins de sommeil, plus sûr pour bébé.\",examTrap:\"Les antihistaminiques de 1ère génération (chlorphéniramine, prométhazine) sont déconseillés chez le nourrisson (somnolence, agitation, convulsions).\"},\n\n// ---------------- DIGESTIF (p.56-66) ----------------\n{id:\"d001\",chapter:\"Appareil digestif\",page:57,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le mécanisme d'action des inhibiteurs de la pompe à protons (IPP) ?\",\n options:[\"Blocage des récepteurs H2 de l'histamine\",\"Inhibition de l'ATPase H+K+ au niveau de la cellule pariétale gastrique\",\"Neutralisation directe de l'acide chlorhydrique\",\"Formation d'un gel protecteur sur l'ulcère\"],\n correctAnswer:\"Inhibition de l'ATPase H+K+ au niveau de la cellule pariétale gastrique\",\n explanation:\"Les IPP agissent en inhibant l'activité enzymatique de l'ATPase H+K+ au niveau de la cellule pariétale gastrique, avec une activité antisécrétoire puissante et prolongée (24h en une prise).\",\n simpleExplanation:\"C'est comme fermer le robinet principal qui fabrique l'acide de l'estomac, à la source.\",\n memoryTip:\"IPP = ferme la Pompe à Protons.\",examTrap:\"Ne pas confondre avec les anti-H2 qui bloquent seulement un signal, moins puissant.\"},\n{id:\"d002\",chapter:\"Appareil digestif\",page:58,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel est le mécanisme d'action du sucralfate (ULCAR) ?\",\n options:[\"Il neutralise directement l'acide gastrique\",\"Il forme un gel qui se fixe sur les protéines des lésions ulcéreuses en milieu acide\",\"Il bloque les récepteurs H2\",\"Il inhibe la pompe à protons\"],\n correctAnswer:\"Il forme un gel qui se fixe sur les protéines des lésions ulcéreuses en milieu acide\",\n explanation:\"En milieu acide, le sucralfate forme un gel visqueux chargé négativement qui se fixe sur les protéines des lésions ulcéreuses (chargées positivement), isolant l'ulcère du tube digestif.\",\n simpleExplanation:\"Le sucralfate colle un pansement chimique directement sur la plaie de l'estomac.\",\n memoryTip:\"ULCAR = pansement de l'ULCère.\",examTrap:\"Le sucralfate est un topique antiulcéreux, pas un antisécrétoire.\"},\n{id:\"d003\",chapter:\"Appareil digestif\",page:60,type:\"libre\",difficulty:\"moyen\",\n question:\"Quel est le nouveau schéma thérapeutique de première intention (14 jours) recommandé pour éradiquer Helicobacter pylori ?\",\n keywords:[\"quadrithérapie concomitante 14 jours\",\"IPP amoxicilline clarithromycine métronidazole\",\"quadrithérapie bismuth 10 jours\"],\n explanation:\"En 1ère intention : quadrithérapie concomitante 14 jours (IPP, amoxicilline, clarithromycine, métronidazole) ou quadrithérapie 10 jours avec bismuth (oméprazole, sel de bismuth, tétracycline, métronidazole). La trithérapie classique de 7 jours ne doit plus être utilisée.\",\n simpleExplanation:\"On utilise maintenant quatre médicaments ensemble pendant deux semaines pour vraiment chasser cette bactérie tenace de l'estomac.\",\n memoryTip:\"H. pylori = Quadrithérapie, pas trithérapie.\",examTrap:\"La trithérapie classique de 7 jours (2 antibiotiques + IPP) ne doit plus être utilisée.\"},\n{id:\"d004\",chapter:\"Appareil digestif\",page:61,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le principal symptôme clinique du reflux gastro-œsophagien (RGO) ?\",\n options:[\"Le pyrosis (brûlure rétrosternale)\",\"La constipation\",\"La fièvre\",\"La toux sèche uniquement\"],correctAnswer:\"Le pyrosis (brûlure rétrosternale)\",\n explanation:\"Au niveau clinique, le RGO se manifeste par un pyrosis, douleur à type de brûlure rétrosternale, parfois avec régurgitation.\",\n simpleExplanation:\"C'est cette sensation de brûlure qui remonte derrière le sternum après un repas trop copieux.\",\n memoryTip:\"Pyrosis = brûlure qui remonte.\",examTrap:\"Le RGO peut aussi provoquer des manifestations extradigestives : toux chronique, asthme, laryngite.\"},\n{id:\"d005\",chapter:\"Appareil digestif\",page:61,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quels médicaments renforcent le tonus du sphincter inférieur de l'œsophage dans le traitement du RGO ?\",\n options:[\"Les IPP\",\"Les procinétiques comme le métoclopramide (PRIMPERAN)\",\"Les argiles\",\"Les laxatifs\"],correctAnswer:\"Les procinétiques comme le métoclopramide (PRIMPERAN)\",\n explanation:\"Les procinétiques (Métoclopramide, Dompéridone, Lévosulpiride, Cisapride) renforcent le tonus du sphincter, accélèrent la vidange gastrique et stimulent la motricité.\",\n simpleExplanation:\"Ces médicaments referment un peu plus fort la porte entre l'estomac et l'œsophage pour empêcher les remontées.\",\n memoryTip:\"Procinétique = pousse le contenu vers l'avant + resserre la porte.\",examTrap:\"La dompéridone ne doit plus être utilisée chez l'enfant de moins de 12 ans.\"},\n{id:\"d006\",chapter:\"Appareil digestif\",page:61,type:\"qcm\",difficulty:\"moyen\",\n question:\"Le RGO est-il fréquent chez la femme enceinte, et pourquoi ?\",\n options:[\"Non, il est rare pendant la grossesse\",\"Oui, par hyperpression intra-abdominale et relâchement hormonal du sphincter\",\"Oui, uniquement à cause du stress\",\"Non, la grossesse protège du RGO\"],\n correctAnswer:\"Oui, par hyperpression intra-abdominale et relâchement hormonal du sphincter\",\n explanation:\"Le RGO est fréquent chez la femme enceinte : hyperpression intra-abdominale et relâchement du sphincter œsophagien inférieur d'origine hormonale.\",\n simpleExplanation:\"Le bébé qui grandit pousse sur l'estomac, et les hormones détendent la porte qui devrait rester fermée.\",\n memoryTip:\"Grossesse = pression + hormones = RGO fréquent.\",examTrap:\"Il n'existe pas de risque fœtal démontré lié à l'exposition aux IPP.\"},\n{id:\"d007\",chapter:\"Appareil digestif\",page:61,type:\"qcm\",difficulty:\"facile\",\n question:\"Quelle classe de médicaments correspond aux alginates (GAVISCON) utilisés dans le RGO ?\",\n options:[\"Pansements gastriques\",\"Antisécrétoires\",\"Procinétiques\",\"Antibiotiques\"],correctAnswer:\"Pansements gastriques\",\n explanation:\"Pour réduire l'acidité gastrique dans le RGO, on utilise les alginates (pansements gastriques) et les antisécrétoires.\",\n simpleExplanation:\"L'alginate forme une sorte de radeau protecteur qui flotte sur le contenu de l'estomac.\",\n memoryTip:\"GAVISCON = pansement flottant.\",examTrap:\"L'alginate est un pansement mécanique, pas un antisécrétoire chimique.\"},\n{id:\"d008\",chapter:\"Appareil digestif\",page:62,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quelle classe d'antiémétiques est indiquée en première intention pour les nausées-vomissements induits par la chimiothérapie ?\",\n options:[\"Les procinétiques\",\"Les antagonistes des récepteurs 5-HT3 de la sérotonine (Ondansétron)\",\"Les neuroleptiques antiémétiques\",\"Les antihistaminiques H1\"],\n correctAnswer:\"Les antagonistes des récepteurs 5-HT3 de la sérotonine (Ondansétron)\",\n explanation:\"Les antagonistes 5-HT3 (Granisétron KYTRIL, Ondansétron ZOPHREN) sont indiqués pour les nausées-vomissements induits par la chimiothérapie et post-opératoires.\",\n simpleExplanation:\"Ces médicaments bloquent un messager chimique précis (la sérotonine) responsable des nausées de chimiothérapie.\",\n memoryTip:\"ZOPHREN = anti-chimio nausées.\",examTrap:\"Les procinétiques (métoclopramide) sont plutôt indiqués dans le RGO et la dyspepsie, pas en 1ère ligne de la chimio.\"},\n{id:\"d009\",chapter:\"Appareil digestif\",page:62,type:\"libre\",difficulty:\"difficile\",\n question:\"Quel traitement de première intention (association) est recommandé pour les nausées et vomissements de la grossesse (NVG) ?\",\n keywords:[\"doxylamine pyridoxine\",\"vitamine B6\",\"NOSIC\",\"ADIONE\"],\n explanation:\"La pyridoxine (vitamine B6), en monothérapie ou associée à la doxylamine, est recommandée en première intention (Spécialités : NOSIC, ADIONE) en raison de son efficacité et de son innocuité.\",\n simpleExplanation:\"On commence par une combinaison douce de deux substances peu risquées avant d'essayer des médicaments plus forts.\",\n memoryTip:\"NVG = Doxylamine + Vitamine B6 en 1er choix.\",examTrap:\"L'ondansétron n'est utilisé qu'en dernier recours, quand les autres associations ont échoué.\"},\n{id:\"d010\",chapter:\"Appareil digestif\",page:64,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le mode d'action du lopéramide (IMODIUM) dans le traitement de la diarrhée ?\",\n options:[\"Diminution de la motilité et des sécrétions intestinales\",\"Inhibition des sécrétions d'eau et d'électrolytes\",\"Action antibactérienne directe\",\"Formation d'un gel protecteur\"],\n correctAnswer:\"Diminution de la motilité et des sécrétions intestinales\",\n explanation:\"Le Lopéramide (IMODIUM, ARESTAL) est un ralentisseur du transit intestinal qui diminue la motilité et les sécrétions intestinales.\",\n simpleExplanation:\"Il ralentit le transit intestinal, comme un frein sur des intestins trop pressés.\",\n memoryTip:\"IMODIUM = ralentit le transit.\",examTrap:\"Ne pas confondre avec le racécadotril (TIORFAN), un antisécrétoire intestinal au mécanisme différent.\"},\n{id:\"d011\",chapter:\"Appareil digestif\",page:64,type:\"qcm\",difficulty:\"moyen\",\n question:\"Le racécadotril (TIORFAN) agit selon quel mécanisme ?\",\n options:[\"Diminution de la motilité intestinale\",\"Inhibition des sécrétions d'eau et d'électrolytes intestinaux\",\"Action laxative osmotique\",\"Formation d'un film protecteur gastrique\"],\n correctAnswer:\"Inhibition des sécrétions d'eau et d'électrolytes intestinaux\",\n explanation:\"Le Racécadotril (TIORFAN) est un antisécrétoire intestinal dont le mode d'action est l'inhibition des sécrétions d'eau et d'électrolytes.\",\n simpleExplanation:\"Ce médicament empêche l'intestin de trop 'pleurer' de l'eau et des sels dans les selles.\",\n memoryTip:\"TIORFAN = ferme les sécrétions d'eau.\",examTrap:\"Contrairement au lopéramide, il n'agit pas en ralentissant le transit lui-même.\"},\n{id:\"d012\",chapter:\"Appareil digestif\",page:65,type:\"association\",difficulty:\"moyen\",\n question:\"Associez le type de laxatif à son mode d'action.\",\n pairs:[[\"Laxatifs osmotiques\",\"Augmentation de l'hydratation par effet osmotique\"],[\"Laxatifs lubrifiants\",\"Lubrification et ramollissement du contenu colique\"],[\"Laxatifs stimulants\",\"Irritation de la paroi intestinale entraînant une évacuation rapide\"]],\n explanation:\"Laxatifs osmotiques (Lactulose DUPHALAC), lubrifiants (huile de paraffine), stimulants (Bisacodyl), et de lest (Psylium) agissent chacun par un mécanisme différent.\",\n simpleExplanation:\"Certains laxatifs attirent l'eau, d'autres graissent le passage, d'autres encore forcent l'intestin à se contracter.\",\n memoryTip:\"Osmotique = attire l'eau. Lubrifiant = glisse. Stimulant = irrite et pousse.\",examTrap:\"Les laxatifs stimulants (Bisacodyl) sont les plus agressifs et ne doivent pas être utilisés en continu.\"},\n{id:\"d013\",chapter:\"Appareil digestif\",page:57,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quelle est l'étiologie la plus fréquente citée pour la maladie ulcéreuse (classification actuelle) ?\",\n options:[\"Toxicité médicamenteuse (AINS, aspirine) et Helicobacter pylori\",\"Uniquement le stress\",\"Uniquement une allergie alimentaire\",\"Une carence en vitamine C\"],\n correctAnswer:\"Toxicité médicamenteuse (AINS, aspirine) et Helicobacter pylori\",\n explanation:\"La classification actuelle de l'ulcère selon la cause inclut : toxicité médicamenteuse (AINS, aspirine), présence d'Helicobacter pylori, ulcère de stress, et étiologies rares.\",\n simpleExplanation:\"Un ulcère vient souvent soit d'un médicament irritant pour l'estomac, soit d'une bactérie appelée Helicobacter pylori.\",\n memoryTip:\"Ulcère = AINS + H. pylori en priorité.\",examTrap:\"Le syndrome de Zollinger-Ellison est une étiologie rare, pas la plus fréquente.\"},\n\n// ---------------- SNC / PSYCHOTROPES (p.67-71) ----------------\n{id:\"s001\",chapter:\"Médicaments du SNC (Psychotropes)\",page:68,type:\"qcm\",difficulty:\"facile\",\n question:\"Combien de grandes familles de médicaments psychotropes sont décrites dans le cours ?\",\n options:[\"Trois\",\"Quatre\",\"Cinq\",\"Six\"],correctAnswer:\"Cinq\",\n explanation:\"Cinq grandes familles : anxiolytiques, antidépresseurs, neuroleptiques, hypnotiques, thymorégulateurs.\",\n simpleExplanation:\"Cinq grandes équipes de médicaments qui agissent tous sur le cerveau, mais chacune avec un rôle différent.\",\n memoryTip:\"A-A-N-H-T : Anxiolytiques, Antidépresseurs, Neuroleptiques, Hypnotiques, Thymorégulateurs.\",examTrap:\"Les antiparkinsoniens et antiépileptiques sont décrits séparément, hors des 5 grandes familles.\"},\n{id:\"s002\",chapter:\"Médicaments du SNC (Psychotropes)\",page:69,type:\"qcm\",difficulty:\"facile\",\n question:\"À quelle classe pharmacologique appartient le diazépam (VALIUM) ?\",\n options:[\"Anxiolytique benzodiazépine\",\"Neuroleptique phénothiazine\",\"Antidépresseur tricyclique\",\"Antiparkinsonien\"],correctAnswer:\"Anxiolytique benzodiazépine\",\n explanation:\"Le diazépam (VALIUM) fait partie des anxiolytiques benzodiazépines, avec l'alprazolam, le bromazépam, etc.\",\n simpleExplanation:\"Le Valium calme l'anxiété en agissant sur le cerveau, c'est une benzodiazépine classique.\",\n memoryTip:\"VALIUM = anxiolytique benzodiazépine emblématique.\",examTrap:\"Le diazépam est aussi utilisé comme antiépileptique et myorelaxant central, selon le contexte.\"},\n{id:\"s003\",chapter:\"Médicaments du SNC (Psychotropes)\",page:69,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel est l'effet principal recherché avec un neuroleptique dans le traitement de la schizophrénie ?\",\n options:[\"Stimuler l'humeur\",\"Diminuer ou faire disparaître les hallucinations et le délire\",\"Induire le sommeil profond immédiat\",\"Augmenter l'appétit\"],\n correctAnswer:\"Diminuer ou faire disparaître les hallucinations et le délire\",\n explanation:\"Un neuroleptique entraîne indifférence affective, diminution de l'agressivité, diminution/disparition des hallucinations et du délire, réduction de la psychose.\",\n simpleExplanation:\"Le neuroleptique calme les pensées confuses et les fausses perceptions qui perturbent le patient.\",\n memoryTip:\"Neuroleptique = anti-délire, anti-hallucination.\",examTrap:\"Ils sont aussi utilisés hors AMM pour l'insomnie ou l'anxiété, du fait de leurs propriétés sédatives.\"},\n{id:\"s004\",chapter:\"Médicaments du SNC (Psychotropes)\",page:70,type:\"qcm\",difficulty:\"moyen\",\n question:\"À quelle classe de neuroleptiques appartient l'Halopéridol (HALDOL) ?\",\n options:[\"Phénothiazines\",\"Butyrophénones\",\"Thioxanthènes\",\"Neuroleptiques atypiques\"],correctAnswer:\"Butyrophénones\",\n explanation:\"L'Halopéridol appartient à la classe des Butyrophénones, avec le Dropéridol, le Benpéridol.\",\n simpleExplanation:\"L'Haldol fait partie d'une des quatre grandes familles chimiques de neuroleptiques.\",\n memoryTip:\"HALDOL = Butyrophénone.\",examTrap:\"La Chlorpromazine, elle, appartient aux phénothiazines, une famille différente.\"},\n{id:\"s005\",chapter:\"Médicaments du SNC (Psychotropes)\",page:71,type:\"libre\",difficulty:\"difficile\",\n question:\"Pourquoi préfère-t-on l'oxazépam (Séresta) si un anxiolytique est nécessaire pendant l'allaitement ?\",\n keywords:[\"passe le moins dans le lait maternel\",\"surveiller le bébé\"],\n explanation:\"Si un anxiolytique est nécessaire pendant l'allaitement, il faut choisir celui qui passe le moins dans le lait maternel, comme l'oxazépam (Séresta), et surveiller le bébé.\",\n simpleExplanation:\"Parmi tous les anxiolytiques, celui-ci passe le moins dans le lait, donc il dérange le moins le bébé.\",\n memoryTip:\"Séresta = allaitement = moindre passage lacté.\",examTrap:\"Les anxiolytiques restent à éviter ou limiter en général pendant l'allaitement, même l'oxazépam nécessite une surveillance.\"},\n{id:\"s006\",chapter:\"Médicaments du SNC (Psychotropes)\",page:71,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel médicament est utilisé dans la maladie de Parkinson en association avec la bensérazide ?\",\n options:[\"La Lévodopa (MODOPAR)\",\"Le Diazépam\",\"La Carbamazépine\",\"L'Acide valproïque\"],correctAnswer:\"La Lévodopa (MODOPAR)\",\n explanation:\"Lévodopa + bensérazide (MODOPAR) et Lévodopa + carbidopa (SINEMET) sont utilisés pour diminuer les tremblements et la rigidité de la maladie de Parkinson.\",\n simpleExplanation:\"La Lévodopa remplace une substance manquante dans le cerveau des patients parkinsoniens.\",\n memoryTip:\"MODOPAR = Lévodopa + Bensérazide, contre Parkinson.\",examTrap:\"Les anticholinergiques (Trihexiphénidyle) sont une autre classe utilisée dans le Parkinson, à ne pas confondre.\"},\n\n// ---------------- HORMONAUX GYNECO (p.72-80) ----------------\n{id:\"o001\",chapter:\"Hormonaux gynécologiques\",page:75,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel est le mécanisme principal des ocytociques comme la méthylergométrine (METHERGIN) ?\",\n options:[\"Bloquer les contractions utérines\",\"Augmenter le tonus des fibres musculaires utérines et les contractions\",\"Réduire la tension artérielle\",\"Stimuler l'ovulation\"],\n correctAnswer:\"Augmenter le tonus des fibres musculaires utérines et les contractions\",\n explanation:\"La méthylergométrine (METHERGIN-UTERGIN) est un utérotonique puissant, indiqué dans les hémorragies de la délivrance et du post-partum, l'atonie utérine.\",\n simpleExplanation:\"Ce médicament fait se contracter l'utérus fort et bien après l'accouchement pour stopper les saignements.\",\n memoryTip:\"METHERGIN = contraction utérine puissante.\",examTrap:\"La méthylergométrine passe dans le lait maternel : attention chez la femme allaitante.\"},\n{id:\"o002\",chapter:\"Hormonaux gynécologiques\",page:76,type:\"qcm\",difficulty:\"moyen\",\n question:\"Le Misoprostol réduit de quel pourcentage environ le risque de saignements abondants lors des hémorragies du post-partum, selon le cours ?\",\n options:[\"20%\",\"40%\",\"60%\",\"90%\"],correctAnswer:\"60%\",\n explanation:\"L'utilisation du Misoprostol immédiatement après l'accouchement réduit le risque de saignements abondants de 60%.\",\n simpleExplanation:\"C'est un chiffre à retenir précisément pour l'examen : 60% de réduction du risque hémorragique.\",\n memoryTip:\"Misoprostol = 60% de risque en moins.\",examTrap:\"Le Misoprostol est aussi utilisé en association avec la mifépristone pour l'avortement précoce.\"},\n{id:\"o003\",chapter:\"Hormonaux gynécologiques\",page:78,type:\"qcd\",difficulty:\"difficile\",\n question:\"Quels sont les trois mécanismes par lesquels la contraception hormonale agit ?\",\n options:[\"Blocage de l'ovulation\",\"Épaississement de la glaire cervicale\",\"Réduction de l'épaisseur de l'endomètre\",\"Augmentation de la production d'ovules\"],\n correctAnswer:[\"Blocage de l'ovulation\",\"Épaississement de la glaire cervicale\",\"Réduction de l'épaisseur de l'endomètre\"],\n explanation:\"La contraception hormonale bloque l'ovulation, épaissit la glaire cervicale (empêchant le passage des spermatozoïdes), et réduit l'épaisseur de l'endomètre (empêchant la nidation).\",\n simpleExplanation:\"La pilule agit sur trois fronts à la fois : elle empêche l'ovule de sortir, elle bloque les spermatozoïdes, et elle rend le nid trop fin pour un bébé.\",\n memoryTip:\"3 verrous : Ovulation bloquée, Glaire épaissie, Endomètre aminci.\",examTrap:\"Ne pas confondre avec le stérilet au cuivre, qui agit différemment (effet spermicide local, sans hormone).\"},\n{id:\"o004\",chapter:\"Hormonaux gynécologiques\",page:78,type:\"qcm\",difficulty:\"difficile\",\n question:\"Pourquoi privilégie-t-on les pilules de 1ère et 2ème génération par rapport à celles de 3ème/4ème génération ?\",\n options:[\"Elles sont moins chères uniquement\",\"Les thromboses veineuses sont moins fréquentes avec elles\",\"Elles sont plus efficaces contre l'ovulation\",\"Elles n'ont aucun effet secondaire\"],\n correctAnswer:\"Les thromboses veineuses sont moins fréquentes avec elles\",\n explanation:\"Les thromboses veineuses (phlébite, embolie pulmonaire) sont plus fréquentes avec les pilules de 3ème et 4ème génération. C'est pourquoi les pilules de 1ère et 2ème génération doivent être privilégiées.\",\n simpleExplanation:\"Les pilules plus anciennes ont un risque de caillots dans le sang un peu plus faible que les plus récentes.\",\n memoryTip:\"1ère/2ème génération = moins de risque de thrombose veineuse.\",examTrap:\"Le risque de thrombose artérielle (AVC, infarctus), lui, existe quelle que soit la génération de la pilule.\"},\n{id:\"o005\",chapter:\"Hormonaux gynécologiques\",page:80,type:\"qcm\",difficulty:\"moyen\",\n question:\"Dans quel délai maximal après un rapport non protégé le Lévonorgestrel (NORLEVO) doit-il être pris ?\",\n options:[\"24 heures\",\"48 heures\",\"72 heures\",\"120 heures\"],correctAnswer:\"72 heures\",\n explanation:\"Le Lévonorgestrel (NORLEVO, PREGNON) : un comprimé de 1,5 mg, en une seule prise, le plus tôt possible et au plus tard 72 heures (3 jours) après le rapport.\",\n simpleExplanation:\"Plus on prend la pilule du lendemain rapidement, plus elle est efficace ; la limite est de 3 jours pour le Norlevo.\",\n memoryTip:\"NORLEVO = 72 heures (3 jours).\",examTrap:\"L'Ulipristal acétate (ELLAONE), lui, peut être pris jusqu'à 120 heures (5 jours) après le rapport.\"},\n{id:\"o006\",chapter:\"Hormonaux gynécologiques\",page:81,type:\"qcm\",difficulty:\"difficile\",\n question:\"Quelle est l'indication de l'Atosiban, utérorelaxant non bêta-stimulant ?\",\n options:[\"Contraception d'urgence\",\"Menace d'accouchement prématuré entre la 24e et la 33e semaine de grossesse\",\"Déclenchement du travail à terme\",\"Traitement de l'hypertension gravidique\"],\n correctAnswer:\"Menace d'accouchement prématuré entre la 24e et la 33e semaine de grossesse\",\n explanation:\"L'Atosiban est indiqué dans la menace d'accouchement prématuré de la 24e à la 33e semaine incluse, en cas de contractions régulières et de modification du col.\",\n simpleExplanation:\"Ce médicament aide à retarder un accouchement qui arriverait trop tôt.\",\n memoryTip:\"Atosiban = frein à l'accouchement prématuré.\",examTrap:\"Ne pas confondre avec les bêta-mimétiques (Salbutamol, Terbutaline) qui sont d'autres utérorelaxants, avec un mécanisme différent.\"},\n\n// ---------------- CARDIO-VASCULAIRE (p.81-89) ----------------\n{id:\"c001\",chapter:\"Appareil cardio-vasculaire\",page:83,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le mécanisme d'action des inhibiteurs de l'enzyme de conversion (IEC) ?\",\n options:[\"Blocage des canaux calciques\",\"Blocage de l'activation de l'angiotensine II en inhibant l'enzyme de conversion\",\"Blocage des récepteurs bêta\",\"Augmentation de l'élimination du sodium uniquement\"],\n correctAnswer:\"Blocage de l'activation de l'angiotensine II en inhibant l'enzyme de conversion\",\n explanation:\"Les IEC empêchent l'activation de l'angiotensine II (vasoconstricteur puissant) en bloquant l'enzyme de conversion, provoquant une vasodilatation et diminuant la synthèse d'aldostérone.\",\n simpleExplanation:\"Ils coupent la fabrication d'une substance qui resserre les vaisseaux sanguins, donc les vaisseaux restent plus détendus.\",\n memoryTip:\"IEC = -PRIL (Captopril, Ramipril, Enalapril...).\",examTrap:\"Les IEC diminuent l'aldostérone, donc attention au risque d'hyperkaliémie.\"},\n{id:\"c002\",chapter:\"Appareil cardio-vasculaire\",page:84,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quelle est la différence de mécanisme entre les IEC et les antagonistes des récepteurs de l'angiotensine II (sartans) ?\",\n options:[\"Les sartans empêchent l'angiotensine II de se former, les IEC bloquent ses récepteurs\",\"Les sartans empêchent l'angiotensine II d'agir sur ses récepteurs mais ne l'empêchent pas de se former, contrairement aux IEC\",\"Il n'y a aucune différence\",\"Les sartans agissent uniquement sur le cœur\"],\n correctAnswer:\"Les sartans empêchent l'angiotensine II d'agir sur ses récepteurs mais ne l'empêchent pas de se former, contrairement aux IEC\",\n explanation:\"Les sartans (ARAII) empêchent l'angiotensine II d'agir sur ses récepteurs sans empêcher sa formation, alors que les IEC bloquent directement sa formation.\",\n simpleExplanation:\"Les IEC empêchent de fabriquer la substance nocive ; les sartans laissent la substance exister mais bloquent la porte où elle agirait.\",\n memoryTip:\"Sartans = -SARTAN (Losartan, Valsartan, Irbésartan...).\",examTrap:\"Ne pas confondre le point d'action : formation (IEC) versus récepteur (sartans).\"},\n{id:\"c003\",chapter:\"Appareil cardio-vasculaire\",page:84,type:\"qcm\",difficulty:\"facile\",\n question:\"Quelle est la 'règle des 3R' associée aux cardiotoniques (digitaliques) ?\",\n options:[\"Renforce, Régularise, Ralentit le rythme cardiaque\",\"Réduit, Répare, Restaure\",\"Rapide, Réversible, Résistant\",\"Régule la tension, Réduit l'œdème, Renforce les reins\"],\n correctAnswer:\"Renforce, Régularise, Ralentit le rythme cardiaque\",\n explanation:\"Les cardiotoniques améliorent la fonction cardiaque selon la règle des 3R (ou règle de Potain) : Renforce le rythme, Régularise le rythme, Ralentit le rythme.\",\n simpleExplanation:\"La Digoxine agit comme un chef d'orchestre qui rend le cœur plus fort, plus régulier et plus calme.\",\n memoryTip:\"3R = Renforce, Régularise, Ralentit.\",examTrap:\"Le principal effet secondaire est l'intoxication digitalique, qui apparaît souvent trop tard.\"},\n{id:\"c004\",chapter:\"Appareil cardio-vasculaire\",page:85,type:\"qcd\",difficulty:\"moyen\",\n question:\"Quelles sont les indications des diurétiques citées dans le cours ?\",\n options:[\"Hypertension artérielle essentielle modérée\",\"Œdèmes\",\"Œdème aigu du poumon\",\"Constipation chronique\"],\n correctAnswer:[\"Hypertension artérielle essentielle modérée\",\"Œdèmes\",\"Œdème aigu du poumon\"],\n explanation:\"Les diurétiques sont indiqués dans l'HTA essentielle modérée, le traitement des œdèmes, l'OAP (pour éviter la noyade alvéolaire) et l'insuffisance rénale aiguë (correction de l'anurie).\",\n simpleExplanation:\"Les diurétiques font sortir l'excès d'eau et de sel du corps, ce qui aide contre l'hypertension et les gonflements.\",\n memoryTip:\"Diurétique = fait uriner davantage = draine l'excès d'eau.\",examTrap:\"Ils n'ont aucune indication dans la constipation, ce n'est pas leur mécanisme.\"},\n{id:\"c005\",chapter:\"Appareil cardio-vasculaire\",page:85,type:\"qcm\",difficulty:\"moyen\",\n question:\"Le Furosémide (LASILIX) appartient à quelle classe de diurétiques ?\",\n options:[\"Diurétiques de l'anse (hypokaliémiants)\",\"Diurétiques hyperkaliémiants\",\"Diurétiques osmotiques\",\"Inhibiteurs de l'anhydrase carbonique\"],correctAnswer:\"Diurétiques de l'anse (hypokaliémiants)\",\n explanation:\"Le Furosémide (LASILIX) est un diurétique de l'anse, hypokaliémiant, comme le Torasémide et le Bumétamide.\",\n simpleExplanation:\"Le Lasilix est un diurétique puissant qui fait aussi perdre du potassium, il faut donc surveiller ce paramètre.\",\n memoryTip:\"LASILIX = diurétique de l'anse = hypokaliémiant.\",examTrap:\"Ne pas confondre avec la Spironolactone (ALDACTONE), diurétique hyperkaliémiant (épargneur de potassium).\"},\n{id:\"c006\",chapter:\"Appareil cardio-vasculaire\",page:87,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel est le rôle principal des antiagrégants plaquettaires comme l'Aspirine à faible dose ou le Clopidogrel ?\",\n options:[\"Dissoudre un caillot déjà formé\",\"Empêcher l'agrégation des plaquettes et donc la formation de caillots\",\"Réguler le rythme cardiaque\",\"Baisser la tension artérielle\"],\n correctAnswer:\"Empêcher l'agrégation des plaquettes et donc la formation de caillots\",\n explanation:\"Les antiagrégants plaquettaires (Aspirine, Clopidogrel CLOPACT, Ticagrelor BRILIQUE...) empêchent les plaquettes de s'agréger entre elles.\",\n simpleExplanation:\"Ils empêchent les petites plaquettes du sang de se coller entre elles pour former un bouchon dangereux.\",\n memoryTip:\"Antiagrégant = empêche les plaquettes de s'agréger (se coller).\",examTrap:\"Ne pas confondre avec les thrombolytiques (Streptokinase, Altéplase), qui eux dissolvent un caillot déjà formé.\"},\n\n// ---------------- VITAMINES & OLIGO (p.89-99) ----------------\n{id:\"v001\",chapter:\"Vitamines & Oligo-éléments\",page:92,type:\"qcm\",difficulty:\"facile\",\n question:\"Quelle vitamine est systématiquement prescrite chez toute femme en âge de procréer ayant un désir de grossesse ?\",\n options:[\"Vitamine B9 (acide folique)\",\"Vitamine C\",\"Vitamine D\",\"Vitamine K\"],correctAnswer:\"Vitamine B9 (acide folique)\",\n explanation:\"L'acide folique (vitamine B9) est prescrit de manière systématique chez toute femme en âge de procréer ayant un désir de grossesse ; les folates sont indispensables au développement du système nerveux de l'embryon.\",\n simpleExplanation:\"Cette vitamine aide à bien construire le système nerveux du futur bébé dès les premières semaines.\",\n memoryTip:\"B9 = Bébé, avant la grossesse.\",examTrap:\"Une carence en B9 ou B12 provoque toutes deux des anémies macrocytaires, ne pas les confondre entre elles pour l'examen.\"},\n{id:\"v002\",chapter:\"Vitamines & Oligo-éléments\",page:93,type:\"qcm\",difficulty:\"moyen\",\n question:\"La vitamine K est essentielle à quelle fonction principale ?\",\n options:[\"La vision nocturne\",\"La coagulation du sang\",\"La contraction musculaire\",\"La production d'hormones thyroïdiennes\"],correctAnswer:\"La coagulation du sang\",\n explanation:\"La vitamine K est un facteur de la coagulation, permettant la synthèse de la prothrombine par le foie (activation des facteurs II, VII, IX, X).\",\n simpleExplanation:\"Sans vitamine K, le sang aurait du mal à coaguler correctement en cas de blessure.\",\n memoryTip:\"Vitamine K = Koagulation.\",examTrap:\"Le lait maternel est pauvre en vitamine K, un apport est donc systématiquement prescrit au nouveau-né.\"},\n{id:\"v003\",chapter:\"Vitamines & Oligo-éléments\",page:89,type:\"qcm\",difficulty:\"moyen\",\n question:\"Que provoque un apport excessif de vitamines liposolubles comme la vitamine A ou D ?\",\n options:[\"Aucun risque, elles sont éliminées facilement\",\"Une hypervitaminose, très toxique pour l'organisme\",\"Une hypovitaminose\",\"Un simple ralentissement de l'absorption\"],\n correctAnswer:\"Une hypervitaminose, très toxique pour l'organisme\",\n explanation:\"Un apport excessif de vitamines liposolubles (A et D essentiellement) provoque une hypervitaminose, très toxique pour l'organisme.\",\n simpleExplanation:\"Contrairement aux vitamines solubles dans l'eau qu'on élimine facilement, les vitamines A et D s'accumulent dans les graisses du corps et peuvent devenir toxiques en excès.\",\n memoryTip:\"Liposoluble = stockée = risque de surdosage (A, D, E, K).\",examTrap:\"Un déficit provoque une hypovitaminose ou avitaminose, l'excès une hypervitaminose : ne pas inverser ces deux notions.\"},\n{id:\"v004\",chapter:\"Vitamines & Oligo-éléments\",page:96,type:\"qcm\",difficulty:\"facile\",\n question:\"Quel oligo-élément est essentiel à la formation des hormones thyroïdiennes ?\",\n options:[\"Le fer\",\"L'iode\",\"Le zinc\",\"Le calcium\"],correctAnswer:\"L'iode\",\n explanation:\"L'iode sert à la formation des hormones thyroïdiennes, nécessaires à la croissance, au développement et au métabolisme de base. Il est indispensable à la maturation du système nerveux du fœtus.\",\n simpleExplanation:\"L'iode est l'ingrédient indispensable que la thyroïde utilise pour fabriquer ses hormones.\",\n memoryTip:\"Iode = thyroïde.\",examTrap:\"Ne pas confondre avec le fer, essentiel au transport de l'oxygène par l'hémoglobine, pas à la thyroïde.\"},\n{id:\"v005\",chapter:\"Vitamines & Oligo-éléments\",page:99,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel oligo-élément est particulièrement associé au système immunitaire et à la cicatrisation ?\",\n options:[\"Le zinc\",\"Le magnésium\",\"Le phosphore\",\"Le potassium\"],correctAnswer:\"Le zinc\",\n explanation:\"Le zinc joue un rôle important dans la croissance, le système immunitaire (notamment la cicatrisation), les fonctions neurologiques, la vision, le goût et l'odorat.\",\n simpleExplanation:\"Le zinc aide le corps à se défendre contre les infections et à réparer les plaies plus vite.\",\n memoryTip:\"Zinc = immunité + cicatrisation.\",examTrap:\"Le manganèse, lui, est surtout associé à la lutte contre les radicaux libres, un rôle différent.\"},\n\n// ---------------- COMPLEMENTS ISSUS DU SUPPORT 2022 ----------------\n// Récapitulatif antibiotiques (contre-indications, effets secondaires)\n{id:\"i015\",chapter:\"Anti-infectieux\",page:34,source:\"2022\",type:\"qcd\",difficulty:\"difficile\",\n question:\"Quelles familles d'antibiotiques sont contre-indiquées en cas de grossesse et d'allaitement selon le tableau récapitulatif du cours ?\",\n options:[\"Aminosides\",\"Cyclines\",\"Fluoroquinolones\",\"Amoxicilline seule\"],\n correctAnswer:[\"Aminosides\",\"Cyclines\",\"Fluoroquinolones\"],\n explanation:\"Le récapitulatif du cours cite : Aminosides, Cyclines, Fluoroquinolones, Sulfamides, Vancomycine, Teicoplanine, Fosfomycine, Fucidine comme contre-indiqués en grossesse et allaitement.\",\n simpleExplanation:\"Ce tableau récapitulatif rassemble d'un coup d'œil toutes les familles à éviter chez la femme enceinte ou qui allaite.\",\n memoryTip:\"Grossesse/allaitement : Amino-Cyclines-Fluoroquinolones-Sulfamides-Vanco-Teico-Fosfo-Fucidine.\",\n examTrap:\"L'amoxicilline (pénicilline) reste, elle, utilisable avec précaution pendant la grossesse.\"},\n{id:\"i016\",chapter:\"Anti-infectieux\",page:34,source:\"2022\",type:\"qcm\",difficulty:\"moyen\",\n question:\"Quels sont les deux types d'effets indésirables communs à la plupart des familles d'antibiotiques ?\",\n options:[\"Les réactions allergiques et les troubles digestifs\",\"La toxicité rénale et la surdité\",\"Les convulsions et l'hypertension\",\"La somnolence et la prise de poids\"],\n correctAnswer:\"Les réactions allergiques et les troubles digestifs\",\n explanation:\"Deux types d'effets indésirables sont communs à toutes les familles d'antibiotiques : les réactions allergiques (démangeaisons, urticaire, œdème de Quincke, choc anaphylactique) et les troubles digestifs (nausées, diarrhées, perturbation de la flore intestinale).\",\n simpleExplanation:\"Presque tous les antibiotiques peuvent soit énerver le système de défense du corps (allergie), soit perturber le ventre (digestion).\",\n memoryTip:\"2 effets communs : Allergie + Digestif.\",\n examTrap:\"La survenue d'une réaction allergique impose l'arrêt du traitement, contrairement à de simples troubles digestifs légers.\"},\n{id:\"i017\",chapter:\"Anti-infectieux\",page:35,source:\"2022\",type:\"qcm\",difficulty:\"difficile\",\n question:\"Quelles classes d'antibiotiques sont particulièrement associées à un risque de photosensibilisation ?\",\n options:[\"Les macrolides et aminosides\",\"Les cyclines et quinolones\",\"Les pénicillines et céphalosporines\",\"Les sulfamides et carbapénèmes\"],\n correctAnswer:\"Les cyclines et quinolones\",\n explanation:\"Les cyclines et les quinolones sont susceptibles de provoquer des réactions de photosensibilisation ; il faut éviter l'exposition aux UV pendant le traitement. Les quinolones peuvent aussi causer des tendinites.\",\n simpleExplanation:\"Ces médicaments rendent la peau beaucoup plus sensible au soleil, un peu comme un coup de soleil qui arrive plus vite que d'habitude.\",\n memoryTip:\"Cyclines + Quinolones = attention au soleil.\",\n examTrap:\"Les quinolones ont un deuxième piège : le risque de tendinite, parfois nécessitant l'arrêt du traitement.\"},\n\n// Chapitre : Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\n{id:\"pec001\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:35,source:\"2022\",type:\"qcm\",difficulty:\"facile\",\n question:\"Pourquoi certaines pathologies comme le paludisme, le VIH, la tuberculose et la lèpre ont-elles une prescription encadrée par des directives mondiales ?\",\n options:[\"Parce que leurs médicaments sont très bon marché\",\"Parce qu'il s'agit de pandémies à forte mortalité et morbidité connues dans le monde entier\",\"Parce qu'elles ne touchent que les enfants\",\"Parce qu'elles n'ont pas de traitement efficace\"],\n correctAnswer:\"Parce qu'il s'agit de pandémies à forte mortalité et morbidité connues dans le monde entier\",\n explanation:\"Un certain nombre de pathologies ont leur prescription encadrée par des protocoles de prise en charge mondiale sécurisés, principalement des pandémies à mortalité et morbidité élevées.\",\n simpleExplanation:\"Pour des maladies qui touchent énormément de monde, on suit tous la même recette partout, pour être sûr de bien soigner tout le monde pareil.\",\n memoryTip:\"4 grandes directives mondiales : Paludisme, VIH, Tuberculose, Lèpre.\",\n examTrap:\"Ces protocoles sont mondiaux (OMS) mais adaptés ensuite par des directives nationales, comme en Côte d'Ivoire.\"},\n{id:\"pec002\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:36,source:\"2022\",type:\"qcd\",difficulty:\"moyen\",\n question:\"Quelles associations font partie des ACT (combinaisons thérapeutiques à base d'artémisinine) recommandées par l'OMS ?\",\n options:[\"Artéméther + luméfantrine\",\"Artésunate + amodiaquine\",\"Artésunate + sulfadoxine-pyriméthamine\",\"Chloroquine seule\"],\n correctAnswer:[\"Artéméther + luméfantrine\",\"Artésunate + amodiaquine\",\"Artésunate + sulfadoxine-pyriméthamine\"],\n explanation:\"L'OMS recommande actuellement : Artéméther+luméfantrine, Artésunate+amodiaquine, Artésunate+méfloquine, Artésunate+sulfadoxine-pyriméthamine.\",\n simpleExplanation:\"Ce sont des équipes de deux médicaments anti-paludisme qui travaillent ensemble, la base étant toujours l'artémisinine.\",\n memoryTip:\"ACT = toujours un dérivé de l'Artémisinine + un partenaire.\",\n examTrap:\"La chloroquine seule n'est plus une ACT recommandée en 1ère intention aujourd'hui, contrairement à il y a plusieurs décennies.\"},\n{id:\"pec003\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:36,source:\"2022\",type:\"qcm\",difficulty:\"moyen\",\n question:\"À quelle classe d'antirétroviraux appartient la Zidovudine (RETROVIR) ?\",\n options:[\"Inhibiteurs nucléosidiques de la transcriptase inverse (INTI)\",\"Inhibiteurs non nucléosidiques de la transcriptase inverse (INNTI)\",\"Inhibiteurs de la protéase\",\"Inhibiteurs de l'intégrase\"],\n correctAnswer:\"Inhibiteurs nucléosidiques de la transcriptase inverse (INTI)\",\n explanation:\"La Zidovudine (ZDV-AZT/RETROVIR) fait partie des inhibiteurs nucléosidiques de la transcriptase inverse (INTI), avec la lamivudine, l'emtricitabine, le ténofovir.\",\n simpleExplanation:\"Ce médicament bloque un outil (la transcriptase inverse) dont le virus du VIH a besoin pour se copier dans nos cellules.\",\n memoryTip:\"AZT = premier antirétroviral historique, un INTI.\",\n examTrap:\"Ne pas confondre avec l'Efavirenz (SUSTIVA), qui est un INNTI, une classe différente.\"},\n{id:\"pec004\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:37,source:\"2022\",type:\"qcd\",difficulty:\"difficile\",\n question:\"Quelles sont, parmi les classes suivantes, de vraies classes d'antirétroviraux citées dans le cours ?\",\n options:[\"Inhibiteurs de l'intégrase\",\"Inhibiteurs d'entrée (CCR5)\",\"Inhibiteurs de la fusion\",\"Inhibiteurs de la cyclo-oxygénase\"],\n correctAnswer:[\"Inhibiteurs de l'intégrase\",\"Inhibiteurs d'entrée (CCR5)\",\"Inhibiteurs de la fusion\"],\n explanation:\"Classes d'ARV : INTI, INNTI, inhibiteurs de la protéase, inhibiteurs de l'intégrase (Raltégravir), inhibiteurs d'entrée CCR5 (Maraviroc), inhibiteurs de la fusion (Enfuvirtide), inhibiteurs de maturation.\",\n simpleExplanation:\"Le virus du VIH a plusieurs étapes pour infecter une cellule ; chaque classe de médicament bloque une étape différente de ce parcours.\",\n memoryTip:\"VIH = plusieurs portes d'entrée, plusieurs classes de bloqueurs.\",\n examTrap:\"L'inhibition de la cyclo-oxygénase est le mécanisme des antipyrétiques/AINS, rien à voir avec le VIH.\"},\n{id:\"pec005\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:37,source:\"2022\",type:\"qcd\",difficulty:\"moyen\",\n question:\"Quels médicaments antituberculeux sont classés comme bactéricides selon le cours ?\",\n options:[\"Isoniazide (RIMIFON)\",\"Rifampicine (RIFADINE)\",\"Ethambutol (MYAMBUTOL)\",\"Pyrazinamide (PIRILENE)\"],\n correctAnswer:[\"Isoniazide (RIMIFON)\",\"Rifampicine (RIFADINE)\",\"Pyrazinamide (PIRILENE)\"],\n explanation:\"Sont bactéricides : Isoniazide (RIMIFON), Rifampicine (RIFADINE-RIMACTAN), Pyrazinamide (PIRILENE), Streptomycine. L'Ethambutol et la Rifabutine sont bactériostatiques.\",\n simpleExplanation:\"Trois des médicaments antituberculeux de base tuent directement le bacille, un seul se contente de l'empêcher de se multiplier.\",\n memoryTip:\"Bactéricides TB : Isoniazide, Rifampicine, Pyrazinamide, Streptomycine (I-R-P-S).\",\n examTrap:\"L'Ethambutol (MYAMBUTOL) est bactériostatique, pas bactéricide : piège classique.\"},\n{id:\"pec006\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:37,source:\"2022\",type:\"libre\",difficulty:\"moyen\",\n question:\"Citez deux médicaments utilisés dans le traitement de la lèpre selon le cours.\",\n keywords:[\"dapsone\",\"disulone\",\"clofazimine\",\"lamprene\",\"rifampicine\",\"sulfadoxine\",\"thalidomide\"],\n explanation:\"Médicaments antilépreux : Dapsone/sulfone-mère/DDS (DISULONE), Acédapsone/DADDS (HANSOLAR), Clofazimine (LAMPRENE), Rifampicine, Sulfadoxine, Thalidomide (THALIDOMIDE CELGENE).\",\n simpleExplanation:\"Plusieurs médicaments différents sont combinés pour venir à bout de la bactérie responsable de la lèpre.\",\n memoryTip:\"Lèpre = Dapsone + Clofazimine + Rifampicine en tête de liste.\",\n examTrap:\"La Rifampicine sert à la fois pour la tuberculose ET pour la lèpre, ne pas l'oublier dans les deux chapitres.\"},\n\n// Chapitre : Antidiabétiques\n{id:\"ad001\",chapter:\"Antidiabétiques\",page:59,source:\"2022\",type:\"qcm\",difficulty:\"facile\",\n question:\"Comment définit-on le diabète sur le plan biologique selon le cours ?\",\n options:[\"Une hypoglycémie chronique\",\"Une hyperglycémie chronique mise en évidence par au moins deux glycémies à jeun > 7 mmol/L\",\"Une glycémie ponctuelle élevée après un repas très sucré\",\"Une carence en glucagon uniquement\"],\n correctAnswer:\"Une hyperglycémie chronique mise en évidence par au moins deux glycémies à jeun > 7 mmol/L\",\n explanation:\"Le diabète se définit par une hyperglycémie chronique, mise en évidence par au moins deux glycémies à jeun > 7 mmol/L (>1,26 g/L), résultant d'une carence en insuline.\",\n simpleExplanation:\"Le sucre reste trop élevé dans le sang de façon durable, même à jeun, et ce n'est pas juste après un bon repas.\",\n memoryTip:\"Diabète = glycémie à jeun > 1,26 g/L, deux fois de suite.\",\n examTrap:\"Une seule glycémie élevée ne suffit pas au diagnostic : il en faut deux, à jeun.\"},\n{id:\"ad002\",chapter:\"Antidiabétiques\",page:59,source:\"2022\",type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel mécanisme est en cause dans le diabète de type 1 ?\",\n options:[\"Résistance périphérique à l'insuline\",\"Destruction des cellules bêta pancréatiques qui n'assurent plus la sécrétion d'insuline\",\"Excès de sécrétion de glucagon\",\"Consommation excessive de sucre uniquement\"],\n correctAnswer:\"Destruction des cellules bêta pancréatiques qui n'assurent plus la sécrétion d'insuline\",\n explanation:\"Dans le diabète de type 1, la destruction des cellules bêta pancréatiques empêche la sécrétion d'insuline. Le diabète de type 2, lui, résulte d'une résistance à l'insuline avec hypersécrétion compensatrice insuffisante.\",\n simpleExplanation:\"Dans le type 1, l'usine à insuline (le pancréas) est cassée. Dans le type 2, l'usine tourne mais le corps n'écoute plus bien le message.\",\n memoryTip:\"Type 1 = plus d'usine. Type 2 = usine ignorée (résistance).\",\n examTrap:\"Le diabète de type 1 nécessite une substitution en insuline d'emblée, contrairement au type 2 qui commence par la metformine.\"},\n{id:\"ad003\",chapter:\"Antidiabétiques\",page:60,source:\"2022\",type:\"qcm\",difficulty:\"facile\",\n question:\"Quelle classe d'antidiabétiques oraux est utilisée en première intention dans le diabète de type 2 ?\",\n options:[\"Les sulfamides hypoglycémiants\",\"Les biguanides (metformine)\",\"Les inhibiteurs de la DPP4\",\"L'insuline injectable\"],\n correctAnswer:\"Les biguanides (metformine)\",\n explanation:\"Dans un premier temps (insulinorésistance), ce sont les biguanides (metformine, GLUCOPHAGE) qu'il faut employer dans le diabète de type 2.\",\n simpleExplanation:\"La metformine est le premier médicament qu'on essaie, avant d'en ajouter d'autres si besoin.\",\n memoryTip:\"GLUCOPHAGE = 1er choix du diabète de type 2.\",\n examTrap:\"Ne pas confondre 1ère intention (biguanides) et dernier recours (insuline), qui n'arrive qu'après échec de la bi/trithérapie orale.\"},\n{id:\"ad004\",chapter:\"Antidiabétiques\",page:60,source:\"2022\",type:\"qcd\",difficulty:\"difficile\",\n question:\"Quelles classes d'antidiabétiques oraux sont des insulino-sécréteurs (stimulent la sécrétion d'insuline) ?\",\n options:[\"Les sulfamides hypoglycémiants\",\"Les glinides\",\"Les biguanides\",\"Les incrétino-mimétiques (analogues GLP-1, inhibiteurs DPP4)\"],\n correctAnswer:[\"Les sulfamides hypoglycémiants\",\"Les glinides\",\"Les incrétino-mimétiques (analogues GLP-1, inhibiteurs DPP4)\"],\n explanation:\"Les insulino-sécréteurs comprennent les sulfamides hypoglycémiants (Glibenclamide, Gliclazide...), les glinides (Repaglinide) et les incrétino-mimétiques (Exénatide, Sitagliptine...). Les biguanides sont des insulino-sensibilisateurs, pas des sécréteurs.\",\n simpleExplanation:\"Ces médicaments donnent un petit coup de fouet au pancréas pour qu'il libère plus d'insuline.\",\n memoryTip:\"Sécréteurs = font sortir plus d'insuline. Sensibilisateurs (biguanides) = rendent le corps plus réceptif à l'insuline déjà là.\",\n examTrap:\"La Metformine (biguanide) est un insulino-sensibilisateur, elle ne stimule pas la sécrétion d'insuline.\"},\n{id:\"ad005\",chapter:\"Antidiabétiques\",page:61,source:\"2022\",type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel est le mécanisme des inhibiteurs des alpha-glucosidases comme l'Acarbose ?\",\n options:[\"Ils stimulent le pancréas à sécréter de l'insuline\",\"Ils inhibent l'absorption intestinale des glucides\",\"Ils bloquent la réabsorption rénale du glucose\",\"Ils remplacent directement l'insuline\"],\n correctAnswer:\"Ils inhibent l'absorption intestinale des glucides\",\n explanation:\"Les inhibiteurs des alpha-glucosidases (Acarbose, Miglitol) sont des inhibiteurs de l'absorption des glucides au niveau intestinal.\",\n simpleExplanation:\"Ce médicament ralentit la digestion des sucres dans l'intestin pour que le sucre ne monte pas trop vite dans le sang.\",\n memoryTip:\"Acarbose = freine l'absorption du sucre dans l'intestin.\",\n examTrap:\"Ne pas confondre avec les inhibiteurs de la DPP4 (Sitagliptine), qui agissent sur les hormones incrétines, pas sur l'absorption intestinale.\"},\n\n// Chapitre : Antiseptiques, désinfectants & détergents\n{id:\"as001\",chapter:\"Antiseptiques, désinfectants & détergents\",page:91,source:\"2022\",type:\"qcm\",difficulty:\"facile\",\n question:\"Quelle est la différence essentielle entre un détergent et un antiseptique ?\",\n options:[\"Il n'y a aucune différence\",\"Le détergent enlève les salissures mais ne tue pas les microbes, contrairement à l'antiseptique\",\"Le détergent tue les microbes, pas l'antiseptique\",\"Le détergent s'utilise uniquement sur le matériel inerte\"],\n correctAnswer:\"Le détergent enlève les salissures mais ne tue pas les microbes, contrairement à l'antiseptique\",\n explanation:\"Un détergent enlève les salissures et graisses (matériel inerte et tissus vivants) mais ne tue pas les microbes. Un antiseptique, lui, élimine ou empêche le développement des micro-organismes sur les tissus vivants.\",\n simpleExplanation:\"Le détergent nettoie juste la saleté, comme un savon simple. L'antiseptique, en plus de nettoyer, tue les microbes.\",\n memoryTip:\"Détergent = nettoie. Antiseptique = nettoie ET désinfecte le vivant.\",\n examTrap:\"Un détergent peut être utilisé sur du matériel ET des tissus vivants, mais sans jamais tuer les microbes.\"},\n{id:\"as002\",chapter:\"Antiseptiques, désinfectants & détergents\",page:92,source:\"2022\",type:\"qcm\",difficulty:\"moyen\",\n question:\"Quelle est la différence entre antisepsie et asepsie ?\",\n options:[\"Ce sont des synonymes stricts\",\"L'antisepsie élimine les microbes déjà présents sur un tissu vivant, l'asepsie prévient tout apport de microbes\",\"L'asepsie ne concerne que les tissus vivants\",\"L'antisepsie ne concerne que le matériel inerte\"],\n correctAnswer:\"L'antisepsie élimine les microbes déjà présents sur un tissu vivant, l'asepsie prévient tout apport de microbes\",\n explanation:\"L'antisepsie est l'opération permettant d'éliminer les micro-organismes sur les tissus vivants. L'asepsie est une méthode préventive visant à empêcher tout apport exogène de micro-organisme (ex : stérilisation du matériel opératoire).\",\n simpleExplanation:\"L'antisepsie nettoie ce qui est déjà là. L'asepsie empêche que quelque chose de sale n'arrive du tout, comme fermer la porte avant que la saleté n'entre.\",\n memoryTip:\"ASepsie = Avant (prévention). ANTIsepsie = Après (élimination).\",\n examTrap:\"La désinfection, elle, s'applique aux milieux ou matières inertes, pas aux tissus vivants (c'est le rôle de l'antisepsie).\"},\n{id:\"as003\",chapter:\"Antiseptiques, désinfectants & détergents\",page:93,source:\"2022\",type:\"qcm\",difficulty:\"moyen\",\n question:\"Comment doit-on conserver l'eau de javel selon le cours ?\",\n options:[\"Dans un emballage transparent, à la lumière\",\"Dans un emballage opaque, en évitant de la mélanger au détergent\",\"Mélangée systématiquement à un détergent pour renforcer son action\",\"À température ambiante dans une bouteille en verre transparent\"],\n correctAnswer:\"Dans un emballage opaque, en évitant de la mélanger au détergent\",\n explanation:\"L'eau de javel doit être conservée dans un emballage opaque et ne doit pas être mélangée au détergent.\",\n simpleExplanation:\"La javel n'aime pas la lumière (elle se dégrade) et n'aime pas être mélangée à d'autres produits nettoyants.\",\n memoryTip:\"Javel = emballage opaque, jamais mélangée au détergent.\",\n examTrap:\"La javel peut aussi servir d'antiseptique, mais uniquement à des degrés inférieurs à 5°chl.\"},\n{id:\"as004\",chapter:\"Antiseptiques, désinfectants & détergents\",page:93,source:\"2022\",type:\"qcm\",difficulty:\"facile\",\n question:\"À quelle famille d'antiseptiques appartient la chlorhexidine ?\",\n options:[\"Les colorants\",\"Les biguanides\",\"Les dérivés iodés\",\"Les oxydants\"],correctAnswer:\"Les biguanides\",\n explanation:\"La chlorhexidine appartient à la famille des biguanides, un antiseptique à large spectre d'action, actif même à très faible concentration, rémanent et cumulatif.\",\n simpleExplanation:\"La chlorhexidine continue d'agir longtemps après application, contrairement à d'autres antiseptiques qui agissent puis s'arrêtent vite.\",\n memoryTip:\"Chlorhexidine = biguanide, effet rémanent et cumulatif.\",\n examTrap:\"Ne pas confondre avec la povidone iodée, qui appartient aux dérivés iodés, une famille différente.\"},\n{id:\"as005\",chapter:\"Antiseptiques, désinfectants & détergents\",page:94,source:\"2022\",type:\"qcm\",difficulty:\"moyen\",\n question:\"Pourquoi le nettoyage à l'eau oxygénée doit-il être bref et réservé aux plaies sans hémorragie active ?\",\n options:[\"Parce qu'elle est très chère\",\"Parce qu'elle dégrade les cellules et nuit à la cicatrisation en dehors de son usage hémostatique\",\"Parce qu'elle tache les vêtements\",\"Parce qu'elle n'a aucune action sur les microbes\"],\n correctAnswer:\"Parce qu'elle dégrade les cellules et nuit à la cicatrisation en dehors de son usage hémostatique\",\n explanation:\"L'eau oxygénée est surtout hémostatique ; son usage doit être bref et réservé aux situations avec présence de sang, car elle dégrade les cellules et nuit à la cicatrisation.\",\n simpleExplanation:\"L'eau oxygénée est surtout utile pour arrêter un petit saignement, mais utilisée trop souvent, elle abîme la peau qui essaie de guérir.\",\n memoryTip:\"Eau oxygénée = hémostatique avant tout, pas un nettoyant de plaie au quotidien.\",\n examTrap:\"Un usage prolongé ou répété de l'eau oxygénée peut ralentir la cicatrisation, contrairement à l'idée reçue qu'elle 'nettoie bien'.\"},\n{id:\"as006\",chapter:\"Antiseptiques, désinfectants & détergents\",page:94,source:\"2022\",type:\"qcd\",difficulty:\"moyen\",\n question:\"Quelles sont les propriétés microbiologiques des solutions hydro-alcooliques (SHA) selon le cours ?\",\n options:[\"Bactéricides\",\"Virucides\",\"Fongicides\",\"Nettoyantes (effet détergent puissant)\"],\n correctAnswer:[\"Bactéricides\",\"Virucides\",\"Fongicides\"],\n explanation:\"Les solutions hydro-alcooliques ont des propriétés bactéricides, virucides et fongicides, mais sans effet nettoyant : elles doivent être appliquées sur des mains sèches et non souillées.\",\n simpleExplanation:\"Les SHA tuent les microbes mais ne nettoient pas la saleté visible, c'est pour ça qu'il faut des mains déjà propres avant de les utiliser.\",\n memoryTip:\"SHA = tue les microbes mais ne lave pas la saleté.\",\n examTrap:\"Les SHA sont contre-indiquées sur des mains mouillées, souillées, lésées ou gantées.\"},\n{id:\"as007\",chapter:\"Antiseptiques, désinfectants & détergents\",page:95,source:\"2022\",type:\"qcm\",difficulty:\"facile\",\n question:\"Quelle est la durée de contact minimale recommandée pour une friction hydro-alcoolique efficace ?\",\n options:[\"1 à 2 secondes\",\"Dix à quinze secondes\",\"Cinq minutes\",\"Une heure\"],correctAnswer:\"Dix à quinze secondes\",\n explanation:\"Pour une efficacité optimale, le temps de contact doit être au minimum de dix à quinze secondes ; la durée totale de la procédure est en moyenne de trente secondes.\",\n simpleExplanation:\"Il faut frotter ses mains avec la solution pendant au moins 10 à 15 secondes pour que ça marche vraiment.\",\n memoryTip:\"SHA = 10-15 secondes minimum, 30 secondes en tout.\",\n examTrap:\"C'est plus rapide que le lavage antiseptique classique, qui dure environ deux minutes.\"},\n{id:\"as008\",chapter:\"Antiseptiques, désinfectants & détergents\",page:96,source:\"2022\",type:\"qcd\",difficulty:\"difficile\",\n question:\"Dans quelles situations l'usage des solutions hydro-alcooliques est-il contre-indiqué ?\",\n options:[\"Sur des mains mouillées\",\"Sur des mains souillées par du sang ou des sécrétions\",\"Sur des mains lésées ou des muqueuses\",\"Sur des mains propres et sèches avant un soin\"],\n correctAnswer:[\"Sur des mains mouillées\",\"Sur des mains souillées par du sang ou des sécrétions\",\"Sur des mains lésées ou des muqueuses\"],\n explanation:\"Les SHA sont contre-indiquées sur mains mouillées, souillées (sang, sécrétions), talquées, lésées, sur les muqueuses, sur mains gantées, et pour la désinfection cutanée pré-interventionnelle ou de surfaces inertes.\",\n simpleExplanation:\"Les solutions hydro-alcooliques ont besoin de mains déjà propres et sèches pour bien agir ; sur une peau abîmée ou mouillée, elles ne fonctionnent pas bien et peuvent irriter.\",\n memoryTip:\"SHA = seulement sur mains propres, sèches et intactes.\",\n examTrap:\"Sur des mains propres et sèches, c'est au contraire l'usage normal et recommandé, pas une contre-indication.\"},\n\n// Compléments respiratoire / antihistaminiques (renforcement)\n{id:\"r005\",chapter:\"Appareil respiratoire\",page:51,type:\"qcm\",difficulty:\"moyen\",\n question:\"Quel est le mode d'action des expectorants/mucolytiques comme l'Acétylcystéine (EXOMUC) ?\",\n options:[\"Diminution de la viscosité du mucus bronchique\",\"Blocage du réflexe de toux au niveau cérébral\",\"Bronchodilatation par relâchement musculaire\",\"Blocage des récepteurs à l'histamine\"],\n correctAnswer:\"Diminution de la viscosité du mucus bronchique\",\n explanation:\"Les expectorants et mucolytiques (Acétylcystéine, Carbocistéine, Ambroxol) agissent par diminution de la viscosité du mucus bronchique, facilitant son évacuation par la toux.\",\n simpleExplanation:\"Ce médicament rend le mucus plus liquide, plus facile à cracher, comme fluidifier un sirop trop épais.\",\n memoryTip:\"Mucolytique = rend le mucus moins collant.\",\n examTrap:\"Contre-indiqué en cas d'impossibilité de tousser et de cracher, car il existe un risque d'inondation bronchique.\"},\n{id:\"h003\",chapter:\"Antihistaminiques\",page:55,type:\"qcd\",difficulty:\"moyen\",\n question:\"Parmi les indications suivantes, lesquelles sont citées pour les antihistaminiques anti-H1 ?\",\n options:[\"Rhinite allergique\",\"Urticaire\",\"Conjonctivite allergique\",\"Hypertension artérielle\"],\n correctAnswer:[\"Rhinite allergique\",\"Urticaire\",\"Conjonctivite allergique\"],\n explanation:\"Les antihistaminiques anti-H1 sont indiqués dans les états allergiques : rhinite allergique, conjonctivite allergique, dermatite de contact, urticaire/prurit, réactions anaphylactiques ou anaphylactoïdes.\",\n simpleExplanation:\"Ces médicaments traitent toutes les manifestations allergiques classiques : nez qui coule, yeux qui piquent, peau qui gratte.\",\n memoryTip:\"Anti-H1 = toutes les allergies (nez, yeux, peau).\",\n examTrap:\"Ils n'ont aucune indication dans l'hypertension artérielle, qui relève d'une toute autre classe pharmacologique.\"},\n];\n\n/* =========================================================\n   MEDICAMENTS PAR GROUPE (référence rapide, DCI -> noms commerciaux)\n   ========================================================= */\nconst Q_EXTRA = [\n{\n\"id\": \"ng001\",\n\"chapter\": \"Généralités\",\n\"page\": 6,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"D'où vient le mot « pharmacie » ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Du grec pharmakôn : drogue, venin ou poison\",\n\"Du latin pharma : plante\",\n\"De l'arabe : guérisseur\",\n\"Du grec pharos : lumière\"\n],\n\"correctAnswer\": \"Du grec pharmakôn : drogue, venin ou poison\",\n\"explanation\": \"Pharmacie vient du grec φάρμακον (pharmakôn) qui signifie à la fois drogue, venin ou poison : la frontière entre remède et poison, c'est la dose.\",\n\"simpleExplanation\": \"Le même mot grec veut dire « remède » et « poison » : trop de médicament devient un poison !\",\n\"memoryTip\": \"Pharmakôn = remède ET poison ☠️💊\",\n\"examTrap\": \"Ne pas inventer une origine latine.\"\n},\n{\n\"id\": \"ng002\",\n\"chapter\": \"Généralités\",\n\"page\": 7,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des spécialisations possibles du pharmacien citées dans le cours ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Pharmacie hospitalière\",\n\"Pharmacie industrielle\",\n\"Radio pharmacie\",\n\"Pharmacie chirurgicale\"\n],\n\"correctAnswer\": [\n\"Pharmacie hospitalière\",\n\"Pharmacie industrielle\",\n\"Radio pharmacie\"\n],\n\"explanation\": \"Le cours cite : officinale, industrielle, hospitalière, des collectivités, clinique, humanitaire, militaire, vétérinaire, radio pharmacie.\",\n\"simpleExplanation\": \"Le pharmacien peut travailler à l'hôpital, à l'usine, à l'armée ou même avec les animaux.\",\n\"memoryTip\": \"OIH-CCH-MVR : Officine, Industrie, Hôpital, Collectivités, Clinique, Humanitaire, Militaire, Vétérinaire, Radio.\",\n\"examTrap\": \"« Pharmacie chirurgicale » n'existe pas dans la liste.\"\n},\n{\n\"id\": \"ng003\",\n\"chapter\": \"Généralités\",\n\"page\": 7,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle discipline pharmaceutique étudie l'art de présenter et conserver les médicaments ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"La galénique\",\n\"La pharmacognosie\",\n\"La toxicologie\",\n\"La biopharmacie\"\n],\n\"correctAnswer\": \"La galénique\",\n\"explanation\": \"La galénique est la science et l'art de conserver et présenter les médicaments de la façon la plus adaptée à leur mode d'administration (dosage précis, stabilité, observance).\",\n\"simpleExplanation\": \"La galénique, c'est le « styliste » du médicament : il choisit s'il sera comprimé, sirop ou pommade.\",\n\"memoryTip\": \"Galénique = Galien = forme du médicament 💊\",\n\"examTrap\": \"La pharmacognosie étudie les substances d'origine naturelle (plantes).\"\n},\n{\n\"id\": \"ng004\",\n\"chapter\": \"Généralités\",\n\"page\": 7,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Selon la définition légale, lesquels sont assimilés à des médicaments ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Produits d'hygiène contenant des substances vénéneuses au-delà des doses fixées par arrêté\",\n\"Produits diététiques renfermant des substances non alimentaires conférant des propriétés sur la santé\",\n\"Tous les produits cosmétiques sans exception\",\n\"Toutes les tisanes alimentaires\"\n],\n\"correctAnswer\": [\n\"Produits d'hygiène contenant des substances vénéneuses au-delà des doses fixées par arrêté\",\n\"Produits diététiques renfermant des substances non alimentaires conférant des propriétés sur la santé\"\n],\n\"explanation\": \"Sont assimilés aux médicaments : les produits d'hygiène/cosmétiques contenant des substances vénéneuses au-delà des seuils, et les produits diététiques contenant des substances non alimentaires à propriétés sur la santé.\",\n\"simpleExplanation\": \"Un shampoing devient « médicament » s'il contient un produit dangereux en grande quantité.\",\n\"memoryTip\": \"Assimilés = Hygiène vénéneuse + Diététique non alimentaire.\",\n\"examTrap\": \"Pas TOUS les cosmétiques : seulement au-delà des seuils.\"\n},\n{\n\"id\": \"ng005\",\n\"chapter\": \"Généralités\",\n\"page\": 9,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Où se fait l'injection intramusculaire selon le cours ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Quadrant supéro-externe de la fesse ou deltoïde\",\n\"Quadrant inféro-interne de la fesse\",\n\"Face antérieure de l'avant-bras\",\n\"Paroi abdominale uniquement\"\n],\n\"correctAnswer\": \"Quadrant supéro-externe de la fesse ou deltoïde\",\n\"explanation\": \"L'IM se fait dans le quadrant supéro-externe de la fesse ou dans le muscle deltoïde ; médicaments en solution aqueuse ou suspension huileuse ; effet retardé et progressif.\",\n\"simpleExplanation\": \"On pique en haut et sur le côté de la fesse pour éviter le gros nerf sciatique.\",\n\"memoryTip\": \"IM = Supéro-Externe 🎯 (SE = Sans Erreur sur le sciatique).\",\n\"examTrap\": \"L'abdomen est un site de la voie sous-cutanée.\"\n},\n{\n\"id\": \"ng006\",\n\"chapter\": \"Généralités\",\n\"page\": 9,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quel est l'inconvénient de la voie parentérale par rapport à la voie orale concernant la dose ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Risque de surdosage plus important\",\n\"Destruction par les sucs digestifs\",\n\"Passage obligatoire par le foie\",\n\"Effet toujours plus lent\"\n],\n\"correctAnswer\": \"Risque de surdosage plus important\",\n\"explanation\": \"Inconvénients de la voie parentérale : administration par infirmier/médecin (sauf insuline), risque de surdosage plus important, douleur, risques infectieux.\",\n\"simpleExplanation\": \"Le médicament injecté arrive directement dans le sang : une erreur de dose ne peut plus être rattrapée.\",\n\"memoryTip\": \"Injection = pas de retour en arrière ⚠️\",\n\"examTrap\": \"La destruction par les sucs digestifs concerne la voie orale.\"\n},\n{\n\"id\": \"ng007\",\n\"chapter\": \"Généralités\",\n\"page\": 9,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quelle est la caractéristique de la voie sublinguale ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Passage direct dans la circulation sans passer par le foie, action rapide\",\n\"Effet retardé et progressif\",\n\"Action uniquement locale sur la langue\",\n\"Absorption au niveau de l'intestin\"\n],\n\"correctAnswer\": \"Passage direct dans la circulation sans passer par le foie, action rapide\",\n\"explanation\": \"Sublinguale : le médicament fond sous la langue, pénètre directement dans la circulation sans passer par le foie : action rapide.\",\n\"simpleExplanation\": \"Sous la langue, il y a plein de petits vaisseaux : le médicament prend un raccourci vers le sang.\",\n\"memoryTip\": \"Sub-linguale = Super rapide ⚡\",\n\"examTrap\": \"Ne pas confondre avec la voie orale (passage hépatique).\"\n},\n{\n\"id\": \"ng008\",\n\"chapter\": \"Généralités\",\n\"page\": 10,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est l'avantage commun des voies transmuqueuses ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Éviter l'acidité gastrique et l'effet de premier passage hépatique\",\n\"Supprimer tout risque d'irritation\",\n\"Permettre des doses plus élevées\",\n\"Être toujours bien acceptées par l'enfant\"\n],\n\"correctAnswer\": \"Éviter l'acidité gastrique et l'effet de premier passage hépatique\",\n\"explanation\": \"Les voies transmuqueuses évitent l'acidité et les protéases gastriques, l'effet de premier passage hépatique et le métabolisme intestinal. Inconvénients : irritation/ulcération, désagrément, réflexe de rejet du suppositoire chez l'enfant.\",\n\"simpleExplanation\": \"Le médicament évite l'estomac et le foie, qui sont comme des douaniers qui le fouillent.\",\n\"memoryTip\": \"Transmuqueuse = pas d'estomac, pas de foie.\",\n\"examTrap\": \"Le rejet du suppositoire chez l'enfant est un INCONVÉNIENT.\"\n},\n{\n\"id\": \"ng009\",\n\"chapter\": \"Généralités\",\n\"page\": 11,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Pourquoi une gélule doit-elle toujours être avalée avec de l'eau ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Elle risque de se coller dans l'œsophage\",\n\"L'eau active le principe actif\",\n\"Elle est toujours effervescente\",\n\"Pour éviter le passage hépatique\"\n],\n\"correctAnswer\": \"Elle risque de se coller dans l'œsophage\",\n\"explanation\": \"La gélule (deux enveloppes de gélatine emboîtées contenant une poudre) doit être avalée avec de l'eau, sinon elle risque de se coller dans l'œsophage.\",\n\"simpleExplanation\": \"La gélatine colle comme un bonbon mou si on l'avale sans boire.\",\n\"memoryTip\": \"Gélule + Gorgée d'eau 💧\",\n\"examTrap\": \"Certaines gélules à microgranules libèrent le PA sur 12 à 24 h.\"\n},\n{\n\"id\": \"ng010\",\n\"chapter\": \"Généralités\",\n\"page\": 11,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Au-delà de quelle durée une potion ne doit-elle plus être utilisée ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Une semaine\",\n\"24 heures\",\n\"Un mois\",\n\"Trois mois\"\n],\n\"correctAnswer\": \"Une semaine\",\n\"explanation\": \"Les potions sont des préparations magistrales aqueuses et sucrées qui ne doivent pas être utilisées au-delà d'une semaine.\",\n\"simpleExplanation\": \"Comme un jus fait maison : il ne se garde pas longtemps.\",\n\"memoryTip\": \"Potion = 7 jours max 📅\",\n\"examTrap\": \"Ne pas confondre avec la validité d'une ordonnance (3 mois).\"\n},\n{\n\"id\": \"ng011\",\n\"chapter\": \"Généralités\",\n\"page\": 11,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Que faut-il toujours faire avant d'administrer une suspension buvable ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"L'agiter\",\n\"La chauffer\",\n\"La diluer dans du lait\",\n\"La filtrer\"\n],\n\"correctAnswer\": \"L'agiter\",\n\"explanation\": \"Dans une suspension, le PA n'est pas soluble dans l'eau : il faut toujours agiter avant emploi et mesurer avec le dispositif fourni.\",\n\"simpleExplanation\": \"Le médicament tombe au fond comme du sable : il faut secouer pour le remettre partout.\",\n\"memoryTip\": \"Suspension = Secouer 🔄\",\n\"examTrap\": \"Toujours utiliser la cuillère/seringue doseuse du conditionnement.\"\n},\n{\n\"id\": \"ng012\",\n\"chapter\": \"Généralités\",\n\"page\": 12,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Combien de formes injectables le cours décrit-il ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Cinq\",\n\"Trois\",\n\"Quatre\",\n\"Six\"\n],\n\"correctAnswer\": \"Cinq\",\n\"explanation\": \"5 formes injectables : préparations injectables, pour perfusion, à diluer, poudres pour préparations injectables, implants.\",\n\"simpleExplanation\": \"Cinq façons de préparer un médicament à piquer, comme les 5 doigts d'une main.\",\n\"memoryTip\": \"5 doigts = 5 injectables ✋\",\n\"examTrap\": \"Les implants font partie des formes injectables.\"\n},\n{\n\"id\": \"ng013\",\n\"chapter\": \"Généralités\",\n\"page\": 12,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle forme cutanée est décrite comme « non grasse et limpide » ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le gel\",\n\"La pommade\",\n\"La crème\",\n\"La pâte\"\n],\n\"correctAnswer\": \"Le gel\",\n\"explanation\": \"Pommades = grasses ; crèmes = moins grasses ; gels = non gras, limpides ; pâtes = faites à partir de poudres ; patch = dispositif transdermique.\",\n\"simpleExplanation\": \"Le gel est transparent comme de l'eau gélifiée.\",\n\"memoryTip\": \"Pommade > Crème > Gel (du plus gras au moins gras).\",\n\"examTrap\": \"La pommade est la forme la plus grasse.\"\n},\n{\n\"id\": \"ng014\",\n\"chapter\": \"Généralités\",\n\"page\": 13,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Qu'est-ce qu'un médicament magistral ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Un médicament préparé extemporanément à l'officine selon l'ordonnance, pour un seul malade\",\n\"Un médicament fabriqué par l'industrie sous un nom commercial\",\n\"Un produit conseil préparé à l'avance par le pharmacien\",\n\"Un produit naturel inscrit à la nomenclature nationale\"\n],\n\"correctAnswer\": \"Un médicament préparé extemporanément à l'officine selon l'ordonnance, pour un seul malade\",\n\"explanation\": \"Le médicament magistral est préparé extemporanément à l'officine, conformément à l'ordonnance qui en précise la formule détaillée ; il est destiné à un seul malade.\",\n\"simpleExplanation\": \"C'est un médicament « sur mesure », cousu pour un seul patient.\",\n\"memoryTip\": \"Magistral = Maître + Mesure (un seul patient) 🧑‍⚕️\",\n\"examTrap\": \"Le produit conseil = médicament spécialisé de l'officine.\"\n},\n{\n\"id\": \"ng015\",\n\"chapter\": \"Généralités\",\n\"page\": 13,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle est la définition d'un médicament homéopathique selon le cours ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Substance provoquant chez l'individu sain des symptômes retrouvés chez le malade\",\n\"Produit dont l'action chez l'homme sain provoque des phénomènes différents de ceux du malade\",\n\"Médicament préparé à l'avance par un laboratoire\",\n\"Produit naturel utilisé tel quel\"\n],\n\"correctAnswer\": \"Substance provoquant chez l'individu sain des symptômes retrouvés chez le malade\",\n\"explanation\": \"Homéopathique : provoque chez le sujet sain les mêmes symptômes que chez le malade. Allopathique : provoque des phénomènes morbides autres que ceux du malade (traitement habituel).\",\n\"simpleExplanation\": \"Homéo = « même » ; allo = « autre ».\",\n\"memoryTip\": \"HOMÉO = MÊME ; ALLO = AUTRE.\",\n\"examTrap\": \"L'allopathie est le traitement habituel des maladies.\"\n},\n{\n\"id\": \"ng016\",\n\"chapter\": \"Généralités\",\n\"page\": 14,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment appelle-t-on les « produits maison » ou « produits conseils » ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Les médicaments spécialisés de l'officine\",\n\"Les spécialités pharmaceutiques\",\n\"Les médicaments magistraux\",\n\"Les médicaments génériques\"\n],\n\"correctAnswer\": \"Les médicaments spécialisés de l'officine\",\n\"explanation\": \"Les médicaments spécialisés de l'officine (produits maison/conseils) sont préparés à l'avance dans l'officine selon une formule du pharmacien, pour sa clientèle, sans AMM.\",\n\"simpleExplanation\": \"Ce sont les « recettes maison » du pharmacien.\",\n\"memoryTip\": \"Produit Maison = Officine.\",\n\"examTrap\": \"Ils ne sont pas soumis à l'AMM.\"\n},\n{\n\"id\": \"ng017\",\n\"chapter\": \"Généralités\",\n\"page\": 15,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Pourquoi un générique peut-il être produit pendant la protection d'un princeps dans certains pays ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Par choix de politique de santé (ex : médicaments contre le SIDA)\",\n\"Parce que les génériques ne sont jamais soumis aux brevets\",\n\"Parce que le princeps est toujours plus dangereux\",\n\"Parce que l'OMS interdit les brevets\"\n],\n\"correctAnswer\": \"Par choix de politique de santé (ex : médicaments contre le SIDA)\",\n\"explanation\": \"Par des choix politiques de santé, une entorse peut être imposée sur des médicaments encore protégés, par exemple les médicaments contre le SIDA dans les pays en développement.\",\n\"simpleExplanation\": \"Pour sauver des vies, un pays peut autoriser des copies avant la fin du brevet.\",\n\"memoryTip\": \"Santé publique > brevet (SIDA).\",\n\"examTrap\": \"Normalement le générique arrive après expiration du brevet.\"\n},\n{\n\"id\": \"ng018\",\n\"chapter\": \"Généralités\",\n\"page\": 16,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des causes de survenue des effets indésirables citées dans le cours ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Automédication\",\n\"Médicament de contrefaçon\",\n\"Non observance\",\n\"Bonne dose bien respectée\"\n],\n\"correctAnswer\": [\n\"Automédication\",\n\"Médicament de contrefaçon\",\n\"Non observance\"\n],\n\"explanation\": \"Causes : mésusage, diagnostic erroné, erreur médicamenteuse, interaction, automédication, non observance, terrain (allergie), contrefaçon.\",\n\"simpleExplanation\": \"Se soigner tout seul ou acheter des faux médicaments au marché peut rendre malade.\",\n\"memoryTip\": \"AUTO-CONTRE-FAÇON = danger 🚫\",\n\"examTrap\": \"Respecter la bonne dose fait partie des conditions optimales, pas des causes.\"\n},\n{\n\"id\": \"ng019\",\n\"chapter\": \"Généralités\",\n\"page\": 16,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quelles sont les 3 conditions d'utilisation optimale des médicaments ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Médicament de qualité, bonne dose, respect des précautions d'usage\",\n\"Prix bas, goût agréable, forme orale\",\n\"Nom commercial, emballage, notice\",\n\"Prescription, automédication, conseil\"\n],\n\"correctAnswer\": \"Médicament de qualité, bonne dose, respect des précautions d'usage\",\n\"explanation\": \"Conditions optimales : médicament de qualité, la bonne dose, le respect des précautions d'usage.\",\n\"simpleExplanation\": \"Bon médicament + bonne quantité + bonnes règles = traitement réussi.\",\n\"memoryTip\": \"Q-D-P : Qualité, Dose, Précautions ✅\",\n\"examTrap\": \"L'automédication est une cause d'effet indésirable.\"\n},\n{\n\"id\": \"ng020\",\n\"chapter\": \"Généralités\",\n\"page\": 17,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle est la conduite à tenir face à un effet indésirable pharmacologique, l'arrêt définitif étant rare ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Diminuer la dose, doser le médicament dans le plasma pour ajuster\",\n\"Doubler la dose\",\n\"Changer immédiatement de voie d'administration\",\n\"Ajouter un second médicament de la même classe\"\n],\n\"correctAnswer\": \"Diminuer la dose, doser le médicament dans le plasma pour ajuster\",\n\"explanation\": \"CAT : diminution de la dose, dosage plasmatique pour ajustement posologique ; arrêt définitif du médicament : rare.\",\n\"simpleExplanation\": \"On baisse le volume avant d'éteindre la radio.\",\n\"memoryTip\": \"Baisser → Doser → (rarement) Arrêter.\",\n\"examTrap\": \"L'arrêt définitif n'est pas la réponse habituelle.\"\n},\n{\n\"id\": \"ng021\",\n\"chapter\": \"Généralités\",\n\"page\": 17,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des éléments OBLIGATOIRES d'une ordonnance ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Nom et prénom du patient\",\n\"Date de rédaction\",\n\"Signature du praticien\",\n\"Poids et taille du patient\"\n],\n\"correctAnswer\": [\n\"Nom et prénom du patient\",\n\"Date de rédaction\",\n\"Signature du praticien\"\n],\n\"explanation\": \"Obligatoires : nom/prénom du patient, identification du médecin, date, médicaments/actes, dosage, durée, renouvellements, signature. Âge, sexe, poids, taille sont facultatifs.\",\n\"simpleExplanation\": \"Sans nom, date ni signature, l'ordonnance ne vaut rien.\",\n\"memoryTip\": \"N-D-S : Nom, Date, Signature ✍️\",\n\"examTrap\": \"Poids et taille sont FACULTATIFS selon le cours.\"\n},\n{\n\"id\": \"ng022\",\n\"chapter\": \"Généralités\",\n\"page\": 18,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quelle est la durée maximale d'un traitement prescrit sur une ordonnance (hors exceptions) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Un an\",\n\"Trois mois\",\n\"Six mois\",\n\"Douze semaines\"\n],\n\"correctAnswer\": \"Un an\",\n\"explanation\": \"Validité de l'ordonnance pour se faire délivrer : 3 mois ; durée du traitement : 1 an maximum (anxiolytiques limités à 12 semaines). Le pharmacien délivre par période d'un mois.\",\n\"simpleExplanation\": \"On a 3 mois pour aller à la pharmacie, mais le traitement peut durer jusqu'à un an.\",\n\"memoryTip\": \"3 mois pour retirer, 1 an pour traiter, 12 semaines pour les anxiolytiques.\",\n\"examTrap\": \"Ne pas confondre validité (3 mois) et durée du traitement (1 an).\"\n},\n{\n\"id\": \"ng023\",\n\"chapter\": \"Généralités\",\n\"page\": 18,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le délai de validité d'une prescription d'actes médicaux (kiné, soins infirmiers, analyses) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Aucun délai de validité\",\n\"3 mois\",\n\"1 mois\",\n\"1 an\"\n],\n\"correctAnswer\": \"Aucun délai de validité\",\n\"explanation\": \"Il n'y a pas de délai pour les actes médicaux (kinésithérapie, soins infirmiers, orthophonie, analyses), mais il est conseillé de les réaliser rapidement.\",\n\"simpleExplanation\": \"Pour les soins, pas de date limite, mais mieux vaut ne pas traîner.\",\n\"memoryTip\": \"Actes = pas de chrono ⏱️❌\",\n\"examTrap\": \"Les 3 mois concernent la délivrance des médicaments.\"\n},\n{\n\"id\": \"ng024\",\n\"chapter\": \"Généralités\",\n\"page\": 8,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Définissez le médicament et citez ses deux composantes.\",\n\"type\": \"ouverte\",\n\"answer\": \"Toute substance ou composition présentée comme possédant des propriétés curatives ou préventives à l'égard des maladies humaines ou animales, ou administrée pour établir un diagnostic ou restaurer, corriger, modifier les fonctions organiques. Deux composantes : le principe actif (effet thérapeutique) et l'excipient (consistance, forme, goût, sans interaction avec le PA).\",\n\"keywords\": [\n\"curatives\",\n\"préventives\",\n\"diagnostic\",\n\"principe actif\",\n\"excipient\"\n],\n\"explanation\": \"Toute substance ou composition présentée comme possédant des propriétés curatives ou préventives à l'égard des maladies humaines ou animales, ou administrée pour établir un diagnostic ou restaurer, corriger, modifier les fonctions organiques. Deux composantes : le principe actif (effet thérapeutique) et l'excipient (consistance, forme, goût, sans interaction avec le PA).\",\n\"memoryTip\": \"🧪 PA = l'acteur ; Excipient = le costume.\"\n},\n{\n\"id\": \"ng025\",\n\"chapter\": \"Généralités\",\n\"page\": 9,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les avantages et les inconvénients de la voie parentérale.\",\n\"type\": \"ouverte\",\n\"answer\": \"Avantages : rapidité de l'effet (surtout IV), pas de destruction par les sucs digestifs, arrivée directe dans le sang sans passage hépatique initial. Inconvénients : administration par infirmier ou médecin (sauf insuline du diabétique), risque de surdosage plus important, douleur, risques infectieux.\",\n\"keywords\": [\n\"rapidité\",\n\"sucs digestifs\",\n\"foie\",\n\"surdosage\",\n\"douloureuse\",\n\"infectieux\"\n],\n\"explanation\": \"Avantages : rapidité de l'effet (surtout IV), pas de destruction par les sucs digestifs, arrivée directe dans le sang sans passage hépatique initial. Inconvénients : administration par infirmier ou médecin (sauf insuline du diabétique), risque de surdosage plus important, douleur, risques infectieux.\",\n\"memoryTip\": \"💉 Rapide mais Risquée : surdosage, douleur, infection.\"\n},\n{\n\"id\": \"ng026\",\n\"chapter\": \"Généralités\",\n\"page\": 11,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Citez les différents types de comprimés décrits dans le cours.\",\n\"type\": \"ouverte\",\n\"answer\": \"Comprimés non enrobés, comprimés enrobés et comprimés spéciaux : effervescents, à utiliser dans la cavité buccale, gastro-résistants, à couches multiples, à libération modifiée.\",\n\"keywords\": [\n\"non enrobés\",\n\"enrobés\",\n\"effervescents\",\n\"gastro-résistants\",\n\"couches multiples\",\n\"libération modifiée\"\n],\n\"explanation\": \"Comprimés non enrobés, comprimés enrobés et comprimés spéciaux : effervescents, à utiliser dans la cavité buccale, gastro-résistants, à couches multiples, à libération modifiée.\",\n\"memoryTip\": \"💊 N-E-S : Non enrobé, Enrobé, Spéciaux (Effervescent, Buccal, Gastro, Couches, LM).\"\n},\n{\n\"id\": \"ng027\",\n\"chapter\": \"Généralités\",\n\"page\": 16,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Selon l'OMS (2000), citez au moins 5 situations dont peut résulter un effet indésirable.\",\n\"type\": \"ouverte\",\n\"answer\": \"Mésusage, usage abusif, syndrome de sevrage, pharmacodépendance, erreur médicamenteuse, inefficacité thérapeutique, effet sur le produit de conception, produit défectueux ou de mauvaise qualité.\",\n\"keywords\": [\n\"mésusage\",\n\"abusif\",\n\"sevrage\",\n\"dépendance\",\n\"erreur\",\n\"inefficacité\",\n\"conception\",\n\"défectueux\"\n],\n\"explanation\": \"Mésusage, usage abusif, syndrome de sevrage, pharmacodépendance, erreur médicamenteuse, inefficacité thérapeutique, effet sur le produit de conception, produit défectueux ou de mauvaise qualité.\",\n\"memoryTip\": \"⚠️ OMS 2000 : MAS-PEI-CD (Mésusage, Abus, Sevrage, Pharmacodépendance, Erreur, Inefficacité, Conception, Défectueux).\"\n},\n{\n\"id\": \"ng028\",\n\"chapter\": \"Généralités\",\n\"page\": 17,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Qu'est-ce qu'un effet indésirable grave ? Donnez ses critères.\",\n\"type\": \"ouverte\",\n\"answer\": \"Effet indésirable à l'origine d'un décès, d'une menace pour la vie, d'une hospitalisation ou prolongation d'hospitalisation, de séquelles ou incapacité notable et durable, d'une anomalie congénitale ou atteinte périnatale.\",\n\"keywords\": [\n\"décès\",\n\"menace\",\n\"hospitalisation\",\n\"séquelles\",\n\"incapacité\",\n\"congénitale\"\n],\n\"explanation\": \"Effet indésirable à l'origine d'un décès, d'une menace pour la vie, d'une hospitalisation ou prolongation d'hospitalisation, de séquelles ou incapacité notable et durable, d'une anomalie congénitale ou atteinte périnatale.\",\n\"memoryTip\": \"🚨 Grave = DMHSC : Décès, Menace vitale, Hospitalisation, Séquelles, Congénital.\"\n},\n{\n\"id\": \"na001\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 19,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quelle est la différence entre antalgie et analgésie ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Antalgie = diminuer la douleur ; analgésie = l'abolir\",\n\"Antalgie = abolir la douleur ; analgésie = la diminuer\",\n\"Ce sont deux mots pour la fièvre\",\n\"Analgésie = perte de conscience\"\n],\n\"correctAnswer\": \"Antalgie = diminuer la douleur ; analgésie = l'abolir\",\n\"explanation\": \"Les médicaments de la douleur diminuent (antalgie) ou abolissent (analgésie) la douleur sans perte de conscience. En pratique les deux termes sont souvent synonymes.\",\n\"simpleExplanation\": \"Antalgie baisse le volume de la douleur ; analgésie l'éteint.\",\n\"memoryTip\": \"ANTalgie = ATténue ; ANAlgésie = ANnule.\",\n\"examTrap\": \"Aucun des deux n'entraîne de perte de conscience.\"\n},\n{\n\"id\": \"na002\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 19,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Selon la hiérarchie d'utilisation, que donne-t-on en 4e intention ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Antalgique central narcotique\",\n\"Antalgique périphérique\",\n\"Antalgique central non narcotique\",\n\"Association périphérique + central non narcotique\"\n],\n\"correctAnswer\": \"Antalgique central narcotique\",\n\"explanation\": \"1re : périphérique ; 2e : central non narcotique ; 3e : association périphérique + central non narcotique ; 4e : central narcotique.\",\n\"simpleExplanation\": \"On monte les marches de l'escalier de la douleur, la morphine est tout en haut.\",\n\"memoryTip\": \"1 Périph → 2 Central doux → 3 Duo → 4 Morphine 🪜\",\n\"examTrap\": \"La morphine ne vient jamais en première intention.\"\n},\n{\n\"id\": \"na003\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 20,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Pourquoi associe-t-on souvent codéine ou tramadol à un antalgique de palier 1 ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Leurs modes d'action sont différents et complémentaires : action synergique\",\n\"Pour diminuer le coût\",\n\"Pour supprimer les effets indésirables\",\n\"Parce qu'ils sont du même palier\"\n],\n\"correctAnswer\": \"Leurs modes d'action sont différents et complémentaires : action synergique\",\n\"explanation\": \"Codéine et tramadol sont associés au palier 1 car leurs modes d'action sont différents et complémentaires : l'action est synergique.\",\n\"simpleExplanation\": \"Deux joueurs qui attaquent par des côtés différents marquent plus.\",\n\"memoryTip\": \"Synergie : 1 + 1 > 2 ⚡\",\n\"examTrap\": \"Synergie ≠ addition simple.\"\n},\n{\n\"id\": \"na004\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 20,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"À partir de combien de comprimés de paracétamol 500 mg le cours signale-t-il un risque de cytolyse hépatique ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Plus de 18 comprimés\",\n\"Plus de 4 comprimés\",\n\"Plus de 8 comprimés\",\n\"Plus de 50 comprimés\"\n],\n\"correctAnswer\": \"Plus de 18 comprimés\",\n\"explanation\": \"Intoxication au paracétamol (> 18 comprimés de 500 mg) : risque de cytolyse hépatique irréversible. Antidote : acétylcystéine en IV.\",\n\"simpleExplanation\": \"Trop de paracétamol brûle le foie.\",\n\"memoryTip\": \"18 cp = 9 g = danger foie 🫀☠️\",\n\"examTrap\": \"L'antidote n'est pas la naloxone (antidote des morphiniques).\"\n},\n{\n\"id\": \"na005\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 20,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quel est l'antidote de l'intoxication au paracétamol ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"L'acétylcystéine en IV\",\n\"La vitamine K\",\n\"La naloxone\",\n\"Le charbon de bois seul\"\n],\n\"correctAnswer\": \"L'acétylcystéine en IV\",\n\"explanation\": \"L'antidote du paracétamol est l'acétylcystéine (N-acétylcystéine) en IV.\",\n\"simpleExplanation\": \"Le même produit qui fluidifie le mucus protège aussi le foie.\",\n\"memoryTip\": \"Paracétamol ↔ AcétylCystéine (2 « acét »).\",\n\"examTrap\": \"La vitamine K est l'antidote des AVK.\"\n},\n{\n\"id\": \"na006\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 20,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Chez l'enfant de moins de 16 ans avec varicelle ou syndrome grippal, quel antalgique/antipyrétique préférer ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le paracétamol\",\n\"L'aspirine\",\n\"La codéine\",\n\"Le tramadol\"\n],\n\"correctAnswer\": \"Le paracétamol\",\n\"explanation\": \"Le paracétamol est à préférer à l'aspirine chez l'enfant de moins de 16 ans dans les infections virales (varicelle, grippe).\",\n\"simpleExplanation\": \"Chez l'enfant malade d'un virus, on choisit le doux paracétamol plutôt que l'aspirine.\",\n\"memoryTip\": \"Virus + enfant = Paracétamol 🧒\",\n\"examTrap\": \"L'aspirine n'est utilisée qu'en 2e intention dans la fièvre.\"\n},\n{\n\"id\": \"na007\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 20,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des spécialités contenant du paracétamol ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"DOLIPRANE\",\n\"EFFERALGAN\",\n\"PANADOL\",\n\"ASPEGIC\"\n],\n\"correctAnswer\": [\n\"DOLIPRANE\",\n\"EFFERALGAN\",\n\"PANADOL\"\n],\n\"explanation\": \"Spécialités du paracétamol : DOLIPRANE, EFFERALGAN, DOLIMEX, CLARADOL, EFFADOL, PANADOL, DOLKO... ASPEGIC = aspirine.\",\n\"simpleExplanation\": \"Les noms en « DOLI- », « EFFER- », « PANA- » cachent du paracétamol.\",\n\"memoryTip\": \"DOLI-EFFER-PANA = Paracétamol.\",\n\"examTrap\": \"ASPEGIC et KARDEGIC sont de l'aspirine.\"\n},\n{\n\"id\": \"na008\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 21,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le nom commercial de la Floctafénine ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"IDARAC\",\n\"NOVALGINE\",\n\"ACUPAN\",\n\"TRAMADOL\"\n],\n\"correctAnswer\": \"IDARAC\",\n\"explanation\": \"Floctafénine (dérivé de l'amino-4-quinoléine) : IDARAC, pour les douleurs légères et modérées.\",\n\"simpleExplanation\": \"IDARAC = Idée pour la petite douleur.\",\n\"memoryTip\": \"Flocta → IDARAC.\",\n\"examTrap\": \"NOVALGINE = noramidopyrine ; ACUPAN = néfopam.\"\n},\n{\n\"id\": \"na009\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 21,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Le Néfopam (ACUPAN) est :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Un analgésique central non morphinique\",\n\"Un opioïde fort\",\n\"Un AINS\",\n\"Un antispasmodique musculotrope\"\n],\n\"correctAnswer\": \"Un analgésique central non morphinique\",\n\"explanation\": \"Le néfopam (ACUPAN) est un analgésique central non morphinique, indiqué dans les douleurs aiguës, notamment post-opératoires.\",\n\"simpleExplanation\": \"Il agit dans le cerveau sans être de la famille de la morphine.\",\n\"memoryTip\": \"Néfopam = Non morphinique.\",\n\"examTrap\": \"Ne pas le classer parmi les opioïdes.\"\n},\n{\n\"id\": \"na010\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 21,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"La codéine est contre-indiquée chez :\",\n\"type\": \"qcm\",\n\"options\": [\n\"L'enfant de moins de 12 ans\",\n\"La personne âgée de plus de 65 ans\",\n\"La femme ménopausée\",\n\"Le sportif\"\n],\n\"correctAnswer\": \"L'enfant de moins de 12 ans\",\n\"explanation\": \"La codéine (CODENFAN, DICODIN) est contre-indiquée chez l'enfant de moins de 12 ans.\",\n\"simpleExplanation\": \"La codéine est trop risquée pour les petits.\",\n\"memoryTip\": \"Codéine : pas avant 12 ans 🚸\",\n\"examTrap\": \"La dompéridone est aussi interdite avant 12 ans (ne pas confondre les contextes).\"\n},\n{\n\"id\": \"na011\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 22,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel opioïde fort se présente en patch (DUROGESIC) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le fentanyl\",\n\"La morphine\",\n\"Le tramadol\",\n\"La nalbuphine\"\n],\n\"correctAnswer\": \"Le fentanyl\",\n\"explanation\": \"Fentanyl : douleurs chroniques d'origine cancéreuse, stables ; spécialités DUROGESIC (patch), ACTIQ, ABSTRAL...\",\n\"simpleExplanation\": \"Le fentanyl peut se coller sur la peau comme un pansement.\",\n\"memoryTip\": \"DUROGESIC = Dur et Durable (patch) 🩹\",\n\"examTrap\": \"SKENAN/ACTISKENAN = morphine.\"\n},\n{\n\"id\": \"na012\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 22,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des spécialités à base de morphine ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"ACTISKENAN\",\n\"SKENAN LP\",\n\"MOSCONTIN LP\",\n\"PALEXIA LP\"\n],\n\"correctAnswer\": [\n\"ACTISKENAN\",\n\"SKENAN LP\",\n\"MOSCONTIN LP\"\n],\n\"explanation\": \"Morphine : ACTISKENAN, ORAMORPH, SEVREDOL, MOSCONTIN LP, SKENAN LP. PALEXIA LP = tapentadol.\",\n\"simpleExplanation\": \"Les noms en « -SKENAN » et « MOS- » contiennent de la morphine.\",\n\"memoryTip\": \"SKENAN = morphine ; ORAMORPH = ORAl MORPHine.\",\n\"examTrap\": \"PALEXIA est le tapentadol.\"\n},\n{\n\"id\": \"na013\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 22,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quel analgésique est administré par voie intrarachidienne ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Ziconotide (PRIALT)\",\n\"Fentanyl (DUROGESIC)\",\n\"Néfopam (ACUPAN)\",\n\"Oxycodone (OXYNORM)\"\n],\n\"correctAnswer\": \"Ziconotide (PRIALT)\",\n\"explanation\": \"Le ziconotide (PRIALT INJ) est un analgésique intrarachidien pour douleurs intenses et chroniques de l'adulte.\",\n\"simpleExplanation\": \"On l'injecte directement dans le liquide autour de la moelle épinière.\",\n\"memoryTip\": \"Z comme Zone rachidienne.\",\n\"examTrap\": \"Seul le ziconotide est intrarachidien dans le cours.\"\n},\n{\n\"id\": \"na014\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 23,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Qu'est-ce que le MEOPA ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Mélange équimolaire d'oxygène et de protoxyde d'azote\",\n\"Un morphinique injectable\",\n\"Un anesthésique local\",\n\"Un antispasmodique\"\n],\n\"correctAnswer\": \"Mélange équimolaire d'oxygène et de protoxyde d'azote\",\n\"explanation\": \"MEOPA = Mélange Équimolaire d'Oxygène et de Protoxyde d'Azote (KALINOX, ENTONOX) : analgésie d'urgence, actes douloureux courts, soins dentaires, obstétrique.\",\n\"simpleExplanation\": \"Un gaz « qui fait rire » mélangé moitié-moitié avec l'oxygène pour calmer la douleur.\",\n\"memoryTip\": \"MEOPA = 50% O₂ + 50% N₂O 🎈\",\n\"examTrap\": \"Ce n'est pas un morphinique.\"\n},\n{\n\"id\": \"na015\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 23,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des indications du MEOPA ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Ponction lombaire chez l'enfant\",\n\"Soins dentaires chez l'enfant anxieux\",\n\"Analgésie en attente d'une péridurale\",\n\"Traitement de fond de la migraine\"\n],\n\"correctAnswer\": [\n\"Ponction lombaire chez l'enfant\",\n\"Soins dentaires chez l'enfant anxieux\",\n\"Analgésie en attente d'une péridurale\"\n],\n\"explanation\": \"Indications : aide médicale d'urgence, actes douloureux de courte durée (ponction lombaire, biopsie, pansements de brûlés), fractures simples, soins dentaires, obstétrique.\",\n\"simpleExplanation\": \"Pour les gestes courts qui font mal, on respire le gaz magique.\",\n\"memoryTip\": \"MEOPA = actes Courts et douloureux ⏱️\",\n\"examTrap\": \"Pas de traitement de fond.\"\n},\n{\n\"id\": \"na016\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 23,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment agissent les antispasmodiques neurotropes (anticholinergiques) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Ils inhibent le spasme induit par l'acétylcholine\",\n\"Ils agissent directement sur la fibre musculaire lisse\",\n\"Ils bloquent la synthèse des prostaglandines\",\n\"Ils stimulent les récepteurs bêta-2\"\n],\n\"correctAnswer\": \"Ils inhibent le spasme induit par l'acétylcholine\",\n\"explanation\": \"Les neurotropes/anticholinergiques inhibent le spasme induit par l'acétylcholine ; les musculotropes agissent directement sur la fibre musculaire lisse.\",\n\"simpleExplanation\": \"Neurotrope coupe le message du nerf ; musculotrope calme directement le muscle.\",\n\"memoryTip\": \"NEUROtrope = Nerf (acétylcholine) ; MUSCULOtrope = Muscle.\",\n\"examTrap\": \"Ne pas inverser neurotrope et musculotrope.\"\n},\n{\n\"id\": \"na017\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 24,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel antispasmodique musculotrope est indiqué en adjuvant des contractions pendant la grossesse ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Phloroglucinol (SPASFON)\",\n\"Butylhyoscine (BUSCOPAN)\",\n\"Scopolamine (SCOPODERM)\",\n\"Propanthéline (PROBANTHINE)\"\n],\n\"correctAnswer\": \"Phloroglucinol (SPASFON)\",\n\"explanation\": \"Le phloroglucinol (SPASFON, SPASMEX) est indiqué comme traitement adjuvant des contractions au cours de la grossesse, en association au repos.\",\n\"simpleExplanation\": \"Le SPASFON est l'ami des femmes enceintes qui ont des contractions.\",\n\"memoryTip\": \"SPASFON = SPAsme de la Femme enceinte 🤰\",\n\"examTrap\": \"BUSCOPAN est un anticholinergique (neurotrope).\"\n},\n{\n\"id\": \"na018\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 24,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Associez : lesquels sont des antispasmodiques musculotropes ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Trimébutine (DEBRIDAT)\",\n\"Pinavérium (DICETEL)\",\n\"Mébévérine (DUSPATALIN)\",\n\"Tiémonium (VISCERALGINE)\"\n],\n\"correctAnswer\": [\n\"Trimébutine (DEBRIDAT)\",\n\"Pinavérium (DICETEL)\",\n\"Mébévérine (DUSPATALIN)\"\n],\n\"explanation\": \"Musculotropes : mébévérine (DUSPATALIN), pinavérium (DICETEL), phloroglucinol (SPASFON), trimébutine (DEBRIDAT). Tiémonium = anticholinergique.\",\n\"simpleExplanation\": \"Les musculotropes parlent directement au muscle.\",\n\"memoryTip\": \"DDDS : Debridat, Dicetel, Duspatalin, Spasfon = Musculotropes.\",\n\"examTrap\": \"VISCERALGINE est anti-muscarinique.\"\n},\n{\n\"id\": \"na019\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 19,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Présentez la classification OMS des antalgiques en 3 paliers avec un exemple par palier.\",\n\"type\": \"ouverte\",\n\"answer\": \"Palier 1 : antalgiques périphériques pour douleurs légères à moyennes (paracétamol, AINS comme l'ibuprofène, noramidopyrine). Palier 2 : antalgiques centraux faibles pour douleurs moyennes à intenses (codéine, dihydrocodéine, tramadol). Palier 3 : antalgiques centraux forts pour douleurs très intenses ou rebelles (morphine, fentanyl, oxycodone, buprénorphine, nalbuphine).\",\n\"keywords\": [\n\"palier 1\",\n\"paracétamol\",\n\"palier 2\",\n\"codéine\",\n\"tramadol\",\n\"palier 3\",\n\"morphine\"\n],\n\"explanation\": \"Palier 1 : antalgiques périphériques pour douleurs légères à moyennes (paracétamol, AINS comme l'ibuprofène, noramidopyrine). Palier 2 : antalgiques centraux faibles pour douleurs moyennes à intenses (codéine, dihydrocodéine, tramadol). Palier 3 : antalgiques centraux forts pour douleurs très intenses ou rebelles (morphine, fentanyl, oxycodone, buprénorphine, nalbuphine).\",\n\"memoryTip\": \"🪜 1 Paracétamol · 2 Codéine/Tramadol · 3 Morphine.\"\n},\n{\n\"id\": \"na020\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 21,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Citez les indications de la morphine et 3 de ses spécialités.\",\n\"type\": \"ouverte\",\n\"answer\": \"Traitement des douleurs intenses et/ou rebelles aux autres produits, notamment algies post-opératoires ou d'origine cancéreuse. Spécialités : ACTISKENAN, ORAMORPH, SEVREDOL, MOSCONTIN LP, SKENAN LP.\",\n\"keywords\": [\n\"intenses\",\n\"rebelles\",\n\"post-opératoires\",\n\"cancéreuse\",\n\"skenan\",\n\"moscontin\",\n\"oramorph\"\n],\n\"explanation\": \"Traitement des douleurs intenses et/ou rebelles aux autres produits, notamment algies post-opératoires ou d'origine cancéreuse. Spécialités : ACTISKENAN, ORAMORPH, SEVREDOL, MOSCONTIN LP, SKENAN LP.\",\n\"memoryTip\": \"🌙 Morphine = Morphée, dieu des rêves : douleur forte, cancer, post-op.\"\n},\n{\n\"id\": \"na021\",\n\"chapter\": \"Antalgiques & fièvre\",\n\"page\": 23,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Définissez les antispasmodiques et citez leurs 2 grandes classes.\",\n\"type\": \"ouverte\",\n\"answer\": \"Ils traitent les manifestations spasmodiques et/ou douloureuses des voies digestives, urinaires, ainsi qu'en gynécologie-obstétrique, en luttant contre les spasmes des muscles lisses. Deux classes : neurotropes ou anticholinergiques (anti-muscariniques, anti-nicotiniques) et musculotropes.\",\n\"keywords\": [\n\"spasmes\",\n\"muscles lisses\",\n\"digestives\",\n\"urinaires\",\n\"neurotropes\",\n\"musculotropes\"\n],\n\"explanation\": \"Ils traitent les manifestations spasmodiques et/ou douloureuses des voies digestives, urinaires, ainsi qu'en gynécologie-obstétrique, en luttant contre les spasmes des muscles lisses. Deux classes : neurotropes ou anticholinergiques (anti-muscariniques, anti-nicotiniques) et musculotropes.\",\n\"memoryTip\": \"🌀 Spasme = muscle lisse qui se tord ; Neuro vs Musculo.\"\n},\n{\n\"id\": \"nai001\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 24,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quel est l'anti-inflammatoire naturel cité dans le cours ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le froid\",\n\"La chaleur\",\n\"Le sel\",\n\"Le miel\"\n],\n\"correctAnswer\": \"Le froid\",\n\"explanation\": \"Le cours précise : « Le froid est un anti-inflammatoire naturel. »\",\n\"simpleExplanation\": \"Une poche de glace sur une cheville gonflée calme l'inflammation.\",\n\"memoryTip\": \"Froid = Anti-inflammatoire gratuit 🧊\",\n\"examTrap\": \"La chaleur n'est pas citée.\"\n},\n{\n\"id\": \"nai002\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 25,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel effet secondaire est commun à tous les anti-inflammatoires ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Lésion de la muqueuse gastroduodénale\",\n\"Hypoglycémie\",\n\"Bradycardie\",\n\"Constipation\"\n],\n\"correctAnswer\": \"Lésion de la muqueuse gastroduodénale\",\n\"explanation\": \"Sur le plan des effets secondaires, les anti-inflammatoires provoquent une lésion de la muqueuse gastroduodénale (ils ont aussi un caractère acide).\",\n\"simpleExplanation\": \"Les anti-inflammatoires grattent l'estomac.\",\n\"memoryTip\": \"AINS = Attention Intestin et Estomac 🔥\",\n\"examTrap\": \"Ils sont aussi à l'origine d'ulcères (cf. digestif).\"\n},\n{\n\"id\": \"nai003\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 25,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Outre l'effet anti-inflammatoire, quels effets possèdent les anti-inflammatoires ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Analgésiques et antipyrétiques\",\n\"Antibiotiques et antiviraux\",\n\"Sédatifs et hypnotiques\",\n\"Diurétiques\"\n],\n\"correctAnswer\": \"Analgésiques et antipyrétiques\",\n\"explanation\": \"Les anti-inflammatoires possèdent aussi des effets analgésiques et antipyrétiques.\",\n\"simpleExplanation\": \"Ils calment l'inflammation, la douleur et la fièvre : 3 en 1.\",\n\"memoryTip\": \"AINS = 3 A : Anti-inflammatoire, Antalgique, Antipyrétique.\",\n\"examTrap\": \"Pas d'action antibiotique.\"\n},\n{\n\"id\": \"nai004\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 25,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Le Diclofénac (VOLTARENE) appartient à quelle famille d'AINS ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Arylcarboxyliques\",\n\"Oxicams\",\n\"Coxibs\",\n\"Indoliques\"\n],\n\"correctAnswer\": \"Arylcarboxyliques\",\n\"explanation\": \"Arylcarboxyliques : diclofénac (VOLTARENE), ibuprofène (BRUFEN), kétoprofène (PROFENID), naproxène (NAPROSYNE)...\",\n\"simpleExplanation\": \"La grande famille la plus utilisée.\",\n\"memoryTip\": \"VOLTARENE, BRUFEN, PROFENID = ARYL.\",\n\"examTrap\": \"Piroxicam/méloxicam = oxicams.\"\n},\n{\n\"id\": \"nai005\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 25,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels AINS appartiennent à la famille des oxicams ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Piroxicam (FELDENE)\",\n\"Méloxicam (MOBIC)\",\n\"Ténoxicam (TILCOTIL)\",\n\"Indométacine (INDOCID)\"\n],\n\"correctAnswer\": [\n\"Piroxicam (FELDENE)\",\n\"Méloxicam (MOBIC)\",\n\"Ténoxicam (TILCOTIL)\"\n],\n\"explanation\": \"Oxicams : méloxicam (MOBIC), piroxicam (FELDENE), ténoxicam (TILCOTIL). Indométacine = indolique.\",\n\"simpleExplanation\": \"Ils se terminent tous par « -oxicam ».\",\n\"memoryTip\": \"« -oxicam » = oxicams 🔤\",\n\"examTrap\": \"INDOCID = indolique.\"\n},\n{\n\"id\": \"nai006\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 26,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des glucocorticoïdes cités dans le cours ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Prednisolone (SOLUPRED)\",\n\"Bétaméthasone (CELESTENE)\",\n\"Dexaméthasone (DECTANCYL)\",\n\"Naproxène (NAPROSYNE)\"\n],\n\"correctAnswer\": [\n\"Prednisolone (SOLUPRED)\",\n\"Bétaméthasone (CELESTENE)\",\n\"Dexaméthasone (DECTANCYL)\"\n],\n\"explanation\": \"Glucocorticoïdes : prednisone (CORTANCYL), prednisolone (SOLUPRED), méthylprednisolone (MEDROL), bétaméthasone (CELESTENE), dexaméthasone (DECTANCYL)...\",\n\"simpleExplanation\": \"Les corticoïdes finissent souvent en « -sone » ou « -solone ».\",\n\"memoryTip\": \"« -sone » = corticoïde 💪\",\n\"examTrap\": \"Le naproxène est un AINS.\"\n},\n{\n\"id\": \"nai007\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 26,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Par voie générale, les glucocorticoïdes sont indiqués dans :\",\n\"type\": \"qcd\",\n\"options\": [\n\"Le choc anaphylactique\",\n\"Les maladies auto-immunes comme le lupus\",\n\"L'asthme\",\n\"L'hypoglycémie\"\n],\n\"correctAnswer\": [\n\"Le choc anaphylactique\",\n\"Les maladies auto-immunes comme le lupus\",\n\"L'asthme\"\n],\n\"explanation\": \"Indications par voie générale : réactions inflammatoires, allergiques (urticaire, œdème de Quincke, choc anaphylactique), respiratoires (asthme), maladies auto-immunes (lupus, hépatite).\",\n\"simpleExplanation\": \"Les corticoïdes éteignent les grosses réactions du corps.\",\n\"memoryTip\": \"Corticoïdes = Pompiers de l'inflammation 🚒\",\n\"examTrap\": \"Ils augmentent la glycémie, ils ne la corrigent pas.\"\n},\n{\n\"id\": \"nai008\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 26,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Qu'est-ce qu'un co-antalgique ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Un médicament non développé pour la douleur mais qui favorise l'action des antalgiques\",\n\"Un antalgique de palier 3\",\n\"Un anesthésique local\",\n\"Une association paracétamol-codéine\"\n],\n\"correctAnswer\": \"Un médicament non développé pour la douleur mais qui favorise l'action des antalgiques\",\n\"explanation\": \"Les co-antalgiques favorisent l'action des antalgiques ou agissent sur la cause : antidépresseurs, neuroleptiques, benzodiazépines, antiépileptiques, corticoïdes, calcitonine, antispasmodiques.\",\n\"simpleExplanation\": \"Ce sont des « coéquipiers » qui aident l'antalgique à gagner.\",\n\"memoryTip\": \"CO-antalgique = COéquipier 🤝\",\n\"examTrap\": \"Leur effet antalgique a été découvert à l'usage.\"\n},\n{\n\"id\": \"nai009\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 26,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quel co-antalgique est utilisé dans certaines douleurs osseuses ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"La calcitonine\",\n\"Les antiépileptiques\",\n\"Les neuroleptiques\",\n\"Les antispasmodiques\"\n],\n\"correctAnswer\": \"La calcitonine\",\n\"explanation\": \"La calcitonine est utilisée dans certaines douleurs osseuses ; les antiépileptiques dans les douleurs neurologiques ; les antispasmodiques dans les douleurs viscérales.\",\n\"simpleExplanation\": \"Calcitonine = calcium = os.\",\n\"memoryTip\": \"CALCItonine = os 🦴\",\n\"examTrap\": \"Antiépileptiques = douleurs neurologiques.\"\n},\n{\n\"id\": \"nai010\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 27,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Qu'est-ce qu'un adjuvant de l'anesthésie ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Un agent associé aux anesthésiques pour augmenter l'efficacité ou diminuer la dose\",\n\"Un anesthésique local\",\n\"Un antidote des anesthésiques\",\n\"Un antibiotique prophylactique\"\n],\n\"correctAnswer\": \"Un agent associé aux anesthésiques pour augmenter l'efficacité ou diminuer la dose\",\n\"explanation\": \"Les adjuvants de l'anesthésie sont administrés avec les anesthésiques pour augmenter l'efficacité, améliorer la délivrance ou diminuer la dose exigée.\",\n\"simpleExplanation\": \"C'est l'assistant qui aide l'anesthésiste à faire dormir avec moins de produit.\",\n\"memoryTip\": \"Adjuvant = Aide ➕\",\n\"examTrap\": \"Ce n'est pas un antidote.\"\n},\n{\n\"id\": \"nai011\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 27,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des anesthésiques généraux gazeux ou volatils ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Halothane\",\n\"Sévoflurane\",\n\"Protoxyde d'azote\",\n\"Lidocaïne\"\n],\n\"correctAnswer\": [\n\"Halothane\",\n\"Sévoflurane\",\n\"Protoxyde d'azote\"\n],\n\"explanation\": \"Gazeux/volatils : chloroforme, éther, desflurane, enflurane, halothane, isoflurane, sévoflurane, protoxyde d'azote, xénon. La lidocaïne est un anesthésique local.\",\n\"simpleExplanation\": \"On les respire pour s'endormir.\",\n\"memoryTip\": \"« -flurane » = gaz anesthésique 🌬️\",\n\"examTrap\": \"Lidocaïne (XYLOCAINE) = locale.\"\n},\n{\n\"id\": \"nai012\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 27,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel anesthésique injectable est connu sous le nom de KETALAR ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"La kétamine\",\n\"Le thiopental\",\n\"La ropivacaïne\",\n\"L'hexobarbital\"\n],\n\"correctAnswer\": \"La kétamine\",\n\"explanation\": \"Anesthésiques injectables : barbituriques (hexobarbital, thiobarbital, thiopental) et kétamine (KETALAR).\",\n\"simpleExplanation\": \"KETALAR = KETAmine.\",\n\"memoryTip\": \"KETA-LAR = KETA-mine.\",\n\"examTrap\": \"La ropivacaïne est locale.\"\n},\n{\n\"id\": \"nai013\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 27,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le nom commercial de la ropivacaïne ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"NAROPEINE\",\n\"CARBOCAINE\",\n\"QUTENZA\",\n\"XYLOCAINE\"\n],\n\"correctAnswer\": \"NAROPEINE\",\n\"explanation\": \"Anesthésiques locaux : lidocaïne (XYLOCAINE), mépivacaïne (CARBOCAINE), procaïne, ropivacaïne (NAROPEINE), capsaïcine (QUTENZA).\",\n\"simpleExplanation\": \"Les anesthésiques locaux finissent en « -caïne ».\",\n\"memoryTip\": \"« -caïne » = local 💉\",\n\"examTrap\": \"QUTENZA = capsaïcine.\"\n},\n{\n\"id\": \"nai014\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 25,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les 4 caractères communs aux anti-inflammatoires.\",\n\"type\": \"ouverte\",\n\"answer\": \"Pharmacologique : tous inhibent la synthèse des prostaglandines. Activité : effets analgésiques et antipyrétiques en plus de l'effet anti-inflammatoire. Chimique : fonctions ou caractères acides. Effets secondaires : lésion de la muqueuse gastroduodénale.\",\n\"keywords\": [\n\"prostaglandines\",\n\"analgésiques\",\n\"antipyrétiques\",\n\"acides\",\n\"gastroduodénale\"\n],\n\"explanation\": \"Pharmacologique : tous inhibent la synthèse des prostaglandines. Activité : effets analgésiques et antipyrétiques en plus de l'effet anti-inflammatoire. Chimique : fonctions ou caractères acides. Effets secondaires : lésion de la muqueuse gastroduodénale.\",\n\"memoryTip\": \"🔥 PACE : Prostaglandines, Activité (antalgique-antipyrétique), Chimie acide, Estomac.\"\n},\n{\n\"id\": \"nai015\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 26,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les indications des corticoïdes par voie inhalée.\",\n\"type\": \"ouverte\",\n\"answer\": \"Traitement de fond de l'asthme, broncho-pneumopathies chroniques obstructives spastiques, bronchites inflammatoires.\",\n\"keywords\": [\n\"fond\",\n\"asthme\",\n\"broncho-pneumopathies\",\n\"bronchites\"\n],\n\"explanation\": \"Traitement de fond de l'asthme, broncho-pneumopathies chroniques obstructives spastiques, bronchites inflammatoires.\",\n\"memoryTip\": \"🫁 Inhalé = Fond de l'asthme + BPCO + bronchites.\"\n},\n{\n\"id\": \"nai016\",\n\"chapter\": \"Anti-inflammatoires & anesthésiques\",\n\"page\": 27,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Définissez les anesthésiques et donnez leurs 2 grandes classes avec un exemple chacune.\",\n\"type\": \"ouverte\",\n\"answer\": \"Substances utilisées pour faire disparaître artificiellement la sensation de douleur ou pour endormir un patient (chirurgie, actes moins invasifs). Classes : anesthésiques généraux (halothane, sévoflurane, protoxyde d'azote, thiopental, kétamine) et anesthésiques locaux/locorégionaux (lidocaïne, ropivacaïne, mépivacaïne).\",\n\"keywords\": [\n\"douleur\",\n\"endormir\",\n\"généraux\",\n\"locaux\",\n\"lidocaïne\",\n\"kétamine\"\n],\n\"explanation\": \"Substances utilisées pour faire disparaître artificiellement la sensation de douleur ou pour endormir un patient (chirurgie, actes moins invasifs). Classes : anesthésiques généraux (halothane, sévoflurane, protoxyde d'azote, thiopental, kétamine) et anesthésiques locaux/locorégionaux (lidocaïne, ropivacaïne, mépivacaïne).\",\n\"memoryTip\": \"😴 Général = tout le corps dort ; Local = une seule zone.\"\n},\n{\n\"id\": \"nx001\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 28,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Qui découvre en 1929 l'inhibition du staphylocoque doré par un pénicillium ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Fleming\",\n\"Pasteur\",\n\"Chain\",\n\"Duchesne\"\n],\n\"correctAnswer\": \"Fleming\",\n\"explanation\": \"1877 Pasteur et Joubert ; 1897 Duchesne ; 1929 Fleming (pénicillium sur boîte de Pétri) ; 1940 Chain (forme stable) ; 1942 production industrielle.\",\n\"simpleExplanation\": \"Fleming a trouvé une moisissure qui tuait les microbes dans sa boîte oubliée.\",\n\"memoryTip\": \"1929 = Fleming ; 1940 = Chain ; 1942 = Industrie 🏭\",\n\"examTrap\": \"Chain a obtenu la forme stable, pas la découverte.\"\n},\n{\n\"id\": \"nx002\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 28,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"En quelle année a lieu la production industrielle de la pénicilline ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"1942\",\n\"1929\",\n\"1877\",\n\"1960\"\n],\n\"correctAnswer\": \"1942\",\n\"explanation\": \"1942 : production industrielle de la pénicilline, utilisée pendant la Seconde Guerre mondiale.\",\n\"simpleExplanation\": \"Pendant la guerre, on a fabriqué la pénicilline en grande quantité pour soigner les soldats.\",\n\"memoryTip\": \"42 = Guerre = Usine.\",\n\"examTrap\": \"1929 = découverte par Fleming.\"\n},\n{\n\"id\": \"nx003\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 28,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Sur quels critères choisit-on un antibiotique ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Le germe à combattre\",\n\"La localisation de l'infection\",\n\"Les effets indésirables\",\n\"La couleur du comprimé\"\n],\n\"correctAnswer\": [\n\"Le germe à combattre\",\n\"La localisation de l'infection\",\n\"Les effets indésirables\"\n],\n\"explanation\": \"On choisit l'antibiotique en fonction du germe, de la localisation de l'infection, de sa voie d'élimination et de ses effets indésirables.\",\n\"simpleExplanation\": \"Comme un clé : il faut la bonne clé (germe) pour la bonne porte (organe).\",\n\"memoryTip\": \"G-L-E-E : Germe, Localisation, Élimination, Effets.\",\n\"examTrap\": \"La forme galénique n'est pas un critère cité.\"\n},\n{\n\"id\": \"nx004\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 29,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Qu'est-ce que l'antibiothérapie probabiliste ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Antibiothérapie donnée selon la bactérie la plus probablement en cause\",\n\"Antibiothérapie guidée par l'antibiogramme\",\n\"Antibiothérapie préventive avant chirurgie\",\n\"Association de deux antibiotiques\"\n],\n\"correctAnswer\": \"Antibiothérapie donnée selon la bactérie la plus probablement en cause\",\n\"explanation\": \"L'antibiothérapie probabiliste est administrée en fonction de la bactérie qui a le plus de chance d'être la cause ; on utilise des antibiotiques de 1re intention.\",\n\"simpleExplanation\": \"On parie sur le coupable le plus probable avant d'avoir les résultats.\",\n\"memoryTip\": \"Probabiliste = Pari intelligent 🎲\",\n\"examTrap\": \"On change en 2e intention si germe connu, résistance ou effets indésirables.\"\n},\n{\n\"id\": \"nx005\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 29,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quelle est la durée habituelle d'un traitement antibiotique ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"5 à 10 jours\",\n\"1 à 2 jours\",\n\"3 à 6 mois\",\n\"1 an\"\n],\n\"correctAnswer\": \"5 à 10 jours\",\n\"explanation\": \"Le traitement dure en général 5 à 10 jours, parfois plus court (cystite aiguë) ou plus long (ostéites, prostatites).\",\n\"simpleExplanation\": \"Environ une semaine, comme un petit voyage.\",\n\"memoryTip\": \"ATB = 5 à 10 jours 📆\",\n\"examTrap\": \"Cystite = plus court ; ostéite = plus long.\"\n},\n{\n\"id\": \"nx006\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 29,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quand doit-on réaliser les prélèvements bactériologiques pour l'antibiogramme ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Impérativement avant le début de l'antibiothérapie\",\n\"Après 48 h de traitement\",\n\"À la fin du traitement\",\n\"Uniquement en cas d'échec\"\n],\n\"correctAnswer\": \"Impérativement avant le début de l'antibiothérapie\",\n\"explanation\": \"L'antibiogramme implique de pratiquer les prélèvements bactériologiques de façon impérative avant le début de l'antibiothérapie.\",\n\"simpleExplanation\": \"On photographie le coupable avant de l'attaquer, sinon il se cache.\",\n\"memoryTip\": \"Prélever AVANT de traiter 🧫\",\n\"examTrap\": \"Après traitement, les cultures peuvent être faussement négatives.\"\n},\n{\n\"id\": \"nx007\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 30,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Comment appelle-t-on les bactéries de forme ronde ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Cocci\",\n\"Bacilles\",\n\"Spirilles\",\n\"Vibrions\"\n],\n\"correctAnswer\": \"Cocci\",\n\"explanation\": \"Selon la forme : rondes = cocci ; allongées = bacilles. Selon la coloration : Gram + (prennent la coloration) ; Gram – (ne la prennent pas).\",\n\"simpleExplanation\": \"Cocci = petites billes ; bacilles = petits bâtons.\",\n\"memoryTip\": \"Cocci = Cercle ⚪ ; Bacille = Bâton 🦯\",\n\"examTrap\": \"Gram – ne prennent PAS la coloration.\"\n},\n{\n\"id\": \"nx008\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 30,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle est la cause de la résistance acquise aux antibiotiques ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"L'emploi abusif d'antibiotiques (traitement trop court, automédication)\",\n\"L'absence du germe dans le spectre\",\n\"Une allergie du patient\",\n\"La voie d'administration IV\"\n],\n\"correctAnswer\": \"L'emploi abusif d'antibiotiques (traitement trop court, automédication)\",\n\"explanation\": \"La résistance acquise est due à l'emploi abusif d'ATB : apparition de mutants, traitement trop court, automédication répétée. Elle est croisée dans une même famille.\",\n\"simpleExplanation\": \"Si on arrête trop tôt, les microbes survivants deviennent plus forts.\",\n\"memoryTip\": \"Acquise = Abus 🚫\",\n\"examTrap\": \"La résistance naturelle existe d'emblée (germe hors spectre).\"\n},\n{\n\"id\": \"nx009\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 30,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels antibiotiques agissent sur l'ARN des ribosomes (synthèse protéique) ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Macrolides\",\n\"Tétracyclines\",\n\"Aminosides\",\n\"Quinolones\"\n],\n\"correctAnswer\": [\n\"Macrolides\",\n\"Tétracyclines\",\n\"Aminosides\"\n],\n\"explanation\": \"Ribosomes : macrolides, tétracyclines, chloramphénicol, aminosides. Paroi : pénicillines, vancomycine, fosfomycine. ADN : quinolones. Membrane : polymyxines.\",\n\"simpleExplanation\": \"Ils bloquent l'usine à protéines de la bactérie.\",\n\"memoryTip\": \"MaTCA = Macrolides, Tétracyclines, Chloramphénicol, Aminosides → Ribosome 🏭\",\n\"examTrap\": \"Les quinolones ciblent l'ADN.\"\n},\n{\n\"id\": \"nx010\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 31,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quelles sont les 5 familles d'antibiotiques les plus utilisées ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Bêtalactamines, macrolides, aminosides, cyclines, quinolones\",\n\"Pénicillines, sulfamides, imidazolés, polymyxines, glycopeptides\",\n\"Céphalosporines, carbapénèmes, monobactames, oxazolidinones, phénicolés\",\n\"Fluoroquinolones, lincosanides, fusidanines, nitrofuranes, rifamycines\"\n],\n\"correctAnswer\": \"Bêtalactamines, macrolides, aminosides, cyclines, quinolones\",\n\"explanation\": \"Il existe 20 grandes familles ; les plus utilisées : bêtalactamines, macrolides, aminosides, cyclines, quinolones.\",\n\"simpleExplanation\": \"Les 5 stars de l'antibiothérapie.\",\n\"memoryTip\": \"BMACQ : « Bien Manger Avant Chaque Quiz ».\",\n\"examTrap\": \"Le cours décrit 20 familles au total.\"\n},\n{\n\"id\": \"nx011\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 31,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle est l'action des bêtalactamines ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Bactéricide\",\n\"Bactériostatique\",\n\"Antivirale\",\n\"Antifongique\"\n],\n\"correctAnswer\": \"Bactéricide\",\n\"explanation\": \"Les bêtalactamines (pénicillines, céphalosporines, carbapénèmes, monobactames) ont une action bactéricide.\",\n\"simpleExplanation\": \"Elles cassent le mur de la bactérie qui explose.\",\n\"memoryTip\": \"Bêta-lactamine = Boum (bactéricide) 💥\",\n\"examTrap\": \"Macrolides et cyclines = bactériostatiques.\"\n},\n{\n\"id\": \"nx012\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 31,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La Benzathine-benzylpénicilline (EXTENCILLINE) est une :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Pénicilline retard\",\n\"Pénicilline M\",\n\"Aminopénicilline\",\n\"Carboxypénicilline\"\n],\n\"correctAnswer\": \"Pénicilline retard\",\n\"explanation\": \"Pénicillines retard : benzathine-benzylpénicilline (RETARPEN, EXTENCILLINE, DICACILLINE).\",\n\"simpleExplanation\": \"Une seule injection agit longtemps.\",\n\"memoryTip\": \"EXTENCILLINE = EXTENsion dans le temps ⏳\",\n\"examTrap\": \"Cloxacilline (ORBENINE) = pénicilline M.\"\n},\n{\n\"id\": \"nx013\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 31,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle pénicilline M est commercialisée sous le nom ORBENINE ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Cloxacilline\",\n\"Oxacilline\",\n\"Ampicilline\",\n\"Ticarcilline\"\n],\n\"correctAnswer\": \"Cloxacilline\",\n\"explanation\": \"Pénicillines M : cloxacilline (ORBENINE), oxacilline (OXAGRAM).\",\n\"simpleExplanation\": \"Pénicilline M = anti-staphylocoque.\",\n\"memoryTip\": \"ORBENINE = Cloxacilline.\",\n\"examTrap\": \"OXAGRAM = oxacilline.\"\n},\n{\n\"id\": \"nx014\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 31,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quelles céphalosporines sont de 1re génération ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Céfalexine (KEFORAL)\",\n\"Céfadroxil (ORACEFAL)\",\n\"Céfaclor (ALFATIL)\",\n\"Céfixime (OROKEN)\"\n],\n\"correctAnswer\": [\n\"Céfalexine (KEFORAL)\",\n\"Céfadroxil (ORACEFAL)\",\n\"Céfaclor (ALFATIL)\"\n],\n\"explanation\": \"C1G : céfaclor (ALFATIL), céfatrizine, céfadroxil (ORACEFAL), céfalexine (KEFORAL), céfradine, céfazoline. Céfixime (OROKEN) = C3G.\",\n\"simpleExplanation\": \"Les plus anciennes céphalosporines.\",\n\"memoryTip\": \"C1G : KEFORAL, ORACEFAL, ALFATIL.\",\n\"examTrap\": \"OROKEN, ROCEPHINE, CLAFORAN = C3G.\"\n},\n{\n\"id\": \"nx015\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 32,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Le Céfépime (AXEPIME) est une céphalosporine de :\",\n\"type\": \"qcm\",\n\"options\": [\n\"4e génération\",\n\"3e génération\",\n\"2e génération\",\n\"5e génération\"\n],\n\"correctAnswer\": \"4e génération\",\n\"explanation\": \"C4G : céfépime (AXEPIME) : septicémies, bactériémies, fièvre chez le neutropénique. C5G : ceftaroline (ZINFORO), ceftobiprole (MABELIO).\",\n\"simpleExplanation\": \"4 = Axepime, l'arme des infections graves.\",\n\"memoryTip\": \"AXEPIME = 4e (A-X-E-P = 4 lettres) 4️⃣\",\n\"examTrap\": \"Ceftriaxone = C3G.\"\n},\n{\n\"id\": \"nx016\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 32,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des carbapénèmes ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Imipénème (TIENAM)\",\n\"Méropénème (MERONEM)\",\n\"Ertapénème (INVANZ)\",\n\"Aztréonam (AZACTAM)\"\n],\n\"correctAnswer\": [\n\"Imipénème (TIENAM)\",\n\"Méropénème (MERONEM)\",\n\"Ertapénème (INVANZ)\"\n],\n\"explanation\": \"Carbapénèmes : imipénème (TIENAM), méropénème (MERONEM), ertapénème (INVANZ). Aztréonam = monobactame.\",\n\"simpleExplanation\": \"Ils finissent en « -pénème ».\",\n\"memoryTip\": \"« -pénème » = carbapénème 🛡️\",\n\"examTrap\": \"AZACTAM = monobactame.\"\n},\n{\n\"id\": \"nx017\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 32,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Les macrolides ont une action :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Bactériostatique\",\n\"Bactéricide\",\n\"Fongicide\",\n\"Virucide\"\n],\n\"correctAnswer\": \"Bactériostatique\",\n\"explanation\": \"Macrolides (bactériostatiques) : spiramycine (ROVAMYCINE), josamycine, clarithromycine (NAXY), érythromycine (ERY), roxithromycine (RULID), azithromycine (ZITHROMAX).\",\n\"simpleExplanation\": \"Ils empêchent les bactéries de se multiplier sans les tuer.\",\n\"memoryTip\": \"Macrolides en « -mycine » = Stop multiplication ✋\",\n\"examTrap\": \"Ne pas confondre avec les aminosides (bactéricides).\"\n},\n{\n\"id\": \"nx018\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 32,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des aminosides ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Gentamicine (GENTALLINE)\",\n\"Amikacine\",\n\"Tobramycine (NEBCINE)\",\n\"Azithromycine (ZITHROMAX)\"\n],\n\"correctAnswer\": [\n\"Gentamicine (GENTALLINE)\",\n\"Amikacine\",\n\"Tobramycine (NEBCINE)\"\n],\n\"explanation\": \"Aminosides (bactéricides) : gentamicine, tobramycine, amikacine. Ils sont néphrotoxiques et contre-indiqués pendant la grossesse.\",\n\"simpleExplanation\": \"Aminosides = puissants mais durs pour les reins.\",\n\"memoryTip\": \"GAT : Gentamicine, Amikacine, Tobramycine 🫘\",\n\"examTrap\": \"Azithromycine = macrolide.\"\n},\n{\n\"id\": \"nx019\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 32,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle quinolone est citée pour le traitement de la fièvre typhoïde ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Les quinolones (fluoroquinolones) comme la ciprofloxacine\",\n\"La gentamicine\",\n\"La doxycycline\",\n\"La vancomycine\"\n],\n\"correctAnswer\": \"Les quinolones (fluoroquinolones) comme la ciprofloxacine\",\n\"explanation\": \"Les quinolones de 2e génération (fluoroquinolones : ciprofloxacine CIFLOX, ofloxacine OFLOCET...) sont citées dans le traitement de la fièvre typhoïde.\",\n\"simpleExplanation\": \"Les « -floxacine » chassent la salmonelle de la typhoïde.\",\n\"memoryTip\": \"Typhoïde → « -floxacine » 🌡️\",\n\"examTrap\": \"Fluoroquinolones contre-indiquées < 15 ans et grossesse.\"\n},\n{\n\"id\": \"nx020\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 33,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La Pristinamycine (PYOSTACINE) appartient à :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Streptogramines (synergistines)\",\n\"Macrolides\",\n\"Lincosanides\",\n\"Glycopeptides\"\n],\n\"correctAnswer\": \"Streptogramines (synergistines)\",\n\"explanation\": \"Streptogramines ou synergistines (bactériostatiques) : pristinamycine (PYOSTACINE).\",\n\"simpleExplanation\": \"PYOSTACINE = anti-pus.\",\n\"memoryTip\": \"PYO = pus → synergistine.\",\n\"examTrap\": \"Clindamycine (DALACINE) = lincosanide.\"\n},\n{\n\"id\": \"nx021\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 33,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels antibiotiques sont des glycopeptides ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Vancomycine (VANCOCINE)\",\n\"Téicoplanine (TARGOCID)\",\n\"Linézolide (ZYVOXID)\",\n\"Colistine (COLIMYCINE)\"\n],\n\"correctAnswer\": [\n\"Vancomycine (VANCOCINE)\",\n\"Téicoplanine (TARGOCID)\"\n],\n\"explanation\": \"Glycopeptides (bactéricides) : vancomycine, téicoplanine. Linézolide = oxazolidinone ; colistine = polymyxine.\",\n\"simpleExplanation\": \"Les glycopeptides attaquent la paroi.\",\n\"memoryTip\": \"VANCO-TEICO = glycopeptides.\",\n\"examTrap\": \"Linézolide est bactériostatique.\"\n},\n{\n\"id\": \"nx022\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 33,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Le cotrimoxazole (BACTRIM) associe :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Triméthoprime + sulfaméthoxazole\",\n\"Sulfadoxine + pyriméthamine\",\n\"Amoxicilline + acide clavulanique\",\n\"Pipéracilline + tazobactam\"\n],\n\"correctAnswer\": \"Triméthoprime + sulfaméthoxazole\",\n\"explanation\": \"Sulfamides : triméthoprime + sulfaméthoxazole = cotrimoxazole (BACTRIM) ; sulfadoxine + pyriméthamine (FANSIDAR).\",\n\"simpleExplanation\": \"BACTRIM = duo T + S.\",\n\"memoryTip\": \"BACTRIM = TMP + SMX.\",\n\"examTrap\": \"FANSIDAR = sulfadoxine + pyriméthamine.\"\n},\n{\n\"id\": \"nx023\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 33,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Le Métronidazole (FLAGYL) appartient à quelle famille ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Nitro-imidazolés (anti-anaérobies)\",\n\"Nitrofuranes\",\n\"Quinolones\",\n\"Macrolides\"\n],\n\"correctAnswer\": \"Nitro-imidazolés (anti-anaérobies)\",\n\"explanation\": \"Nitro-imidazolés (bactéricides, anti-anaérobies) : métronidazole (FLAGYL), ornidazole (TIBERAL). Ils sont aussi antiamibiens.\",\n\"simpleExplanation\": \"FLAGYL tue les microbes qui vivent sans oxygène et les amibes.\",\n\"memoryTip\": \"Imidazolé = Anaérobies + Amibes.\",\n\"examTrap\": \"FURADANTINE = nitrofurane urinaire.\"\n},\n{\n\"id\": \"nx024\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 34,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel antibiotique est un nitrofurane urinaire ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Nitrofurantoïne (FURADANTINE)\",\n\"Fosfomycine (FOSFOCINE)\",\n\"Spectinomycine (TROBICINE)\",\n\"Colistine (COLIMYCINE)\"\n],\n\"correctAnswer\": \"Nitrofurantoïne (FURADANTINE)\",\n\"explanation\": \"Nitrofuranes urinaires (bactériostatiques) : nitrofurantoïne (FURADANTINE).\",\n\"simpleExplanation\": \"FURADANTINE soigne les infections urinaires.\",\n\"memoryTip\": \"FURADANTINE = Urines 🚽\",\n\"examTrap\": \"TROBICINE = spectinomycine.\"\n},\n{\n\"id\": \"nx025\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 34,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quelle famille est contre-indiquée chez l'enfant de moins de 8 ans ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Les cyclines\",\n\"Les macrolides\",\n\"Les pénicillines\",\n\"Les céphalosporines\"\n],\n\"correctAnswer\": \"Les cyclines\",\n\"explanation\": \"Moins de 8 ans : cyclines (coloration des dents). Moins de 15 ans : fluoroquinolones, sulfamides antibactériens.\",\n\"simpleExplanation\": \"Les cyclines tachent les dents des enfants.\",\n\"memoryTip\": \"Cyclines < 8 ans 🦷 ; Fluoroquinolones < 15 ans.\",\n\"examTrap\": \"Les fluoroquinolones sont interdites < 15 ans, pas < 8.\"\n},\n{\n\"id\": \"nx026\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 34,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quels antibiotiques sont contre-indiqués en cas d'insuffisance rénale ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Aminosides\",\n\"Vancomycine\",\n\"Sulfamides\",\n\"Pénicilline V\"\n],\n\"correctAnswer\": [\n\"Aminosides\",\n\"Vancomycine\",\n\"Sulfamides\"\n],\n\"explanation\": \"Insuffisance rénale : aminosides (néphrotoxiques), glycopeptides (vancomycine), sulfamides, cyclines de 1re génération. Insuffisance hépatique : macrolides, tétracyclines IV.\",\n\"simpleExplanation\": \"Les reins fragiles ne supportent pas les antibiotiques toxiques pour eux.\",\n\"memoryTip\": \"Rein : AVSC (Aminosides, Vanco, Sulfamides, Cyclines 1G).\",\n\"examTrap\": \"Macrolides = insuffisance HÉPATIQUE.\"\n},\n{\n\"id\": \"nx027\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 34,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels sont les deux effets indésirables communs à tous les antibiotiques ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Réactions allergiques et troubles digestifs\",\n\"Photosensibilisation et tendinite\",\n\"Néphrotoxicité et ototoxicité\",\n\"Hypoglycémie et hypertension\"\n],\n\"correctAnswer\": \"Réactions allergiques et troubles digestifs\",\n\"explanation\": \"Deux types d'effets sont communs : réactions allergiques et troubles digestifs (perturbation de la flore intestinale).\",\n\"simpleExplanation\": \"Les antibiotiques peuvent donner des boutons et la diarrhée.\",\n\"memoryTip\": \"ATB = Allergie + Tube digestif 🤧💩\",\n\"examTrap\": \"Photosensibilisation = cyclines et quinolones seulement.\"\n},\n{\n\"id\": \"nx028\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 35,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels antibiotiques exposent à la photosensibilisation ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Cyclines\",\n\"Quinolones\",\n\"Pénicillines\",\n\"Aminosides\"\n],\n\"correctAnswer\": [\n\"Cyclines\",\n\"Quinolones\"\n],\n\"explanation\": \"Les cyclines et les quinolones peuvent provoquer une photosensibilisation : éviter le soleil et les UV pendant le traitement. Les quinolones peuvent donner des tendinites.\",\n\"simpleExplanation\": \"Avec ces médicaments, le soleil brûle plus fort.\",\n\"memoryTip\": \"CQ = Coup de soleil ☀️ ; Quinolones = tendons.\",\n\"examTrap\": \"Les aminosides sont néphro/ototoxiques.\"\n},\n{\n\"id\": \"nx029\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 38,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels antiparasitaires sont des antiamibiens ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Métronidazole (FLAGYL)\",\n\"Secnidazole (SECNOL)\",\n\"Ornidazole (TIBERAL)\",\n\"Praziquantel (BILTRICIDE)\"\n],\n\"correctAnswer\": [\n\"Métronidazole (FLAGYL)\",\n\"Secnidazole (SECNOL)\",\n\"Ornidazole (TIBERAL)\"\n],\n\"explanation\": \"Antiamibiens : métronidazole, secnidazole, ornidazole, tilbroquinol + tiliquinol (INTETRIX). Praziquantel = antibilharzien, taenicide.\",\n\"simpleExplanation\": \"Les « -nidazole » chassent les amibes.\",\n\"memoryTip\": \"« -nidazole » = amibes 🦠\",\n\"examTrap\": \"BILTRICIDE soigne la bilharziose.\"\n},\n{\n\"id\": \"nx030\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 38,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel médicament est indiqué dans la bilharziose ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Praziquantel (BILTRICIDE)\",\n\"Diéthylcarbamazine (NOTEZINE)\",\n\"Pyrantel (HELMINTOX)\",\n\"Benzoate de benzyle (ASCABIOL)\"\n],\n\"correctAnswer\": \"Praziquantel (BILTRICIDE)\",\n\"explanation\": \"Praziquantel (BILTRICIDE) : antibilharzien et taenicide.\",\n\"simpleExplanation\": \"BILTRICIDE tue les BILharzies.\",\n\"memoryTip\": \"BIL-TRICIDE = BILharzie ✂️\",\n\"examTrap\": \"NOTEZINE = antifilarien.\"\n},\n{\n\"id\": \"nx031\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 38,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des anthelminthiques ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Albendazole (ZENTEL)\",\n\"Mébendazole (VERMOX)\",\n\"Pyrantel (COMBANTRIN)\",\n\"Pentamidine (PENTACARINAT)\"\n],\n\"correctAnswer\": [\n\"Albendazole (ZENTEL)\",\n\"Mébendazole (VERMOX)\",\n\"Pyrantel (COMBANTRIN)\"\n],\n\"explanation\": \"Anthelminthiques : flubendazole, pyrantel, triclabendazole, albendazole, mébendazole, niclosamide, praziquantel, ivermectine, diéthylcarbamazine. Pentamidine = trypanocide.\",\n\"simpleExplanation\": \"Ils chassent les vers intestinaux.\",\n\"memoryTip\": \"VERMOX = VERs 🪱\",\n\"examTrap\": \"PENTACARINAT traite la trypanosomiase.\"\n},\n{\n\"id\": \"nx032\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 38,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel antiparasitaire est un antifilarien ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Diéthylcarbamazine (NOTEZINE)\",\n\"Niclosamide (TREDEMINE)\",\n\"Triclabendazole (EGATEN)\",\n\"Malathion (PRIODERM)\"\n],\n\"correctAnswer\": \"Diéthylcarbamazine (NOTEZINE)\",\n\"explanation\": \"Diéthylcarbamazine (NOTEZINE) : antifilarien. Niclosamide : taenicide. Triclabendazole : distomatoses. Malathion : antipoux/antiscabieux.\",\n\"simpleExplanation\": \"NOTEZINE chasse les filaires.\",\n\"memoryTip\": \"NOTEZINE = filaires.\",\n\"examTrap\": \"PRIODERM est utilisé contre les poux/gale.\"\n},\n{\n\"id\": \"nx033\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 38,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel produit est un antiscabieux (contre la gale) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Benzoate de benzyle (ASCABIOL)\",\n\"Albendazole (ZENTEL)\",\n\"Pentamidine (PENTACARINAT)\",\n\"Atovaquone\"\n],\n\"correctAnswer\": \"Benzoate de benzyle (ASCABIOL)\",\n\"explanation\": \"Antiscabieux : benzoate de benzyle (ASCABIOL), malathion (PRIODERM), pyréthrines (SPREGAL). L'ivermectine est aussi citée pour la gale.\",\n\"simpleExplanation\": \"ASCABIOL = anti-gale (scabies = gale en latin).\",\n\"memoryTip\": \"A-SCAB-IOL = SCABies = gale.\",\n\"examTrap\": \"ZENTEL = vers.\"\n},\n{\n\"id\": \"nx034\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 39,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des antifongiques par voie générale ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Amphotéricine B (FUNGIZONE)\",\n\"Fluconazole\",\n\"Itraconazole (CANDITRAL)\",\n\"Amorolfine (LOCERYL 5%)\"\n],\n\"correctAnswer\": [\n\"Amphotéricine B (FUNGIZONE)\",\n\"Fluconazole\",\n\"Itraconazole (CANDITRAL)\"\n],\n\"explanation\": \"Antifongiques généraux : amphotéricine B, flucytosine, caspofungine, fluconazole, itraconazole, voriconazole, posaconazole, nystatine, griséofulvine. LOCERYL (amorolfine) = vernis externe.\",\n\"simpleExplanation\": \"Certains soignent tout le corps, d'autres seulement la peau ou les ongles.\",\n\"memoryTip\": \"Externe = crème/vernis ; Général = comprimé/IV.\",\n\"examTrap\": \"LOCERYL est externe (ongles).\"\n},\n{\n\"id\": \"nx035\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 29,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Qu'est-ce que l'antibiogramme et quel est son intérêt ?\",\n\"type\": \"ouverte\",\n\"answer\": \"Examen de laboratoire de bactériologie qui définit les antibiotiques vis-à-vis desquels la souche isolée est sensible. Il guide la prescription et permet de surveiller la survenue et l'évolution des résistances acquises. Il exige des prélèvements avant le début de l'antibiothérapie.\",\n\"keywords\": [\n\"laboratoire\",\n\"sensible\",\n\"guider\",\n\"prescription\",\n\"résistances\",\n\"avant\"\n],\n\"explanation\": \"Examen de laboratoire de bactériologie qui définit les antibiotiques vis-à-vis desquels la souche isolée est sensible. Il guide la prescription et permet de surveiller la survenue et l'évolution des résistances acquises. Il exige des prélèvements avant le début de l'antibiothérapie.\",\n\"memoryTip\": \"🧫 Antibiogramme = le GPS de l'antibiotique.\"\n},\n{\n\"id\": \"nx036\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 30,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Différenciez résistance naturelle et résistance acquise et donnez 3 mesures de prévention.\",\n\"type\": \"ouverte\",\n\"answer\": \"Résistance naturelle : existe d'emblée quand le germe n'appartient pas au spectre de l'ATB. Résistance acquise : due à l'emploi abusif d'ATB (traitement trop court, automédication), croisée dans une même famille. Prévention : antibiogramme avant traitement, respect de la durée, éviter l'automédication.\",\n\"keywords\": [\n\"naturelle\",\n\"spectre\",\n\"acquise\",\n\"abusif\",\n\"antibiogramme\",\n\"durée\",\n\"automédication\"\n],\n\"explanation\": \"Résistance naturelle : existe d'emblée quand le germe n'appartient pas au spectre de l'ATB. Résistance acquise : due à l'emploi abusif d'ATB (traitement trop court, automédication), croisée dans une même famille. Prévention : antibiogramme avant traitement, respect de la durée, éviter l'automédication.\",\n\"memoryTip\": \"🛡️ Naturelle = Née avec ; Acquise = Apprise par abus.\"\n},\n{\n\"id\": \"nx037\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 30,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les 4 principales cibles d'action des antibiotiques avec un exemple chacune.\",\n\"type\": \"ouverte\",\n\"answer\": \"Paroi bactérienne (pénicillines, vancomycine, fosfomycine) ; membrane cytoplasmique (polymyxines) ; ARN des ribosomes / synthèse protéique (macrolides, tétracyclines, chloramphénicol, aminosides) ; ADN bactérien (quinolones).\",\n\"keywords\": [\n\"paroi\",\n\"membrane\",\n\"ribosomes\",\n\"adn\",\n\"pénicillines\",\n\"quinolones\"\n],\n\"explanation\": \"Paroi bactérienne (pénicillines, vancomycine, fosfomycine) ; membrane cytoplasmique (polymyxines) ; ARN des ribosomes / synthèse protéique (macrolides, tétracyclines, chloramphénicol, aminosides) ; ADN bactérien (quinolones).\",\n\"memoryTip\": \"🎯 P-M-R-A : Paroi, Membrane, Ribosome, ADN.\"\n},\n{\n\"id\": \"nx038\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 34,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Citez les antibiotiques contre-indiqués pendant la grossesse et l'allaitement.\",\n\"type\": \"ouverte\",\n\"answer\": \"Aminosides, cyclines, fluoroquinolones, sulfamides, vancomycine, téicoplanine, fosfomycine, fucidine.\",\n\"keywords\": [\n\"aminosides\",\n\"cyclines\",\n\"fluoroquinolones\",\n\"sulfamides\",\n\"vancomycine\"\n],\n\"explanation\": \"Aminosides, cyclines, fluoroquinolones, sulfamides, vancomycine, téicoplanine, fosfomycine, fucidine.\",\n\"memoryTip\": \"🤰 « ACFS-VT » : Aminosides, Cyclines, Fluoroquinolones, Sulfamides, Vanco, Teico.\"\n},\n{\n\"id\": \"nx039\",\n\"chapter\": \"Anti-infectieux\",\n\"page\": 38,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Définissez un parasite et citez 4 classes d'antiparasitaires.\",\n\"type\": \"ouverte\",\n\"answer\": \"Petit être vivant (règne animal, végétal, bactérien ou fongique) qui vit au sein d'un hôte pour s'y nourrir et s'y reproduire, causant des troubles. Classes : antiamibiens, anti-toxoplasmose, antileishmaniens, trypanocides, anthelminthiques, antiscabieux, acaricides.\",\n\"keywords\": [\n\"hôte\",\n\"nourrir\",\n\"reproduire\",\n\"antiamibiens\",\n\"anthelminthiques\",\n\"antiscabieux\"\n],\n\"explanation\": \"Petit être vivant (règne animal, végétal, bactérien ou fongique) qui vit au sein d'un hôte pour s'y nourrir et s'y reproduire, causant des troubles. Classes : antiamibiens, anti-toxoplasmose, antileishmaniens, trypanocides, anthelminthiques, antiscabieux, acaricides.\",\n\"memoryTip\": \"🪱 Parasite = locataire qui ne paie pas son loyer.\"\n},\n{\n\"id\": \"np001\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 35,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Pourquoi certaines pathologies ont-elles une prescription encadrée par des directives ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Ce sont des pandémies à mortalité et morbidité élevées\",\n\"Ce sont des maladies bénignes\",\n\"Les médicaments sont très bon marché\",\n\"Elles ne touchent que les enfants\"\n],\n\"correctAnswer\": \"Ce sont des pandémies à mortalité et morbidité élevées\",\n\"explanation\": \"Paludisme, VIH, tuberculose, lèpre : pandémies à mortalité et morbidité élevées, d'où des protocoles mondiaux sécurisés.\",\n\"simpleExplanation\": \"Ces grandes maladies ont des « règles du jeu » écrites pour tout le monde.\",\n\"memoryTip\": \"Directives = Grandes pandémies 🌍\",\n\"examTrap\": \"En Côte d'Ivoire, des directives nationales s'appliquent.\"\n},\n{\n\"id\": \"np002\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 35,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des antipaludiques à effet intra-érythrocytaire ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Quinine (QUINIMAX)\",\n\"Chloroquine (NIVAQUINE)\",\n\"Artémisinine\",\n\"Proguanil (PALUDRINE)\"\n],\n\"correctAnswer\": [\n\"Quinine (QUINIMAX)\",\n\"Chloroquine (NIVAQUINE)\",\n\"Artémisinine\"\n],\n\"explanation\": \"Intra-érythrocytaires : quinine, chloroquine, amodiaquine, méfloquine, halofantrine, artémisinine. Proguanil et pyriméthamine = inhibiteurs de la dihydrofolate réductase.\",\n\"simpleExplanation\": \"Ils tuent le parasite caché dans le globule rouge.\",\n\"memoryTip\": \"Intra-GR : Quinine, Chloroquine, Artémisinine 🩸\",\n\"examTrap\": \"PALUDRINE = proguanil.\"\n},\n{\n\"id\": \"np003\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 36,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle association correspond à la MALARONE ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Proguanil + atovaquone\",\n\"Proguanil + chloroquine\",\n\"Artéméther + luméfantrine\",\n\"Pyriméthamine + sulfadoxine\"\n],\n\"correctAnswer\": \"Proguanil + atovaquone\",\n\"explanation\": \"MALARONE = proguanil + atovaquone ; SAVARINE = proguanil + chloroquine ; FANSIDAR = pyriméthamine + sulfadoxine.\",\n\"simpleExplanation\": \"MALARONE = Mal-Arrêté par Atovaquone.\",\n\"memoryTip\": \"MALARONE = Atovaquone + Proguanil.\",\n\"examTrap\": \"SAVARINE = proguanil + chloroquine.\"\n},\n{\n\"id\": \"np004\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 36,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle association correspond à l'ASAQ (CAMOQUIN PLUS) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Artésunate + amodiaquine\",\n\"Artéméther + luméfantrine\",\n\"Artésunate + méfloquine\",\n\"Artéméther + pipéraquine\"\n],\n\"correctAnswer\": \"Artésunate + amodiaquine\",\n\"explanation\": \"ASAQ = ArtéSunate + AmodiaQuine (CAMOQUIN PLUS). Artéméther + luméfantrine = COARTEM-like (ARTEFAN, LYATER...).\",\n\"simpleExplanation\": \"AS-AQ : les lettres disent tout.\",\n\"memoryTip\": \"AS = ArtéSunate ; AQ = AmodiaQuine.\",\n\"examTrap\": \"ARTEQUIN = artésunate + méfloquine.\"\n},\n{\n\"id\": \"np005\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 36,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"En l'absence d'ACT, quelle association l'OMS admet-elle à titre provisoire ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Amodiaquine + sulfadoxine-pyriméthamine\",\n\"Chloroquine seule\",\n\"Quinine + proguanil\",\n\"Méfloquine seule\"\n],\n\"correctAnswer\": \"Amodiaquine + sulfadoxine-pyriméthamine\",\n\"explanation\": \"Nota OMS : amodiaquine + sulfadoxine-pyriméthamine peut être admise à titre d'option provisoire si on ne dispose pas d'ACT, à condition que les deux soient très efficaces.\",\n\"simpleExplanation\": \"C'est la roue de secours quand on n'a pas d'ACT.\",\n\"memoryTip\": \"Roue de secours = AQ + SP 🛞\",\n\"examTrap\": \"La monothérapie n'est pas recommandée.\"\n},\n{\n\"id\": \"np006\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 36,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La zidovudine (AZT / RETROVIR) appartient à quelle classe d'antirétroviraux ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Inhibiteurs nucléosidiques de la transcriptase inverse (INTI)\",\n\"Inhibiteurs non nucléosidiques (INNTI)\",\n\"Inhibiteurs de la protéase\",\n\"Inhibiteurs de l'intégrase\"\n],\n\"correctAnswer\": \"Inhibiteurs nucléosidiques de la transcriptase inverse (INTI)\",\n\"explanation\": \"INTI : zidovudine, lamivudine, emtricitabine, ténofovir, abacavir... INNTI : éfavirenz, névirapine, étravirine, rilpivirine.\",\n\"simpleExplanation\": \"AZT a été le premier médicament contre le VIH.\",\n\"memoryTip\": \"INTI : AZT, 3TC, TDF, FTC, ABC.\",\n\"examTrap\": \"L'éfavirenz est un INNTI.\"\n},\n{\n\"id\": \"np007\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 36,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des INNTI ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Éfavirenz (SUSTIVA)\",\n\"Névirapine (VIRAMUNE)\",\n\"Rilpivirine (EDURANT)\",\n\"Lamivudine (EPIVIR)\"\n],\n\"correctAnswer\": [\n\"Éfavirenz (SUSTIVA)\",\n\"Névirapine (VIRAMUNE)\",\n\"Rilpivirine (EDURANT)\"\n],\n\"explanation\": \"INNTI : éfavirenz, névirapine, étravirine, délavirdine, rilpivirine. Lamivudine = INTI.\",\n\"simpleExplanation\": \"Les « -virine/-virenz » sont non nucléosidiques.\",\n\"memoryTip\": \"INNTI = « -vir-e-nz / -virine ».\",\n\"examTrap\": \"3TC (lamivudine) est un INTI.\"\n},\n{\n\"id\": \"np008\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 36,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Les médicaments se terminant par « -navir » (lopinavir, ritonavir, atazanavir) sont des :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Inhibiteurs de la protéase\",\n\"Inhibiteurs de l'intégrase\",\n\"INTI\",\n\"Inhibiteurs de fusion\"\n],\n\"correctAnswer\": \"Inhibiteurs de la protéase\",\n\"explanation\": \"Inhibiteurs de la protéase : amprénavir, tipranavir, indinavir, saquinavir, ritonavir, darunavir, atazanavir, nelfinavir, lopinavir.\",\n\"simpleExplanation\": \"« -navir » = navire qui bloque la protéase.\",\n\"memoryTip\": \"-NAVIR = protéase ⚓\",\n\"examTrap\": \"« -tégravir » = intégrase.\"\n},\n{\n\"id\": \"np009\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 37,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Le dolutégravir (DTG) est un :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Inhibiteur de l'intégrase\",\n\"Inhibiteur de la protéase\",\n\"Inhibiteur d'entrée CCR5\",\n\"INNTI\"\n],\n\"correctAnswer\": \"Inhibiteur de l'intégrase\",\n\"explanation\": \"Inhibiteurs de l'intégrase : raltégravir (ISENTRESS), dolutégravir (DTG), elvitégravir.\",\n\"simpleExplanation\": \"« -tégravir » = in-TÉGRA-se.\",\n\"memoryTip\": \"TÉGRA = inTÉGRAse 🧩\",\n\"examTrap\": \"Maraviroc = inhibiteur d'entrée CCR5.\"\n},\n{\n\"id\": \"np010\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 37,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel antirétroviral est un inhibiteur de la fusion ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Enfuvirtide (T-20, FUZEON)\",\n\"Maraviroc (CELSENTRI)\",\n\"Bévirimat\",\n\"Raltégravir\"\n],\n\"correctAnswer\": \"Enfuvirtide (T-20, FUZEON)\",\n\"explanation\": \"Inhibiteur de fusion : enfuvirtide (FUZEON). Inhibiteur d'entrée CCR5 : maraviroc. Inhibiteur de maturation : bévirimat.\",\n\"simpleExplanation\": \"FUZEON empêche la FUSION du virus.\",\n\"memoryTip\": \"FUZEON = FUSION.\",\n\"examTrap\": \"Maraviroc agit sur CCR5.\"\n},\n{\n\"id\": \"np011\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 37,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels antituberculeux sont bactéricides selon le cours ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Isoniazide (RIMIFON)\",\n\"Rifampicine (RIFADINE)\",\n\"Pyrazinamide (PIRILENE)\",\n\"Éthambutol (MYAMBUTOL)\"\n],\n\"correctAnswer\": [\n\"Isoniazide (RIMIFON)\",\n\"Rifampicine (RIFADINE)\",\n\"Pyrazinamide (PIRILENE)\"\n],\n\"explanation\": \"Bactéricides : isoniazide, rifampicine, pyrazinamide, streptomycine. Bactériostatiques : éthambutol, rifabutine.\",\n\"simpleExplanation\": \"L'éthambutol freine le bacille, les autres le tuent.\",\n\"memoryTip\": \"RHZ(S) tuent ; E freine.\",\n\"examTrap\": \"Éthambutol = bactériostatique.\"\n},\n{\n\"id\": \"np012\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 37,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des antilépreux ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Dapsone (DISULONE)\",\n\"Clofazimine (LAMPRENE)\",\n\"Rifampicine\",\n\"Isoniazide\"\n],\n\"correctAnswer\": [\n\"Dapsone (DISULONE)\",\n\"Clofazimine (LAMPRENE)\",\n\"Rifampicine\"\n],\n\"explanation\": \"Antilépreux : dapsone (DDS, DISULONE), acédapsone, clofazimine (LAMPRENE), rifampicine, sulfadoxine, thalidomide.\",\n\"simpleExplanation\": \"La rifampicine combat à la fois la tuberculose et la lèpre.\",\n\"memoryTip\": \"Lèpre = DCR : Dapsone, Clofazimine, Rifampicine.\",\n\"examTrap\": \"L'isoniazide est antituberculeux.\"\n},\n{\n\"id\": \"np013\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 36,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les ACT actuellement recommandées par l'OMS.\",\n\"type\": \"ouverte\",\n\"answer\": \"Artéméther + luméfantrine ; artésunate + amodiaquine ; artésunate + méfloquine ; artésunate + sulfadoxine-pyriméthamine.\",\n\"keywords\": [\n\"artéméther\",\n\"luméfantrine\",\n\"artésunate\",\n\"amodiaquine\",\n\"méfloquine\",\n\"sulfadoxine\"\n],\n\"explanation\": \"Artéméther + luméfantrine ; artésunate + amodiaquine ; artésunate + méfloquine ; artésunate + sulfadoxine-pyriméthamine.\",\n\"memoryTip\": \"🦟 4 ACT : AL, AS-AQ, AS-MQ, AS-SP.\"\n},\n{\n\"id\": \"np014\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 36,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Citez les grandes classes d'antirétroviraux avec un exemple pour chacune.\",\n\"type\": \"ouverte\",\n\"answer\": \"INTI (zidovudine, lamivudine, ténofovir) ; INNTI (éfavirenz, névirapine) ; inhibiteurs de la protéase (lopinavir, ritonavir, atazanavir) ; inhibiteurs de l'intégrase (raltégravir, dolutégravir) ; inhibiteurs d'entrée CCR5 (maraviroc) ; inhibiteurs de fusion (enfuvirtide) ; inhibiteurs de maturation (bévirimat).\",\n\"keywords\": [\n\"inti\",\n\"innti\",\n\"protéase\",\n\"intégrase\",\n\"fusion\",\n\"dolutégravir\"\n],\n\"explanation\": \"INTI (zidovudine, lamivudine, ténofovir) ; INNTI (éfavirenz, névirapine) ; inhibiteurs de la protéase (lopinavir, ritonavir, atazanavir) ; inhibiteurs de l'intégrase (raltégravir, dolutégravir) ; inhibiteurs d'entrée CCR5 (maraviroc) ; inhibiteurs de fusion (enfuvirtide) ; inhibiteurs de maturation (bévirimat).\",\n\"memoryTip\": \"🧬 Le virus doit entrer, copier, s'intégrer, mûrir : on bloque chaque étape.\"\n},\n{\n\"id\": \"np015\",\n\"chapter\": \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",\n\"page\": 37,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les antituberculeux du cours en précisant leur action.\",\n\"type\": \"ouverte\",\n\"answer\": \"Isoniazide (bactéricide), rifampicine (bactéricide), rifabutine (bactériostatique), éthambutol (bactériostatique), pyrazinamide (bactéricide), streptomycine (bactéricide).\",\n\"keywords\": [\n\"isoniazide\",\n\"rifampicine\",\n\"éthambutol\",\n\"pyrazinamide\",\n\"streptomycine\"\n],\n\"explanation\": \"Isoniazide (bactéricide), rifampicine (bactéricide), rifabutine (bactériostatique), éthambutol (bactériostatique), pyrazinamide (bactéricide), streptomycine (bactéricide).\",\n\"memoryTip\": \"🫁 RHZE(S) : Rifampicine, H isoniazide, Z pyrazinamide, E éthambutol.\"\n},\n{\n\"id\": \"ndb001\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 59,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment définit-on le diabète selon le cours ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Hyperglycémie chronique avec au moins 2 glycémies à jeun > 1,26 g/L\",\n\"Une seule glycémie > 1 g/L\",\n\"Glycémie post-prandiale < 1,40 g/L\",\n\"Présence de sucre dans les urines uniquement\"\n],\n\"correctAnswer\": \"Hyperglycémie chronique avec au moins 2 glycémies à jeun > 1,26 g/L\",\n\"explanation\": \"Le diabète = hyperglycémie chronique : au moins deux glycémies à jeun > 7 mmol/L (> 1,26 g/L).\",\n\"simpleExplanation\": \"Deux prises de sang le matin à jeun trop sucrées = diabète.\",\n\"memoryTip\": \"2 × 1,26 g/L 🍬\",\n\"examTrap\": \"Une seule glycémie ne suffit pas.\"\n},\n{\n\"id\": \"ndb002\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 59,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le mécanisme du diabète de type 1 ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Destruction des cellules bêta du pancréas\",\n\"Résistance à l'insuline\",\n\"Excès de glucagon\",\n\"Carence en vitamine B1\"\n],\n\"correctAnswer\": \"Destruction des cellules bêta du pancréas\",\n\"explanation\": \"Type 1 : destruction des cellules bêta pancréatiques. Type 2 : carence relative avec insulinorésistance et hypersécrétion compensatrice insuffisante.\",\n\"simpleExplanation\": \"Dans le type 1, l'usine à insuline est détruite.\",\n\"memoryTip\": \"Type 1 = Usine cassée ; Type 2 = Serrure rouillée 🔐\",\n\"examTrap\": \"Le type 1 nécessite l'insuline d'emblée.\"\n},\n{\n\"id\": \"ndb003\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 60,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quel est le traitement du diabète de type 1 ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Insuline d'emblée\",\n\"Metformine\",\n\"Sulfamides hypoglycémiants\",\n\"Régime seul\"\n],\n\"correctAnswer\": \"Insuline d'emblée\",\n\"explanation\": \"Diabète de type 1 : substitution en insuline d'emblée, la carence en insuline étant au premier plan.\",\n\"simpleExplanation\": \"Quand l'usine est cassée, il faut apporter l'insuline de l'extérieur.\",\n\"memoryTip\": \"Type 1 = Insuline 1er jour 💉\",\n\"examTrap\": \"La metformine est le premier traitement du type 2.\"\n},\n{\n\"id\": \"ndb004\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 60,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Que fait-on quand la metformine seule ne contrôle plus le diabète de type 2 ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"On associe d'autres antidiabétiques oraux\",\n\"On arrête tout traitement\",\n\"On passe directement au régime seul\",\n\"On augmente seulement la dose de metformine indéfiniment\"\n],\n\"correctAnswer\": \"On associe d'autres antidiabétiques oraux\",\n\"explanation\": \"Étapes : 1) metformine ; 2) association à d'autres ADO (sulfamides, glinides, inhibiteurs DPP4, analogues GLP1...) ; 3) insuline si bi/trithérapie insuffisante.\",\n\"simpleExplanation\": \"On ajoute des renforts quand la metformine ne suffit plus.\",\n\"memoryTip\": \"Metformine → +ADO → Insuline 🪜\",\n\"examTrap\": \"L'insuline peut encore être associée à la metformine.\"\n},\n{\n\"id\": \"ndb005\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 60,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle est la classe de la Pioglitazone (ACTOS) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Thiazolidinedione (glitazone), insulino-sensibilisateur\",\n\"Sulfamide hypoglycémiant\",\n\"Inhibiteur DPP4\",\n\"Inhibiteur des alpha-glucosidases\"\n],\n\"correctAnswer\": \"Thiazolidinedione (glitazone), insulino-sensibilisateur\",\n\"explanation\": \"Insulino-sensibilisateurs : biguanides (metformine) et glitazones (pioglitazone ACTOS, rosiglitazone AVANDIA).\",\n\"simpleExplanation\": \"Les glitazones rendent les cellules plus sensibles à l'insuline.\",\n\"memoryTip\": \"« -glitazone » = sensibilisateur.\",\n\"examTrap\": \"Les sulfamides sont insulino-sécréteurs.\"\n},\n{\n\"id\": \"ndb006\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 60,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des sulfamides hypoglycémiants ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Glibenclamide (DAONIL)\",\n\"Gliclazide (DIAMICRON)\",\n\"Glimépiride (AMAREL)\",\n\"Metformine (GLUCOPHAGE)\"\n],\n\"correctAnswer\": [\n\"Glibenclamide (DAONIL)\",\n\"Gliclazide (DIAMICRON)\",\n\"Glimépiride (AMAREL)\"\n],\n\"explanation\": \"Sulfamides hypoglycémiants (insulino-sécréteurs) : carbutamide, glibenclamide, glibornuride, gliclazide, glimépiride, glipizide.\",\n\"simpleExplanation\": \"Les « gli- » poussent le pancréas à produire plus d'insuline.\",\n\"memoryTip\": \"« GLI- » = sulfamide sécréteur.\",\n\"examTrap\": \"Metformine = biguanide.\"\n},\n{\n\"id\": \"ndb007\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 61,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La Sitagliptine est un :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Inhibiteur de la DPP4 (incrétino-mimétique)\",\n\"Analogue du GLP-1\",\n\"Glinide\",\n\"Inhibiteur des alpha-glucosidases\"\n],\n\"correctAnswer\": \"Inhibiteur de la DPP4 (incrétino-mimétique)\",\n\"explanation\": \"Incrétino-mimétiques : analogues du GLP-1 (exénatide, liraglutide) et inhibiteurs de la DPP4 (sitagliptine, vildagliptine, saxagliptine).\",\n\"simpleExplanation\": \"« -gliptine » = bloque l'enzyme DPP4.\",\n\"memoryTip\": \"« -gliptine » = DPP4 🔒\",\n\"examTrap\": \"Liraglutide = analogue GLP-1.\"\n},\n{\n\"id\": \"ndb008\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 61,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel antidiabétique inhibe l'absorption intestinale des glucides ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Acarbose\",\n\"Répaglinide\",\n\"Exénatide\",\n\"Glipizide\"\n],\n\"correctAnswer\": \"Acarbose\",\n\"explanation\": \"Inhibiteurs de l'absorption des glucides : inhibiteurs des alpha-glucosidases (acarbose, miglitol).\",\n\"simpleExplanation\": \"L'acarbose ferme la porte de l'intestin au sucre.\",\n\"memoryTip\": \"ACARBOSE = Anti-CARBOhydrates.\",\n\"examTrap\": \"Répaglinide = glinide (sécréteur).\"\n},\n{\n\"id\": \"ndb009\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 61,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Le Répaglinide appartient à quelle classe ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Glinides (insulino-sécréteurs)\",\n\"Biguanides\",\n\"Glitazones\",\n\"Gliptines\"\n],\n\"correctAnswer\": \"Glinides (insulino-sécréteurs)\",\n\"explanation\": \"Les glinides (répaglinide) sont des insulino-sécréteurs.\",\n\"simpleExplanation\": \"Glinide = petit cousin des sulfamides.\",\n\"memoryTip\": \"« -glinide » = sécréteur.\",\n\"examTrap\": \"Ne pas confondre glinide et gliptine.\"\n},\n{\n\"id\": \"ndb010\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 60,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels sont les objectifs du traitement antidiabétique oral ?\",\n\"type\": \"ouverte\",\n\"answer\": \"Normaliser les glycémies. À court terme : faire disparaître les symptômes cliniques et améliorer le confort de vie. À long terme : prévenir ou retarder l'apparition des complications dégénératives.\",\n\"keywords\": [\n\"normaliser\",\n\"glycémies\",\n\"court terme\",\n\"symptômes\",\n\"long terme\",\n\"complications\"\n],\n\"explanation\": \"Normaliser les glycémies. À court terme : faire disparaître les symptômes cliniques et améliorer le confort de vie. À long terme : prévenir ou retarder l'apparition des complications dégénératives.\",\n\"memoryTip\": \"🎯 Court terme = confort ; Long terme = complications.\"\n},\n{\n\"id\": \"ndb011\",\n\"chapter\": \"Antidiabétiques\",\n\"page\": 60,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Classez les antidiabétiques oraux avec un exemple par classe.\",\n\"type\": \"ouverte\",\n\"answer\": \"Insulino-sensibilisateurs : biguanides (metformine/GLUCOPHAGE), glitazones (pioglitazone). Insulino-sécréteurs : sulfamides hypoglycémiants (glibenclamide, gliclazide), glinides (répaglinide). Incrétino-mimétiques : analogues GLP-1 (exénatide, liraglutide), inhibiteurs DPP4 (sitagliptine). Inhibiteurs de l'absorption des glucides : acarbose, miglitol.\",\n\"keywords\": [\n\"sensibilisateurs\",\n\"metformine\",\n\"sécréteurs\",\n\"sulfamides\",\n\"glinides\",\n\"dpp4\",\n\"glp\",\n\"acarbose\"\n],\n\"explanation\": \"Insulino-sensibilisateurs : biguanides (metformine/GLUCOPHAGE), glitazones (pioglitazone). Insulino-sécréteurs : sulfamides hypoglycémiants (glibenclamide, gliclazide), glinides (répaglinide). Incrétino-mimétiques : analogues GLP-1 (exénatide, liraglutide), inhibiteurs DPP4 (sitagliptine). Inhibiteurs de l'absorption des glucides : acarbose, miglitol.\",\n\"memoryTip\": \"🍬 S-S-I-A : Sensibiliser, Sécréter, Incrétines, Absorption.\"\n},\n{\n\"id\": \"nrs001\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 40,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Où agissent les antitussifs vrais ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Sur les centres de la toux situés dans le cerveau\",\n\"Sur le mucus bronchique\",\n\"Sur les récepteurs bêta-2\",\n\"Sur l'histamine des bronches\"\n],\n\"correctAnswer\": \"Sur les centres de la toux situés dans le cerveau\",\n\"explanation\": \"Les antitussifs vrais diminuent le réflexe de la toux en agissant sur ses centres dans le cerveau ; ils traitent les toux sèches.\",\n\"simpleExplanation\": \"Ils baissent le bouton « tousser » dans le cerveau.\",\n\"memoryTip\": \"Antitussif = Cerveau 🧠 ; Expectorant = Mucus.\",\n\"examTrap\": \"Les toux grasses relèvent des expectorants.\"\n},\n{\n\"id\": \"nrs002\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 40,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Le dextrométhorphane (PULMODEXANE) et la pholcodine sont des antitussifs :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Opiacés\",\n\"Antihistaminiques\",\n\"Phytothérapiques\",\n\"Homéopathiques\"\n],\n\"correctAnswer\": \"Opiacés\",\n\"explanation\": \"Antitussifs opiacés : dextrométhorphane, codéthyline, pholcodine, codéine, noscapine.\",\n\"simpleExplanation\": \"De la même famille que la morphine, mais pour la toux.\",\n\"memoryTip\": \"Opiacés : Dextro, Pholco, Codé, Nosca.\",\n\"examTrap\": \"Oxomémazine (TOPLEXIL) = antihistaminique.\"\n},\n{\n\"id\": \"nrs003\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 40,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"L'oxomémazine (TOPLEXIL) est un antitussif :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Antihistaminique\",\n\"Opiacé\",\n\"Non opiacé non antihistaminique\",\n\"Mucolytique\"\n],\n\"correctAnswer\": \"Antihistaminique\",\n\"explanation\": \"Antitussifs antihistaminiques : alimémazine (THERALENE), oxomémazine (TOPLEXIL), prométhazine (FLUISSEDAL), piméthixène.\",\n\"simpleExplanation\": \"Ces antitussifs font aussi dormir.\",\n\"memoryTip\": \"« -mazine » = antihistaminique.\",\n\"examTrap\": \"TOPLEXIL n'est pas un opiacé.\"\n},\n{\n\"id\": \"nrs004\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 41,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelles sont les contre-indications des mucolytiques ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Allergie connue\",\n\"Impossibilité de tousser et de cracher\",\n\"Toux grasse\",\n\"Âge adulte\"\n],\n\"correctAnswer\": [\n\"Allergie connue\",\n\"Impossibilité de tousser et de cracher\"\n],\n\"explanation\": \"Contre-indications des expectorants/mucolytiques : allergie connue, impossibilité de tousser et cracher (risque d'inondation bronchique).\",\n\"simpleExplanation\": \"Si on ne peut pas cracher, le mucus liquéfié noie les bronches.\",\n\"memoryTip\": \"Mucolytique = Il faut pouvoir CRACHER.\",\n\"examTrap\": \"La toux grasse est l'indication.\"\n},\n{\n\"id\": \"nrs005\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 41,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quel est l'effet secondaire grave des mucolytiques chez un patient incapable de tousser ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Inondation bronchique\",\n\"Bronchospasme par blocage bêta\",\n\"Dépression respiratoire\",\n\"Hypokaliémie\"\n],\n\"correctAnswer\": \"Inondation bronchique\",\n\"explanation\": \"Effet secondaire : inondation bronchique par liquéfaction brutale des sécrétions si le patient ne peut ni tousser ni cracher.\",\n\"simpleExplanation\": \"Le mucus devient liquide comme de l'eau et remplit les poumons.\",\n\"memoryTip\": \"Liquéfier sans cracher = Inonder 🌊\",\n\"examTrap\": \"À surveiller chez le nourrisson et le grabataire.\"\n},\n{\n\"id\": \"nrs006\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 41,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des mucolytiques/expectorants ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Carbocistéine (BRONCHOKOD)\",\n\"Ambroxol (SURBRONC)\",\n\"Bromhexine (BISOLVON)\",\n\"Salbutamol (VENTOLINE)\"\n],\n\"correctAnswer\": [\n\"Carbocistéine (BRONCHOKOD)\",\n\"Ambroxol (SURBRONC)\",\n\"Bromhexine (BISOLVON)\"\n],\n\"explanation\": \"Mucolytiques : acétylcystéine, bromhexine, ambroxol, carbocistéine, erdostéine, guaïfénésine, éprazinone.\",\n\"simpleExplanation\": \"Ils rendent le mucus plus liquide.\",\n\"memoryTip\": \"Carbo-Ambro-Bromhex = Fluidifiants 💧\",\n\"examTrap\": \"VENTOLINE = bronchodilatateur.\"\n},\n{\n\"id\": \"nrs007\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 42,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment agissent les bronchodilatateurs anticholinergiques comme l'ipratropium (ATROVENT) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Ils s'opposent à l'acétylcholine au niveau des muscles bronchiques\",\n\"Ils stimulent les récepteurs bêta-2\",\n\"Ils réduisent l'inflammation\",\n\"Ils bloquent les leucotriènes\"\n],\n\"correctAnswer\": \"Ils s'opposent à l'acétylcholine au niveau des muscles bronchiques\",\n\"explanation\": \"Anticholinergiques : bronchodilatation par action contre l'acétylcholine au niveau des récepteurs des muscles bronchiques (ipratropium ATROVENT, tiotropium SPIRIVA).\",\n\"simpleExplanation\": \"Ils coupent le signal qui serre les bronches.\",\n\"memoryTip\": \"ATROVENT/SPIRIVA = Anti-acétylcholine.\",\n\"examTrap\": \"Le salbutamol est un bêta-2-stimulant.\"\n},\n{\n\"id\": \"nrs008\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 42,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel médicament appartient aux méthylxanthines ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Théophylline\",\n\"Tiotropium\",\n\"Montélukast\",\n\"Omalizumab\"\n],\n\"correctAnswer\": \"Théophylline\",\n\"explanation\": \"Méthylxanthines : théophylline (DILATRANE LP...), aminophylline : bronchodilatation et stimulation de la commande respiratoire.\",\n\"simpleExplanation\": \"La théophylline est cousine de la caféine.\",\n\"memoryTip\": \"THÉophylline = THÉ ☕\",\n\"examTrap\": \"Montélukast = antileucotriène.\"\n},\n{\n\"id\": \"nrs009\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 42,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quand utilise-t-on les corticoïdes par voie orale ou injectable dans l'asthme ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Pendant et après les crises d'asthme graves\",\n\"En entretien quotidien de tous les asthmes\",\n\"Jamais\",\n\"Uniquement chez l'enfant\"\n],\n\"correctAnswer\": \"Pendant et après les crises d'asthme graves\",\n\"explanation\": \"Corticoïdes oraux/injectables : employés pendant et après les crises graves. Inhalés : médicaments d'entretien réguliers.\",\n\"simpleExplanation\": \"Les comprimés de corticoïdes sont pour les grosses crises.\",\n\"memoryTip\": \"Inhalé = Entretien ; Oral/IV = Crise grave 🚑\",\n\"examTrap\": \"Les inhalés sont le traitement de fond.\"\n},\n{\n\"id\": \"nrs010\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 43,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Pourquoi le montélukast (SINGULAIR) ne doit-il pas être utilisé pour soulager une crise d'asthme ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Il n'ouvre pas les voies respiratoires : c'est un traitement d'entretien\",\n\"Il est trop puissant\",\n\"Il provoque un bronchospasme\",\n\"Il est réservé à la BPCO\"\n],\n\"correctAnswer\": \"Il n'ouvre pas les voies respiratoires : c'est un traitement d'entretien\",\n\"explanation\": \"Les antileucotriènes (montélukast, zafirlukast) réduisent l'inflammation et le mucus mais n'ouvrent pas les voies respiratoires : traitement d'entretien quotidien.\",\n\"simpleExplanation\": \"C'est un garde du corps, pas un pompier.\",\n\"memoryTip\": \"Antileucotriène = Entretien, pas Secours.\",\n\"examTrap\": \"Le secours = bêta-2-stimulant de courte durée.\"\n},\n{\n\"id\": \"nrs011\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 43,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"L'omalizumab (XOLAIR) est :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Un anticorps monoclonal anti-IgE pour l'asthme allergique sévère\",\n\"Un bêta-2-stimulant\",\n\"Un corticoïde inhalé\",\n\"Un antitussif\"\n],\n\"correctAnswer\": \"Un anticorps monoclonal anti-IgE pour l'asthme allergique sévère\",\n\"explanation\": \"Omalizumab (XOLAIR) : anticorps monoclonal anti-IgE, asthme sévère allergique persistant malgré les corticoïdes inhalés ; pas un médicament de secours.\",\n\"simpleExplanation\": \"Il bloque les anticorps de l'allergie.\",\n\"memoryTip\": \"« -mab » = anticorps monoclonal ; XOLAIR = anti-IgE.\",\n\"examTrap\": \"Il ne dilate pas les bronches.\"\n},\n{\n\"id\": \"nrs012\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 43,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Le cromoglycate et le kétotifène sont classés dans l'asthme comme :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Antihistaminiques d'entretien\",\n\"Bronchodilatateurs de crise\",\n\"Anticorps monoclonaux\",\n\"Mucolytiques\"\n],\n\"correctAnswer\": \"Antihistaminiques d'entretien\",\n\"explanation\": \"Antihistaminiques (cromoglycate LOMUDAL, kétotifène ZADITEN) : empêchent la réaction aux allergènes, traitement d'entretien, n'atténuent pas les crises.\",\n\"simpleExplanation\": \"Ils préviennent l'allergie mais n'ouvrent pas les bronches.\",\n\"memoryTip\": \"ZADITEN = Zéro allergie (prévention).\",\n\"examTrap\": \"Pas utilisés en crise.\"\n},\n{\n\"id\": \"nrs013\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 40,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Différenciez toux sèche et toux grasse et leur traitement respectif.\",\n\"type\": \"ouverte\",\n\"answer\": \"Toux sèche : traitée par les antitussifs vrais (suppresseurs de la toux) qui diminuent le réflexe en agissant sur les centres cérébraux. Toux grasse/productive : traitée par les expectorants/mucolytiques qui fluidifient et aident à expulser le mucus.\",\n\"keywords\": [\n\"sèche\",\n\"antitussifs\",\n\"cerveau\",\n\"grasse\",\n\"expectorants\",\n\"mucus\"\n],\n\"explanation\": \"Toux sèche : traitée par les antitussifs vrais (suppresseurs de la toux) qui diminuent le réflexe en agissant sur les centres cérébraux. Toux grasse/productive : traitée par les expectorants/mucolytiques qui fluidifient et aident à expulser le mucus.\",\n\"memoryTip\": \"🫁 Sèche = Stopper ; Grasse = Évacuer.\"\n},\n{\n\"id\": \"nrs014\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 41,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Citez les classes de médicaments anti-asthmatiques.\",\n\"type\": \"ouverte\",\n\"answer\": \"Bronchodilatateurs (bêta-2-stimulants, anticholinergiques, méthylxanthines), corticoïdes (inhalés et oraux/injectables), antileucotriènes, antihistaminiques, anticorps monoclonaux anti-IgE.\",\n\"keywords\": [\n\"bêta-2\",\n\"anticholinergiques\",\n\"méthylxanthines\",\n\"corticoïdes\",\n\"leucotriènes\",\n\"anti-ige\"\n],\n\"explanation\": \"Bronchodilatateurs (bêta-2-stimulants, anticholinergiques, méthylxanthines), corticoïdes (inhalés et oraux/injectables), antileucotriènes, antihistaminiques, anticorps monoclonaux anti-IgE.\",\n\"memoryTip\": \"🌬️ B-C-L-H-M : Bronchodilatateurs, Corticoïdes, Leucotriènes, Histamine, Monoclonaux.\"\n},\n{\n\"id\": \"nrs015\",\n\"chapter\": \"Appareil respiratoire\",\n\"page\": 41,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Expliquez le mode d'action des bêta-2-stimulants et citez 3 produits.\",\n\"type\": \"ouverte\",\n\"answer\": \"Relâchement de la musculature bronchique (bronchodilatation) et utérine (utérorelaxation) par action sur les récepteurs bêta-2 du système sympathique. Produits : salbutamol (VENTOLINE), terbutaline (BRICANYL), formotérol (FORADIL), salmétérol (SEREVENT).\",\n\"keywords\": [\n\"relâchement\",\n\"bronchodilatation\",\n\"utérorelaxation\",\n\"bêta-2\",\n\"salbutamol\",\n\"terbutaline\"\n],\n\"explanation\": \"Relâchement de la musculature bronchique (bronchodilatation) et utérine (utérorelaxation) par action sur les récepteurs bêta-2 du système sympathique. Produits : salbutamol (VENTOLINE), terbutaline (BRICANYL), formotérol (FORADIL), salmétérol (SEREVENT).\",\n\"memoryTip\": \"🫁 Bêta-2 = 2 organes : bronches + utérus.\"\n},\n{\n\"id\": \"nhs001\",\n\"chapter\": \"Antihistaminiques\",\n\"page\": 44,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Comment agissent les antihistaminiques atypiques ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Ils inhibent l'histidine décarboxylase et empêchent la formation d'histamine\",\n\"Ils bloquent les récepteurs H2 gastriques\",\n\"Ils stimulent la libération d'histamine\",\n\"Ils neutralisent l'acide gastrique\"\n],\n\"correctAnswer\": \"Ils inhibent l'histidine décarboxylase et empêchent la formation d'histamine\",\n\"explanation\": \"Les antihistaminiques atypiques empêchent la transformation de l'histidine en histamine en inhibant l'histidine décarboxylase.\",\n\"simpleExplanation\": \"Ils coupent la fabrication de l'histamine à la source.\",\n\"memoryTip\": \"Atypique = Avant l'histamine (usine coupée) 🏭\",\n\"examTrap\": \"Les classiques bloquent les récepteurs.\"\n},\n{\n\"id\": \"nhs002\",\n\"chapter\": \"Antihistaminiques\",\n\"page\": 44,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des antihistaminiques H1 peu sédatifs ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Desloratadine (AERIUS)\",\n\"Cétirizine (ZYRTEC)\",\n\"Fexofénadine (TELFAST)\",\n\"Prométhazine (PHENERGAN)\"\n],\n\"correctAnswer\": [\n\"Desloratadine (AERIUS)\",\n\"Cétirizine (ZYRTEC)\",\n\"Fexofénadine (TELFAST)\"\n],\n\"explanation\": \"Peu sédatifs : desloratadine, bilastine, loratadine, ébastine, mizolastine, fexofénadine, cétirizine, rupatadine, lévocétirizine. Prométhazine = phénothiazinique sédatif.\",\n\"simpleExplanation\": \"Ils calment l'allergie sans trop endormir.\",\n\"memoryTip\": \"« -tadine / -tirizine » = peu sédatif ☀️\",\n\"examTrap\": \"PHENERGAN fait dormir.\"\n},\n{\n\"id\": \"nhs003\",\n\"chapter\": \"Antihistaminiques\",\n\"page\": 44,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La Dexchlorphéniramine (POLARAMINE) est un antihistaminique :\",\n\"type\": \"qcm\",\n\"options\": [\n\"H1 sédatif\",\n\"H1 peu sédatif\",\n\"Anti-H2\",\n\"Atypique\"\n],\n\"correctAnswer\": \"H1 sédatif\",\n\"explanation\": \"Sédatifs : dexchlorphéniramine (POLARAMINE), bromphéniramine, cyproheptadine (PERIACTINE). Phénothiaziniques : prométhazine, alimémazine, hydroxyzine.\",\n\"simpleExplanation\": \"POLARAMINE peut endormir.\",\n\"memoryTip\": \"POLARAMINE = Pas Pour conduire 🚗💤\",\n\"examTrap\": \"Pas un anti-H2.\"\n},\n{\n\"id\": \"nhs004\",\n\"chapter\": \"Antihistaminiques\",\n\"page\": 44,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des indications des antihistaminiques anti-H1 ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Rhinite allergique\",\n\"Urticaire\",\n\"Conjonctivite allergique\",\n\"Ulcère gastrique\"\n],\n\"correctAnswer\": [\n\"Rhinite allergique\",\n\"Urticaire\",\n\"Conjonctivite allergique\"\n],\n\"explanation\": \"Indications : rhinite et conjonctivite allergiques, dermatites de contact, urticaire, prurit, réactions anaphylactiques ou anaphylactoïdes.\",\n\"simpleExplanation\": \"Tout ce qui gratte, coule ou gonfle à cause d'une allergie.\",\n\"memoryTip\": \"H1 = nez, yeux, peau 👃👁️\",\n\"examTrap\": \"L'ulcère relève des anti-H2.\"\n},\n{\n\"id\": \"nhs005\",\n\"chapter\": \"Antihistaminiques\",\n\"page\": 44,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"L'hydroxyzine (ATARAX) appartient aux antihistaminiques :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Phénothiaziniques / sédatifs\",\n\"Peu sédatifs\",\n\"Atypiques\",\n\"Anti-H2\"\n],\n\"correctAnswer\": \"Phénothiaziniques / sédatifs\",\n\"explanation\": \"Le cours classe l'hydroxyzine (ATARAX) avec prométhazine et alimémazine ; elle est aussi un anxiolytique non benzodiazépinique.\",\n\"simpleExplanation\": \"ATARAX calme l'allergie et l'angoisse.\",\n\"memoryTip\": \"ATARAX = ATAraxie (calme) 😌\",\n\"examTrap\": \"Elle est sédative.\"\n},\n{\n\"id\": \"nhs006\",\n\"chapter\": \"Antihistaminiques\",\n\"page\": 44,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Définissez un antihistaminique et citez 4 indications des anti-H1.\",\n\"type\": \"ouverte\",\n\"answer\": \"Médicament qui réduit ou élimine les effets de l'histamine (médiateur libéré lors des réactions allergiques) en agissant sur ses récepteurs. Indications : rhinite allergique, conjonctivite allergique, dermatite de contact, urticaire, prurit, réactions anaphylactiques.\",\n\"keywords\": [\n\"histamine\",\n\"récepteurs\",\n\"rhinite\",\n\"conjonctivite\",\n\"urticaire\",\n\"prurit\"\n],\n\"explanation\": \"Médicament qui réduit ou élimine les effets de l'histamine (médiateur libéré lors des réactions allergiques) en agissant sur ses récepteurs. Indications : rhinite allergique, conjonctivite allergique, dermatite de contact, urticaire, prurit, réactions anaphylactiques.\",\n\"memoryTip\": \"🤧 Histamine = alarme de l'allergie ; antihistaminique = bouton OFF.\"\n},\n{\n\"id\": \"nhs007\",\n\"chapter\": \"Antihistaminiques\",\n\"page\": 44,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les 3 grandes classes d'antihistaminiques H1 avec un exemple.\",\n\"type\": \"ouverte\",\n\"answer\": \"Peu sédatifs : cétirizine (ZYRTEC), loratadine (CLARITYNE), desloratadine (AERIUS). Sédatifs : dexchlorphéniramine (POLARAMINE), cyproheptadine (PERIACTINE). Phénothiaziniques : prométhazine (PHENERGAN), alimémazine (THERALENE), hydroxyzine (ATARAX).\",\n\"keywords\": [\n\"peu sédatifs\",\n\"cétirizine\",\n\"sédatifs\",\n\"polaramine\",\n\"phénothiaziniques\",\n\"prométhazine\"\n],\n\"explanation\": \"Peu sédatifs : cétirizine (ZYRTEC), loratadine (CLARITYNE), desloratadine (AERIUS). Sédatifs : dexchlorphéniramine (POLARAMINE), cyproheptadine (PERIACTINE). Phénothiaziniques : prométhazine (PHENERGAN), alimémazine (THERALENE), hydroxyzine (ATARAX).\",\n\"memoryTip\": \"😴 Peu sédatif le jour, sédatif la nuit.\"\n},\n{\n\"id\": \"ndg001\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 45,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Qu'est-ce qu'un ulcère ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Une destruction localisée de la muqueuse de l'estomac et/ou du duodénum\",\n\"Une inflammation du côlon\",\n\"Une hernie de l'estomac\",\n\"Une infection du foie\"\n],\n\"correctAnswer\": \"Une destruction localisée de la muqueuse de l'estomac et/ou du duodénum\",\n\"explanation\": \"L'ulcère est une destruction localisée de la muqueuse gastrique et/ou duodénale, par déséquilibre entre défense et attaques chlorhydropeptiques.\",\n\"simpleExplanation\": \"C'est un trou dans la paroi de l'estomac.\",\n\"memoryTip\": \"Ulcère = trou 🕳️ dans estomac/duodénum.\",\n\"examTrap\": \"Ne pas confondre avec la colite.\"\n},\n{\n\"id\": \"ndg002\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 46,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quand administre-t-on surtout les anti-H2 ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le soir, pour réduire l'acidité nocturne\",\n\"Le matin à jeun uniquement\",\n\"Après chaque repas\",\n\"En cas de diarrhée\"\n],\n\"correctAnswer\": \"Le soir, pour réduire l'acidité nocturne\",\n\"explanation\": \"Les anti-H2 diminuent la sécrétion acide de 50 à 80 %, cicatrisation en 6 à 8 semaines dans 90 % des cas ; prise surtout le soir.\",\n\"simpleExplanation\": \"Ils protègent l'estomac pendant la nuit.\",\n\"memoryTip\": \"Anti-H2 = Bonne Nuit 🌙\",\n\"examTrap\": \"Les IPP se prennent en 1 prise unique.\"\n},\n{\n\"id\": \"ndg003\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 46,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des anti-H2 ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Cimétidine (TAGAMET)\",\n\"Ranitidine (AZANTAC)\",\n\"Famotidine (PEPDINE)\",\n\"Oméprazole (MOPRAL)\"\n],\n\"correctAnswer\": [\n\"Cimétidine (TAGAMET)\",\n\"Ranitidine (AZANTAC)\",\n\"Famotidine (PEPDINE)\"\n],\n\"explanation\": \"Anti-H2 : cimétidine, famotidine, nizatidine, ranitidine. Oméprazole = IPP.\",\n\"simpleExplanation\": \"« -tidine » = anti-H2.\",\n\"memoryTip\": \"« -tidine » = H2 ; « -prazole » = IPP.\",\n\"examTrap\": \"MOPRAL est un IPP.\"\n},\n{\n\"id\": \"ndg004\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 46,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Quel suffixe caractérise les inhibiteurs de la pompe à protons ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"-prazole\",\n\"-tidine\",\n\"-sartan\",\n\"-pril\"\n],\n\"correctAnswer\": \"-prazole\",\n\"explanation\": \"IPP : oméprazole, lansoprazole, pantoprazole, ésoméprazole, rabéprazole.\",\n\"simpleExplanation\": \"Tous les IPP finissent par « prazole ».\",\n\"memoryTip\": \"PRAZOLE = Pompe 🧯\",\n\"examTrap\": \"« -tidine » = anti-H2.\"\n},\n{\n\"id\": \"ndg005\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 46,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le médicament analogue des prostaglandines utilisé dans l'ulcère ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Misoprostol (CYTOTEC)\",\n\"Sucralfate (ULCAR)\",\n\"Pantoprazole (INIPOMP)\",\n\"Famotidine (PEPDINE)\"\n],\n\"correctAnswer\": \"Misoprostol (CYTOTEC)\",\n\"explanation\": \"Misoprostol (CYTOTEC) : diminue la sécrétion acide, favorise mucus et bicarbonates, cytoprotecteur.\",\n\"simpleExplanation\": \"Il épaissit le bouclier de l'estomac.\",\n\"memoryTip\": \"CYTOTEC = CYTOprotecteur 🛡️\",\n\"examTrap\": \"ULCAR = sucralfate (topique).\"\n},\n{\n\"id\": \"ndg006\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 47,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des topiques antiacides ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Hydroxyde d'aluminium + magnésium (MAALOX)\",\n\"Phosphate d'aluminium (PHOSPHALUGEL)\",\n\"Argiles (ACTAPULGITE)\",\n\"Lansoprazole (LANZOR)\"\n],\n\"correctAnswer\": [\n\"Hydroxyde d'aluminium + magnésium (MAALOX)\",\n\"Phosphate d'aluminium (PHOSPHALUGEL)\",\n\"Argiles (ACTAPULGITE)\"\n],\n\"explanation\": \"Antiacides : MAALOX, ROCGEL, PHOSPHALUGEL, alginates (GAVISCON), argiles (BEDELIX, ACTAPULGITE), silicones (POLYSILANE). Effet de courte durée.\",\n\"simpleExplanation\": \"Ils éteignent l'acide comme de l'eau sur le feu, mais pour peu de temps.\",\n\"memoryTip\": \"Antiacides = effet COURT ⏱️\",\n\"examTrap\": \"LANZOR est un IPP.\"\n},\n{\n\"id\": \"ndg007\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 47,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quelle est la trithérapie d'éradication d'Helicobacter pylori décrite dans le cours ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"IPP double dose + amoxicilline + clarithromycine (ou imidazolé + clarithromycine), 8 à 10 jours\",\n\"Anti-H2 + métronidazole, 3 jours\",\n\"IPP seul, 4 semaines\",\n\"Amoxicilline seule, 14 jours\"\n],\n\"correctAnswer\": \"IPP double dose + amoxicilline + clarithromycine (ou imidazolé + clarithromycine), 8 à 10 jours\",\n\"explanation\": \"Trithérapie orale 8 à 10 jours : IPP double dose (oméprazole 40 mg/j) + 2 antibiotiques : amoxicilline + clarithromycine ou imidazolé + clarithromycine.\",\n\"simpleExplanation\": \"Un médicament baisse l'acide, deux antibiotiques tuent la bactérie.\",\n\"memoryTip\": \"1 IPP + 2 ATB = 3 💊💊💊\",\n\"examTrap\": \"Ne jamais utiliser un seul antibiotique.\"\n},\n{\n\"id\": \"ndg008\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 47,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des conseils hygiéno-diététiques dans l'ulcère ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Arrêt du tabac et de l'alcool\",\n\"Dormir la tête surélevée de 10 à 15 cm\",\n\"Attendre environ 2 h entre le repas et le coucher\",\n\"Jeûner longtemps entre les repas\"\n],\n\"correctAnswer\": [\n\"Arrêt du tabac et de l'alcool\",\n\"Dormir la tête surélevée de 10 à 15 cm\",\n\"Attendre environ 2 h entre le repas et le coucher\"\n],\n\"explanation\": \"Conseils : alimentation équilibrée fractionnée, éviter le jeûne prolongé, arrêter tabac et alcool, 2 h entre repas et coucher, éviter épices, café, boissons gazeuses, tête surélevée.\",\n\"simpleExplanation\": \"Manger souvent en petites quantités et ne pas se coucher juste après.\",\n\"memoryTip\": \"Ni tabac, ni alcool, ni coucher après repas 🛏️\",\n\"examTrap\": \"Le jeûne prolongé est à éviter.\"\n},\n{\n\"id\": \"ndg009\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 48,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment agissent les prokinétiques (métoclopramide, dompéridone) dans le RGO ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Accélèrent la vidange gastrique et augmentent le tonus du sphincter inférieur de l'œsophage\",\n\"Neutralisent l'acide\",\n\"Inhibent la pompe à protons\",\n\"Forment un gel sur l'ulcère\"\n],\n\"correctAnswer\": \"Accélèrent la vidange gastrique et augmentent le tonus du sphincter inférieur de l'œsophage\",\n\"explanation\": \"Prokinétiques : accélèrent la vidange gastrique, augmentent le tonus du SIO et stimulent la motricité œso-gastro-duodénale.\",\n\"simpleExplanation\": \"Ils poussent la nourriture vers le bas et ferment la porte du haut.\",\n\"memoryTip\": \"Prokinétique = PRO-mouvement ➡️\",\n\"examTrap\": \"Les alginates forment un radeau, ce sont des pansements.\"\n},\n{\n\"id\": \"ndg010\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 49,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"À partir de quel âge la dompéridone peut-elle être utilisée selon le cours ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Elle ne doit plus être utilisée chez l'enfant de moins de 12 ans\",\n\"Dès la naissance\",\n\"Après 6 mois\",\n\"Après 2 ans\"\n],\n\"correctAnswer\": \"Elle ne doit plus être utilisée chez l'enfant de moins de 12 ans\",\n\"explanation\": \"NB du cours : les médicaments à base de dompéridone ne doivent plus être utilisés chez l'enfant de moins de 12 ans.\",\n\"simpleExplanation\": \"Le MOTILIUM est interdit aux petits.\",\n\"memoryTip\": \"Dompéridone : pas avant 12 ans 🚸\",\n\"examTrap\": \"Comme la codéine.\"\n},\n{\n\"id\": \"ndg011\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 49,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels antiémétiques sont indiqués dans les vomissements induits par la chimiothérapie ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Antagonistes 5-HT3 : ondansétron (ZOPHREN), granisétron (KYTRIL)\",\n\"Lopéramide\",\n\"Lactulose\",\n\"Misoprostol\"\n],\n\"correctAnswer\": \"Antagonistes 5-HT3 : ondansétron (ZOPHREN), granisétron (KYTRIL)\",\n\"explanation\": \"Antagonistes 5-HT3 de la sérotonine : nausées/vomissements de chimiothérapie et post-opératoires (ondansétron ZOPHREN, granisétron KYTRIL).\",\n\"simpleExplanation\": \"Ils bloquent le signal « vomir » envoyé par la chimio.\",\n\"memoryTip\": \"« -sétron » = Sérotonine = Chimio 🧪\",\n\"examTrap\": \"Le métoclopramide est un prokinétique.\"\n},\n{\n\"id\": \"ndg012\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 49,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Les neuroleptiques à visée antiémétique (dropéridol, alizapride) sont indiqués dans :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Les vomissements post-opératoires et induits par les morphiniques\",\n\"La diarrhée infectieuse\",\n\"Le RGO du nourrisson\",\n\"La constipation\"\n],\n\"correctAnswer\": \"Les vomissements post-opératoires et induits par les morphiniques\",\n\"explanation\": \"Neuroleptiques antiémétiques (dropéridol DROLEPTAN, alizapride PLITICAN, halopéridol) : NV post-opératoires et induits par les morphiniques.\",\n\"simpleExplanation\": \"Après l'opération ou la morphine, ils arrêtent les vomissements.\",\n\"memoryTip\": \"Neuroleptique antiémétique = Post-op + Morphine.\",\n\"examTrap\": \"5-HT3 = chimio.\"\n},\n{\n\"id\": \"ndg013\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 50,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le traitement de 1re intention des nausées et vomissements de la grossesse ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Pyridoxine seule ou doxylamine + pyridoxine\",\n\"Ondansétron\",\n\"Métoclopramide seul\",\n\"Dompéridone\"\n],\n\"correctAnswer\": \"Pyridoxine seule ou doxylamine + pyridoxine\",\n\"explanation\": \"La pyridoxine (B6) seule ou l'association doxylamine + pyridoxine est recommandée en 1re intention ; le gingembre peut aider ; l'ondansétron seulement en dernier recours.\",\n\"simpleExplanation\": \"La vitamine B6 est la meilleure amie de la femme enceinte qui vomit.\",\n\"memoryTip\": \"Grossesse = B6 + doxylamine 🤰\",\n\"examTrap\": \"L'ondansétron n'est utilisé qu'en cas d'échec.\"\n},\n{\n\"id\": \"ndg014\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 50,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Comment définit-on la diarrhée selon le cours ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Émission trop fréquente et rapide de selles liquides (plus de 3 selles/jour)\",\n\"Une selle dure par jour\",\n\"Absence de selles pendant 3 jours\",\n\"Selles noires\"\n],\n\"correctAnswer\": \"Émission trop fréquente et rapide de selles liquides (plus de 3 selles/jour)\",\n\"explanation\": \"Diarrhée : émission trop fréquente et rapide de selles liquides (plus de 3 selles par jour) ; ne jamais la négliger (risque de déshydratation chez le bébé).\",\n\"simpleExplanation\": \"Aller trop souvent aux toilettes avec des selles liquides.\",\n\"memoryTip\": \"Diarrhée > 3 selles/j 💧\",\n\"examTrap\": \"L'essentiel du traitement = réhydratation.\"\n},\n{\n\"id\": \"ndg015\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 51,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Les produits d'origine microbienne (ULTRA-LEVURE, LACTEOL) sont indiqués dans :\",\n\"type\": \"qcm\",\n\"options\": [\n\"La prévention des diarrhées induites par les antibiotiques\",\n\"La constipation chronique\",\n\"Le RGO\",\n\"L'ulcère à Helicobacter\"\n],\n\"correctAnswer\": \"La prévention des diarrhées induites par les antibiotiques\",\n\"explanation\": \"Produits microbiens (Saccharomyces boulardii ULTRA-LEVURE, Lactobacillus) : prévention des diarrhées induites par les antibiotiques.\",\n\"simpleExplanation\": \"Ce sont de bons microbes qui remplacent ceux tués par l'antibiotique.\",\n\"memoryTip\": \"ATB + ULTRA-LEVURE = flore protégée 🦠✅\",\n\"examTrap\": \"Ce ne sont pas des laxatifs.\"\n},\n{\n\"id\": \"ndg016\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 52,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est l'élément essentiel du traitement de la diarrhée ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"La réhydratation (SRO)\",\n\"Les antibiotiques systématiques\",\n\"Le lopéramide chez le nourrisson\",\n\"Le jeûne total\"\n],\n\"correctAnswer\": \"La réhydratation (SRO)\",\n\"explanation\": \"La réhydratation (solution de réhydratation orale, SRO) est l'essentiel du traitement de la diarrhée, avec un régime sans résidus.\",\n\"simpleExplanation\": \"Il faut remplacer toute l'eau perdue.\",\n\"memoryTip\": \"Diarrhée = SRO d'abord 🥤\",\n\"examTrap\": \"Les antibiotiques ne sont pas systématiques.\"\n},\n{\n\"id\": \"ndg017\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 52,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Le nifuroxazide (ERCEFURYL) est :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Un antiseptique intestinal (nitrofurane) à résorption quasi nulle\",\n\"Un laxatif osmotique\",\n\"Un anti-H2\",\n\"Un antiémétique\"\n],\n\"correctAnswer\": \"Un antiseptique intestinal (nitrofurane) à résorption quasi nulle\",\n\"explanation\": \"Nitrofuranes intestinaux (nifuroxazide, nifurzide) : résorption digestive pratiquement nulle, action antibactérienne locale (staphylocoques, E. coli, Salmonella, Shigella).\",\n\"simpleExplanation\": \"Il reste dans l'intestin pour y tuer les microbes.\",\n\"memoryTip\": \"ERCEFURYL = reste dans le tube.\",\n\"examTrap\": \"Il ne passe pas dans le sang.\"\n},\n{\n\"id\": \"ndg018\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 53,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des laxatifs osmotiques ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Lactulose (DUPHALAC)\",\n\"Macrogol (FORLAX)\",\n\"Sorbitol\",\n\"Bisacodyl (DULCOLAX)\"\n],\n\"correctAnswer\": [\n\"Lactulose (DUPHALAC)\",\n\"Macrogol (FORLAX)\",\n\"Sorbitol\"\n],\n\"explanation\": \"Osmotiques : lactulose, pentaérythritol, macrogol, sorbitol ; ils attirent l'eau dans le côlon. Bisacodyl = stimulant.\",\n\"simpleExplanation\": \"Ils appellent l'eau dans l'intestin pour ramollir les selles.\",\n\"memoryTip\": \"Osmotique = Aimant à eau 🧲💧\",\n\"examTrap\": \"DULCOLAX = stimulant.\"\n},\n{\n\"id\": \"ndg019\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 53,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment agit l'huile de paraffine (LANSOYL) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Par lubrification et ramollissement du contenu colique\",\n\"Par effet osmotique\",\n\"Par irritation de la paroi\",\n\"Par augmentation du volume du bol (lest)\"\n],\n\"correctAnswer\": \"Par lubrification et ramollissement du contenu colique\",\n\"explanation\": \"Laxatifs lubrifiants : huile de paraffine/vaseline (LANSOYL, LUBENTYL) : lubrification et ramollissement du contenu colique.\",\n\"simpleExplanation\": \"Elle fait glisser les selles comme de l'huile sur un toboggan.\",\n\"memoryTip\": \"Paraffine = Toboggan 🛝\",\n\"examTrap\": \"Le psyllium est un laxatif de lest.\"\n},\n{\n\"id\": \"ndg020\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 53,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quel médicament est indiqué dans la constipation liée aux opioïdes en soins palliatifs ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Bromure de méthylnaltrexone (RELISTOR)\",\n\"Prucalopride (RESOLOR)\",\n\"Lactulose\",\n\"Psyllium\"\n],\n\"correctAnswer\": \"Bromure de méthylnaltrexone (RELISTOR)\",\n\"explanation\": \"Méthylnaltrexone (RELISTOR) : constipation liée aux opioïdes en soins palliatifs après échec des laxatifs. Prucalopride : constipation chronique résistante.\",\n\"simpleExplanation\": \"Il bloque l'effet constipant de la morphine dans l'intestin.\",\n\"memoryTip\": \"RELISTOR = RELâcher le frein de la morphine.\",\n\"examTrap\": \"RESOLOR = prucalopride.\"\n},\n{\n\"id\": \"ndg021\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 54,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des conseils pour un patient sous laxatif ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Prise de préférence le matin\",\n\"Activité physique régulière\",\n\"Boire environ 1,5 L d'eau par jour\",\n\"Régime pauvre en fibres\"\n],\n\"correctAnswer\": [\n\"Prise de préférence le matin\",\n\"Activité physique régulière\",\n\"Boire environ 1,5 L d'eau par jour\"\n],\n\"explanation\": \"Conseils : prise le matin, activité physique, régime riche en fibres, apport hydrique 1,5 L/j, surveiller fréquence et consistance des selles.\",\n\"simpleExplanation\": \"Bouger, boire, manger des fibres : l'intestin adore ça.\",\n\"memoryTip\": \"3 B : Bouger, Boire, Brocolis (fibres) 🥦\",\n\"examTrap\": \"Le régime doit être RICHE en fibres.\"\n},\n{\n\"id\": \"ndg022\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 54,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quel médicament est un antilithiasique biliaire ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Acide ursodésoxycholique (DELURSAN, URSOLVAN)\",\n\"Silymarine (LEGALON)\",\n\"Hymécromone (CANTABILINE)\",\n\"Entécavir (BARACLUDE)\"\n],\n\"correctAnswer\": \"Acide ursodésoxycholique (DELURSAN, URSOLVAN)\",\n\"explanation\": \"Antilithiasiques biliaires : acides biliaires (acide ursodésoxycholique). Silymarine = hépatotrope ; hymécromone = cholérétique ; entécavir = anti-hépatite B.\",\n\"simpleExplanation\": \"Il dissout les petits cailloux de la vésicule.\",\n\"memoryTip\": \"URSO = dissout les calculs.\",\n\"examTrap\": \"BARACLUDE traite l'hépatite B.\"\n},\n{\n\"id\": \"ndg023\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 54,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des antiviraux de l'hépatite B ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Entécavir (BARACLUDE)\",\n\"Ténofovir (VIREAD)\",\n\"Adéfovir (HEPSERA)\",\n\"Ribavirine (REBETOL)\"\n],\n\"correctAnswer\": [\n\"Entécavir (BARACLUDE)\",\n\"Ténofovir (VIREAD)\",\n\"Adéfovir (HEPSERA)\"\n],\n\"explanation\": \"Anti-hépatite B : adéfovir, entécavir, ténofovir, telbivudine, interférons. Ribavirine, bocéprévir, télaprévir = hépatite C.\",\n\"simpleExplanation\": \"Le ténofovir sert à la fois pour le VIH et l'hépatite B.\",\n\"memoryTip\": \"B = Baraclude ; C = Ribavirine.\",\n\"examTrap\": \"Ribavirine = hépatite C.\"\n},\n{\n\"id\": \"ndg024\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 46,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Expliquez le mécanisme d'action du sucralfate.\",\n\"type\": \"ouverte\",\n\"answer\": \"En milieu acide, le sucralfate forme un gel visqueux chargé négativement qui se fixe sur les protéines des lésions ulcéreuses (chargées positivement). L'ulcère est isolé du contenu digestif, ce qui favorise sa cicatrisation spontanée.\",\n\"keywords\": [\n\"gel\",\n\"acide\",\n\"négativement\",\n\"positivement\",\n\"isole\",\n\"cicatrisation\"\n],\n\"explanation\": \"En milieu acide, le sucralfate forme un gel visqueux chargé négativement qui se fixe sur les protéines des lésions ulcéreuses (chargées positivement). L'ulcère est isolé du contenu digestif, ce qui favorise sa cicatrisation spontanée.\",\n\"memoryTip\": \"🩹 Sucralfate = pansement aimanté sur l'ulcère.\"\n},\n{\n\"id\": \"ndg025\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 48,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quels sont les objectifs et les moyens du traitement du RGO ?\",\n\"type\": \"ouverte\",\n\"answer\": \"Réduire l'acidité gastrique (alginates/pansements gastriques, antisécrétoires) et renforcer le tonus du sphincter inférieur de l'œsophage (prokinétiques : métoclopramide, dompéridone, cisapride) qui accélèrent la vidange et stimulent la motricité.\",\n\"keywords\": [\n\"acidité\",\n\"alginates\",\n\"antisécrétoires\",\n\"sphincter\",\n\"prokinétiques\",\n\"métoclopramide\"\n],\n\"explanation\": \"Réduire l'acidité gastrique (alginates/pansements gastriques, antisécrétoires) et renforcer le tonus du sphincter inférieur de l'œsophage (prokinétiques : métoclopramide, dompéridone, cisapride) qui accélèrent la vidange et stimulent la motricité.\",\n\"memoryTip\": \"🔥 RGO : baisser l'acide + fermer la porte.\"\n},\n{\n\"id\": \"ndg026\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 49,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les 3 classes d'antiémétiques et leurs indications.\",\n\"type\": \"ouverte\",\n\"answer\": \"Prokinétiques (métoclopramide, dompéridone, métopimazine) : nausées-vomissements, RGO, dyspepsie. Antagonistes 5-HT3 (ondansétron, granisétron) : chimiothérapie et post-opératoire. Neuroleptiques (dropéridol, alizapride, halopéridol) : post-opératoire et morphiniques.\",\n\"keywords\": [\n\"prokinétiques\",\n\"5-ht3\",\n\"ondansétron\",\n\"chimiothérapie\",\n\"neuroleptiques\",\n\"post-opératoires\"\n],\n\"explanation\": \"Prokinétiques (métoclopramide, dompéridone, métopimazine) : nausées-vomissements, RGO, dyspepsie. Antagonistes 5-HT3 (ondansétron, granisétron) : chimiothérapie et post-opératoire. Neuroleptiques (dropéridol, alizapride, halopéridol) : post-opératoire et morphiniques.\",\n\"memoryTip\": \"🤢 P-S-N : Prokinétiques, Sérotonine, Neuroleptiques.\"\n},\n{\n\"id\": \"ndg027\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 51,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Classez les anti-diarrhéiques avec un exemple par classe.\",\n\"type\": \"ouverte\",\n\"answer\": \"Ralentisseurs du transit (lopéramide IMODIUM), antisécrétoires intestinaux (racécadotril TIORFAN), produits microbiens (ULTRA-LEVURE, LACTEOL), argiles (SMECTA, ACTAPULGITE), produits végétaux (GELOPECTOSE), antibactériens intestinaux (néomycine, colistine), antiseptiques intestinaux (nifuroxazide, INTETRIX), traitement adjuvant : SRO.\",\n\"keywords\": [\n\"ralentisseurs\",\n\"lopéramide\",\n\"antisécrétoires\",\n\"racécadotril\",\n\"argiles\",\n\"smecta\",\n\"sro\"\n],\n\"explanation\": \"Ralentisseurs du transit (lopéramide IMODIUM), antisécrétoires intestinaux (racécadotril TIORFAN), produits microbiens (ULTRA-LEVURE, LACTEOL), argiles (SMECTA, ACTAPULGITE), produits végétaux (GELOPECTOSE), antibactériens intestinaux (néomycine, colistine), antiseptiques intestinaux (nifuroxazide, INTETRIX), traitement adjuvant : SRO.\",\n\"memoryTip\": \"💧 R-A-M-A-V-A + SRO : Ralentir, Antisécréter, Microbes, Argiles, Végétaux, Antiseptiques.\"\n},\n{\n\"id\": \"ndg028\",\n\"chapter\": \"Appareil digestif\",\n\"page\": 53,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les 4 grandes classes de laxatifs et leur mode d'action.\",\n\"type\": \"ouverte\",\n\"answer\": \"Osmotiques : attirent l'eau dans le côlon (lactulose, macrogol). Lubrifiants : lubrifient et ramollissent (huile de paraffine). Stimulants : irritent la paroi qui se contracte (bisacodyl). De lest : augmentent le volume du bol qui distend la paroi (psyllium, son).\",\n\"keywords\": [\n\"osmotiques\",\n\"eau\",\n\"lubrifiants\",\n\"stimulants\",\n\"irritation\",\n\"lest\",\n\"volume\"\n],\n\"explanation\": \"Osmotiques : attirent l'eau dans le côlon (lactulose, macrogol). Lubrifiants : lubrifient et ramollissent (huile de paraffine). Stimulants : irritent la paroi qui se contracte (bisacodyl). De lest : augmentent le volume du bol qui distend la paroi (psyllium, son).\",\n\"memoryTip\": \"🚽 O-L-S-L : Osmotique, Lubrifiant, Stimulant, Lest.\"\n},\n{\n\"id\": \"nsn001\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 55,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Que signifie littéralement « psychotrope » ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Qui agit sur l'esprit ou le comportement\",\n\"Qui tue les microbes\",\n\"Qui fait dormir uniquement\",\n\"Qui calme la douleur\"\n],\n\"correctAnswer\": \"Qui agit sur l'esprit ou le comportement\",\n\"explanation\": \"Psycho = esprit/comportement ; trope = qui agit, qui donne une direction. Un psychotrope agit principalement sur le système nerveux central.\",\n\"simpleExplanation\": \"Un médicament qui change l'humeur, les pensées ou le comportement.\",\n\"memoryTip\": \"PSYCHO-TROPE = agit sur la PSYCHÉ 🧠\",\n\"examTrap\": \"Il ne préjuge pas du risque de dépendance.\"\n},\n{\n\"id\": \"nsn002\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 55,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Sur quels critères repose la classification OMS (1971) des psychotropes selon le danger ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Dépendance psychique, dépendance physique, tolérance\",\n\"Sédation, euphorie, hallucination\",\n\"Prix, disponibilité, voie\",\n\"Âge, sexe, poids\"\n],\n\"correctAnswer\": \"Dépendance psychique, dépendance physique, tolérance\",\n\"explanation\": \"Classification OMS 1971 selon le danger : dépendance psychique, dépendance physique, tolérance (accoutumance).\",\n\"simpleExplanation\": \"On mesure si le produit rend accro dans la tête, dans le corps, ou s'il faut en prendre toujours plus.\",\n\"memoryTip\": \"PPT : Psychique, Physique, Tolérance.\",\n\"examTrap\": \"Les classifications juridiques : conventions 1961 et 1971.\"\n},\n{\n\"id\": \"nsn003\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 56,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des familles de psychotropes ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Anxiolytiques\",\n\"Thymorégulateurs\",\n\"Hypnotiques\",\n\"Antibiotiques\"\n],\n\"correctAnswer\": [\n\"Anxiolytiques\",\n\"Thymorégulateurs\",\n\"Hypnotiques\"\n],\n\"explanation\": \"Les 5 familles : anxiolytiques, antidépresseurs, neuroleptiques, hypnotiques, thymorégulateurs.\",\n\"simpleExplanation\": \"5 familles pour l'esprit.\",\n\"memoryTip\": \"A-A-N-H-T : Anxio, Antidép, Neuro, Hypno, Thymo.\",\n\"examTrap\": \"Les antibiotiques n'en font pas partie.\"\n},\n{\n\"id\": \"nsn004\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 56,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des anxiolytiques non benzodiazépiniques ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Buspirone\",\n\"Étifoxine\",\n\"Hydroxyzine\",\n\"Alprazolam\"\n],\n\"correctAnswer\": [\n\"Buspirone\",\n\"Étifoxine\",\n\"Hydroxyzine\"\n],\n\"explanation\": \"Anxiolytiques non BZD : buspirone, captodiamine, étifoxine, hydroxyzine, méprobamate. Alprazolam = BZD.\",\n\"simpleExplanation\": \"Ils calment l'anxiété sans être des « -azépam ».\",\n\"memoryTip\": \"Non BZD : BEHM (Buspirone, Étifoxine, Hydroxyzine, Méprobamate).\",\n\"examTrap\": \"Le suffixe « -azépam/-azolam » = benzodiazépine.\"\n},\n{\n\"id\": \"nsn005\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 56,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Que signifie « neuroleptique » ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Qui affaiblit le nerf (neuron + leptos)\",\n\"Qui stimule le nerf\",\n\"Qui détruit le nerf\",\n\"Qui répare le nerf\"\n],\n\"correctAnswer\": \"Qui affaiblit le nerf (neuron + leptos)\",\n\"explanation\": \"Neuroleptique : du grec neuron (nerf) et leptos (qui affaiblit). Effet tranquillisant, anti-délirant, contre la désorganisation de la pensée.\",\n\"simpleExplanation\": \"Il baisse l'activité excessive des nerfs.\",\n\"memoryTip\": \"NEURO-LEPTIQUE = nerf affaibli.\",\n\"examTrap\": \"On les appelle aussi antipsychotiques.\"\n},\n{\n\"id\": \"nsn006\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 57,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels effets caractérisent un neuroleptique ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Indifférence affective\",\n\"Diminution des hallucinations et du délire\",\n\"Diminution de l'agressivité\",\n\"Euphorie intense\"\n],\n\"correctAnswer\": [\n\"Indifférence affective\",\n\"Diminution des hallucinations et du délire\",\n\"Diminution de l'agressivité\"\n],\n\"explanation\": \"Neuroleptique : indifférence affective, diminution de l'agressivité/agitation, diminution des hallucinations et du délire, réduction de la psychose, effets neurologiques et neurovégétatifs.\",\n\"simpleExplanation\": \"Il éteint le délire et calme l'agitation.\",\n\"memoryTip\": \"Neuroleptique = Calme + Anti-délire.\",\n\"examTrap\": \"Pas d'euphorie.\"\n},\n{\n\"id\": \"nsn007\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 57,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des neuroleptiques atypiques ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Olanzapine\",\n\"Rispéridone\",\n\"Clozapine\",\n\"Chlorpromazine\"\n],\n\"correctAnswer\": [\n\"Olanzapine\",\n\"Rispéridone\",\n\"Clozapine\"\n],\n\"explanation\": \"Atypiques : clozapine, olanzapine, rispéridone, quétiapine, ziprasidone, aripiprazole. Chlorpromazine = phénothiazine.\",\n\"simpleExplanation\": \"Les nouveaux neuroleptiques avec moins d'effets neurologiques.\",\n\"memoryTip\": \"Atypiques en « -apine / -idone ».\",\n\"examTrap\": \"LARGACTIL/chlorpromazine = phénothiazine.\"\n},\n{\n\"id\": \"nsn008\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 57,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Pourquoi la fièvre est-elle une contre-indication absolue aux neuroleptiques ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Risque de syndrome malin pouvant entraîner le décès\",\n\"Risque d'hypoglycémie\",\n\"Risque de diarrhée\",\n\"Risque d'allergie cutanée\"\n],\n\"correctAnswer\": \"Risque de syndrome malin pouvant entraîner le décès\",\n\"explanation\": \"Contre-indication absolue : l'hyperthermie. Même une fièvre légère (38 °C) peut provoquer un syndrome malin mortel.\",\n\"simpleExplanation\": \"Avec de la fièvre, le neuroleptique peut faire « surchauffer » le corps.\",\n\"memoryTip\": \"Neuroleptique + Fièvre = Syndrome Malin ☠️🌡️\",\n\"examTrap\": \"Même à 38 °C !\"\n},\n{\n\"id\": \"nsn009\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 58,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des hypnotiques apparentés aux benzodiazépines ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Zolpidem\",\n\"Zopiclone\",\n\"Zaleplon\",\n\"Phénobarbital\"\n],\n\"correctAnswer\": [\n\"Zolpidem\",\n\"Zopiclone\",\n\"Zaleplon\"\n],\n\"explanation\": \"Apparentés aux BZD : zaleplon, zolpidem, zopiclone (les « Z-drugs »). Phénobarbital = barbiturique.\",\n\"simpleExplanation\": \"Les 3 « Z » du sommeil.\",\n\"memoryTip\": \"Z-Z-Z = sommeil 😴\",\n\"examTrap\": \"Le phénobarbital est un barbiturique.\"\n},\n{\n\"id\": \"nsn010\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 58,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelles plantes sont citées comme hypnotiques d'origine végétale ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Valériane\",\n\"Passiflore\",\n\"Tilleul\",\n\"Cannelle\"\n],\n\"correctAnswer\": [\n\"Valériane\",\n\"Passiflore\",\n\"Tilleul\"\n],\n\"explanation\": \"Plantes : valériane, mélisse, aubépine, tilleul, passiflore, gui, ballote.\",\n\"simpleExplanation\": \"Les tisanes du soir pour mieux dormir.\",\n\"memoryTip\": \"Valériane-Passiflore-Tilleul = tisane dodo 🍵\",\n\"examTrap\": \"La cannelle n'est pas citée.\"\n},\n{\n\"id\": \"nsn011\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 58,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel antiparkinsonien est un anticholinergique ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Trihexyphénidyle (ARTANE)\",\n\"Lévodopa + carbidopa (SINEMET)\",\n\"Bromocriptine\",\n\"Lévodopa + bensérazide (MODOPAR)\"\n],\n\"correctAnswer\": \"Trihexyphénidyle (ARTANE)\",\n\"explanation\": \"Anticholinergiques antiparkinsoniens : trihexyphénidyle (ARTANE, PARKINANE), tropatépine (LEPTICUR).\",\n\"simpleExplanation\": \"ARTANE calme les tremblements en bloquant l'acétylcholine.\",\n\"memoryTip\": \"ARTANE = Anti-acétylcholine.\",\n\"examTrap\": \"MODOPAR/SINEMET = lévodopa.\"\n},\n{\n\"id\": \"nsn012\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 59,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Que se passe-t-il à l'arrêt d'un traitement antiépileptique ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Les crises reprennent : le traitement est symptomatique et non curatif\",\n\"L'épilepsie est guérie définitivement\",\n\"Rien, le traitement est curatif\",\n\"Le patient devient résistant\"\n],\n\"correctAnswer\": \"Les crises reprennent : le traitement est symptomatique et non curatif\",\n\"explanation\": \"Les antiépileptiques ont une action symptomatique et non curative : l'arrêt signe la reprise des crises. Environ un tiers des épilepsies sont rebelles au traitement.\",\n\"simpleExplanation\": \"Le médicament cache les crises mais ne guérit pas la maladie.\",\n\"memoryTip\": \"Antiépileptique = Contrôle, pas Guérison.\",\n\"examTrap\": \"1/3 des épilepsies sont pharmacorésistantes.\"\n},\n{\n\"id\": \"nsn013\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 59,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des antiépileptiques cités dans le cours ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Acide valproïque (DÉPAKINE)\",\n\"Carbamazépine (TÉGRÉTOL)\",\n\"Phénobarbital (GARDÉNAL)\",\n\"Halopéridol (HALDOL)\"\n],\n\"correctAnswer\": [\n\"Acide valproïque (DÉPAKINE)\",\n\"Carbamazépine (TÉGRÉTOL)\",\n\"Phénobarbital (GARDÉNAL)\"\n],\n\"explanation\": \"Antiépileptiques : acide valproïque, phénobarbital, primidone, diazépam, clonazépam, clobazam, carbamazépine, gabapentine, lamotrigine.\",\n\"simpleExplanation\": \"DÉPAKINE, TÉGRÉTOL, GARDÉNAL : les grands classiques.\",\n\"memoryTip\": \"DTG : Dépakine, Tégrétol, Gardénal ⚡\",\n\"examTrap\": \"HALDOL est un neuroleptique.\"\n},\n{\n\"id\": \"nsn014\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 56,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les 5 grandes familles de médicaments psychotropes.\",\n\"type\": \"ouverte\",\n\"answer\": \"Anxiolytiques, antidépresseurs, neuroleptiques (antipsychotiques), hypnotiques, thymorégulateurs.\",\n\"keywords\": [\n\"anxiolytiques\",\n\"antidépresseurs\",\n\"neuroleptiques\",\n\"hypnotiques\",\n\"thymorégulateurs\"\n],\n\"explanation\": \"Anxiolytiques, antidépresseurs, neuroleptiques (antipsychotiques), hypnotiques, thymorégulateurs.\",\n\"memoryTip\": \"🧠 « AA-NHT » : Anxio, Antidép, Neuro, Hypno, Thymo.\"\n},\n{\n\"id\": \"nsn015\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 57,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Citez les 4 classes de neuroleptiques avec un exemple chacune et leur contre-indication absolue.\",\n\"type\": \"ouverte\",\n\"answer\": \"Phénothiazines (chlorpromazine, lévomépromazine), butyrophénones (halopéridol, dropéridol), thioxanthènes (flupentixol, zuclopenthixol), atypiques (clozapine, olanzapine, rispéridone). Contre-indication absolue : l'hyperthermie (risque de syndrome malin mortel).\",\n\"keywords\": [\n\"phénothiazines\",\n\"butyrophénones\",\n\"halopéridol\",\n\"thioxanthènes\",\n\"atypiques\",\n\"hyperthermie\",\n\"syndrome malin\"\n],\n\"explanation\": \"Phénothiazines (chlorpromazine, lévomépromazine), butyrophénones (halopéridol, dropéridol), thioxanthènes (flupentixol, zuclopenthixol), atypiques (clozapine, olanzapine, rispéridone). Contre-indication absolue : l'hyperthermie (risque de syndrome malin mortel).\",\n\"memoryTip\": \"🌡️ P-B-T-A et JAMAIS avec la fièvre.\"\n},\n{\n\"id\": \"nsn016\",\n\"chapter\": \"Médicaments du SNC (Psychotropes)\",\n\"page\": 58,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Définissez les hypnotiques et citez leurs classes.\",\n\"type\": \"ouverte\",\n\"answer\": \"Médicaments qui induisent le sommeil chez les patients ayant des difficultés d'endormissement et/ou des réveils précoces. Classes : barbituriques, benzodiazépines, apparentés aux BZD (zolpidem, zopiclone, zaleplon), non barbituriques/phénothiazines sédatives (doxylamine, alimémazine, prométhazine), plantes (valériane, passiflore).\",\n\"keywords\": [\n\"sommeil\",\n\"endormissement\",\n\"barbituriques\",\n\"benzodiazépines\",\n\"zolpidem\",\n\"plantes\"\n],\n\"explanation\": \"Médicaments qui induisent le sommeil chez les patients ayant des difficultés d'endormissement et/ou des réveils précoces. Classes : barbituriques, benzodiazépines, apparentés aux BZD (zolpidem, zopiclone, zaleplon), non barbituriques/phénothiazines sédatives (doxylamine, alimémazine, prométhazine), plantes (valériane, passiflore).\",\n\"memoryTip\": \"😴 Hypnos = dieu du sommeil.\"\n},\n{\n\"id\": \"ngy001\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 61,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Où sont principalement produits les œstrogènes ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Par les follicules ovariens et le placenta\",\n\"Par le corps jaune uniquement\",\n\"Par l'hypophyse\",\n\"Par les testicules uniquement\"\n],\n\"correctAnswer\": \"Par les follicules ovariens et le placenta\",\n\"explanation\": \"Les œstrogènes sont produits en premier lieu par les follicules ovariens et par le placenta ; ils déterminent les caractères sexuels féminins secondaires.\",\n\"simpleExplanation\": \"Les œstrogènes sont fabriqués dans les petites bulles de l'ovaire.\",\n\"memoryTip\": \"Œstrogènes = Follicules 🌸\",\n\"examTrap\": \"La progestérone vient du corps jaune.\"\n},\n{\n\"id\": \"ngy002\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 61,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quelle est l'indication du Diéthylstilbestrol (DISTILBENE) dans le cours ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Anticancéreux pour le cancer de la prostate\",\n\"Contraception d'urgence\",\n\"Sécheresse vaginale\",\n\"Induction de l'ovulation\"\n],\n\"correctAnswer\": \"Anticancéreux pour le cancer de la prostate\",\n\"explanation\": \"DISTILBENE : anticancéreux pour le cancer de la prostate ; Estradiol : œstrogénothérapie substitutive ; Promestriène : affections vulvo-vaginales.\",\n\"simpleExplanation\": \"Un œstrogène utilisé contre le cancer de l'homme.\",\n\"memoryTip\": \"DISTILBENE = Prostate.\",\n\"examTrap\": \"COLPOTROPHINE = vulvo-vaginal.\"\n},\n{\n\"id\": \"ngy003\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 62,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Par quelles cellules la progestérone est-elle principalement sécrétée ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Les cellules du corps jaune et le placenta\",\n\"Les follicules en croissance\",\n\"Les cellules bêta du pancréas\",\n\"Les surrénales uniquement\"\n],\n\"correctAnswer\": \"Les cellules du corps jaune et le placenta\",\n\"explanation\": \"La progestérone est sécrétée par le corps jaune et le placenta ; elle prépare l'utérus à la grossesse et augmente après l'ovulation.\",\n\"simpleExplanation\": \"La progestérone protège la grossesse : pro-gestation.\",\n\"memoryTip\": \"PRO-GESTÉRONE = POUR la GESTATION 🤰\",\n\"examTrap\": \"Les œstrogènes viennent des follicules.\"\n},\n{\n\"id\": \"ngy004\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 62,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des progestatifs cités dans le cours ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Progestérone (UTROGESTAN)\",\n\"Didrogestérone (DUPHASTON)\",\n\"Nomégestrol (LUTENYL)\",\n\"Testostérone (ANDROGEL)\"\n],\n\"correctAnswer\": [\n\"Progestérone (UTROGESTAN)\",\n\"Didrogestérone (DUPHASTON)\",\n\"Nomégestrol (LUTENYL)\"\n],\n\"explanation\": \"Progestatifs : progestérone (UTROGESTAN, LUTTAGEN), didrogestérone (DUPHASTON), hydroxyprogestérone, nomégestrol (LUTENYL).\",\n\"simpleExplanation\": \"« -gest- » dans le nom = progestatif.\",\n\"memoryTip\": \"« GEST » = progestatif.\",\n\"examTrap\": \"ANDROGEL = androgène.\"\n},\n{\n\"id\": \"ngy005\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 63,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lequel est un inducteur de l'ovulation ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Clomifène (CLOMID)\",\n\"Danazol (DANATROL)\",\n\"Estradiol (OESTROGEL)\",\n\"Atosiban\"\n],\n\"correctAnswer\": \"Clomifène (CLOMID)\",\n\"explanation\": \"Inducteurs d'ovulation : clomifène (CLOMID), follitropine (GONAL-F, PUREGON), ménotropine (MENOPUR), HCG, lutropine...\",\n\"simpleExplanation\": \"CLOMID aide l'ovaire à libérer un ovule.\",\n\"memoryTip\": \"CLOMID = Coup de pouce à l'ovulation 🥚\",\n\"examTrap\": \"DANATROL = androgène.\"\n},\n{\n\"id\": \"ngy006\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 63,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des indications de l'ocytocine (SYNTOCINON) ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Insuffisance de contraction utérine pendant le travail\",\n\"Atonie utérine du post-partum\",\n\"Rétraction utérine après césarienne\",\n\"Menace d'accouchement prématuré\"\n],\n\"correctAnswer\": [\n\"Insuffisance de contraction utérine pendant le travail\",\n\"Atonie utérine du post-partum\",\n\"Rétraction utérine après césarienne\"\n],\n\"explanation\": \"Ocytocine : insuffisance des contractions, rétraction utérine après naissance par césarienne, atonie post-partum et hémorragie de la délivrance. La MAP relève des utérorelaxants.\",\n\"simpleExplanation\": \"L'ocytocine fait contracter l'utérus.\",\n\"memoryTip\": \"Ocytocine = Contracter ; Atosiban = Relâcher.\",\n\"examTrap\": \"La MAP = utérorelaxants (contraire).\"\n},\n{\n\"id\": \"ngy007\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 64,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quelle prostaglandine est indiquée pour la maturation cervicale à terme ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"PREPIDIL\",\n\"Sulprostone (NALADOR)\",\n\"Géméprost (CERVAGEME)\",\n\"Misoprostol (CYTOTEC)\"\n],\n\"correctAnswer\": \"PREPIDIL\",\n\"explanation\": \"Prostaglandines ocytociques (dinoprostones) : PROSTINE E2 (avortement thérapeutique, déclenchement) ; PREPIDIL (maturation cervicale à terme) ; NALADOR (avortement 2e trimestre) ; CERVAGEME (préparation du col).\",\n\"simpleExplanation\": \"PREPIDIL PRÉPARE le col pour l'accouchement.\",\n\"memoryTip\": \"PREPIDIL = PRÉPArer le col.\",\n\"examTrap\": \"NALADOR = 2e trimestre.\"\n},\n{\n\"id\": \"ngy008\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 65,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle est la durée d'action de l'implant contraceptif ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"3 ans\",\n\"1 mois\",\n\"3 mois\",\n\"1 semaine\"\n],\n\"correctAnswer\": \"3 ans\",\n\"explanation\": \"Pilule : quotidienne ; timbre : hebdomadaire ; anneau : mensuel ; injection : trimestrielle ; implant : 3 ans.\",\n\"simpleExplanation\": \"Un petit bâtonnet sous la peau qui protège 3 ans.\",\n\"memoryTip\": \"Pilule 1j · Patch 1 sem · Anneau 1 mois · Injection 3 mois · Implant 3 ans.\",\n\"examTrap\": \"L'injection dure 3 mois, pas l'implant.\"\n},\n{\n\"id\": \"ngy009\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 66,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Combien de temps dure une injection de médroxyprogestérone (DEPO-PROVERA) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"12 semaines\",\n\"8 semaines\",\n\"4 semaines\",\n\"1 an\"\n],\n\"correctAnswer\": \"12 semaines\",\n\"explanation\": \"DEPO-PROVERA (médroxyprogestérone) : 12 semaines ; NORISTERAT (noréthistérone) : 8 semaines.\",\n\"simpleExplanation\": \"Une piqûre tous les 3 mois.\",\n\"memoryTip\": \"DEPO = 12 sem ; NORISTERAT = 8 sem.\",\n\"examTrap\": \"Ne pas inverser les deux durées.\"\n},\n{\n\"id\": \"ngy010\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 66,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Le désogestrel (CERAZETTE) est un progestatif de quelle génération ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"3e génération\",\n\"1re génération\",\n\"2e génération\",\n\"4e génération\"\n],\n\"correctAnswer\": \"3e génération\",\n\"explanation\": \"1re : noréthistérone ; 2e : lévonorgestrel, norgestrel ; 3e : gestodène, désogestrel, norgestimate ; 4e : drospirénone, chlormadinone, diénogest, nomégestrol.\",\n\"simpleExplanation\": \"CERAZETTE fait partie de la 3e vague.\",\n\"memoryTip\": \"3G : Gestodène, Désogestrel, norGestimate.\",\n\"examTrap\": \"Le lévonorgestrel est de 2e génération.\"\n},\n{\n\"id\": \"ngy011\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 67,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Dans quel délai maximal l'ulipristal (ELLAONE) doit-il être pris ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"120 heures (5 jours)\",\n\"72 heures\",\n\"24 heures\",\n\"7 jours\"\n],\n\"correctAnswer\": \"120 heures (5 jours)\",\n\"explanation\": \"Ulipristal 30 mg : au plus tard 120 h ; lévonorgestrel 1,5 mg : au plus tard 72 h ; DIU au cuivre : au plus tard 120 h.\",\n\"simpleExplanation\": \"ELLAONE laisse un peu plus de temps : 5 jours.\",\n\"memoryTip\": \"LNG = 3 jours ; ELLAONE = 5 jours ; DIU = 5 jours.\",\n\"examTrap\": \"Le lévonorgestrel = 72 h.\"\n},\n{\n\"id\": \"ngy012\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 67,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des caractéristiques de la contraception d'urgence ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Utilisation exceptionnelle\",\n\"Ne remplace pas une contraception régulière\",\n\"N'interrompt pas une grossesse déjà en cours\",\n\"Efficace à 100 %\"\n],\n\"correctAnswer\": [\n\"Utilisation exceptionnelle\",\n\"Ne remplace pas une contraception régulière\",\n\"N'interrompt pas une grossesse déjà en cours\"\n],\n\"explanation\": \"La CU est exceptionnelle, ne remplace pas une contraception régulière (surdosage hormonal), n'est pas abortive, échoue dans 5 à 42 % des cas.\",\n\"simpleExplanation\": \"C'est une roue de secours, pas une habitude.\",\n\"memoryTip\": \"CU = Exceptionnelle, non abortive, pas 100 %.\",\n\"examTrap\": \"Échec possible de 5 à 42 %.\"\n},\n{\n\"id\": \"ngy013\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 68,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des indications des bêta-stimulants utérorelaxants (salbutamol, terbutaline) ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Menace d'accouchement prématuré\",\n\"Prophylaxie des contractions lors d'un cerclage\",\n\"Tocolyse avant césarienne\",\n\"Hémorragie de la délivrance\"\n],\n\"correctAnswer\": [\n\"Menace d'accouchement prématuré\",\n\"Prophylaxie des contractions lors d'un cerclage\",\n\"Tocolyse avant césarienne\"\n],\n\"explanation\": \"Utérorelaxants bêta-stimulants : MAP, prophylaxie des contractions après 12 SA lors d'interventions/cerclage, dystocie dynamique, hypercinésie, tocolyse avant césarienne, souffrance fœtale.\",\n\"simpleExplanation\": \"Ils relâchent l'utérus trop pressé.\",\n\"memoryTip\": \"Bêta-2 relâche : bronches ET utérus.\",\n\"examTrap\": \"L'hémorragie de la délivrance nécessite des ocytociques.\"\n},\n{\n\"id\": \"ngy014\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 63,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Définissez les ocytociques et citez-en deux avec leurs indications.\",\n\"type\": \"ouverte\",\n\"answer\": \"Médicaments destinés à provoquer des contractions de l'utérus gravide pour expulser le fœtus, induire ou accélérer le travail, ou assurer une bonne rétraction utérine après l'accouchement. Méthylergométrine (METHERGIN) : hémorragies de la délivrance et du post-partum, curetage, atonie. Ocytocine (SYNTOCINON) : insuffisance de contraction en travail, rétraction après césarienne, atonie post-partum.\",\n\"keywords\": [\n\"contractions\",\n\"utérus\",\n\"travail\",\n\"méthylergométrine\",\n\"ocytocine\",\n\"hémorragie\",\n\"atonie\"\n],\n\"explanation\": \"Médicaments destinés à provoquer des contractions de l'utérus gravide pour expulser le fœtus, induire ou accélérer le travail, ou assurer une bonne rétraction utérine après l'accouchement. Méthylergométrine (METHERGIN) : hémorragies de la délivrance et du post-partum, curetage, atonie. Ocytocine (SYNTOCINON) : insuffisance de contraction en travail, rétraction après césarienne, atonie post-partum.\",\n\"memoryTip\": \"🤰 Ocytocique = Ocytocine = contraction.\"\n},\n{\n\"id\": \"ngy015\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 65,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Citez les 3 mécanismes de la contraception hormonale et 4 voies d'administration.\",\n\"type\": \"ouverte\",\n\"answer\": \"Blocage de l'ovulation, épaississement de la glaire cervicale (obstacle aux spermatozoïdes), amincissement de l'endomètre (obstacle à la nidation). Voies : orale (pilule), cutanée (timbre), sous-cutanée (implant), intramusculaire (injection), vaginale (anneau).\",\n\"keywords\": [\n\"ovulation\",\n\"glaire\",\n\"endomètre\",\n\"nidation\",\n\"pilule\",\n\"implant\",\n\"anneau\"\n],\n\"explanation\": \"Blocage de l'ovulation, épaississement de la glaire cervicale (obstacle aux spermatozoïdes), amincissement de l'endomètre (obstacle à la nidation). Voies : orale (pilule), cutanée (timbre), sous-cutanée (implant), intramusculaire (injection), vaginale (anneau).\",\n\"memoryTip\": \"🛑 3 barrières : pas d'ovule, pas de passage, pas de nid.\"\n},\n{\n\"id\": \"ngy016\",\n\"chapter\": \"Hormonaux gynécologiques\",\n\"page\": 67,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les situations où la contraception d'urgence est indiquée.\",\n\"type\": \"ouverte\",\n\"answer\": \"Rapport sans contraception, accident de préservatif ou de diaphragme, oubli de pilule, retrait trop tardif, viol.\",\n\"keywords\": [\n\"préservatif\",\n\"oubli\",\n\"pilule\",\n\"retrait\",\n\"viol\"\n],\n\"explanation\": \"Rapport sans contraception, accident de préservatif ou de diaphragme, oubli de pilule, retrait trop tardif, viol.\",\n\"memoryTip\": \"🆘 Pas de contraception, Accident, Oubli, Retrait, Viol.\"\n},\n{\n\"id\": \"ncv001\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 69,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Les sympathomimétiques (adrénaline, dobutamine) sont utilisés pour :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Augmenter la contractilité cardiaque et la pression artérielle (insuffisance cardiaque, choc anaphylactique)\",\n\"Ralentir le rythme cardiaque\",\n\"Faire baisser la tension\",\n\"Fluidifier le sang\"\n],\n\"correctAnswer\": \"Augmenter la contractilité cardiaque et la pression artérielle (insuffisance cardiaque, choc anaphylactique)\",\n\"explanation\": \"Sympathomimétiques : augmentent l'amplitude des contractions et la pression artérielle en cas d'insuffisance cardiaque ou de choc anaphylactique (adrénaline ANAPEN, dopamine, dobutamine...).\",\n\"simpleExplanation\": \"Ils donnent un coup de fouet au cœur.\",\n\"memoryTip\": \"Sympathomimétique = Accélérateur 🏎️\",\n\"examTrap\": \"Les bêtabloquants sont l'inverse.\"\n},\n{\n\"id\": \"ncv002\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 69,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels sont les effets des bêtabloquants sur le cœur ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Baisse du débit, diminution de la contractilité, ralentissement du rythme\",\n\"Augmentation du débit et du rythme\",\n\"Vasodilatation coronaire directe\",\n\"Augmentation de la diurèse\"\n],\n\"correctAnswer\": \"Baisse du débit, diminution de la contractilité, ralentissement du rythme\",\n\"explanation\": \"Les bêtabloquants entraînent une baisse du débit, une diminution de la contractilité et un ralentissement du rythme.\",\n\"simpleExplanation\": \"Ils mettent le cœur en mode « économie ».\",\n\"memoryTip\": \"Bêtabloquant = Frein du cœur 🛑\",\n\"examTrap\": \"Le contraire des sympathomimétiques.\"\n},\n{\n\"id\": \"ncv003\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 69,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des indications per os des bêtabloquants ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Hypertension artérielle\",\n\"Angor\",\n\"Migraine (certains)\",\n\"Choc anaphylactique\"\n],\n\"correctAnswer\": [\n\"Hypertension artérielle\",\n\"Angor\",\n\"Migraine (certains)\"\n],\n\"explanation\": \"Per os : HTA, angor, anti-arythmique, antimigraineux pour certains. En réanimation : angor instable, infarctus, troubles du rythme.\",\n\"simpleExplanation\": \"Ils protègent le cœur et la tête.\",\n\"memoryTip\": \"HTA + Angor + Arythmie + Migraine.\",\n\"examTrap\": \"Le choc anaphylactique = adrénaline.\"\n},\n{\n\"id\": \"ncv004\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 69,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Lesquels sont des bêtabloquants cardio-sélectifs ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Aténolol (TENORMINE)\",\n\"Bisoprolol (DETENSIEL)\",\n\"Nébivolol (NEBILOX)\",\n\"Propranolol (AVLOCARDYL)\"\n],\n\"correctAnswer\": [\n\"Aténolol (TENORMINE)\",\n\"Bisoprolol (DETENSIEL)\",\n\"Nébivolol (NEBILOX)\"\n],\n\"explanation\": \"Cardio-sélectifs : aténolol, bétaxolol, bisoprolol, métoprolol, acébutolol, céliprolol, nébivolol, esmolol. Propranolol = non cardio-sélectif.\",\n\"simpleExplanation\": \"Ils visent surtout le cœur et épargnent les bronches.\",\n\"memoryTip\": \"« A-B-M-N » cardio-sélectifs ; Propranolol = non sélectif.\",\n\"examTrap\": \"Le propranolol n'est pas cardio-sélectif.\"\n},\n{\n\"id\": \"ncv005\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 70,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment agissent les inhibiteurs calciques ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Ils inhibent l'entrée du calcium dans les cellules myocardiques et musculaires lisses artérielles\",\n\"Ils bloquent l'enzyme de conversion\",\n\"Ils augmentent l'élimination du sodium\",\n\"Ils bloquent les récepteurs bêta\"\n],\n\"correctAnswer\": \"Ils inhibent l'entrée du calcium dans les cellules myocardiques et musculaires lisses artérielles\",\n\"explanation\": \"Les inhibiteurs calciques inhibent l'entrée du calcium : diminution de la contractilité, vasodilatation (notamment coronaire), baisse de la TA et de la conduction AV.\",\n\"simpleExplanation\": \"Sans calcium, le muscle des artères se relâche.\",\n\"memoryTip\": \"Ca²⁺ bloqué = artère relâchée.\",\n\"examTrap\": \"Les IEC bloquent l'enzyme de conversion.\"\n},\n{\n\"id\": \"ncv006\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 70,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des inhibiteurs calciques ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Amlodipine (AMLOR)\",\n\"Nifédipine (ADALATE)\",\n\"Vérapamil (ISOPTINE)\",\n\"Losartan (COZAAR)\"\n],\n\"correctAnswer\": [\n\"Amlodipine (AMLOR)\",\n\"Nifédipine (ADALATE)\",\n\"Vérapamil (ISOPTINE)\"\n],\n\"explanation\": \"Inhibiteurs calciques : diltiazem, vérapamil, amlodipine, félodipine, nicardipine, nifédipine, lercanidipine... Losartan = sartan.\",\n\"simpleExplanation\": \"Beaucoup finissent en « -dipine ».\",\n\"memoryTip\": \"« -dipine » = calcium bloqué.\",\n\"examTrap\": \"COZAAR = ARA II.\"\n},\n{\n\"id\": \"ncv007\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 70,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Les dérivés nitrés (RISORDAN) sont :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Des vasodilatateurs artériels et veineux\",\n\"Des diurétiques\",\n\"Des cardiotoniques\",\n\"Des antiagrégants\"\n],\n\"correctAnswer\": \"Des vasodilatateurs artériels et veineux\",\n\"explanation\": \"Dérivés nitrés : vasodilatateurs mixtes (artériels et veineux), indiqués dans l'angor, l'infarctus aigu, l'insuffisance ventriculaire gauche et l'OAP.\",\n\"simpleExplanation\": \"Ils ouvrent toutes les « routes » du sang.\",\n\"memoryTip\": \"Nitrés = grands ouvreurs 🚪\",\n\"examTrap\": \"Pas d'effet diurétique.\"\n},\n{\n\"id\": \"ncv008\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 71,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le principal effet secondaire des digitaliques ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"L'intoxication digitalique\",\n\"L'hypoglycémie\",\n\"La toux sèche\",\n\"La photosensibilisation\"\n],\n\"correctAnswer\": \"L'intoxication digitalique\",\n\"explanation\": \"Principal effet secondaire des cardiotoniques (digoxine, hémigoxine) : intoxication digitalique, et dès qu'elle apparaît il est trop tard.\",\n\"simpleExplanation\": \"Entre bonne dose et poison, la marge est petite.\",\n\"memoryTip\": \"Digoxine = marge étroite ⚠️\",\n\"examTrap\": \"La toux sèche est typique des IEC.\"\n},\n{\n\"id\": \"ncv009\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 71,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des IEC ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Énalapril (RENITEC)\",\n\"Périndopril (COVERSYL)\",\n\"Captopril (LOPRIL)\",\n\"Valsartan (TAREG)\"\n],\n\"correctAnswer\": [\n\"Énalapril (RENITEC)\",\n\"Périndopril (COVERSYL)\",\n\"Captopril (LOPRIL)\"\n],\n\"explanation\": \"IEC : énalapril, lisinopril, périndopril, ramipril, captopril... Valsartan = ARA II.\",\n\"simpleExplanation\": \"« -pril » = IEC.\",\n\"memoryTip\": \"« -PRIL » = IEC ; « -SARTAN » = ARA II.\",\n\"examTrap\": \"TAREG est un sartan.\"\n},\n{\n\"id\": \"ncv010\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 71,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment les IEC agissent-ils sur l'aldostérone ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Ils diminuent ou inhibent sa synthèse\",\n\"Ils l'augmentent\",\n\"Ils n'ont aucun effet\",\n\"Ils la remplacent\"\n],\n\"correctAnswer\": \"Ils diminuent ou inhibent sa synthèse\",\n\"explanation\": \"L'angiotensine II stimule l'aldostérone (rétention de sodium et d'eau) ; les IEC, en bloquant l'angiotensine II, diminuent ou inhibent la synthèse d'aldostérone.\",\n\"simpleExplanation\": \"Moins d'aldostérone = moins d'eau retenue = tension plus basse.\",\n\"memoryTip\": \"IEC ↓ Angio II ↓ Aldostérone ↓ TA.\",\n\"examTrap\": \"Les diurétiques hyperkaliémiants bloquent l'aldostérone à un autre niveau.\"\n},\n{\n\"id\": \"ncv011\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 72,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des diurétiques hyperkaliémiants ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Spironolactone (ALDACTONE)\",\n\"Éplérénone (INSPRA)\",\n\"Amiloride (MODAMIDE)\",\n\"Furosémide (LASILIX)\"\n],\n\"correctAnswer\": [\n\"Spironolactone (ALDACTONE)\",\n\"Éplérénone (INSPRA)\",\n\"Amiloride (MODAMIDE)\"\n],\n\"explanation\": \"Hyperkaliémiants (épargneurs de potassium) : spironolactone, éplérénone, canrénoate de potassium, amiloride. Furosémide = hypokaliémiant.\",\n\"simpleExplanation\": \"Ils gardent le potassium dans le corps.\",\n\"memoryTip\": \"ALDACTONE = garde le K⁺.\",\n\"examTrap\": \"LASILIX fait perdre du potassium.\"\n},\n{\n\"id\": \"ncv012\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 72,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"L'hydrochlorothiazide (ESIDREX) est un diurétique :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Thiazidique hypokaliémiant\",\n\"De l'anse\",\n\"Hyperkaliémiant\",\n\"Osmotique\"\n],\n\"correctAnswer\": \"Thiazidique hypokaliémiant\",\n\"explanation\": \"Diurétiques thiazidiques (hypokaliémiants) : hydrochlorothiazide (action courte), chlortalidone (action prolongée).\",\n\"simpleExplanation\": \"Il fait uriner et perdre du potassium.\",\n\"memoryTip\": \"« -thiazide » = thiazidique.\",\n\"examTrap\": \"Le mannitol est osmotique.\"\n},\n{\n\"id\": \"ncv013\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 73,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quel diurétique est un inhibiteur de l'anhydrase carbonique ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Acétazolamide (DIAMOX)\",\n\"Mannitol\",\n\"Indapamide (FLUDEX)\",\n\"Bumétanide (BURINEX)\"\n],\n\"correctAnswer\": \"Acétazolamide (DIAMOX)\",\n\"explanation\": \"Inhibiteur de l'anhydrase carbonique : acétazolamide (DIAMOX). Mannitol = osmotique ; indapamide = diurétique antihypertenseur ; bumétanide = de l'anse.\",\n\"simpleExplanation\": \"DIAMOX est un diurétique particulier.\",\n\"memoryTip\": \"DIAMOX = Anhydrase.\",\n\"examTrap\": \"Le mannitol est osmotique.\"\n},\n{\n\"id\": \"ncv014\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 73,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Pourquoi le cours met-il en garde contre la prescription d'antiarythmiques pour des arythmies bénignes ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Il n'existe pas d'antiarythmique mineur inoffensif\",\n\"Ils sont trop chers\",\n\"Ils sont inefficaces\",\n\"Ils provoquent une hypoglycémie\"\n],\n\"correctAnswer\": \"Il n'existe pas d'antiarythmique mineur inoffensif\",\n\"explanation\": \"Les antiarythmiques sont trop souvent prescrits pour des arythmies bénignes, ce qui est dangereux : il n'y a pas d'antiarythmique mineur inoffensif.\",\n\"simpleExplanation\": \"Même un « petit » médicament du rythme peut dérégler le cœur.\",\n\"memoryTip\": \"Pas d'antiarythmique gentil ⚠️\",\n\"examTrap\": \"Amiodarone (CORDARONE) en fait partie.\"\n},\n{\n\"id\": \"ncv015\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 73,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels antihypertenseurs sont d'action centrale ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Clonidine (CATAPRESSAN)\",\n\"Méthyldopa (ALDOMET)\",\n\"Rilménidine (HYPERIUM)\",\n\"Minoxidil (LONOTEN)\"\n],\n\"correctAnswer\": [\n\"Clonidine (CATAPRESSAN)\",\n\"Méthyldopa (ALDOMET)\",\n\"Rilménidine (HYPERIUM)\"\n],\n\"explanation\": \"Antihypertenseurs centraux : rilménidine, moxonidine, clonidine, méthyldopa. Minoxidil = vasodilatateur.\",\n\"simpleExplanation\": \"Ils calment la tension depuis le cerveau.\",\n\"memoryTip\": \"Centraux : CMRM (Clonidine, Méthyldopa, Rilménidine, Moxonidine).\",\n\"examTrap\": \"Le minoxidil est vasodilatateur.\"\n},\n{\n\"id\": \"ncv016\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 74,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"L'Aliskiren (RASILEZ) est un :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Inhibiteur de la rénine\",\n\"IEC\",\n\"ARA II\",\n\"Bêtabloquant\"\n],\n\"correctAnswer\": \"Inhibiteur de la rénine\",\n\"explanation\": \"Aliskiren (RASILEZ) : antihypertenseur inhibiteur direct de la rénine.\",\n\"simpleExplanation\": \"Il bloque la toute première étape du système rénine.\",\n\"memoryTip\": \"ALISKIREN = anti-RÉNINE.\",\n\"examTrap\": \"Pas un IEC.\"\n},\n{\n\"id\": \"ncv017\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 74,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des correcteurs de l'hypotension ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Midodrine (GUTRON)\",\n\"Heptaminol (HEPT-A-MYL)\",\n\"Étiléfrine (EFFORTIL)\",\n\"Amlodipine (AMLOR)\"\n],\n\"correctAnswer\": [\n\"Midodrine (GUTRON)\",\n\"Heptaminol (HEPT-A-MYL)\",\n\"Étiléfrine (EFFORTIL)\"\n],\n\"explanation\": \"Correcteurs des hypotensions : midodrine, phényléphrine, heptaminol, étiléfrine, cafédrine + théodrénaline (PRAXINOR).\",\n\"simpleExplanation\": \"Ils remontent la tension trop basse.\",\n\"memoryTip\": \"GUTRON-HEPTAMYL-EFFORTIL = remonte la TA ⬆️\",\n\"examTrap\": \"L'amlodipine fait baisser la tension.\"\n},\n{\n\"id\": \"ncv018\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 74,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des antiagrégants plaquettaires ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Clopidogrel (PLAVIX)\",\n\"Aspirine\",\n\"Ticagrélor (BRILIQUE)\",\n\"Streptokinase\"\n],\n\"correctAnswer\": [\n\"Clopidogrel (PLAVIX)\",\n\"Aspirine\",\n\"Ticagrélor (BRILIQUE)\"\n],\n\"explanation\": \"Antiagrégants : clopidogrel, aspirine, ticlopidine, prasugrel, dipyridamole, ticagrélor... Streptokinase = thrombolytique.\",\n\"simpleExplanation\": \"Ils empêchent les plaquettes de s'agglutiner.\",\n\"memoryTip\": \"PLAVIX + Aspirine = plaquettes séparées.\",\n\"examTrap\": \"Les thrombolytiques dissolvent le caillot déjà formé.\"\n},\n{\n\"id\": \"ncv019\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 74,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quelle est la différence entre antiagrégant et thrombolytique ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"L'antiagrégant empêche l'agrégation ; le thrombolytique dissout un caillot formé\",\n\"Ce sont des synonymes\",\n\"Le thrombolytique empêche l'agrégation\",\n\"L'antiagrégant dissout le caillot\"\n],\n\"correctAnswer\": \"L'antiagrégant empêche l'agrégation ; le thrombolytique dissout un caillot formé\",\n\"explanation\": \"Antiagrégants (aspirine, clopidogrel) : préviennent l'agrégation plaquettaire. Thrombolytiques (altéplase, ténectéplase, streptokinase, urokinase) : dissolvent le caillot.\",\n\"simpleExplanation\": \"Antiagrégant = prévenir ; thrombolytique = détruire le bouchon.\",\n\"memoryTip\": \"Thrombo-LYSE = casser le caillot 🔨\",\n\"examTrap\": \"Ne pas confondre prévention et lyse.\"\n},\n{\n\"id\": \"ncv020\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 75,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des indications des veinotoniques ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Jambes lourdes\",\n\"Varices\",\n\"Hémorroïdes\",\n\"Hypertension artérielle\"\n],\n\"correctAnswer\": [\n\"Jambes lourdes\",\n\"Varices\",\n\"Hémorroïdes\"\n],\n\"explanation\": \"Veinotoniques (diosmine DAFLON, troxérutine...) : jambes lourdes, varices, hémorroïdes, pétéchies, purpuras, épistaxis, gingivorragies.\",\n\"simpleExplanation\": \"Ils renforcent les petites veines.\",\n\"memoryTip\": \"DAFLON = jambes et hémorroïdes 🦵\",\n\"examTrap\": \"Pas d'indication dans l'HTA.\"\n},\n{\n\"id\": \"ncv021\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 75,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"À quoi servent les sclérosants veineux (AETOXISCLEROL) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Traiter les varices en sclérosant la veine\",\n\"Faire baisser la tension\",\n\"Dissoudre les caillots\",\n\"Accélérer le rythme cardiaque\"\n],\n\"correctAnswer\": \"Traiter les varices en sclérosant la veine\",\n\"explanation\": \"Sclérosants veineux : glycérine chromée, lauromacrogol 400 (AETOXISCLEROL), tétradécylsulfate de sodium : utilisés dans le traitement des varices.\",\n\"simpleExplanation\": \"On injecte un produit qui ferme la varice.\",\n\"memoryTip\": \"SCLÉROSANT = ferme la veine.\",\n\"examTrap\": \"Ce ne sont pas des thrombolytiques.\"\n},\n{\n\"id\": \"ncv022\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 71,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Expliquez la règle des 3R (règle de Potain) des digitaliques.\",\n\"type\": \"ouverte\",\n\"answer\": \"Les digitaliques (digoxine, hémigoxine) Renforcent la contraction cardiaque, Régularisent le rythme et Ralentissent le rythme cardiaque. Risque principal : intoxication digitalique.\",\n\"keywords\": [\n\"renforce\",\n\"régularise\",\n\"ralentit\",\n\"digoxine\",\n\"intoxication\"\n],\n\"explanation\": \"Les digitaliques (digoxine, hémigoxine) Renforcent la contraction cardiaque, Régularisent le rythme et Ralentissent le rythme cardiaque. Risque principal : intoxication digitalique.\",\n\"memoryTip\": \"❤️ 3R : Renforcer, Régulariser, Ralentir.\"\n},\n{\n\"id\": \"ncv023\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 72,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Citez les classes de diurétiques avec un exemple chacune et leurs indications.\",\n\"type\": \"ouverte\",\n\"answer\": \"Hypokaliémiants : de l'anse (furosémide LASILIX), thiazidiques (hydrochlorothiazide). Hyperkaliémiants : spironolactone, amiloride. Antihypertenseurs : indapamide. Osmotiques : mannitol. Inhibiteurs de l'anhydrase carbonique : acétazolamide. Indications : HTA essentielle modérée, œdèmes, OAP, insuffisance rénale aiguë (anurie).\",\n\"keywords\": [\n\"anse\",\n\"furosémide\",\n\"thiazidiques\",\n\"hyperkaliémiants\",\n\"spironolactone\",\n\"œdèmes\",\n\"oap\"\n],\n\"explanation\": \"Hypokaliémiants : de l'anse (furosémide LASILIX), thiazidiques (hydrochlorothiazide). Hyperkaliémiants : spironolactone, amiloride. Antihypertenseurs : indapamide. Osmotiques : mannitol. Inhibiteurs de l'anhydrase carbonique : acétazolamide. Indications : HTA essentielle modérée, œdèmes, OAP, insuffisance rénale aiguë (anurie).\",\n\"memoryTip\": \"💧 Hypo-K perd le potassium, Hyper-K le garde.\"\n},\n{\n\"id\": \"ncv024\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 73,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelles règles hygiéno-diététiques associer au traitement antihypertenseur ?\",\n\"type\": \"ouverte\",\n\"answer\": \"Régime hyposodé à long terme, régime hypocalorique chez l'obèse hypertendu, suppression des facteurs de risque vasculaire (tabac...), exercice physique modéré. Le traitement est symptomatique et poursuivi à vie.\",\n\"keywords\": [\n\"hyposodé\",\n\"hypocalorique\",\n\"facteurs de risque\",\n\"exercice\",\n\"vie\"\n],\n\"explanation\": \"Régime hyposodé à long terme, régime hypocalorique chez l'obèse hypertendu, suppression des facteurs de risque vasculaire (tabac...), exercice physique modéré. Le traitement est symptomatique et poursuivi à vie.\",\n\"memoryTip\": \"🧂 Moins de sel, moins de calories, plus de marche.\"\n},\n{\n\"id\": \"ncv025\",\n\"chapter\": \"Appareil cardio-vasculaire\",\n\"page\": 71,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Comparez le mécanisme des IEC et des antagonistes de l'angiotensine II.\",\n\"type\": \"ouverte\",\n\"answer\": \"IEC : bloquent l'enzyme de conversion qui transforme l'angiotensine I en angiotensine II : l'angiotensine II ne se forme pas, d'où vasodilatation et baisse de l'aldostérone. ARA II (sartans) : n'empêchent pas la formation d'angiotensine II mais l'empêchent d'agir sur ses récepteurs.\",\n\"keywords\": [\n\"enzyme de conversion\",\n\"angiotensine\",\n\"formation\",\n\"récepteurs\",\n\"sartans\",\n\"aldostérone\"\n],\n\"explanation\": \"IEC : bloquent l'enzyme de conversion qui transforme l'angiotensine I en angiotensine II : l'angiotensine II ne se forme pas, d'où vasodilatation et baisse de l'aldostérone. ARA II (sartans) : n'empêchent pas la formation d'angiotensine II mais l'empêchent d'agir sur ses récepteurs.\",\n\"memoryTip\": \"🔑 IEC = pas de clé fabriquée ; Sartan = serrure bouchée.\"\n},\n{\n\"id\": \"nvt001\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 75,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Qu'est-ce qu'une vitamine ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Substance organique nécessaire en faible quantité, que l'organisme ne synthétise pas suffisamment\",\n\"Un minéral pur\",\n\"Une hormone produite par le pancréas\",\n\"Un médicament antibiotique\"\n],\n\"correctAnswer\": \"Substance organique nécessaire en faible quantité, que l'organisme ne synthétise pas suffisamment\",\n\"explanation\": \"Une vitamine est une substance organique nécessaire en faible quantité au métabolisme, non synthétisée en quantité suffisante par l'organisme.\",\n\"simpleExplanation\": \"Un petit ingrédient indispensable qu'il faut trouver dans l'alimentation.\",\n\"memoryTip\": \"VITA-mine = VIE 🌱\",\n\"examTrap\": \"Les oligo-éléments sont des minéraux.\"\n},\n{\n\"id\": \"nvt002\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 76,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelles maladies sont liées à des carences vitaminiques ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Scorbut\",\n\"Béribéri\",\n\"Rachitisme\",\n\"Paludisme\"\n],\n\"correctAnswer\": [\n\"Scorbut\",\n\"Béribéri\",\n\"Rachitisme\"\n],\n\"explanation\": \"Hypovitaminose/avitaminose : scorbut (C), béribéri (B1), rachitisme (D), pellagre (PP)...\",\n\"simpleExplanation\": \"Manquer de vitamine rend malade.\",\n\"memoryTip\": \"Scorbut C · Béribéri B1 · Rachitisme D · Pellagre PP.\",\n\"examTrap\": \"Le paludisme est parasitaire.\"\n},\n{\n\"id\": \"nvt003\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 76,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La carence en vitamine A est l'une des premières causes de :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Cécité dans les pays en développement\",\n\"Surdité\",\n\"Diabète\",\n\"Hypertension\"\n],\n\"correctAnswer\": \"Cécité dans les pays en développement\",\n\"explanation\": \"La carence en vitamine A est l'une des premières causes de cécité dans les pays en développement : vision nocturne difficile, cornée épaissie.\",\n\"simpleExplanation\": \"Sans vitamine A, on ne voit plus la nuit.\",\n\"memoryTip\": \"Vitamine A = Avoir de bons yeux 👀\",\n\"examTrap\": \"L'huile de palme rouge (sauce graine) en est riche.\"\n},\n{\n\"id\": \"nvt004\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 77,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel aliment local riche en provitamine A est cité dans le cours ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"L'huile de palme rouge (sauce graine)\",\n\"Le manioc blanc\",\n\"Le riz blanc\",\n\"L'eau de coco\"\n],\n\"correctAnswer\": \"L'huile de palme rouge (sauce graine)\",\n\"explanation\": \"La prévention se fait avec des aliments riches en provitamines A comme l'huile de palme rouge (sauce graine).\",\n\"simpleExplanation\": \"La sauce graine protège les yeux des enfants.\",\n\"memoryTip\": \"Sauce graine = Vitamine A 🥘\",\n\"examTrap\": \"Le riz blanc en est pauvre.\"\n},\n{\n\"id\": \"nvt005\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 77,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle maladie traduit une carence en thiamine (B1) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le béribéri\",\n\"La pellagre\",\n\"Le scorbut\",\n\"Le rachitisme\"\n],\n\"correctAnswer\": \"Le béribéri\",\n\"explanation\": \"La carence en thiamine (B1) = béribéri ; à risque : alcooliques, maladies intestinales, chirurgie gastrique. Thé et café réduisent son absorption.\",\n\"simpleExplanation\": \"B1 = Béribéri.\",\n\"memoryTip\": \"B1 → Béribéri (2 B !).\",\n\"examTrap\": \"La pellagre = B3/PP.\"\n},\n{\n\"id\": \"nvt006\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 78,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels signes traduisent une insuffisance en vitamine B2 (riboflavine) ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Gerçures des lèvres et des coins de la bouche\",\n\"Saignements des gencives\",\n\"Cécité nocturne\",\n\"Rachitisme\"\n],\n\"correctAnswer\": \"Gerçures des lèvres et des coins de la bouche\",\n\"explanation\": \"Insuffisance en B2 : gerçures des lèvres et des commissures, peau grasse, maux de gorge.\",\n\"simpleExplanation\": \"Les coins de la bouche craquent.\",\n\"memoryTip\": \"B2 = Bouche gercée 👄\",\n\"examTrap\": \"Saignements des gencives = scorbut (C).\"\n},\n{\n\"id\": \"nvt007\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 79,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La pellagre est due à une carence en :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Vitamine B3 (PP, niacine)\",\n\"Vitamine B12\",\n\"Vitamine K\",\n\"Vitamine E\"\n],\n\"correctAnswer\": \"Vitamine B3 (PP, niacine)\",\n\"explanation\": \"La vitamine B3/PP prévient la pellagre : érythèmes en plaques, gastro-entérites, troubles nerveux, inflammation de la bouche et de la langue.\",\n\"simpleExplanation\": \"PP = Prévient la Pellagre.\",\n\"memoryTip\": \"PP = Prévient Pellagre.\",\n\"examTrap\": \"B12 = anémie macrocytaire.\"\n},\n{\n\"id\": \"nvt008\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 79,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le signe caractéristique de la carence en vitamine B5 ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Sensation de brûlure dans les pieds\",\n\"Gerçures des lèvres\",\n\"Saignements de nez\",\n\"Cécité nocturne\"\n],\n\"correctAnswer\": \"Sensation de brûlure dans les pieds\",\n\"explanation\": \"La carence en B5 (acide pantothénique) est rare et se traduit par une sensation de brûlure dans les pieds.\",\n\"simpleExplanation\": \"Des pieds qui chauffent.\",\n\"memoryTip\": \"B5 = 5 orteils qui brûlent 🦶🔥\",\n\"examTrap\": \"La carence en vitamine E donne aussi des brûlures, mais elle est rarissime.\"\n},\n{\n\"id\": \"nvt009\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 80,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La vitamine B6 (pyridoxine) prévient :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Les polynévrites de l'éthylisme\",\n\"Le scorbut\",\n\"Le rachitisme\",\n\"Les hémorragies du nouveau-né\"\n],\n\"correctAnswer\": \"Les polynévrites de l'éthylisme\",\n\"explanation\": \"La B6 prévient les polynévrites dans l'éthylisme ; carence : gerçures, inflammation buccale, anémie. Utilisée dans les NVG et le syndrome prémenstruel.\",\n\"simpleExplanation\": \"B6 protège les nerfs des buveurs.\",\n\"memoryTip\": \"B6 = Nerfs + Grossesse (vomissements).\",\n\"examTrap\": \"La vitamine K prévient l'hémorragie néonatale.\"\n},\n{\n\"id\": \"nvt010\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 80,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La biotine (vitamine B8 ou H) est proposée pour :\",\n\"type\": \"qcm\",\n\"options\": [\n\"Les ongles fragiles et la chute des cheveux\",\n\"La coagulation\",\n\"La vision nocturne\",\n\"Le rachitisme\"\n],\n\"correctAnswer\": \"Les ongles fragiles et la chute des cheveux\",\n\"explanation\": \"Biotine (B8/H) : métabolisme énergétique ; proposée pour ongles fragiles, acné, peau grasse, chute et grisonnement des cheveux.\",\n\"simpleExplanation\": \"La vitamine de la beauté des cheveux et des ongles.\",\n\"memoryTip\": \"B8 = Beauté (cheveux, ongles) 💅\",\n\"examTrap\": \"La vision = vitamine A.\"\n},\n{\n\"id\": \"nvt011\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 81,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quelles malformations sont liées à une carence en folates pendant la grossesse ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Spina bifida\",\n\"Anencéphalie\",\n\"Fente labiale uniquement\",\n\"Cardiopathie uniquement\"\n],\n\"correctAnswer\": [\n\"Spina bifida\",\n\"Anencéphalie\"\n],\n\"explanation\": \"Carence en folates en début de grossesse : malformations du tube neural (spina bifida, anencéphalie).\",\n\"simpleExplanation\": \"Sans B9, la colonne et le cerveau du bébé se ferment mal.\",\n\"memoryTip\": \"B9 = 9 mois de grossesse 🤰\",\n\"examTrap\": \"D'où la prescription systématique en cas de désir de grossesse.\"\n},\n{\n\"id\": \"nvt012\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 82,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle vitamine est systématiquement absente des fruits et légumes ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"La vitamine B12\",\n\"La vitamine C\",\n\"La vitamine B9\",\n\"La vitamine K\"\n],\n\"correctAnswer\": \"La vitamine B12\",\n\"explanation\": \"La B12 est la seule vitamine systématiquement absente des fruits et légumes : les végétaliens stricts sont à risque.\",\n\"simpleExplanation\": \"On ne la trouve que dans les produits animaux.\",\n\"memoryTip\": \"B12 = 100 % animal 🥩🥚\",\n\"examTrap\": \"Les légumes verts sont riches en B9 et K.\"\n},\n{\n\"id\": \"nvt013\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 82,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des populations à risque de carence en B12 ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Végétaliens stricts\",\n\"Patients ayant subi une chirurgie de l'estomac\",\n\"Personnes âgées\",\n\"Grands consommateurs de viande\"\n],\n\"correctAnswer\": [\n\"Végétaliens stricts\",\n\"Patients ayant subi une chirurgie de l'estomac\",\n\"Personnes âgées\"\n],\n\"explanation\": \"À risque : végétaliens/macrobiotiques, maladies intestinales, chirurgie bariatrique/gastrique, anémie pernicieuse, personnes âgées (moins d'acidité gastrique).\",\n\"simpleExplanation\": \"Sans viande ou avec un estomac opéré, la B12 manque.\",\n\"memoryTip\": \"B12 : Végétaliens, Estomac opéré, Vieux.\",\n\"examTrap\": \"La viande en apporte beaucoup.\"\n},\n{\n\"id\": \"nvt014\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 83,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quels signes caractérisent le scorbut ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Saignements des gencives et ecchymoses\",\n\"Cécité nocturne\",\n\"Brûlures des pieds\",\n\"Rachitisme\"\n],\n\"correctAnswer\": \"Saignements des gencives et ecchymoses\",\n\"explanation\": \"Scorbut (carence en vitamine C) : saignements des gencives, ecchymoses, sécheresse bouche/yeux, douleurs, fatigue, anémie, coma possible.\",\n\"simpleExplanation\": \"Sans vitamine C, les gencives saignent.\",\n\"memoryTip\": \"C = Collagène = Gencives solides 🍊\",\n\"examTrap\": \"La vitamine C aide aussi l'absorption du fer.\"\n},\n{\n\"id\": \"nvt015\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 83,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle forme de vitamine D est produite par la peau sous l'action des UVB ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Vitamine D3 (cholécalciférol)\",\n\"Vitamine D2 (ergocalciférol)\",\n\"Vitamine K2\",\n\"Vitamine A\"\n],\n\"correctAnswer\": \"Vitamine D3 (cholécalciférol)\",\n\"explanation\": \"D2 (ergocalciférol) : végétaux ; D3 (cholécalciférol) : origine animale et produite par la peau sous les UVB.\",\n\"simpleExplanation\": \"Le soleil fabrique la vitamine D3 dans la peau.\",\n\"memoryTip\": \"D3 = 3e soleil ☀️ ; D2 = végétal 🌿\",\n\"examTrap\": \"Ne pas inverser D2 et D3.\"\n},\n{\n\"id\": \"nvt016\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 84,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"La carence en vitamine D provoque chez l'adulte :\",\n\"type\": \"qcm\",\n\"options\": [\n\"L'ostéomalacie\",\n\"Le rachitisme\",\n\"Le béribéri\",\n\"La pellagre\"\n],\n\"correctAnswer\": \"L'ostéomalacie\",\n\"explanation\": \"Carence en vitamine D : rachitisme chez l'enfant, ostéomalacie chez l'adulte (risque d'ostéoporose et fractures).\",\n\"simpleExplanation\": \"Les os deviennent mous.\",\n\"memoryTip\": \"Enfant = Rachitisme ; Adulte = Ostéomalacie 🦴\",\n\"examTrap\": \"Le rachitisme concerne l'enfant.\"\n},\n{\n\"id\": \"nvt017\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 85,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quels facteurs de coagulation la vitamine K permet-elle d'activer ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"II, VII, IX, X\",\n\"I, V, VIII, XIII\",\n\"III, IV, VI, XI\",\n\"XII seulement\"\n],\n\"correctAnswer\": \"II, VII, IX, X\",\n\"explanation\": \"La vitamine K permet la synthèse de la prothrombine et l'activation des facteurs II, VII, IX, X.\",\n\"simpleExplanation\": \"Elle allume 4 interrupteurs de la coagulation.\",\n\"memoryTip\": \"« 1972 » : facteurs 10-9-7-2 🔢\",\n\"examTrap\": \"Le lait maternel est pauvre en vitamine K.\"\n},\n{\n\"id\": \"nvt018\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 85,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Pourquoi donne-t-on systématiquement de la vitamine K au nouveau-né ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le lait maternel est pauvre en vitamine K\",\n\"Pour sa croissance osseuse\",\n\"Pour sa vision\",\n\"Pour éviter le rachitisme\"\n],\n\"correctAnswer\": \"Le lait maternel est pauvre en vitamine K\",\n\"explanation\": \"Le lait maternel étant pauvre en vitamine K, un apport est systématiquement prescrit au nouveau-né (prévention des hémorragies).\",\n\"simpleExplanation\": \"Le bébé n'a pas assez de vitamine K pour bien coaguler.\",\n\"memoryTip\": \"Bébé + K = pas d'hémorragie 👶🩸\",\n\"examTrap\": \"Ce n'est pas pour le rachitisme (vitamine D).\"\n},\n{\n\"id\": \"nvt019\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 86,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment définit-on un oligo-élément ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Élément minéral nécessaire en quantité très faible (masse < 1 mg/kg)\",\n\"Substance organique non synthétisée\",\n\"Un acide aminé essentiel\",\n\"Une hormone\"\n],\n\"correctAnswer\": \"Élément minéral nécessaire en quantité très faible (masse < 1 mg/kg)\",\n\"explanation\": \"Les oligo-éléments sont des éléments minéraux purs nécessaires à la vie en quantités très faibles (< 1 mg/kg) ; toxiques à taux trop élevés.\",\n\"simpleExplanation\": \"De tout petits minéraux indispensables.\",\n\"memoryTip\": \"OLIGO = peu (en grec).\",\n\"examTrap\": \"Carence ou excès peuvent être mortels.\"\n},\n{\n\"id\": \"nvt020\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 86,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel oligo-élément stimule les effets de l'insuline ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le chrome\",\n\"Le cuivre\",\n\"Le fer\",\n\"Le sélénium\"\n],\n\"correctAnswer\": \"Le chrome\",\n\"explanation\": \"Le chrome participe au métabolisme du glucose en stimulant les effets de l'insuline ; usage : diabète de type 2 avec insulinorésistance.\",\n\"simpleExplanation\": \"Le chrome aide l'insuline à faire entrer le sucre.\",\n\"memoryTip\": \"CHROME = Contrôle du glucose 🍬\",\n\"examTrap\": \"Le sélénium est antioxydant/thyroïde.\"\n},\n{\n\"id\": \"nvt021\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 88,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquels sont des signes de carence en magnésium ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Crises de tétanie (mains d'accoucheur)\",\n\"Crampes et tremblements\",\n\"Irritabilité et insomnie\",\n\"Hypertension artérielle sévère\"\n],\n\"correctAnswer\": [\n\"Crises de tétanie (mains d'accoucheur)\",\n\"Crampes et tremblements\",\n\"Irritabilité et insomnie\"\n],\n\"explanation\": \"Hypomagnésémie : tétanie, troubles immunitaires, atteintes cardiovasculaires, fatigabilité, troubles digestifs, irritabilité, insomnie, crampes, tremblements, myoclonies, convulsions.\",\n\"simpleExplanation\": \"Sans magnésium, les muscles et les nerfs s'énervent.\",\n\"memoryTip\": \"Mg = Anti-stress 😌 ; manque = tétanie.\",\n\"examTrap\": \"L'hypermagnésémie donne hypotension et bradycardie.\"\n},\n{\n\"id\": \"nvt022\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 89,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Quelle est l'origine presque toujours retrouvée de l'hypermagnésémie ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Iatrogène (due à un médicament)\",\n\"Alimentaire\",\n\"Génétique\",\n\"Infectieuse\"\n],\n\"correctAnswer\": \"Iatrogène (due à un médicament)\",\n\"explanation\": \"NB du cours : l'hypermagnésémie est pratiquement toujours d'origine iatrogène ; signes : hypotension, bradycardie, hyporéflexie, coma.\",\n\"simpleExplanation\": \"C'est le traitement lui-même qui en donne trop.\",\n\"memoryTip\": \"Hyper-Mg = Iatrogène 💉\",\n\"examTrap\": \"L'alimentation n'entraîne pas d'excès.\"\n},\n{\n\"id\": \"nvt023\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 89,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le minéral le plus abondant de l'organisme après le calcium ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le phosphore\",\n\"Le potassium\",\n\"Le fer\",\n\"Le zinc\"\n],\n\"correctAnswer\": \"Le phosphore\",\n\"explanation\": \"Le phosphore est le plus abondant après le calcium : os et dents, croissance, pH sanguin, membranes cellulaires.\",\n\"simpleExplanation\": \"Calcium et phosphore construisent les os ensemble.\",\n\"memoryTip\": \"Ca puis P = os 🦴\",\n\"examTrap\": \"Le calcium reste le plus abondant.\"\n},\n{\n\"id\": \"nvt024\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 90,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel oligo-élément est essentiel au système immunitaire et à la thyroïde, avec une forte capacité antioxydante ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Le sélénium\",\n\"Le cuivre\",\n\"Le manganèse\",\n\"Le chrome\"\n],\n\"correctAnswer\": \"Le sélénium\",\n\"explanation\": \"Le sélénium : capacité antioxydante, essentiel au système immunitaire et à la glande thyroïde ; source riche : noix du Brésil.\",\n\"simpleExplanation\": \"Le sélénium est un bouclier contre l'usure des cellules.\",\n\"memoryTip\": \"SÉLÉNIUM = Sentinelle 🛡️\",\n\"examTrap\": \"L'iode forme les hormones thyroïdiennes.\"\n},\n{\n\"id\": \"nvt025\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 90,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des conséquences d'une carence en zinc ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Retard de croissance\",\n\"Troubles du goût et de l'odorat\",\n\"Plaies qui guérissent mal\",\n\"Excès de vision nocturne\"\n],\n\"correctAnswer\": [\n\"Retard de croissance\",\n\"Troubles du goût et de l'odorat\",\n\"Plaies qui guérissent mal\"\n],\n\"explanation\": \"Carence en zinc : baisse de l'immunité, retard de croissance, troubles goût/odorat, baisse de fertilité masculine, dermatites, diarrhée, dépression...\",\n\"simpleExplanation\": \"Sans zinc, on grandit moins et on cicatrise mal.\",\n\"memoryTip\": \"ZINC = Zéro Infection, Nez, Croissance.\",\n\"examTrap\": \"Les personnes vivant avec le VIH sont souvent carencées.\"\n},\n{\n\"id\": \"nvt026\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 76,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Citez 5 intérêts thérapeutiques de la vitamine A.\",\n\"type\": \"ouverte\",\n\"answer\": \"Diminue le risque de cancer du sein ; diminue le risque de cataracte et la mortalité par diarrhées chez l'enfant séropositif ; réduit les symptômes du paludisme chez l'enfant ; réduit les complications de la rougeole ; réduit les complications de la grossesse ; améliore la cicatrisation et l'acuité visuelle ; prévient la dégénérescence maculaire ; réduit le risque d'anémie.\",\n\"keywords\": [\n\"cancer\",\n\"cataracte\",\n\"paludisme\",\n\"rougeole\",\n\"grossesse\",\n\"cicatrisation\",\n\"anémie\"\n],\n\"explanation\": \"Diminue le risque de cancer du sein ; diminue le risque de cataracte et la mortalité par diarrhées chez l'enfant séropositif ; réduit les symptômes du paludisme chez l'enfant ; réduit les complications de la rougeole ; réduit les complications de la grossesse ; améliore la cicatrisation et l'acuité visuelle ; prévient la dégénérescence maculaire ; réduit le risque d'anémie.\",\n\"memoryTip\": \"🥕 Vitamine A = yeux, peau, défenses.\"\n},\n{\n\"id\": \"nvt027\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 81,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel est le rôle de l'acide folique et quand le prescrit-on systématiquement ?\",\n\"type\": \"ouverte\",\n\"answer\": \"Nécessaire à la synthèse des nucléoprotéines, à la multiplication cellulaire et à l'érythropoïèse ; prévient les anémies macrocytaires et, en début de grossesse, les malformations du tube neural. Prescrit systématiquement chez toute femme en âge de procréer ayant un désir de grossesse.\",\n\"keywords\": [\n\"nucléoprotéines\",\n\"érythropoïèse\",\n\"macrocytaires\",\n\"tube neural\",\n\"désir de grossesse\"\n],\n\"explanation\": \"Nécessaire à la synthèse des nucléoprotéines, à la multiplication cellulaire et à l'érythropoïèse ; prévient les anémies macrocytaires et, en début de grossesse, les malformations du tube neural. Prescrit systématiquement chez toute femme en âge de procréer ayant un désir de grossesse.\",\n\"memoryTip\": \"🤰 B9 avant même d'être enceinte.\"\n},\n{\n\"id\": \"nvt028\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 85,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez le rôle de la vitamine K et les signes de sa carence.\",\n\"type\": \"ouverte\",\n\"answer\": \"Facteur de coagulation : synthèse de la prothrombine par le foie, activation des facteurs II, VII, IX, X ; rôle dans le métabolisme osseux. Carence : ecchymoses, épistaxis, selles noires, règles abondantes, ostéoporose.\",\n\"keywords\": [\n\"coagulation\",\n\"prothrombine\",\n\"ii, vii, ix, x\",\n\"ecchymoses\",\n\"saignements\"\n],\n\"explanation\": \"Facteur de coagulation : synthèse de la prothrombine par le foie, activation des facteurs II, VII, IX, X ; rôle dans le métabolisme osseux. Carence : ecchymoses, épistaxis, selles noires, règles abondantes, ostéoporose.\",\n\"memoryTip\": \"🩸 K = Koagulation (en allemand !).\"\n},\n{\n\"id\": \"nvt029\",\n\"chapter\": \"Vitamines & Oligo-éléments\",\n\"page\": 87,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez le rôle du fer et de l'iode.\",\n\"type\": \"ouverte\",\n\"answer\": \"Fer : transport de l'oxygène, formation des globules rouges, fabrication des cellules, hormones et neurotransmetteurs. Iode : formation des hormones thyroïdiennes (croissance, développement, métabolisme de base), maturation du système nerveux du fœtus.\",\n\"keywords\": [\n\"oxygène\",\n\"globules rouges\",\n\"hormones thyroïdiennes\",\n\"croissance\",\n\"fœtus\"\n],\n\"explanation\": \"Fer : transport de l'oxygène, formation des globules rouges, fabrication des cellules, hormones et neurotransmetteurs. Iode : formation des hormones thyroïdiennes (croissance, développement, métabolisme de base), maturation du système nerveux du fœtus.\",\n\"memoryTip\": \"🩸 Fer = Oxygène ; 🦋 Iode = Thyroïde.\"\n},\n{\n\"id\": \"nas001\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 91,\n\"source\": \"2022\",\n\"difficulty\": \"facile\",\n\"question\": \"Les détergents tuent-ils les microbes ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Non, ils enlèvent salissures et graisses\",\n\"Oui, tous\",\n\"Uniquement les virus\",\n\"Uniquement les bactéries\"\n],\n\"correctAnswer\": \"Non, ils enlèvent salissures et graisses\",\n\"explanation\": \"Un détergent enlève salissures et graisses, sur matériel inerte et tissus vivants ; les détergents ne tuent pas les microbes.\",\n\"simpleExplanation\": \"Le savon nettoie la saleté mais ne tue pas forcément les microbes.\",\n\"memoryTip\": \"Détergent = Décrasser, pas Désinfecter 🧼\",\n\"examTrap\": \"Ne pas confondre avec le désinfectant.\"\n},\n{\n\"id\": \"nas002\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 92,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quelle est la différence entre antiseptique et désinfectant ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"L'antiseptique agit sur les tissus vivants ; le désinfectant sur les milieux inertes\",\n\"Ils sont identiques\",\n\"Le désinfectant agit sur la peau\",\n\"L'antiseptique nettoie les sols\"\n],\n\"correctAnswer\": \"L'antiseptique agit sur les tissus vivants ; le désinfectant sur les milieux inertes\",\n\"explanation\": \"Antiseptique : tissus vivants (peau, muqueuses, plaies). Désinfectant : milieux ou matières inertes (sols, surfaces, dispositifs).\",\n\"simpleExplanation\": \"Antiseptique pour la peau, désinfectant pour la table.\",\n\"memoryTip\": \"ANTI-septique = vivANT ; DÉS-infectant = DÉcor inerte.\",\n\"examTrap\": \"La javel diluée < 5 °chl peut servir d'antiseptique.\"\n},\n{\n\"id\": \"nas003\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 92,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment définit-on l'asepsie ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Ensemble des mesures préventives empêchant tout apport exogène de micro-organismes\",\n\"Opération qui tue les germes sur la peau\",\n\"Nettoyage des salissures\",\n\"Désinfection des sols\"\n],\n\"correctAnswer\": \"Ensemble des mesures préventives empêchant tout apport exogène de micro-organismes\",\n\"explanation\": \"L'asepsie est une méthode préventive : ensemble des mesures empêchant tout apport exogène de micro-organismes (ex : stérilisation du matériel).\",\n\"simpleExplanation\": \"Asepsie = ne jamais laisser entrer les microbes.\",\n\"memoryTip\": \"A-sepsie = Absence (prévenir) ; Anti-sepsie = Attaquer.\",\n\"examTrap\": \"L'antisepsie a un résultat momentané.\"\n},\n{\n\"id\": \"nas004\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 92,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des précautions d'usage d'un antiseptique ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Indiquer la date d'ouverture sur le flacon\",\n\"Fermer le flacon après chaque usage\",\n\"Jeter le flacon à la sortie du patient\",\n\"Mélanger avec un détergent\"\n],\n\"correctAnswer\": [\n\"Indiquer la date d'ouverture sur le flacon\",\n\"Fermer le flacon après chaque usage\",\n\"Jeter le flacon à la sortie du patient\"\n],\n\"explanation\": \"Précautions : vérifier la péremption, noter la date d'ouverture, fermer le flacon, respecter la durée après ouverture, préférer les petits conditionnements, jeter à la sortie du patient.\",\n\"simpleExplanation\": \"Un flacon ouvert est un nid à microbes s'il traîne.\",\n\"memoryTip\": \"Date · Bouchon · Poubelle à la sortie 🗑️\",\n\"examTrap\": \"Ne jamais mélanger avec un détergent.\"\n},\n{\n\"id\": \"nas005\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 92,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Combien de types de désinfectants le cours distingue-t-il selon le domaine d'utilisation ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Trois\",\n\"Deux\",\n\"Quatre\",\n\"Cinq\"\n],\n\"correctAnswer\": \"Trois\",\n\"explanation\": \"3 types : désinfection par voie aérienne, désinfectants des dispositifs médicaux réutilisables, autres (sols et surfaces).\",\n\"simpleExplanation\": \"Pour l'air, pour le matériel, pour les sols.\",\n\"memoryTip\": \"3 D : Diffusion aérienne, Dispositifs, Dalles (sols).\",\n\"examTrap\": \"Le résultat de la désinfection est momentané.\"\n},\n{\n\"id\": \"nas006\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 93,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Comment doit-on conserver l'eau de javel ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Dans un emballage opaque\",\n\"Dans un flacon transparent au soleil\",\n\"Mélangée à un détergent\",\n\"Au réfrigérateur obligatoirement\"\n],\n\"correctAnswer\": \"Dans un emballage opaque\",\n\"explanation\": \"Javel : puissant désinfectant, antiseptique si < 5 °chl, ne pas mélanger au détergent, conserver dans un emballage opaque (l'hypochlorite se décompose à la lumière).\",\n\"simpleExplanation\": \"La lumière abîme la javel.\",\n\"memoryTip\": \"Javel = À l'ombre 🌑\",\n\"examTrap\": \"Ne jamais mélanger avec un détergent.\"\n},\n{\n\"id\": \"nas007\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 93,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"On veut une eau javellisée à 1 °chl à partir de javel à 12 °chl. Quelle dilution ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"1 volume de javel + 11 volumes d'eau\",\n\"1 volume de javel + 12 volumes d'eau\",\n\"1 volume de javel + 1 volume d'eau\",\n\"12 volumes de javel + 1 volume d'eau\"\n],\n\"correctAnswer\": \"1 volume de javel + 11 volumes d'eau\",\n\"explanation\": \"N = CI/CF = 12/1 = 12. Dilution = 1 volume de CI + (N − 1) = 11 volumes d'eau.\",\n\"simpleExplanation\": \"On divise la force par 12 : 1 part de javel pour 11 parts d'eau.\",\n\"memoryTip\": \"N = CI/CF ; eau = N − 1 🧮\",\n\"examTrap\": \"Piège : ce n'est pas N volumes d'eau mais N − 1.\"\n},\n{\n\"id\": \"nas008\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 93,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Pour obtenir de la javel à 2 °chl à partir d'un extrait à 48 °chl, combien de volumes d'eau ajouter à 1 volume d'extrait ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"23\",\n\"24\",\n\"22\",\n\"48\"\n],\n\"correctAnswer\": \"23\",\n\"explanation\": \"N = 48/2 = 24 ; eau = N − 1 = 23 volumes.\",\n\"simpleExplanation\": \"On divise par 24 : 1 part d'extrait + 23 parts d'eau.\",\n\"memoryTip\": \"N − 1 toujours ! 🧮\",\n\"examTrap\": \"24 serait le facteur N, pas le volume d'eau.\"\n},\n{\n\"id\": \"nas009\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 93,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lequel est un antiseptique de la famille des biguanides, à action rémanente et cumulative ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Chlorhexidine\",\n\"Povidone iodée\",\n\"Éosine\",\n\"Eau oxygénée\"\n],\n\"correctAnswer\": \"Chlorhexidine\",\n\"explanation\": \"Biguanides : chlorhexidine, large spectre même à faible concentration, rémanente et cumulative. Dérivés iodés : povidone iodée. Colorants : éosine.\",\n\"simpleExplanation\": \"La chlorhexidine continue à agir longtemps après l'application.\",\n\"memoryTip\": \"CHLORHEXIDINE = Continue d'agir ⏳\",\n\"examTrap\": \"L'éosine est un colorant.\"\n},\n{\n\"id\": \"nas010\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 94,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Pourquoi le nettoyage à l'eau oxygénée doit-il être bref ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"Elle dégrade les cellules et nuit à la cicatrisation\",\n\"Elle est inflammable\",\n\"Elle colore la peau\",\n\"Elle est inefficace sur les bactéries\"\n],\n\"correctAnswer\": \"Elle dégrade les cellules et nuit à la cicatrisation\",\n\"explanation\": \"L'eau oxygénée (oxydant) est surtout hémostatique ; nettoyage bref, sans hémorragie, car elle dégrade les cellules et nuit à la cicatrisation.\",\n\"simpleExplanation\": \"Elle mousse et nettoie, mais abîme aussi la peau qui se répare.\",\n\"memoryTip\": \"H₂O₂ = Hémostatique mais Hostile à la cicatrisation.\",\n\"examTrap\": \"Elle n'est pas faite pour les longs lavages.\"\n},\n{\n\"id\": \"nas011\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 94,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des propriétés des solutions hydro-alcooliques ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Bactéricides, virucides et fongicides\",\n\"Utilisées sans eau, par friction\",\n\"Appliquées sur mains sèches et non souillées\",\n\"Effet nettoyant sur les mains sales\"\n],\n\"correctAnswer\": [\n\"Bactéricides, virucides et fongicides\",\n\"Utilisées sans eau, par friction\",\n\"Appliquées sur mains sèches et non souillées\"\n],\n\"explanation\": \"SHA : aseptisantes cutanées, friction sans eau, bactéricides, virucides, fongicides, sans effet nettoyant ; sur mains sèches et non souillées.\",\n\"simpleExplanation\": \"La SHA tue les microbes mais ne lave pas la saleté.\",\n\"memoryTip\": \"SHA = Sec, Sans eau, Sans saleté 🙌\",\n\"examTrap\": \"Pas d'effet nettoyant.\"\n},\n{\n\"id\": \"nas012\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 95,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Quel volume de SHA faut-il mettre dans le creux de la main ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"3 mL\",\n\"1 mL\",\n\"10 mL\",\n\"0,5 mL\"\n],\n\"correctAnswer\": \"3 mL\",\n\"explanation\": \"Procédure : remplir le creux d'une main avec 3 mL de SHA et frictionner jusqu'à séchage complet (environ 30 s).\",\n\"simpleExplanation\": \"Une bonne noisette qui remplit le creux de la main.\",\n\"memoryTip\": \"3 mL · 30 secondes 🖐️\",\n\"examTrap\": \"Durée minimale de contact : 10-15 s ; procédure totale : ~30 s.\"\n},\n{\n\"id\": \"nas013\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 95,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Lesquelles sont des contre-indications de la SHA ?\",\n\"type\": \"qcd\",\n\"options\": [\n\"Mains mouillées\",\n\"Mains souillées par du sang\",\n\"Mains gantées\",\n\"Mains propres et sèches\"\n],\n\"correctAnswer\": [\n\"Mains mouillées\",\n\"Mains souillées par du sang\",\n\"Mains gantées\"\n],\n\"explanation\": \"CI : mains mouillées, souillées (sang, sécrétions), talquées, lésées, muqueuses, mains gantées, surfaces inertes, désinfection cutanée pré-interventionnelle.\",\n\"simpleExplanation\": \"La SHA ne marche pas sur des mains sales ou mouillées.\",\n\"memoryTip\": \"SHA : jamais Mouillé, Sale, Ganté, Blessé.\",\n\"examTrap\": \"Mains propres et sèches = indication.\"\n},\n{\n\"id\": \"nas014\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 95,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Combien de temps dure en moyenne un lavage antiseptique des mains comparé à la friction SHA ?\",\n\"type\": \"qcm\",\n\"options\": [\n\"2 minutes contre 30 secondes\",\n\"30 secondes contre 2 minutes\",\n\"5 minutes contre 1 minute\",\n\"1 minute contre 10 secondes\"\n],\n\"correctAnswer\": \"2 minutes contre 30 secondes\",\n\"explanation\": \"Rapidité : la procédure SHA dure en moyenne 30 s, le lavage antiseptique 2 min.\",\n\"simpleExplanation\": \"La SHA est 4 fois plus rapide.\",\n\"memoryTip\": \"SHA 30 s vs Savon 2 min ⏱️\",\n\"examTrap\": \"La SHA est plus rapide mais parfois moins bien tolérée.\"\n},\n{\n\"id\": \"nas015\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 92,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Définissez : détergent, antiseptique, désinfectant, asepsie.\",\n\"type\": \"ouverte\",\n\"answer\": \"Détergent : produit qui enlève salissures et graisses, ne tue pas les microbes. Antiseptique : produit qui élimine ou empêche le développement des micro-organismes sur les tissus vivants. Désinfectant : idem sur les milieux inertes. Asepsie : ensemble des mesures préventives empêchant tout apport exogène de micro-organismes.\",\n\"keywords\": [\n\"salissures\",\n\"tissus vivants\",\n\"inertes\",\n\"préventive\",\n\"exogène\"\n],\n\"explanation\": \"Détergent : produit qui enlève salissures et graisses, ne tue pas les microbes. Antiseptique : produit qui élimine ou empêche le développement des micro-organismes sur les tissus vivants. Désinfectant : idem sur les milieux inertes. Asepsie : ensemble des mesures préventives empêchant tout apport exogène de micro-organismes.\",\n\"memoryTip\": \"🧼 Détergent nettoie · 🩹 Antiseptique = vivant · 🧽 Désinfectant = inerte · 🛡️ Asepsie = prévention.\"\n},\n{\n\"id\": \"nas016\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 93,\n\"source\": \"2022\",\n\"difficulty\": \"difficile\",\n\"question\": \"Expliquez la formule de dilution de l'eau de javel avec un exemple.\",\n\"type\": \"ouverte\",\n\"answer\": \"N = CI/CF ; dilution = 1 volume de solution initiale + (N − 1) volumes d'eau. Exemple : javel 12 °chl vers 2 °chl : N = 6, donc 1 volume de javel + 5 volumes d'eau.\",\n\"keywords\": [\n\"n = ci/cf\",\n\"1 volume\",\n\"n − 1\",\n\"eau\",\n\"exemple\"\n],\n\"explanation\": \"N = CI/CF ; dilution = 1 volume de solution initiale + (N − 1) volumes d'eau. Exemple : javel 12 °chl vers 2 °chl : N = 6, donc 1 volume de javel + 5 volumes d'eau.\",\n\"memoryTip\": \"🧮 Diviser, puis enlever 1.\"\n},\n{\n\"id\": \"nas017\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 95,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Décrivez la procédure de friction hydro-alcoolique des mains.\",\n\"type\": \"ouverte\",\n\"answer\": \"Mains propres et sèches, 3 mL de SHA dans le creux de la main, frictionner jusqu'à séchage : paume contre paume, paume sur dos de la main, doigts entrelacés, dos des doigts, pouces en rotation, pulpe des doigts, tranche cubitale, poignets. Durée totale environ 30 secondes.\",\n\"keywords\": [\n\"3 ml\",\n\"paume\",\n\"doigts entrelacés\",\n\"pouce\",\n\"poignet\",\n\"30 secondes\"\n],\n\"explanation\": \"Mains propres et sèches, 3 mL de SHA dans le creux de la main, frictionner jusqu'à séchage : paume contre paume, paume sur dos de la main, doigts entrelacés, dos des doigts, pouces en rotation, pulpe des doigts, tranche cubitale, poignets. Durée totale environ 30 secondes.\",\n\"memoryTip\": \"🖐️ Paume · Dos · Entre · Dos des doigts · Pouce · Pulpe · Poignet.\"\n},\n{\n\"id\": \"nas018\",\n\"chapter\": \"Antiseptiques, désinfectants & détergents\",\n\"page\": 94,\n\"source\": \"2022\",\n\"difficulty\": \"moyen\",\n\"question\": \"Citez les intérêts des solutions hydro-alcooliques.\",\n\"type\": \"ouverte\",\n\"answer\": \"Recommandées par l'OMS dans la lutte contre les infections nosocomiales, en pratique de soins, en remplacement ou complément du lavage chirurgical au bloc, et dans la prévention des maladies très contagieuses (grippe, Ebola, coronavirus, rotavirus...). Rapides, efficaces, bien tolérées, faciles d'usage.\",\n\"keywords\": [\n\"oms\",\n\"nosocomiales\",\n\"bloc\",\n\"contagieuses\",\n\"rapidité\"\n],\n\"explanation\": \"Recommandées par l'OMS dans la lutte contre les infections nosocomiales, en pratique de soins, en remplacement ou complément du lavage chirurgical au bloc, et dans la prévention des maladies très contagieuses (grippe, Ebola, coronavirus, rotavirus...). Rapides, efficaces, bien tolérées, faciles d'usage.\",\n\"memoryTip\": \"🦠 SHA = arme anti-nosocomiale n°1.\"\n}\n];\n\nconst MEDS = [\n{classe:\"Antalgiques périphériques (niveau 1 OMS)\",chapter:\"Antalgiques & fièvre\",page:21,items:[\n  [\"Paracétamol\",\"DOLIPRANE, DAFALGAN, EFFERALGAN\"],[\"Aspirine (Acide acétylsalicylique)\",\"KARDEGIC, ASPEGIC\"],[\"Ibuprofène (AINS)\",\"NUROFEN, ADVIL\"],[\"Métamizole (Noramidopyrine)\",\"—\"]]},\n{classe:\"Antalgiques centraux faibles (niveau 2 OMS)\",chapter:\"Antalgiques & fièvre\",page:21,items:[\n  [\"Codéine + paracétamol\",\"CODOLIPRANE, EFFERALGAN CODEINE\"],[\"Tramadol\",\"TRABAR, TRACEDOL\"],[\"Néfopam\",\"ACUPAN\"]]},\n{classe:\"Antalgiques centraux forts / Morphiniques (niveau 3 OMS)\",chapter:\"Antalgiques & fièvre\",page:21,items:[\n  [\"Morphine\",\"SKENAN, MOSCONTIN\"],[\"Fentanyl\",\"—\"],[\"Buprénorphine (agoniste-antagoniste)\",\"TEMGESIC\"],[\"Naloxone (antagoniste)\",\"NARCAN\"]]},\n{classe:\"Antispasmodiques neurotropes (anticholinergiques)\",chapter:\"Antalgiques & fièvre\",page:23,items:[\n  [\"Butyl hyoscine\",\"BUSCOPAN\"],[\"Dihexyvérine\",\"SPASMODEX\"],[\"Scopolamine\",\"SCOPODERM\"]]},\n{classe:\"Antispasmodiques musculotropes\",chapter:\"Antalgiques & fièvre\",page:23,items:[\n  [\"Phloroglucinol\",\"SPASFON\"],[\"Trimébutine\",\"DEBRIDAT\"],[\"Alvérine\",\"METEOSPASMYL\"],[\"Bromure de pinavérium\",\"DICETEL\"]]},\n{classe:\"AINS (Anti-inflammatoires non stéroïdiens)\",chapter:\"Anti-inflammatoires & anesthésiques\",page:25,items:[\n  [\"Diclofénac\",\"VOLTARENE\"],[\"Ibuprofène\",\"ADVIL\"],[\"Kétoprofène\",\"PROFENID\"],[\"Célécoxib (Coxib)\",\"CELEBREX\"],[\"Piroxicam (Oxicam)\",\"REUMOXICAM\"],[\"Indométacine\",\"INDOCID\"]]},\n{classe:\"Glucocorticoïdes (anti-inflammatoires stéroïdiens)\",chapter:\"Anti-inflammatoires & anesthésiques\",page:26,items:[\n  [\"Prednisone\",\"CORTANCYL\"],[\"Prednisolone\",\"SOLUPRED\"],[\"Bétaméthasone\",\"CELESTENE\"],[\"Dexaméthasone\",\"DEXACYL\"]]},\n{classe:\"Myorelaxants / Antispastiques\",chapter:\"Anti-inflammatoires & anesthésiques\",page:28,items:[\n  [\"Baclofène\",\"LIORESAL\"],[\"Thiocolchicoside\",\"COLTRAMYL\"],[\"Diazépam\",\"VALIUM\"],[\"Dandrolène\",\"DANTRIUM\"]]},\n{classe:\"Anesthésiques locaux\",chapter:\"Anti-inflammatoires & anesthésiques\",page:28,items:[\n  [\"Lidocaïne\",\"XYLOCAINE\"],[\"Mépivacaïne\",\"CARBOCAINE\"],[\"Ropivacaïne\",\"NAROPEINE\"]]},\n{classe:\"Pénicillines (bêta-lactamines)\",chapter:\"Anti-infectieux\",page:33,items:[\n  [\"Benzylpénicilline (Pénicilline G)\",\"—\"],[\"Amoxicilline\",\"CLAMOXYL\"],[\"Amoxicilline + acide clavulanique\",\"AUGMENTIN\"],[\"Cloxacilline (Pénicilline M)\",\"ORBENINE\"]]},\n{classe:\"Céphalosporines\",chapter:\"Anti-infectieux\",page:35,items:[\n  [\"Céfaclor (1ère génération)\",\"ALFATIL\"],[\"Céfuroxime (2ème génération)\",\"ZINNAT\"],[\"Ceftriaxone (3ème génération)\",\"ROCEPHINE\"],[\"Céfépime (4ème génération)\",\"AXEPIME\"]]},\n{classe:\"Macrolides\",chapter:\"Anti-infectieux\",page:38,items:[\n  [\"Azithromycine\",\"ZITHROMAX\"],[\"Spiramycine\",\"ROVAMYCINE\"],[\"Clarithromycine\",\"NAXY\"]]},\n{classe:\"Aminosides\",chapter:\"Anti-infectieux\",page:39,items:[\n  [\"Gentamicine\",\"GENTALLINE\"],[\"Tobramycine\",\"NEBCINE\"],[\"Amikacine\",\"AMIKACINE\"]]},\n{classe:\"Tétracyclines / Cyclines\",chapter:\"Anti-infectieux\",page:40,items:[\n  [\"Doxycycline\",\"DOXY\"],[\"Minocycline\",\"MESTACINE\"]]},\n{classe:\"Quinolones / Fluoroquinolones\",chapter:\"Anti-infectieux\",page:41,items:[\n  [\"Ciprofloxacine\",\"CIFLOX\"],[\"Ofloxacine\",\"OFLOCET\"],[\"Lévofloxacine\",\"TAVANIC\"]]},\n{classe:\"Antipaludéens\",chapter:\"Anti-infectieux\",page:46,items:[\n  [\"Quinine\",\"QUINIMAX\"],[\"Chloroquine\",\"NIVAQUINE\"],[\"Sulfadoxine + Pyriméthamine\",\"FANSIDAR\"],[\"Artéméther + Luméfantrine (ACT)\",\"—\"]]},\n{classe:\"Anthelminthiques (vers)\",chapter:\"Anti-infectieux\",page:47,items:[\n  [\"Albendazole\",\"ZENTEL\"],[\"Mébendazole\",\"VERMOX\"],[\"Praziquantel\",\"BILTRICIDE\"],[\"Ivermectine\",\"STROMECTOL\"]]},\n{classe:\"Antifongiques\",chapter:\"Anti-infectieux\",page:48,items:[\n  [\"Fluconazole\",\"FLUCAZOLE\"],[\"Kétoconazole\",\"KETODERM\"],[\"Terbinafine\",\"LAMISIL\"],[\"Nystatine\",\"MYCOSTATYNE\"]]},\n{classe:\"Antirétroviraux — INTI\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:36,items:[\n  [\"Zidovudine (AZT)\",\"RETROVIR\"],[\"Lamivudine (3TC)\",\"EPIVIR\"],[\"Ténofovir (TDF)\",\"VIREAD\"]]},\n{classe:\"Antirétroviraux — INNTI, IP, autres classes\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:37,items:[\n  [\"Efavirenz (INNTI)\",\"SUSTIVA\"],[\"Névirapine (INNTI)\",\"VIRAMUNE\"],[\"Ritonavir (IP)\",\"NORVIR\"],[\"Raltégravir (intégrase)\",\"ISENTRESS\"],[\"Maraviroc (entrée CCR5)\",\"CELSENTRI\"]]},\n{classe:\"Antituberculeux\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:37,items:[\n  [\"Isoniazide (bactéricide)\",\"RIMIFON\"],[\"Rifampicine (bactéricide)\",\"RIFADINE\"],[\"Pyrazinamide (bactéricide)\",\"PIRILENE\"],[\"Éthambutol (bactériostatique)\",\"MYAMBUTOL\"]]},\n{classe:\"Antilépreux\",chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:37,items:[\n  [\"Dapsone (DDS)\",\"DISULONE\"],[\"Clofazimine\",\"LAMPRENE\"],[\"Rifampicine\",\"—\"]]},\n{classe:\"Antidiabétiques — Biguanides & Glitazones\",chapter:\"Antidiabétiques\",page:60,items:[\n  [\"Metformine\",\"GLUCOPHAGE\"],[\"Pioglitazone\",\"ACTOS\"]]},\n{classe:\"Antidiabétiques — Sulfamides hypoglycémiants & Glinides\",chapter:\"Antidiabétiques\",page:60,items:[\n  [\"Glibenclamide\",\"DAONIL\"],[\"Gliclazide\",\"DIAMICRON\"],[\"Glimépiride\",\"AMAREL\"],[\"Répaglinide (glinide)\",\"—\"]]},\n{classe:\"Antidiabétiques — Incrétines & inhibiteurs glucidiques\",chapter:\"Antidiabétiques\",page:61,items:[\n  [\"Sitagliptine (inh. DPP4)\",\"—\"],[\"Exénatide (analogue GLP-1)\",\"—\"],[\"Acarbose (inh. alpha-glucosidase)\",\"—\"]]},\n{classe:\"Antitussifs\",chapter:\"Appareil respiratoire\",page:50,items:[\n  [\"Codéine (opiacé)\",\"NEO CODION\"],[\"Dextrométhorphane\",\"PULMODEXANE\"],[\"Oxomémazine (antihistaminique)\",\"TOPLEXIL\"]]},\n{classe:\"Expectorants / Mucolytiques\",chapter:\"Appareil respiratoire\",page:51,items:[\n  [\"Acétylcystéine\",\"EXOMUC, MUCOMYST\"],[\"Carbocistéine\",\"FLUIDITEC\"],[\"Ambroxol\",\"MUXOL\"]]},\n{classe:\"Bronchodilatateurs (asthme)\",chapter:\"Appareil respiratoire\",page:52,items:[\n  [\"Salbutamol (bêta-2)\",\"VENTOLINE\"],[\"Terbutaline (bêta-2)\",\"BRICANYL\"],[\"Ipratropium (anticholinergique)\",\"ATROVENT\"],[\"Théophylline (xanthine)\",\"DILATRANE\"]]},\n{classe:\"Corticoïdes inhalés & anti-leucotriènes (asthme)\",chapter:\"Appareil respiratoire\",page:53,items:[\n  [\"Fluticasone\",\"FLIXOTIDE\"],[\"Béclométasone\",\"MIFLASONE\"],[\"Montélukast (anti-leucotriène)\",\"SINGULAIR\"]]},\n{classe:\"Antihistaminiques H1\",chapter:\"Antihistaminiques\",page:55,items:[\n  [\"Cétirizine (2ème génération)\",\"ZYRTEC\"],[\"Loratadine (2ème génération)\",\"CLARITYNE\"],[\"Dexchlorphéniramine (1ère génération, sédatif)\",\"POLARAMINE\"]]},\n{classe:\"Anti-sécrétoires gastriques (IPP, anti-H2)\",chapter:\"Appareil digestif\",page:57,items:[\n  [\"Oméprazole (IPP)\",\"IPEPRAZOLE\"],[\"Ésoméprazole (IPP)\",\"INEXIUM\"],[\"Cimétidine (anti-H2)\",\"TAGAMET\"]]},\n{classe:\"Topiques & antiacides gastriques\",chapter:\"Appareil digestif\",page:58,items:[\n  [\"Sucralfate\",\"ULCAR\"],[\"Hydroxyde d'aluminium + magnésium\",\"MAALOX\"],[\"Alginate\",\"GAVISCON\"]]},\n{classe:\"Procinétiques / Antiémétiques\",chapter:\"Appareil digestif\",page:61,items:[\n  [\"Métoclopramide\",\"PRIMPERAN\"],[\"Dompéridone\",\"MOTILUM\"],[\"Ondansétron (anti-5HT3)\",\"ZOPHREN\"]]},\n{classe:\"Antidiarrhéiques\",chapter:\"Appareil digestif\",page:64,items:[\n  [\"Lopéramide\",\"IMODIUM\"],[\"Racécadotril\",\"TIORFAN\"],[\"Diosmectite (argile)\",\"SMECTA\"]]},\n{classe:\"Laxatifs\",chapter:\"Appareil digestif\",page:65,items:[\n  [\"Lactulose (osmotique)\",\"DUPHALAC\"],[\"Bisacodyl (stimulant)\",\"DULCOLAX\"],[\"Macrogol (osmotique)\",\"FORLAX\"]]},\n{classe:\"Anxiolytiques (benzodiazépines)\",chapter:\"Médicaments du SNC (Psychotropes)\",page:69,items:[\n  [\"Diazépam\",\"VALIUM\"],[\"Alprazolam\",\"—\"],[\"Oxazépam (allaitement)\",\"SERESTA\"]]},\n{classe:\"Neuroleptiques / Antipsychotiques\",chapter:\"Médicaments du SNC (Psychotropes)\",page:70,items:[\n  [\"Halopéridol (butyrophénone)\",\"HALDOL\"],[\"Chlorpromazine (phénothiazine)\",\"—\"],[\"Olanzapine (atypique)\",\"—\"]]},\n{classe:\"Hypnotiques\",chapter:\"Médicaments du SNC (Psychotropes)\",page:70,items:[\n  [\"Zolpidem\",\"STILNOX\"],[\"Zopiclone\",\"IMOVANE\"],[\"Phénobarbital (barbiturique)\",\"GARDENAL\"]]},\n{classe:\"Antiparkinsoniens\",chapter:\"Médicaments du SNC (Psychotropes)\",page:71,items:[\n  [\"Lévodopa + Bensérazide\",\"MODOPAR\"],[\"Trihexiphénidyle (anticholinergique)\",\"ARTANE\"]]},\n{classe:\"Antiépileptiques\",chapter:\"Médicaments du SNC (Psychotropes)\",page:71,items:[\n  [\"Acide valproïque\",\"DEPAKINE\"],[\"Carbamazépine\",\"TEGRETOL\"],[\"Diazépam\",\"VALIUM\"]]},\n{classe:\"Ocytociques & utérotoniques\",chapter:\"Hormonaux gynécologiques\",page:75,items:[\n  [\"Méthylergométrine\",\"METHERGIN\"],[\"Ocytocine de synthèse\",\"SYNTHOCINON\"],[\"Misoprostol (prostaglandine)\",\"—\"]]},\n{classe:\"Contraceptifs oraux (par génération de progestatif)\",chapter:\"Hormonaux gynécologiques\",page:78,items:[\n  [\"Lévonorgestrel (2ème génération)\",\"MICROVAL\"],[\"Désogestrel (3ème génération)\",\"CERAZETTE\"],[\"Drospirénone (4ème génération)\",\"BELANETTE\"]]},\n{classe:\"Contraception d'urgence\",chapter:\"Hormonaux gynécologiques\",page:80,items:[\n  [\"Lévonorgestrel (72h)\",\"NORLEVO\"],[\"Ulipristal acétate (120h)\",\"ELLAONE\"]]},\n{classe:\"Inhibiteurs de l'enzyme de conversion (IEC)\",chapter:\"Appareil cardio-vasculaire\",page:83,items:[\n  [\"Captopril\",\"LOPRIL\"],[\"Énalapril\",\"RENITEC\"],[\"Périndopril\",\"COVERSYL\"]]},\n{classe:\"Antagonistes de l'angiotensine II (Sartans)\",chapter:\"Appareil cardio-vasculaire\",page:84,items:[\n  [\"Losartan\",\"COZAAR\"],[\"Valsartan\",\"TAREG\"],[\"Irbésartan\",\"APROVEL\"]]},\n{classe:\"Bêta-bloquants\",chapter:\"Appareil cardio-vasculaire\",page:82,items:[\n  [\"Aténolol (cardio-sélectif)\",\"TENORMINE\"],[\"Bisoprolol (cardio-sélectif)\",\"DETENSEL\"],[\"Propranolol (non cardio-sélectif)\",\"AVLOCARDYL\"]]},\n{classe:\"Inhibiteurs calciques\",chapter:\"Appareil cardio-vasculaire\",page:84,items:[\n  [\"Amlodipine\",\"AMLOR\"],[\"Nifédipine\",\"ADALATE\"],[\"Vérapamil\",\"ISOPTINE\"]]},\n{classe:\"Diurétiques\",chapter:\"Appareil cardio-vasculaire\",page:85,items:[\n  [\"Furosémide (de l'anse, hypokaliémiant)\",\"LASILIX\"],[\"Spironolactone (hyperkaliémiant)\",\"ALDACTONE\"],[\"Hydrochlorothiazide (thiazidique)\",\"ESIDREX\"]]},\n{classe:\"Antiagrégants plaquettaires\",chapter:\"Appareil cardio-vasculaire\",page:87,items:[\n  [\"Aspirine à faible dose\",\"—\"],[\"Clopidogrel\",\"CLOPACT\"],[\"Ticagrelor\",\"BRILIQUE\"]]},\n{classe:\"Antiseptiques cutanés\",chapter:\"Antiseptiques, désinfectants & détergents\",page:93,items:[\n  [\"Chlorhexidine (biguanide)\",\"—\"],[\"Povidone iodée (dérivé iodé)\",\"—\"],[\"Éosine (colorant)\",\"—\"],[\"Alcool\",\"—\"]]},\n];\n\n/* =========================================================\n   RESUMES DE COURS (par chapitre)\n   ========================================================= */\nconst SUMMARIES = {\n\"Généralités\":{page:\"4-17\",source:\"2025\",bullets:[\n  \"Le médicament comporte deux composantes : le principe actif (effet thérapeutique) et l'excipient (support, sans action pharmacologique visée).\",\n  \"5 voies d'administration : orale, parentérale (IV, SC, IM), transmuqueuse (sublinguale, rectale, vaginale, nasale, oculaire), percutanée, pulmonaire.\",\n  \"Un médicament princeps est protégé par un brevet (~10 ans + 5 ans CCP) ; le générique copie le même principe actif une fois le brevet expiré.\",\n  \"DCI (Dénomination Commune Internationale) = nom scientifique unique et universel du principe actif, retenu par l'OMS.\",\n  \"3 types d'interactions médicamenteuses : Addition (A+B = A et B), Synergie (A+B > A et B), Antagonisme (A+B < A et B).\",\n  \"Effet indésirable = réaction nocive et non voulue, même à dose normale. 3 stades de gravité : grave (danger vital), sévère (soins en plus), modéré (banal).\",\n  \"L'ordonnance est valable 3 mois après sa rédaction ; la durée maximale d'un traitement est d'1 an (12 semaines pour les anxiolytiques).\"\n]},\n\"Antalgiques & fièvre\":{page:\"18-22\",source:\"2025\",bullets:[\n  \"Classification OMS des antalgiques en 3 niveaux : Niveau 1 = paracétamol + AINS (douleurs faibles/modérées), Niveau 2 = codéine + tramadol (modérées/sévères), Niveau 3 = morphine (très sévères).\",\n  \"Les antipyrétiques (paracétamol, aspirine, ibuprofène, métamizole) agissent en inhibant la cyclo-oxygénase (COX).\",\n  \"Le métamizole est contre-indiqué au 3ème trimestre de grossesse et pendant l'allaitement (risque d'agranulocytose grave).\",\n  \"Antispasmodiques neurotropes/anticholinergiques (Buscopan, Spasmodex) bloquent l'acétylcholine ; les musculotropes (Spasfon, Debridat) agissent directement sur le muscle lisse.\"\n]},\n\"Anti-inflammatoires & anesthésiques\":{page:\"24-29\",source:\"2025\",bullets:[\n  \"Tous les anti-inflammatoires (stéroïdiens et non stéroïdiens) inhibent la synthèse des prostaglandines ; effet secondaire commun : lésion de la muqueuse gastroduodénale.\",\n  \"AINS formellement contre-indiqués à partir du 6ème mois de grossesse (fermeture prématurée du canal artériel) ; le paracétamol reste le seul antipyrétique autorisé toute la grossesse.\",\n  \"L'ibuprofène est l'AINS le plus adapté à l'allaitement.\",\n  \"Contre-indication absolue des neuroleptiques : l'hyperthermie, même légère (risque de syndrome malin).\",\n  \"Anesthésiques locaux (Lidocaïne/XYLOCAINE) vs anesthésiques généraux (Kétamine, Halothane) : ne pas confondre les deux catégories.\"\n]},\n\"Anti-infectieux\":{page:\"29-49\",source:\"2025 & 2022\",bullets:[\n  \"Bactériostatique = inhibe la multiplication ; Bactéricide = tue les bactéries. Piège classique d'examen à ne pas confondre.\",\n  \"L'antibiogramme définit les antibiotiques auxquels une souche est sensible ; il doit être fait avant toute antibiothérapie quand c'est possible.\",\n  \"Grandes familles d'ATB : bêta-lactamines (pénicillines, céphalosporines), macrolides, aminosides, cyclines, quinolones, sulfamides...\",\n  \"Contre-indiqués en grossesse/allaitement : cyclines, aminosides, fluoroquinolones, sulfamides, vancomycine, teicoplanine, fosfomycine, fucidine.\",\n  \"Contre-indiqués chez le nourrisson : sulfamides, ceftriaxone, fluoroquinolones, tétracyclines.\",\n  \"2 effets indésirables communs à tous les ATB : réactions allergiques et troubles digestifs. Cyclines/quinolones → photosensibilisation ; quinolones → tendinite.\",\n  \"Antipaludéens : effet intra-érythrocytaire (quinine, chloroquine) vs inhibiteurs de la dihydrofolate réductase (Fansidar). ACT recommandées par l'OMS = artémisinine + partenaire.\",\n  \"Antifongiques (Fluconazole, Kétoconazole) et anthelminthiques (Albendazole, Praziquantel, Ivermectine) traitent champignons et vers respectivement.\"\n]},\n\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\":{page:\"33-38\",source:\"2022\",bullets:[\n  \"Ces pathologies sont encadrées par des directives OMS mondiales car elles constituent des pandémies à forte morbidité/mortalité.\",\n  \"Antirétroviraux : INTI (Zidovudine, Lamivudine), INNTI (Efavirenz, Névirapine), inhibiteurs de protéase (Ritonavir), inhibiteurs de l'intégrase (Raltégravir), inhibiteurs d'entrée CCR5 (Maraviroc), inhibiteurs de fusion (Enfuvirtide).\",\n  \"Antituberculeux bactéricides : Isoniazide, Rifampicine, Pyrazinamide, Streptomycine. Bactériostatiques : Éthambutol, Rifabutine.\",\n  \"Antilépreux : Dapsone (DDS), Clofazimine, Rifampicine, Sulfadoxine, Thalidomide.\",\n  \"Directives ACT antipaludéennes de l'OMS : Artéméther+Luméfantrine, Artésunate+Amodiaquine, Artésunate+Méfloquine, Artésunate+Sulfadoxine-Pyriméthamine.\"\n]},\n\"Antidiabétiques\":{page:\"58-61\",source:\"2022\",bullets:[\n  \"Diabète = hyperglycémie chronique (≥2 glycémies à jeun > 7 mmol/L / 1,26 g/L).\",\n  \"Type 1 : destruction des cellules bêta pancréatiques → substitution en insuline d'emblée.\",\n  \"Type 2 : insulinorésistance → 1ère intention = biguanides (Metformine/GLUCOPHAGE), puis association d'autres oraux, puis insuline en dernier recours.\",\n  \"Insulino-sensibilisateurs : biguanides, glitazones. Insulino-sécréteurs : sulfamides hypoglycémiants, glinides, incrétino-mimétiques (GLP-1, inhibiteurs DPP4).\",\n  \"Inhibiteurs des alpha-glucosidases (Acarbose, Miglitol) freinent l'absorption intestinale des glucides.\"\n]},\n\"Appareil respiratoire\":{page:\"50-53\",source:\"2025\",bullets:[\n  \"Toux sèche → antitussifs vrais (bloquent le réflexe cérébral de la toux) ; toux grasse → expectorants/mucolytiques (fluidifient le mucus).\",\n  \"Antitussifs opiacés (Codéine) vs non opiacés (Dextrométhorphane, Oxéladine).\",\n  \"Bêta-2-stimulants (Salbutamol/VENTOLINE) = bronchodilatateurs de crise ; corticoïdes inhalés et anti-leucotriènes (Montélukast) = traitements de fond, jamais pour la crise.\"\n]},\n\"Antihistaminiques\":{page:\"54-55\",source:\"2025\",bullets:[\n  \"Les anti-H1 bloquent l'histamine, médiateur des réactions allergiques (rhinite, urticaire, conjonctivite).\",\n  \"2ème génération (Cétirizine, Loratadine) = moins sédative, préférée chez le nourrisson par rapport à la 1ère génération (chlorphéniramine, prométhazine).\"\n]},\n\"Appareil digestif\":{page:\"56-66\",source:\"2025\",bullets:[\n  \"IPP (Oméprazole) inhibent la pompe H+K+ ; anti-H2 (Cimétidine) bloquent le récepteur histaminique ; les deux réduisent l'acidité gastrique.\",\n  \"Nouveau schéma H. pylori : quadrithérapie 14 jours (IPP+amoxicilline+clarithromycine+métronidazole) ou quadrithérapie bismuth 10 jours ; la trithérapie 7 jours n'est plus recommandée.\",\n  \"RGO : alginates/IPP réduisent l'acidité, procinétiques (Métoclopramide) renforcent le sphincter œsophagien inférieur.\",\n  \"Antiémétiques : procinétiques (RGO/nausées), anti-5HT3 (chimiothérapie), neuroleptiques antiémétiques (post-opératoire).\",\n  \"Antidiarrhéiques : ralentisseurs du transit (Lopéramide) vs antisécrétoires intestinaux (Racécadotril). Laxatifs : osmotiques, lubrifiants, stimulants, de lest.\"\n]},\n\"Médicaments du SNC (Psychotropes)\":{page:\"67-71\",source:\"2025\",bullets:[\n  \"5 grandes familles de psychotropes : anxiolytiques, antidépresseurs, neuroleptiques, hypnotiques, thymorégulateurs.\",\n  \"Neuroleptiques : 4 classes (phénothiazines, butyrophénones, thioxanthènes, atypiques) ; contre-indication absolue = hyperthermie.\",\n  \"Anxiolytiques (benzodiazépines) : risques en grossesse (malformations 1er trimestre) et allaitement (choisir l'Oxazépam/SERESTA, qui passe le moins dans le lait).\",\n  \"Antiparkinsoniens (Lévodopa+Bensérazide) et antiépileptiques (Acide valproïque, Carbamazépine, Diazépam) sont décrits à part des 5 grandes familles.\"\n]},\n\"Hormonaux gynécologiques\":{page:\"72-81\",source:\"2025\",bullets:[\n  \"Ocytociques (Méthylergométrine, Ocytocine) provoquent des contractions utérines ; utilisés en cas d'hémorragie du post-partum.\",\n  \"Le Misoprostol réduit de 60% le risque de saignements abondants du post-partum.\",\n  \"Contraception hormonale = 3 mécanismes : blocage de l'ovulation, épaississement de la glaire cervicale, amincissement de l'endomètre.\",\n  \"Pilules 1ère/2ème génération = moins de risque de thrombose veineuse que 3ème/4ème génération.\",\n  \"Contraception d'urgence : Lévonorgestrel/NORLEVO (jusqu'à 72h) ou Ulipristal/ELLAONE (jusqu'à 120h).\"\n]},\n\"Appareil cardio-vasculaire\":{page:\"81-89\",source:\"2025\",bullets:[\n  \"IEC bloquent la formation de l'angiotensine II ; les Sartans bloquent son récepteur sans empêcher sa formation.\",\n  \"Cardiotoniques (Digoxine) : règle des 3R = Renforce, Régularise, Ralentit le rythme cardiaque.\",\n  \"Diurétiques : de l'anse (Furosémide, hypokaliémiant), thiazidiques, hyperkaliémiants (Spironolactone).\",\n  \"Antiagrégants plaquettaires (empêchent la formation de caillots) ≠ thrombolytiques (dissolvent un caillot déjà formé).\"\n]},\n\"Vitamines & Oligo-éléments\":{page:\"89-99\",source:\"2025\",bullets:[\n  \"Vitamines liposolubles (A, D, E, K) sont stockées → risque d'hypervitaminose en cas d'excès.\",\n  \"Vitamine B9 (acide folique) : systématique chez la femme en âge de procréer avant grossesse (développement du système nerveux embryonnaire).\",\n  \"Vitamine K : essentielle à la coagulation (facteurs II, VII, IX, X) ; apport systématique au nouveau-né car le lait maternel en est pauvre.\",\n  \"Oligo-éléments clés : Iode (thyroïde), Fer (hémoglobine), Zinc (immunité/cicatrisation), Calcium (os/coagulation).\"\n]},\n\"Antiseptiques, désinfectants & détergents\":{page:\"91-96\",source:\"2022\",bullets:[\n  \"Détergent = nettoie sans tuer les microbes. Antiseptique = tue les microbes sur tissu vivant. Désinfectant = tue les microbes sur matériel/surface inerte.\",\n  \"Antisepsie = élimine les microbes déjà présents (tissu vivant) ; Asepsie = prévient tout apport de microbes (ex : stérilisation).\",\n  \"Eau de javel : puissant désinfectant, antiseptique seulement à faible degré (<5°chl), à conserver à l'abri de la lumière, jamais mélangée à un détergent.\",\n  \"Antiseptiques cutanés : biguanides (chlorhexidine), dérivés iodés (povidone iodée), colorants (éosine), alcool.\",\n  \"Solutions hydro-alcooliques (SHA) : bactéricides/virucides/fongicides mais sans effet nettoyant ; contact minimal 10-15 secondes ; contre-indiquées sur mains mouillées, souillées ou lésées.\"\n]}\n};\n\n/* =========================================================\n   FLASHCARDS (système Leitner — 200+ cartes)\n   ========================================================= */\nconst FLASHCARDS_STATIC = [\n// Généralités\n{chapter:\"Généralités\",page:5,front:\"Qu'est-ce que le principe actif d'un médicament ?\",back:\"La molécule qui possède l'effet thérapeutique, en faible proportion par rapport aux excipients.\"},\n{chapter:\"Généralités\",page:6,front:\"À quoi sert l'excipient ?\",back:\"À donner une consistance ou des caractéristiques physiques/gustatives au produit, sans interagir avec le principe actif.\"},\n{chapter:\"Généralités\",page:6,front:\"Cite les 5 voies d'administration principales.\",back:\"Orale, parentérale, transmuqueuse, percutanée, pulmonaire.\"},\n{chapter:\"Généralités\",page:13,front:\"Que signifie DCI ?\",back:\"Dénomination Commune Internationale : le nom scientifique unique d'un principe actif, retenu par l'OMS.\"},\n{chapter:\"Généralités\",page:12,front:\"Qu'est-ce qu'un médicament princeps ?\",back:\"Le premier médicament à incorporer un principe actif, protégé par un brevet (~10 ans + 5 ans de CCP).\"},\n{chapter:\"Généralités\",page:13,front:\"Donne un exemple d'interaction médicamenteuse de type synergie.\",back:\"A + B > A et B : l'effet combiné est supérieur à la somme des effets individuels.\"},\n{chapter:\"Généralités\",page:14,front:\"Comment l'OMS (1972) définit-elle un effet indésirable ?\",back:\"Une réaction nocive et non voulue, survenant même aux posologies normalement utilisées.\"},\n{chapter:\"Généralités\",page:16,front:\"Quelle est la durée de validité d'une ordonnance après sa rédaction ?\",back:\"3 mois maximum (durée du traitement : 1 an max, sauf anxiolytiques limités à 12 semaines).\"},\n// Antalgiques\n{chapter:\"Antalgiques & fièvre\",page:20,front:\"Quels antalgiques composent le niveau 1 de l'OMS ?\",back:\"Le paracétamol et les AINS (douleurs faibles à modérées).\"},\n{chapter:\"Antalgiques & fièvre\",page:20,front:\"Quel est le chef de file des antalgiques de niveau 3 ?\",back:\"La morphine (douleurs très sévères, rebelles).\"},\n{chapter:\"Antalgiques & fièvre\",page:21,front:\"Quel est le mécanisme commun des antipyrétiques ?\",back:\"L'inhibition de la voie de la cyclo-oxygénase (COX).\"},\n{chapter:\"Antalgiques & fièvre\",page:23,front:\"Différence entre antispasmodique neurotrope et musculotrope ?\",back:\"Neurotrope bloque l'acétylcholine (Buscopan) ; musculotrope agit directement sur le muscle lisse (Spasfon).\"},\n// Anti-inflammatoires\n{chapter:\"Anti-inflammatoires & anesthésiques\",page:25,front:\"Quel est le mécanisme commun à tous les anti-inflammatoires ?\",back:\"L'inhibition de la synthèse des prostaglandines.\"},\n{chapter:\"Anti-inflammatoires & anesthésiques\",page:26,front:\"À partir de quand les AINS sont-ils formellement contre-indiqués en grossesse ?\",back:\"À partir du 6e mois (24 semaines d'aménorrhée) : risque de fermeture prématurée du canal artériel.\"},\n{chapter:\"Anti-inflammatoires & anesthésiques\",page:27,front:\"Quelle est la contre-indication absolue des neuroleptiques ?\",back:\"L'hyperthermie, même légère (risque de syndrome malin, parfois mortel).\"},\n{chapter:\"Anti-inflammatoires & anesthésiques\",page:28,front:\"Donne un exemple d'anesthésique local.\",back:\"Lidocaïne (XYLOCAINE).\"},\n// Anti-infectieux\n{chapter:\"Anti-infectieux\",page:30,front:\"Différence entre bactériostatique et bactéricide ?\",back:\"Bactériostatique = inhibe la multiplication. Bactéricide = tue les bactéries.\"},\n{chapter:\"Anti-infectieux\",page:32,front:\"À quoi sert un antibiogramme ?\",back:\"À définir les antibiotiques auxquels une souche bactérienne isolée est sensible.\"},\n{chapter:\"Anti-infectieux\",page:34,front:\"Quelles familles d'ATB sont contre-indiquées en grossesse/allaitement ?\",back:\"Aminosides, cyclines, fluoroquinolones, sulfamides, vancomycine, teicoplanine, fosfomycine, fucidine.\"},\n{chapter:\"Anti-infectieux\",page:34,front:\"Quels 2 effets indésirables sont communs à presque tous les antibiotiques ?\",back:\"Réactions allergiques et troubles digestifs.\"},\n{chapter:\"Anti-infectieux\",page:35,front:\"Quelles classes d'ATB provoquent une photosensibilisation ?\",back:\"Les cyclines et les quinolones.\"},\n{chapter:\"Anti-infectieux\",page:46,front:\"Qu'est-ce qu'une ACT dans le traitement du paludisme ?\",back:\"Une combinaison thérapeutique à base d'artémisinine, recommandée en 1ère intention par l'OMS.\"},\n// Prises en charge encadrées\n{chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:36,front:\"Cite les 4 classes principales d'antirétroviraux (ARV).\",back:\"INTI, INNTI, inhibiteurs de la protéase, inhibiteurs de l'intégrase (+ inhibiteurs d'entrée/fusion).\"},\n{chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:37,front:\"Cite 3 antituberculeux bactéricides.\",back:\"Isoniazide, Rifampicine, Pyrazinamide (+ Streptomycine).\"},\n{chapter:\"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\",page:37,front:\"Quel médicament antilépreux est aussi un antituberculeux ?\",back:\"La Rifampicine.\"},\n// Antidiabétiques\n{chapter:\"Antidiabétiques\",page:59,front:\"Quelle est la cause du diabète de type 1 ?\",back:\"Destruction des cellules bêta pancréatiques : carence en insuline d'emblée.\"},\n{chapter:\"Antidiabétiques\",page:60,front:\"Quel est le traitement oral de 1ère intention du diabète de type 2 ?\",back:\"Les biguanides (Metformine / GLUCOPHAGE).\"},\n{chapter:\"Antidiabétiques\",page:61,front:\"Comment agissent les inhibiteurs des alpha-glucosidases (Acarbose) ?\",back:\"Ils inhibent l'absorption intestinale des glucides.\"},\n// Respiratoire\n{chapter:\"Appareil respiratoire\",page:50,front:\"Quand utilise-t-on un expectorant plutôt qu'un antitussif vrai ?\",back:\"En cas de toux grasse/productive (l'antitussif vrai est réservé à la toux sèche).\"},\n{chapter:\"Appareil respiratoire\",page:52,front:\"Quel est le mécanisme des bêta-2-stimulants (Salbutamol) ?\",back:\"Bronchodilatation par relâchement de la musculature bronchique, via les récepteurs bêta-2.\"},\n{chapter:\"Appareil respiratoire\",page:53,front:\"Le Montélukast peut-il être utilisé pour soulager une crise d'asthme ?\",back:\"Non : c'est un traitement de fond, pas un traitement de crise.\"},\n// Antihistaminiques\n{chapter:\"Antihistaminiques\",page:54,front:\"Quel médiateur bloquent les antihistaminiques anti-H1 ?\",back:\"L'histamine.\"},\n{chapter:\"Antihistaminiques\",page:55,front:\"Pourquoi préfère-t-on les antihistaminiques de 2e génération chez le nourrisson ?\",back:\"Ils sont moins sédatifs (traversent moins la barrière hémato-encéphalique).\"},\n// Digestif\n{chapter:\"Appareil digestif\",page:57,front:\"Quel est le mécanisme des IPP ?\",back:\"Inhibition de l'ATPase H+K+ de la cellule pariétale gastrique.\"},\n{chapter:\"Appareil digestif\",page:60,front:\"Quel est le nouveau schéma de 1ère intention pour éradiquer H. pylori ?\",back:\"Quadrithérapie concomitante 14 jours (IPP + amoxicilline + clarithromycine + métronidazole).\"},\n{chapter:\"Appareil digestif\",page:64,front:\"Quel est le mécanisme du Lopéramide (IMODIUM) ?\",back:\"Diminution de la motilité et des sécrétions intestinales.\"},\n// SNC\n{chapter:\"Médicaments du SNC (Psychotropes)\",page:68,front:\"Cite les 5 grandes familles de psychotropes.\",back:\"Anxiolytiques, antidépresseurs, neuroleptiques, hypnotiques, thymorégulateurs.\"},\n{chapter:\"Médicaments du SNC (Psychotropes)\",page:71,front:\"Quel anxiolytique privilégier pendant l'allaitement ?\",back:\"L'oxazépam (SERESTA), qui passe le moins dans le lait maternel.\"},\n// Hormonaux\n{chapter:\"Hormonaux gynécologiques\",page:78,front:\"Cite les 3 mécanismes de la contraception hormonale.\",back:\"Blocage de l'ovulation, épaississement de la glaire cervicale, amincissement de l'endomètre.\"},\n{chapter:\"Hormonaux gynécologiques\",page:80,front:\"Jusqu'à combien d'heures le Lévonorgestrel (NORLEVO) est-il efficace ?\",back:\"72 heures (3 jours) après le rapport.\"},\n// Cardio\n{chapter:\"Appareil cardio-vasculaire\",page:84,front:\"Différence entre IEC et sartans ?\",back:\"IEC bloquent la formation de l'angiotensine II ; sartans bloquent son récepteur sans empêcher sa formation.\"},\n{chapter:\"Appareil cardio-vasculaire\",page:84,front:\"Quelle est la règle des 3R des cardiotoniques ?\",back:\"Renforce, Régularise, Ralentit le rythme cardiaque.\"},\n// Vitamines\n{chapter:\"Vitamines & Oligo-éléments\",page:93,front:\"Quelle vitamine est prescrite systématiquement avant une grossesse désirée ?\",back:\"La vitamine B9 (acide folique).\"},\n{chapter:\"Vitamines & Oligo-éléments\",page:96,front:\"Quel oligo-élément est essentiel à la thyroïde ?\",back:\"L'iode.\"},\n// Antiseptiques\n{chapter:\"Antiseptiques, désinfectants & détergents\",page:91,front:\"Différence entre détergent et antiseptique ?\",back:\"Le détergent nettoie sans tuer les microbes ; l'antiseptique élimine les microbes sur un tissu vivant.\"},\n{chapter:\"Antiseptiques, désinfectants & détergents\",page:94,front:\"Les solutions hydro-alcooliques ont-elles un effet nettoyant ?\",back:\"Non : elles sont bactéricides/virucides/fongicides mais sans effet nettoyant (mains déjà propres requises).\"},\n];\n\nfunction buildFlashcardsFromMeds(){\n  const cards = [];\n  MEDS.forEach((g,gi)=>{\n    g.items.forEach(([dci,brands],ii)=>{\n      cards.push({\n        id:\"fm_\"+gi+\"_\"+ii, chapter:g.chapter, page:g.page,\n        front:\"À quelle classe appartient « \"+dci+\" » ?\",\n        back:g.classe + (brands && brands!==\"—\" ? \"  (ex. \"+brands+\")\" : \"\")\n      });\n    });\n  });\n  return cards;\n}\n\nfunction buildFlashcards(){\n  const fromMeds = buildFlashcardsFromMeds();\n  const statics = FLASHCARDS_STATIC.map((c,i)=> ({ id:\"fs_\"+i, ...c }));\n  return statics.concat(fromMeds);\n}\nconst FLASHCARDS = buildFlashcards();\n\n/* =========================================================\n   ETAT / STOCKAGE\n   ========================================================= */\nconst STORAGE_KEY = \"pharmacoInfasProgress_v1\";\nlet progress = loadProgress();\n\nfunction loadProgress(){\n  try{\n    const raw = localStorage.getItem(STORAGE_KEY);\n    if(!raw) return defaultProgress();\n    const p = JSON.parse(raw);\n    if(!p.mastery) p.mastery = {};\n    if(!p.history) p.history = [];\n    return p;\n  }catch(e){ return defaultProgress(); }\n}\nfunction defaultProgress(){\n  return { mastery:{}, history:[], totalSeen:0, totalCorrect:0, lastExam:null, flashBoxes:{}, flashDue:{} };\n}\nconst LEITNER_INTERVAL_DAYS = [1,2,4,7,14]; // index = box (0..4)\nfunction getFlashBox(id){ if(!progress.flashBoxes) progress.flashBoxes={}; return progress.flashBoxes[id] ?? 0; }\nfunction isFlashDue(card){\n  if(!progress.flashDue) progress.flashDue={};\n  const due = progress.flashDue[card.id];\n  if(!due) return true;\n  return new Date(due).getTime() <= Date.now();\n}\nfunction recordFlashResult(card, result){ // result: \"again\" | \"good\" | \"easy\"\n  if(!progress.flashBoxes) progress.flashBoxes={};\n  if(!progress.flashDue) progress.flashDue={};\n  let box = getFlashBox(card.id);\n  if(result===\"again\") box = 0;\n  else if(result===\"good\") box = Math.min(4, box+1);\n  else if(result===\"easy\") box = 4;\n  progress.flashBoxes[card.id] = box;\n  const next = new Date(Date.now() + LEITNER_INTERVAL_DAYS[box]*24*3600*1000);\n  progress.flashDue[card.id] = next.toISOString();\n  saveProgress();\n}\nfunction flashStats(){\n  const total = FLASHCARDS.length;\n  let dueCount=0, masteredCount=0;\n  FLASHCARDS.forEach(c=>{ if(isFlashDue(c)) dueCount++; if(getFlashBox(c.id)>=4) masteredCount++; });\n  return {total, dueCount, masteredCount};\n}\nfunction saveProgress(){\n  try{ localStorage.setItem(STORAGE_KEY, JSON.stringify(progress)); }catch(e){ console.error(\"Erreur de sauvegarde\", e); }\n}\nfunction testLocalStorage(){\n  try{\n    const testKey=\"__pharmaco_test__\", testVal=\"ok-\"+Date.now();\n    localStorage.setItem(testKey,testVal);\n    const read = localStorage.getItem(testKey);\n    const success = read === testVal;\n    localStorage.removeItem(testKey);\n    const verify = localStorage.getItem(testKey);\n    console.log(\"testLocalStorage:\", success && verify===null ? \"SUCCES\" : \"ECHEC\");\n    return success && verify===null;\n  }catch(e){ console.log(\"testLocalStorage: ECHEC\", e); return false; }\n}\ntestLocalStorage();\n\nfunction getMastery(qid){ return progress.mastery[qid] ?? 0; } // 0..4\nfunction bumpMastery(qid, correct){\n  const cur = getMastery(qid);\n  const next = correct ? Math.min(4, cur+1) : Math.max(0, cur-1);\n  progress.mastery[qid] = next;\n  progress.totalSeen++;\n  if(correct) progress.totalCorrect++;\n  saveProgress();\n}\nconst MASTERY_LABEL = [\"Non maîtrisée\",\"Fragile\",\"En progression\",\"Maîtrisée\",\"Très bien maîtrisée\"];\n\n/* =========================================================\n   NAVIGATION / ETAT DE L'APP\n   ========================================================= */\nlet view = \"home\"; // home | quiz | dashboard | resume | meds | pdf | voice\nlet queue = [];        // array of question objects for current session\nlet qIndex = 0;\nlet answersGiven = {};  // qid -> {given, correct, revealed}\nlet selectedOptions = {}; // qid -> array/string current selection before validating\nlet filters = { chapters: new Set(CHAPTERS), types: new Set([\"qcm\",\"qcd\",\"libre\",\"association\"]), difficulties:new Set([\"facile\",\"moyen\",\"difficile\"]) };\nlet sessionLabel = \"\";\nlet searchQuery = \"\";\nlet medsSearchQuery = \"\";\nlet openChapterInResume = null;\nlet flashQueue = [];\nlet flashIndex = 0;\nlet flashRevealed = false;\nlet flashSessionLabel = \"\";\nlet flashChapterFilter = new Set(CHAPTERS);\nlet chaptersExpanded = false;\nlet flashChaptersExpanded = false;\n\nconst CHAPTER_SHORT = {\n  \"Généralités\":\"Généralités\",\n  \"Antalgiques & fièvre\":\"Antalgiques\",\n  \"Anti-inflammatoires & anesthésiques\":\"Anti-inflam.\",\n  \"Anti-infectieux\":\"Anti-infectieux\",\n  \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\":\"Paludisme/VIH/TB/Lèpre\",\n  \"Antidiabétiques\":\"Antidiabétiques\",\n  \"Appareil respiratoire\":\"Respiratoire\",\n  \"Antihistaminiques\":\"Antihistaminiques\",\n  \"Appareil digestif\":\"Digestif\",\n  \"Médicaments du SNC (Psychotropes)\":\"SNC / Psychotropes\",\n  \"Hormonaux gynécologiques\":\"Hormonaux gynéco\",\n  \"Appareil cardio-vasculaire\":\"Cardio-vasculaire\",\n  \"Vitamines & Oligo-éléments\":\"Vitamines/Oligo\",\n  \"Antiseptiques, désinfectants & détergents\":\"Antiseptiques\"\n};\nfunction shortChapterLabel(ch){ return CHAPTER_SHORT[ch] || ch; }\n\nconst TABS = [\n  {key:\"home\", icon:\"🏠\", label:\"Accueil\"},\n  {key:\"resume\", icon:\"📖\", label:\"Résumé\"},\n  {key:\"meds\", icon:\"💊\", label:\"Médicaments\"},\n  {key:\"flash\", icon:\"🗂️\", label:\"Flashcards\"},\n];\n\nfunction shuffle(arr){\n  const a = arr.slice();\n  for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; }\n  return a;\n}\n\nfunction buildFilteredPool(){\n  return Q.filter(q => filters.chapters.has(q.chapter) && filters.types.has(q.type) && filters.difficulties.has(q.difficulty));\n}\n\nfunction startSession(list, label){\n  queue = shuffle(list);\n  qIndex = 0;\n  answersGiven = {};\n  selectedOptions = {};\n  sessionLabel = label;\n  view = \"quiz\";\n  render();\n}\n\nfunction startQuickRevision(minutes){\n  const perMinute = 1.2;\n  const count = Math.max(5, Math.round(minutes*perMinute));\n  const pool = buildFilteredPool();\n  const weighted = pool.slice().sort((a,b)=> getMastery(a.id)-getMastery(b.id));\n  startSession(weighted.slice(0, Math.min(count, weighted.length)), \"Révision rapide · \"+minutes+\" min\");\n}\n\nfunction startExamBlanc(){\n  const pool = shuffle(Q);\n  startSession(pool.slice(0, Math.min(30,pool.length)), \"Examen blanc\");\n}\n\nfunction startMedOfDay(){\n  const pool = buildFilteredPool();\n  if(pool.length===0){ startSession(Q.slice(0,4),\"Médicament du jour\"); return; }\n  const seed = new Date().toDateString();\n  let h=0; for(let i=0;i<seed.length;i++){ h = (h*31 + seed.charCodeAt(i))>>>0; }\n  const startIdx = h % pool.length;\n  const picks = [];\n  for(let i=0;i<Math.min(4,pool.length);i++){ picks.push(pool[(startIdx+i)%pool.length]); }\n  startSession(picks, \"Médicament du jour\");\n}\n\n/* =========================================================\n   RENDU\n   ========================================================= */\nfunction el(html){ const d=document.createElement(\"div\"); d.innerHTML=html.trim(); return d.firstChild; }\nfunction esc(s){ return (s||\"\").replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\"); }\n\nlet previousView = null;\nfunction render(){\n  const app = document.getElementById(\"app\");\n  app.innerHTML = \"\";\n  if(view!==\"quiz\" && view!==\"flashSession\"){\n    app.appendChild(renderTileGrid());\n    app.appendChild(renderSearchBar());\n  }\n  if(view===\"home\") app.appendChild(renderHome());\n  else if(view===\"quiz\") app.appendChild(renderQuiz());\n  else if(view===\"dashboard\") app.appendChild(renderDashboard());\n  else if(view===\"resume\") app.appendChild(renderResume());\n  else if(view===\"meds\") app.appendChild(renderMeds());\n  else if(view===\"flash\") app.appendChild(renderFlashHub());\n  else if(view===\"flashSession\") app.appendChild(renderFlashSession());\n  if(view!==previousView){ window.scrollTo({top:0,behavior:\"instant\"}); previousView = view; }\n}\n\nfunction renderTileGrid(){\n  const grid = el(`<div class=\"tile-grid\"></div>`);\n  TABS.forEach(t=>{\n    const tile = el(`\n      <div class=\"tile ${view===t.key?'active':''}\">\n        <span class=\"tile-icon\">${t.icon}</span>\n        <span class=\"tile-label\">${esc(t.label)}</span>\n      </div>\n    `);\n    tile.addEventListener(\"click\", ()=>{ view=t.key; searchQuery=\"\"; render(); });\n    grid.appendChild(tile);\n  });\n  return grid;\n}\n\nfunction renderSearchBar(){\n  const wrap = el(`<div class=\"card\" style=\"padding:12px 14px;margin-bottom:10px;\"></div>`);\n  wrap.appendChild(el(`<input type=\"text\" id=\"globalSearch\" placeholder=\"🔍 Rechercher un mot-clé, un médicament, une DCI...\" style=\"width:100%;background:rgba(255,255,255,0.04);border:1px solid var(--panel-brd);border-radius:12px;padding:11px 13px;color:var(--txt);font-size:14px;\" value=\"${esc(searchQuery)}\">`));\n  const resultsHost = el(`<div id=\"searchResults\"></div>`);\n  wrap.appendChild(resultsHost);\n  const input = wrap.querySelector(\"#globalSearch\");\n  input.addEventListener(\"input\", (e)=>{\n    searchQuery = e.target.value;\n    renderSearchResultsInto(resultsHost, searchQuery);\n  });\n  if(searchQuery) renderSearchResultsInto(resultsHost, searchQuery);\n  return wrap;\n}\n\nfunction renderSearchResultsInto(host, query){\n  host.innerHTML = \"\";\n  const q = query.trim().toLowerCase();\n  if(q.length < 2) return;\n\n  const qHits = Q.filter(item=> item.question.toLowerCase().includes(q) || item.chapter.toLowerCase().includes(q) || (item.explanation||\"\").toLowerCase().includes(q)).slice(0,6);\n  const medHits = [];\n  MEDS.forEach(group=>{\n    group.items.forEach(([dci,brands])=>{\n      if(dci.toLowerCase().includes(q) || (brands||\"\").toLowerCase().includes(q) || group.classe.toLowerCase().includes(q)){\n        medHits.push({group, dci, brands});\n      }\n    });\n  });\n  const sumHits = [];\n  Object.keys(SUMMARIES).forEach(ch=>{\n    SUMMARIES[ch].bullets.forEach(b=>{\n      if(b.toLowerCase().includes(q) || ch.toLowerCase().includes(q)) sumHits.push({ch,bullet:b});\n    });\n  });\n\n  if(qHits.length===0 && medHits.length===0 && sumHits.length===0){\n    host.appendChild(el(`<div class=\"hint mt14\">Aucun résultat pour « ${esc(query)} ».</div>`));\n    return;\n  }\n\n  const box = el(`<div class=\"mt14\"></div>`);\n  if(medHits.length>0){\n    box.appendChild(el(`<div class=\"label\" style=\"font-size:11px;text-transform:uppercase;color:var(--txt-faint);margin-bottom:6px;\">💊 Médicaments (${medHits.length})</div>`));\n    medHits.slice(0,6).forEach(h=>{\n      const row = el(`<div class=\"chapter-row\" style=\"cursor:pointer;\"><div class=\"cname\"><b>${esc(h.dci)}</b> <span style=\"color:var(--txt-faint);\">— ${esc(h.brands)}</span><br><small style=\"color:var(--txt-faint);\">${esc(h.group.classe)}</small></div></div>`);\n      row.addEventListener(\"click\", ()=>{ view=\"meds\"; medsSearchQuery=h.dci; searchQuery=\"\"; render(); });\n      box.appendChild(row);\n    });\n  }\n  if(qHits.length>0){\n    box.appendChild(el(`<div class=\"label mt14\" style=\"font-size:11px;text-transform:uppercase;color:var(--txt-faint);margin-bottom:6px;\">❓ Questions (${qHits.length})</div>`));\n    qHits.forEach(item=>{\n      const row = el(`<div class=\"chapter-row\" style=\"cursor:pointer;\"><div class=\"cname\">${esc(item.question.slice(0,80))}${item.question.length>80?'…':''}<br><small style=\"color:var(--txt-faint);\">${esc(item.chapter)}</small></div></div>`);\n      row.addEventListener(\"click\", ()=>{ startSession([item], \"Résultat de recherche\"); searchQuery=\"\"; });\n      box.appendChild(row);\n    });\n  }\n  if(sumHits.length>0){\n    box.appendChild(el(`<div class=\"label mt14\" style=\"font-size:11px;text-transform:uppercase;color:var(--txt-faint);margin-bottom:6px;\">📖 Résumé de cours (${sumHits.length})</div>`));\n    sumHits.slice(0,5).forEach(h=>{\n      const row = el(`<div class=\"chapter-row\" style=\"cursor:pointer;\"><div class=\"cname\">${esc(h.bullet.slice(0,90))}${h.bullet.length>90?'…':''}<br><small style=\"color:var(--txt-faint);\">${esc(h.ch)}</small></div></div>`);\n      row.addEventListener(\"click\", ()=>{ view=\"resume\"; openChapterInResume=h.ch; searchQuery=\"\"; render(); });\n      box.appendChild(row);\n    });\n  }\n  host.appendChild(box);\n}\n\nfunction renderHome(){\n  const wrap = el(`<div></div>`);\n\n  // Dashboard summary strip\n  const totalQ = Q.length;\n  const masteredCount = Q.filter(q=>getMastery(q.id)>=3).length;\n  const globalPct = totalQ ? Math.round((Object.keys(progress.mastery).length? sumMasteryPct():0)) : 0;\n\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Mon niveau</h2>\n      <div class=\"dash-grid\">\n        <div class=\"stat\"><div class=\"num\">${globalPct}%</div><div class=\"lbl\">Maîtrise globale</div></div>\n        <div class=\"stat\"><div class=\"num\">${masteredCount}/${totalQ}</div><div class=\"lbl\">Notions maîtrisées</div></div>\n        <div class=\"stat\"><div class=\"num\">${progress.totalSeen}</div><div class=\"lbl\">Questions vues</div></div>\n        <div class=\"stat\"><div class=\"num\">${progress.totalSeen? Math.round(100*progress.totalCorrect/progress.totalSeen):0}%</div><div class=\"lbl\">Taux de réussite</div></div>\n      </div>\n      <div class=\"row mt14\">\n        <button class=\"btn small\" id=\"btnDashboard\">📊 Tableau de bord détaillé</button>\n        <button class=\"btn small ghost\" id=\"btnReset\">♻️ Réinitialiser ma progression</button>\n      </div>\n    </div>\n  `));\n\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Modes rapides</h2>\n      <div class=\"row\">\n        <button class=\"btn\" data-min=\"5\">⚡ 5 min</button>\n        <button class=\"btn\" data-min=\"10\">⚡ 10 min</button>\n        <button class=\"btn\" data-min=\"20\">⚡ 20 min</button>\n        <button class=\"btn\" data-min=\"30\">⚡ 30 min</button>\n      </div>\n      <p class=\"hint\">Choisit automatiquement les notions les moins maîtrisées, dans les chapitres sélectionnés ci-dessous.</p>\n    </div>\n  `));\n\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Médicament / notion du jour</h2>\n      <p style=\"font-size:13.5px;color:var(--txt-dim);margin:0 0 10px;\">Une petite série de questions ciblées à réviser aujourd'hui.</p>\n      <button class=\"btn primary full\" id=\"btnMedDay\">💊 Lancer le médicament du jour</button>\n    </div>\n  `));\n\n  const chCard = el(`<div class=\"card\"></div>`);\n  const chHead = el(`\n    <div style=\"display:flex;justify-content:space-between;align-items:center;cursor:pointer;\">\n      <h2 class=\"section-title\" style=\"margin:0;\">📚 Chapitres (${filters.chapters.size}/${CHAPTERS.length})</h2>\n      <span style=\"color:var(--txt-faint);font-size:16px;\">${chaptersExpanded?'−':'+'}</span>\n    </div>\n  `);\n  chCard.appendChild(chHead);\n  if(chaptersExpanded){\n    const quickRow = el(`<div class=\"row mt14\"></div>`);\n    const allBtn = el(`<button class=\"btn small\">Tout cocher</button>`);\n    const noneBtn = el(`<button class=\"btn small ghost\">Tout décocher</button>`);\n    allBtn.addEventListener(\"click\", (e)=>{ e.stopPropagation(); filters.chapters = new Set(CHAPTERS); render(); });\n    noneBtn.addEventListener(\"click\", (e)=>{ e.stopPropagation(); filters.chapters = new Set([CHAPTERS[0]]); render(); });\n    quickRow.appendChild(allBtn); quickRow.appendChild(noneBtn);\n    chCard.appendChild(quickRow);\n    const grid = el(`<div class=\"row mt14\"></div>`);\n    CHAPTERS.forEach(ch=>{\n      const active = filters.chapters.has(ch);\n      const n = Q.filter(q=>q.chapter===ch).length;\n      const chip = el(`<div class=\"chip compact ${active?'active':''}\" title=\"${esc(ch)}\">${esc(shortChapterLabel(ch))} <small>(${n})</small></div>`);\n      chip.addEventListener(\"click\", ()=>{\n        if(filters.chapters.has(ch)) filters.chapters.delete(ch); else filters.chapters.add(ch);\n        if(filters.chapters.size===0) filters.chapters.add(ch);\n        render();\n      });\n      grid.appendChild(chip);\n    });\n    chCard.appendChild(grid);\n  }\n  chHead.addEventListener(\"click\", ()=>{ chaptersExpanded = !chaptersExpanded; render(); });\n  wrap.appendChild(chCard);\n\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Type de questions</h2>\n      <div class=\"row\" id=\"typeChips\"></div>\n    </div>\n  `));\n  const typeLabels = {qcm:\"QCM\",qcd:\"QCD\",libre:\"Questions libres\",association:\"Associations\"};\n  const typeHost = wrap.querySelector(\"#typeChips\");\n  Object.keys(typeLabels).forEach(t=>{\n    const active = filters.types.has(t);\n    const chip = el(`<div class=\"chip ${active?'active':''}\" data-t=\"${t}\">${typeLabels[t]}</div>`);\n    chip.addEventListener(\"click\", ()=>{\n      if(filters.types.has(t)) filters.types.delete(t); else filters.types.add(t);\n      if(filters.types.size===0) filters.types.add(t);\n      render();\n    });\n    typeHost.appendChild(chip);\n  });\n\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Difficulté</h2>\n      <div class=\"row\" id=\"diffChips\"></div>\n    </div>\n  `));\n  const diffLabels = {facile:\"🟢 Facile\",moyen:\"🟠 Moyen\",difficile:\"🔴 Difficile\"};\n  const diffHost = wrap.querySelector(\"#diffChips\");\n  Object.keys(diffLabels).forEach(d=>{\n    const active = filters.difficulties.has(d);\n    const chip = el(`<div class=\"chip ${active?'active':''}\" data-d=\"${d}\">${diffLabels[d]}</div>`);\n    chip.addEventListener(\"click\", ()=>{\n      if(filters.difficulties.has(d)) filters.difficulties.delete(d); else filters.difficulties.add(d);\n      if(filters.difficulties.size===0) filters.difficulties.add(d);\n      render();\n    });\n    diffHost.appendChild(chip);\n  });\n\n  const pool = buildFilteredPool();\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Session personnalisée</h2>\n      <p style=\"font-size:13px;color:var(--txt-dim);margin:0 0 12px;\">${pool.length} question(s) correspondent à ta sélection.</p>\n      <button class=\"btn primary full\" id=\"btnCustom\" ${pool.length===0?'disabled':''}>▶️ Démarrer la session (${pool.length})</button>\n    </div>\n  `));\n\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">🎓 Programme spécial 14 jours</h2>\n      <p style=\"font-size:13px;color:var(--txt-dim);line-height:1.6;margin:0 0 10px;\">\n        <b>J1–4</b> : apprentissage complet du cours &nbsp;·&nbsp;\n        <b>J5–8</b> : renforcement des classes difficiles &nbsp;·&nbsp;\n        <b>J9–11</b> : cas cliniques, interactions, surveillance &nbsp;·&nbsp;\n        <b>J12</b> : questions difficiles &nbsp;·&nbsp;\n        <b>J13</b> : examen blanc &nbsp;·&nbsp;\n        <b>J14</b> : révision finale des erreurs.\n      </p>\n      <button class=\"btn full\" id=\"btnExam\">📝 Lancer un examen blanc (30 questions)</button>\n    </div>\n  `));\n\n  wrap.querySelectorAll(\"[data-min]\").forEach(b=> b.addEventListener(\"click\", ()=> startQuickRevision(parseInt(b.dataset.min))));\n  wrap.querySelector(\"#btnMedDay\").addEventListener(\"click\", startMedOfDay);\n  wrap.querySelector(\"#btnCustom\").addEventListener(\"click\", ()=> startSession(pool, \"Session personnalisée\"));\n  wrap.querySelector(\"#btnExam\").addEventListener(\"click\", startExamBlanc);\n  wrap.querySelector(\"#btnDashboard\").addEventListener(\"click\", ()=>{ view=\"dashboard\"; render(); });\n  wrap.querySelector(\"#btnReset\").addEventListener(\"click\", ()=>{\n    if(confirm(\"Réinitialiser toute ta progression ? Cette action est définitive.\")){\n      progress = defaultProgress(); saveProgress(); render();\n    }\n  });\n\n  return wrap;\n}\n\nfunction sumMasteryPct(){\n  const total = Q.length;\n  let sum=0;\n  Q.forEach(q=> sum += getMastery(q.id)/4);\n  return Math.round(100*sum/total);\n}\n\nfunction renderDashboard(){\n  const wrap = el(`<div></div>`);\n  wrap.appendChild(el(`<button class=\"btn small ghost mb14\" id=\"back\">← Retour</button>`));\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Progression par chapitre</h2>\n      <div id=\"chapterList\"></div>\n    </div>\n  `));\n  const list = wrap.querySelector(\"#chapterList\");\n  CHAPTERS.forEach(ch=>{\n    const items = Q.filter(q=>q.chapter===ch);\n    if(items.length===0) return;\n    let sum=0; items.forEach(q=> sum += getMastery(q.id)/4);\n    const pct = Math.round(100*sum/items.length);\n    list.appendChild(el(`\n      <div class=\"chapter-row\">\n        <div class=\"cname\">${esc(ch)}</div>\n        <div class=\"cbar\"><span style=\"width:${pct}%\"></span></div>\n        <div class=\"cpct\">${pct}%</div>\n      </div>\n    `));\n  });\n\n  const weak = Q.slice().sort((a,b)=>getMastery(a.id)-getMastery(b.id)).slice(0,6);\n  const strong = Q.slice().sort((a,b)=>getMastery(b.id)-getMastery(a.id)).slice(0,6);\n\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Notions à revoir</h2>\n      ${weak.map(q=>`<div class=\"chapter-row\"><span class=\"mastery-dot m${getMastery(q.id)}\"></span><div class=\"cname\">${esc(q.question.slice(0,70))}${q.question.length>70?'…':''}</div></div>`).join(\"\")}\n    </div>\n  `));\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Points forts</h2>\n      ${strong.map(q=>`<div class=\"chapter-row\"><span class=\"mastery-dot m${getMastery(q.id)}\"></span><div class=\"cname\">${esc(q.question.slice(0,70))}${q.question.length>70?'…':''}</div></div>`).join(\"\")}\n    </div>\n  `));\n\n  wrap.querySelector(\"#back\").addEventListener(\"click\", ()=>{ view=\"home\"; render(); });\n  return wrap;\n}\n\n/* =========================================================\n   RESUME DE COURS\n   ========================================================= */\nfunction renderResume(){\n  const wrap = el(`<div></div>`);\n  wrap.appendChild(el(`<div class=\"card\"><h2 class=\"section-title\">📖 Résumé de cours</h2><p style=\"font-size:13px;color:var(--txt-dim);margin:0;\">L'essentiel à retenir, chapitre par chapitre — à consulter juste avant l'examen.</p></div>`));\n  Object.keys(SUMMARIES).forEach(ch=>{\n    const s = SUMMARIES[ch];\n    const isOpen = openChapterInResume===ch;\n    const card = el(`<div class=\"card\"></div>`);\n    const head = el(`<div style=\"display:flex;justify-content:space-between;align-items:center;cursor:pointer;\"><h2 class=\"section-title\" style=\"margin:0;\">${esc(ch)}</h2><span style=\"color:var(--txt-faint);font-size:18px;\">${isOpen?'−':'+'}</span></div>`);\n    card.appendChild(head);\n    card.appendChild(el(`<div class=\"q-page\" style=\"margin-top:2px;\">p. ${esc(s.page)} · ${esc(s.source)}</div>`));\n    const body = el(`<div style=\"margin-top:${isOpen?'12px':'0'};display:${isOpen?'block':'none'};\"></div>`);\n    s.bullets.forEach(b=> body.appendChild(el(`<div style=\"font-size:13.5px;line-height:1.6;margin-bottom:8px;padding-left:14px;border-left:2px solid var(--panel-brd);\">${esc(b)}</div>`)));\n    const revBtn = el(`<button class=\"btn small mt14\">▶️ Réviser ce chapitre en questions</button>`);\n    revBtn.addEventListener(\"click\", (e)=>{ e.stopPropagation(); startSession(shuffle(Q.filter(q=>q.chapter===ch)), ch); });\n    if(isOpen) body.appendChild(revBtn);\n    card.appendChild(body);\n    head.addEventListener(\"click\", ()=>{ openChapterInResume = isOpen ? null : ch; render(); });\n    wrap.appendChild(card);\n  });\n  return wrap;\n}\n\n/* =========================================================\n   MEDICAMENTS PAR GROUPE\n   ========================================================= */\nfunction renderMeds(){\n  const wrap = el(`<div></div>`);\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">💊 Médicaments par groupe</h2>\n      <input type=\"text\" id=\"medsFilter\" placeholder=\"Filtrer par DCI, nom commercial ou classe...\" value=\"${esc(medsSearchQuery)}\"\n        style=\"width:100%;background:rgba(255,255,255,0.04);border:1px solid var(--panel-brd);border-radius:12px;padding:11px 13px;color:var(--txt);font-size:14px;\">\n    </div>\n  `));\n  const listHost = el(`<div id=\"medsList\"></div>`);\n  wrap.appendChild(listHost);\n\n  function draw(){\n    listHost.innerHTML = \"\";\n    const q = medsSearchQuery.trim().toLowerCase();\n    const groups = MEDS.filter(g=>{\n      if(!q) return true;\n      if(g.classe.toLowerCase().includes(q)) return true;\n      return g.items.some(([dci,brands])=> dci.toLowerCase().includes(q) || (brands||\"\").toLowerCase().includes(q));\n    });\n    if(groups.length===0){ listHost.appendChild(el(`<div class=\"card center\">Aucun médicament trouvé.</div>`)); return; }\n    groups.forEach(g=>{\n      const card = el(`<div class=\"card\"></div>`);\n      card.appendChild(el(`<h2 class=\"section-title\" style=\"margin-bottom:4px;\">${esc(g.classe)}</h2>`));\n      card.appendChild(el(`<div class=\"q-page\" style=\"margin-bottom:10px;\">${esc(g.chapter)} · p.${g.page}</div>`));\n      g.items.forEach(([dci,brands])=>{\n        card.appendChild(el(`\n          <div class=\"chapter-row\">\n            <div class=\"cname\"><b>${esc(dci)}</b><br><small style=\"color:var(--txt-faint);\">${esc(brands)}</small></div>\n          </div>\n        `));\n      });\n      listHost.appendChild(card);\n    });\n  }\n  draw();\n  wrap.querySelector(\"#medsFilter\").addEventListener(\"input\",(e)=>{ medsSearchQuery = e.target.value; draw(); });\n  return wrap;\n}\n\n/* =========================================================\n   FLASHCARDS — HUB & SESSION (Leitner)\n   ========================================================= */\nfunction startFlashSession(list, label){\n  flashQueue = shuffle(list);\n  flashIndex = 0;\n  flashRevealed = false;\n  flashSessionLabel = label;\n  if(flashQueue.length===0){ alert(\"Aucune flashcard ne correspond à cette sélection.\"); return; }\n  view = \"flashSession\";\n  render();\n}\n\nfunction renderFlashHub(){\n  const wrap = el(`<div></div>`);\n  const stats = flashStats();\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">🗂️ Flashcards (méthode Leitner)</h2>\n      <p style=\"font-size:13px;color:var(--txt-dim);margin:0 0 12px;\">${stats.total} cartes au total. Révise une carte, évalue-toi honnêtement : elle revient plus vite si tu la rates, plus tard si tu la maîtrises.</p>\n      <div class=\"dash-grid\">\n        <div class=\"stat\"><div class=\"num\">${stats.total}</div><div class=\"lbl\">Cartes totales</div></div>\n        <div class=\"stat\"><div class=\"num\">${stats.dueCount}</div><div class=\"lbl\">À réviser aujourd'hui</div></div>\n        <div class=\"stat\"><div class=\"num\">${stats.masteredCount}</div><div class=\"lbl\">Bien maîtrisées</div></div>\n        <div class=\"stat\"><div class=\"num\">${Math.round(100*stats.masteredCount/stats.total)}%</div><div class=\"lbl\">Progression</div></div>\n      </div>\n      <button class=\"btn primary full mt14\" id=\"startDue\" ${stats.dueCount===0?'disabled':''}>🔁 Réviser les cartes dues (${stats.dueCount})</button>\n    </div>\n  `));\n\n  const fchCard = el(`<div class=\"card\"></div>`);\n  const fchHead = el(`\n    <div style=\"display:flex;justify-content:space-between;align-items:center;cursor:pointer;\">\n      <h2 class=\"section-title\" style=\"margin:0;\">📚 Filtrer par chapitre (${flashChapterFilter.size}/${CHAPTERS.length})</h2>\n      <span style=\"color:var(--txt-faint);font-size:16px;\">${flashChaptersExpanded?'−':'+'}</span>\n    </div>\n  `);\n  fchCard.appendChild(fchHead);\n  if(flashChaptersExpanded){\n    const quickRow = el(`<div class=\"row mt14\"></div>`);\n    const allBtn = el(`<button class=\"btn small\">Tout cocher</button>`);\n    const noneBtn = el(`<button class=\"btn small ghost\">Tout décocher</button>`);\n    allBtn.addEventListener(\"click\", (e)=>{ e.stopPropagation(); flashChapterFilter = new Set(CHAPTERS); render(); });\n    noneBtn.addEventListener(\"click\", (e)=>{ e.stopPropagation(); flashChapterFilter = new Set([CHAPTERS[0]]); render(); });\n    quickRow.appendChild(allBtn); quickRow.appendChild(noneBtn);\n    fchCard.appendChild(quickRow);\n    const grid = el(`<div class=\"row mt14\"></div>`);\n    CHAPTERS.forEach(ch=>{\n      const n = FLASHCARDS.filter(c=>c.chapter===ch).length;\n      if(n===0) return;\n      const active = flashChapterFilter.has(ch);\n      const chip = el(`<div class=\"chip compact ${active?'active':''}\" title=\"${esc(ch)}\">${esc(shortChapterLabel(ch))} <small>(${n})</small></div>`);\n      chip.addEventListener(\"click\", ()=>{\n        if(flashChapterFilter.has(ch)) flashChapterFilter.delete(ch); else flashChapterFilter.add(ch);\n        if(flashChapterFilter.size===0) flashChapterFilter.add(ch);\n        render();\n      });\n      grid.appendChild(chip);\n    });\n    fchCard.appendChild(grid);\n  }\n  fchHead.addEventListener(\"click\", ()=>{ flashChaptersExpanded = !flashChaptersExpanded; render(); });\n  wrap.appendChild(fchCard);\n\n  const pool = FLASHCARDS.filter(c=>flashChapterFilter.has(c.chapter));\n  wrap.appendChild(el(`\n    <div class=\"card\">\n      <h2 class=\"section-title\">Session personnalisée</h2>\n      <p style=\"font-size:13px;color:var(--txt-dim);margin:0 0 12px;\">${pool.length} carte(s) correspondent à ta sélection.</p>\n      <div class=\"row\">\n        <button class=\"btn primary\" id=\"startAll\" ${pool.length===0?'disabled':''}>▶️ Toutes les cartes (${pool.length})</button>\n        <button class=\"btn\" id=\"start20\">⚡ Série de 20</button>\n      </div>\n    </div>\n  `));\n\n  wrap.querySelector(\"#startDue\").addEventListener(\"click\", ()=>{\n    const due = FLASHCARDS.filter(isFlashDue);\n    startFlashSession(due, \"Cartes dues\");\n  });\n  wrap.querySelector(\"#startAll\").addEventListener(\"click\", ()=> startFlashSession(pool, \"Toutes les cartes\"));\n  wrap.querySelector(\"#start20\").addEventListener(\"click\", ()=>{\n    const basePool = pool.length? pool : FLASHCARDS;\n    const weighted = basePool.slice().sort((a,b)=>getFlashBox(a.id)-getFlashBox(b.id));\n    startFlashSession(weighted.slice(0,20), \"Série de 20\");\n  });\n  return wrap;\n}\n\nfunction renderFlashSession(){\n  const wrap = el(`<div></div>`);\n  if(flashQueue.length===0){\n    wrap.appendChild(el(`<div class=\"card center\">Session terminée.<br><button class=\"btn mt14\" id=\"back\">← Retour</button></div>`));\n    wrap.querySelector(\"#back\").addEventListener(\"click\", ()=>{ view=\"flash\"; render(); });\n    return wrap;\n  }\n  const card = flashQueue[flashIndex];\n  const pct = Math.round(100*flashIndex/flashQueue.length);\n\n  wrap.appendChild(el(`\n    <div class=\"row\" style=\"justify-content:space-between;align-items:center;margin-bottom:6px;\">\n      <button class=\"btn small ghost\" id=\"quit\">✕ Quitter</button>\n      <div style=\"font-size:11.5px;color:var(--txt-dim);\">${esc(flashSessionLabel)}</div>\n    </div>\n  `));\n  wrap.appendChild(el(`<div class=\"progress-outer\"><div class=\"progress-inner\" style=\"width:${pct}%\"></div></div>`));\n\n  const box = getFlashBox(card.id);\n  const cardEl = el(`<div class=\"card\" style=\"min-height:220px;display:flex;flex-direction:column;\"></div>`);\n  cardEl.appendChild(el(`\n    <div class=\"q-meta\">\n      <div class=\"tags\"><span class=\"badge qcm\">Boîte ${box+1}/5</span></div>\n      <div class=\"q-page\">${esc(card.chapter)} · p.${card.page}</div>\n    </div>\n  `));\n  cardEl.appendChild(el(`<div class=\"q-text\" style=\"margin-bottom:10px;\">${esc(card.front)}</div>`));\n\n  if(!flashRevealed){\n    const revealBtn = el(`<button class=\"btn primary full mt14\">👁️ Révéler la réponse</button>`);\n    revealBtn.addEventListener(\"click\", ()=>{ flashRevealed=true; render(); });\n    cardEl.appendChild(revealBtn);\n  } else {\n    cardEl.appendChild(el(`<div class=\"correction\"><div class=\"block\"><div class=\"label\">Réponse</div><div class=\"content\">${esc(card.back)}</div></div></div>`));\n    const btnRow = el(`<div class=\"row mt14\"></div>`);\n    const again = el(`<button class=\"btn small\" style=\"flex:1;border-color:var(--coral);color:var(--coral);\">❌ À revoir</button>`);\n    const good = el(`<button class=\"btn small\" style=\"flex:1;border-color:var(--amber);color:var(--amber);\">🟡 Correct</button>`);\n    const easy = el(`<button class=\"btn small\" style=\"flex:1;border-color:#4ad991;color:#4ad991;\">🟢 Facile</button>`);\n    [[\"again\",again],[\"good\",good],[\"easy\",easy]].forEach(([res,btn])=>{\n      btn.addEventListener(\"click\", ()=>{\n        recordFlashResult(card,res);\n        if(flashIndex < flashQueue.length-1){ flashIndex++; flashRevealed=false; render(); }\n        else{ flashQueue=[]; alert(\"Série de flashcards terminée ! Ta progression a été sauvegardée.\"); view=\"flash\"; render(); }\n      });\n    });\n    btnRow.appendChild(again); btnRow.appendChild(good); btnRow.appendChild(easy);\n    cardEl.appendChild(btnRow);\n  }\n  wrap.appendChild(cardEl);\n  wrap.appendChild(el(`<div class=\"qcounter mt14\">Carte ${flashIndex+1} / ${flashQueue.length}</div>`));\n  wrap.querySelector(\"#quit\").addEventListener(\"click\", ()=>{ view=\"flash\"; render(); });\n  return wrap;\n}\nfunction optionLetter(i){ return [\"A\",\"B\",\"C\",\"D\",\"E\",\"F\"][i] || String(i+1); }\n\nfunction renderQuiz(){\n  const wrap = el(`<div></div>`);\n  if(queue.length===0){\n    wrap.appendChild(el(`<div class=\"card center\">Aucune question disponible pour cette sélection.<br><button class=\"btn mt14\" id=\"back\">← Retour à l'accueil</button></div>`));\n    wrap.querySelector(\"#back\").addEventListener(\"click\", ()=>{ view=\"home\"; render(); });\n    return wrap;\n  }\n  const q = queue[qIndex];\n  const state = answersGiven[q.id];\n  const pct = Math.round(100*(qIndex)/queue.length);\n\n  wrap.appendChild(el(`\n    <div class=\"row\" style=\"justify-content:space-between;align-items:center;margin-bottom:6px;\">\n      <button class=\"btn small ghost\" id=\"quit\">✕ Quitter</button>\n      <div style=\"font-size:11.5px;color:var(--txt-dim);\">${esc(sessionLabel)}</div>\n    </div>\n  `));\n  wrap.appendChild(el(`<div class=\"progress-outer\"><div class=\"progress-inner\" style=\"width:${pct}%\"></div></div>`));\n\n  const card = el(`<div class=\"card\"></div>`);\n  const diffLabel = {facile:\"Facile\",moyen:\"Moyen\",difficile:\"Difficile\"}[q.difficulty];\n  const typeLabel = {qcm:\"QCM\",qcd:\"QCD\",libre:\"Question libre\",association:\"Association\"}[q.type];\n\n  card.appendChild(el(`\n    <div class=\"q-meta\">\n      <div class=\"tags\">\n        <span class=\"badge ${q.type}\">${typeLabel}</span>\n        <span class=\"badge ${q.difficulty}\">${diffLabel}</span>\n      </div>\n      <div class=\"q-page\">${esc(q.chapter)} · p.${q.page} · éd. ${q.source||\"2025\"}</div>\n    </div>\n  `));\n  card.appendChild(el(`<div class=\"q-text\">${esc(q.question)}</div>`));\n\n  const body = el(`<div id=\"qbody\"></div>`);\n  card.appendChild(body);\n\n  if(q.type===\"qcm\"){ renderQCM(body,q,state); }\n  else if(q.type===\"qcd\"){ renderQCD(body,q,state); }\n  else if(q.type===\"libre\"){ renderLibre(body,q,state); }\n  else if(q.type===\"association\"){ renderAssociation(body,q,state); }\n\n  if(state && state.revealed){\n    const quickNav = el(`<div class=\"mt14\"></div>`);\n    if(qIndex < queue.length-1){\n      const quickNextBtn = el(`<button class=\"btn primary full\" id=\"quickNext\">Suivant →</button>`);\n      quickNav.appendChild(quickNextBtn);\n    } else {\n      const quickFinishBtn = el(`<button class=\"btn primary full\" id=\"quickFinish\">🏁 Terminer et voir mon score</button>`);\n      quickNav.appendChild(quickFinishBtn);\n    }\n    card.appendChild(quickNav);\n    card.appendChild(renderCorrection(q,state));\n  }\n\n  wrap.appendChild(card);\n\n  // Navigation\n  const nav = el(`\n    <div class=\"navrow\">\n      <button class=\"btn arrow-btn\" id=\"prevQ\" ${qIndex===0?'disabled':''}>←</button>\n      <div class=\"qcounter\">Question ${qIndex+1} / ${queue.length}</div>\n      <button class=\"btn arrow-btn\" id=\"nextQ\" ${qIndex===queue.length-1?'disabled':''}>→</button>\n    </div>\n  `);\n  wrap.appendChild(nav);\n\n  wrap.querySelector(\"#quit\").addEventListener(\"click\", ()=>{ view=\"home\"; render(); });\n  wrap.querySelector(\"#prevQ\").addEventListener(\"click\", ()=>{ qIndex=Math.max(0,qIndex-1); render(); });\n  wrap.querySelector(\"#nextQ\").addEventListener(\"click\", ()=>{ qIndex=Math.min(queue.length-1,qIndex+1); render(); });\n  const quickNextBtn = wrap.querySelector(\"#quickNext\");\n  if(quickNextBtn) quickNextBtn.addEventListener(\"click\", ()=>{ qIndex=Math.min(queue.length-1,qIndex+1); render(); });\n  const quickFinishBtn = wrap.querySelector(\"#quickFinish\");\n  if(quickFinishBtn) quickFinishBtn.addEventListener(\"click\", ()=> showSummary());\n\n  return wrap;\n}\n\nfunction markAnswered(q, correct, given){\n  answersGiven[q.id] = { given, correct, revealed:true };\n  bumpMastery(q.id, correct);\n}\n\nfunction renderQCM(body,q,state){\n  const shuffledKey = \"shuf_\"+q.id;\n  if(!selectedOptions[shuffledKey]) selectedOptions[shuffledKey] = shuffle(q.options.map((o,i)=>({text:o,idx:i})));\n  const opts = selectedOptions[shuffledKey];\n  const locked = !!state;\n  opts.forEach((o,i)=>{\n    const isSelected = state ? state.given===o.text : false;\n    const isCorrect = o.text===q.correctAnswer;\n    let cls = \"opt\";\n    if(locked){\n      cls += \" disabled\";\n      if(isCorrect) cls += \" correct\";\n      else if(isSelected) cls += \" incorrect\";\n    } else if(selectedOptions[q.id]===o.text){ cls += \" selected\"; }\n    const div = el(`<div class=\"${cls}\"><span class=\"letter\">${optionLetter(i)}</span><span>${esc(o.text)}</span></div>`);\n    if(!locked){\n      div.addEventListener(\"click\", ()=>{\n        markAnswered(q, o.text===q.correctAnswer, o.text);\n        render();\n      });\n    }\n    body.appendChild(div);\n  });\n}\n\nfunction renderQCD(body,q,state){\n  const shuffledKey = \"shuf_\"+q.id;\n  if(!selectedOptions[shuffledKey]) selectedOptions[shuffledKey] = shuffle(q.options.map((o,i)=>({text:o,idx:i})));\n  const opts = selectedOptions[shuffledKey];\n  const locked = !!state;\n  if(!selectedOptions[q.id]) selectedOptions[q.id] = new Set();\n  const sel = selectedOptions[q.id];\n\n  opts.forEach((o,i)=>{\n    const isCorrectOpt = q.correctAnswer.includes(o.text);\n    const wasSelected = state ? (state.given||[]).includes(o.text) : sel.has(o.text);\n    let cls = \"opt\";\n    if(locked){\n      cls += \" disabled\";\n      if(isCorrectOpt) cls += \" correct\";\n      else if(wasSelected) cls += \" incorrect\";\n    } else if(wasSelected){ cls += \" selected\"; }\n    const div = el(`<div class=\"${cls}\"><span class=\"letter\">${optionLetter(i)}</span><span>${esc(o.text)}</span></div>`);\n    if(!locked){\n      div.addEventListener(\"click\", ()=>{\n        if(sel.has(o.text)) sel.delete(o.text); else sel.add(o.text);\n        render();\n      });\n    }\n    body.appendChild(div);\n  });\n  if(!locked){\n    body.appendChild(el(`<button class=\"btn primary full mt14\" id=\"validQCD\">✓ Valider ma réponse</button>`));\n    body.querySelector(\"#validQCD\").addEventListener(\"click\", ()=>{\n      const given = Array.from(sel);\n      const correctSet = new Set(q.correctAnswer);\n      const givenSet = new Set(given);\n      const correct = given.length>0 && correctSet.size===givenSet.size && [...correctSet].every(x=>givenSet.has(x));\n      markAnswered(q, correct, given);\n      render();\n    });\n  }\n}\n\nfunction renderLibre(body,q,state){\n  const locked = !!state;\n  if(locked){\n    body.appendChild(el(`<div class=\"opt disabled\" style=\"cursor:default;\"><span>${esc(state.given)}</span></div>`));\n    return;\n  }\n  body.appendChild(el(`<textarea class=\"free\" id=\"freeAns\" placeholder=\"Écris ta réponse ici...\"></textarea>`));\n  body.appendChild(el(`<button class=\"btn primary full mt14\" id=\"validLibre\">✓ Corriger ma réponse</button>`));\n  body.querySelector(\"#validLibre\").addEventListener(\"click\", ()=>{\n    const val = body.querySelector(\"#freeAns\").value.trim();\n    const low = val.toLowerCase();\n    const hits = (q.keywords||[]).filter(k=> low.includes(k.toLowerCase().split(\" \")[0]) || low.includes(k.toLowerCase()));\n    const correct = val.length>0 && hits.length >= Math.max(1, Math.ceil((q.keywords||[]).length*0.34));\n    markAnswered(q, correct, val || \"(réponse vide)\");\n    render();\n  });\n}\n\nfunction renderAssociation(body,q,state){\n  const locked = !!state;\n  const leftShuffledKey = \"assocL_\"+q.id, rightShuffledKey=\"assocR_\"+q.id;\n  if(!selectedOptions[leftShuffledKey]) selectedOptions[leftShuffledKey] = q.pairs.map(p=>p[0]);\n  if(!selectedOptions[rightShuffledKey]) selectedOptions[rightShuffledKey] = shuffle(q.pairs.map(p=>p[1]));\n  const lefts = selectedOptions[leftShuffledKey];\n  const rights = selectedOptions[rightShuffledKey];\n  if(!selectedOptions[\"assocSel_\"+q.id]) selectedOptions[\"assocSel_\"+q.id] = {};\n  const sel = selectedOptions[\"assocSel_\"+q.id];\n\n  lefts.forEach((L)=>{\n    const row = el(`<div style=\"margin-bottom:10px;\"></div>`);\n    row.appendChild(el(`<div style=\"font-size:13.5px;font-weight:600;margin-bottom:6px;\">${esc(L)}</div>`));\n    const optRow = el(`<div class=\"row\"></div>`);\n    rights.forEach(R=>{\n      const correctPair = q.pairs.find(p=>p[0]===L)[1]===R;\n      const isSelected = locked ? (state.given||{})[L]===R : sel[L]===R;\n      let cls=\"chip\";\n      if(locked){\n        if(correctPair) cls+=\" active\";\n        else if(isSelected) cls+=\" \";\n      } else if(isSelected) cls+=\" active\";\n      const chip = el(`<div class=\"${cls}\" style=\"${locked&&correctPair?'border-color:#4ad991;color:#4ad991;':''}${locked&&isSelected&&!correctPair?'border-color:var(--coral);color:var(--coral);':''}\">${esc(R)}</div>`);\n      if(!locked){\n        chip.addEventListener(\"click\", ()=>{ sel[L]=R; render(); });\n      }\n      optRow.appendChild(chip);\n    });\n    row.appendChild(optRow);\n    body.appendChild(row);\n  });\n  if(!locked){\n    body.appendChild(el(`<button class=\"btn primary full mt14\" id=\"validAssoc\">✓ Valider mes associations</button>`));\n    body.querySelector(\"#validAssoc\").addEventListener(\"click\", ()=>{\n      const allCorrect = q.pairs.every(([L,R])=> sel[L]===R);\n      markAnswered(q, allCorrect, {...sel});\n      render();\n    });\n  }\n}\n\nfunction renderCorrection(q,state){\n  const box = el(`<div class=\"correction\"></div>`);\n  box.appendChild(el(`\n    <div class=\"block\">\n      <div class=\"label\">${state.correct? \"✅ Bonne réponse\" : \"❌ Réponse incorrecte — voici la correction\"}</div>\n      <div class=\"content\">${esc(explanationAnswerText(q))}</div>\n    </div>\n  `));\n  box.appendChild(el(`\n    <div class=\"block\">\n      <div class=\"label\">📖 Explication</div>\n      <div class=\"content\">${esc(q.explanation)}</div>\n    </div>\n  `));\n  if(q.simpleExplanation){\n    box.appendChild(el(`\n      <div class=\"block\">\n        <div class=\"label\">🧒 Comme à un enfant de 10 ans</div>\n        <div class=\"content kid\">${esc(q.simpleExplanation)}</div>\n      </div>\n    `));\n  }\n  if(q.memoryTip){\n    box.appendChild(el(`\n      <div class=\"block\">\n        <div class=\"label\">💡 Astuce mémoire</div>\n        <div class=\"content tip\">${esc(q.memoryTip)}</div>\n      </div>\n    `));\n  }\n  if(q.examTrap){\n    box.appendChild(el(`\n      <div class=\"block\">\n        <div class=\"label\">⚠️ Piège d'examen</div>\n        <div class=\"content trap\">${esc(q.examTrap)}</div>\n      </div>\n    `));\n  }\n  box.appendChild(el(`<div class=\"q-page\">Source : COURS PHARMACOLOGIE ${q.source===\"2022\"?\"INFAS 2022\":\"L2 INFAS 2025\"} — page ${q.page}</div>`));\n  return box;\n}\n\nfunction explanationAnswerText(q){\n  if(q.type===\"qcm\") return \"Réponse : \" + q.correctAnswer;\n  if(q.type===\"qcd\") return \"Réponses : \" + q.correctAnswer.join(\", \");\n  if(q.type===\"association\") return \"Bonnes associations : \" + q.pairs.map(p=>p[0]+\" → \"+p[1]).join(\" · \");\n  if(q.type===\"libre\") return \"Réponse modèle attendue : mots-clés — \" + (q.keywords||[]).slice(0,4).join(\", \") + \"…\";\n  return \"\";\n}\n\nfunction showSummary(){\n  const answered = queue.filter(q=>answersGiven[q.id]);\n  const correct = answered.filter(q=>answersGiven[q.id].correct).length;\n  const score = answered.length? Math.round(100*correct/answered.length) : 0;\n  alert(\"Session terminée !\\n\\nScore : \"+correct+\" / \"+answered.length+\" (\"+score+\"%)\\n\\nTa progression a été sauvegardée automatiquement.\");\n  progress.history.push({date:new Date().toISOString(), label:sessionLabel, score, total:answered.length});\n  saveProgress();\n  view = \"home\";\n  render();\n}\n\n<%/script>\n<script>\n/* =========================================================\n   V2 — Parcours, questions ouvertes, XP, séries, statistiques\n   Créé par Daniel Noufe · INFAS Daloa\n   ========================================================= */\nQ.push(...Q_EXTRA);\n/* flashcards supplémentaires générées à partir des nouvelles questions */\nQ_EXTRA.forEach(q=>{\n  if(q.type===\"qcm\") FLASHCARDS.push({id:\"fq_\"+q.id,chapter:q.chapter,page:q.page,front:q.question,back:q.correctAnswer+\" — \"+q.memoryTip});\n  else if(q.type===\"ouverte\") FLASHCARDS.push({id:\"fq_\"+q.id,chapter:q.chapter,page:q.page,front:q.question,back:q.answer});\n});\nfilters.types.add(\"ouverte\");\n\n/* ---------- métadonnées des chapitres ---------- */\nconst CH_META = {\n  \"Généralités\":{e:\"📘\",cat:\"Bases\",c:\"navy\",figs:[\"💊\",\"📜\",\"🧪\"]},\n  \"Antalgiques & fièvre\":{e:\"🤕\",cat:\"Douleur\",c:\"violet\",figs:[\"🌡️\",\"💊\",\"🪜\"]},\n  \"Anti-inflammatoires & anesthésiques\":{e:\"🔥\",cat:\"Douleur\",c:\"yellow\",figs:[\"🧊\",\"💉\",\"😴\"]},\n  \"Anti-infectieux\":{e:\"🦠\",cat:\"Infections\",c:\"green\",figs:[\"🧫\",\"🪱\",\"🍄\"]},\n  \"Prises en charge encadrées (Paludisme, VIH, TB, Lèpre)\":{e:\"🦟\",cat:\"Infections\",c:\"navy\",figs:[\"🦟\",\"🧬\",\"🫁\"]},\n  \"Antidiabétiques\":{e:\"🍬\",cat:\"Systèmes\",c:\"yellow\",figs:[\"🍬\",\"💉\",\"🩸\"]},\n  \"Appareil respiratoire\":{e:\"🫁\",cat:\"Systèmes\",c:\"violet\",figs:[\"🌬️\",\"🤧\",\"💨\"]},\n  \"Antihistaminiques\":{e:\"🤧\",cat:\"Systèmes\",c:\"green\",figs:[\"🌸\",\"👁️\",\"😴\"]},\n  \"Appareil digestif\":{e:\"🍽️\",cat:\"Systèmes\",c:\"navy\",figs:[\"🔥\",\"💧\",\"🦠\"]},\n  \"Médicaments du SNC (Psychotropes)\":{e:\"🧠\",cat:\"Systèmes\",c:\"violet\",figs:[\"😴\",\"⚡\",\"🧠\"]},\n  \"Hormonaux gynécologiques\":{e:\"🤰\",cat:\"Femme\",c:\"yellow\",figs:[\"🌸\",\"🥚\",\"👶\"]},\n  \"Appareil cardio-vasculaire\":{e:\"❤️\",cat:\"Systèmes\",c:\"green\",figs:[\"❤️\",\"💧\",\"🩸\"]},\n  \"Vitamines & Oligo-éléments\":{e:\"🥕\",cat:\"Nutrition\",c:\"yellow\",figs:[\"🥕\",\"🍊\",\"🐟\"]},\n  \"Antiseptiques, désinfectants & détergents\":{e:\"🧴\",cat:\"Hygiène\",c:\"navy\",figs:[\"🧼\",\"🖐️\",\"🧴\"]}\n};\nconst CATS = [[\"Tous\",\"✨\"],[\"Bases\",\"📘\"],[\"Douleur\",\"🤕\"],[\"Infections\",\"🦠\"],[\"Systèmes\",\"🫀\"],[\"Femme\",\"🤰\"],[\"Nutrition\",\"🥕\"],[\"Hygiène\",\"🧴\"]];\nconst AVATARS = [\"👩🏾‍⚕️\",\"👨🏾‍⚕️\",\"👩🏾‍🎓\",\"🧑🏾‍🎓\",\"👨🏾‍🔬\",\"👩🏾‍🔬\",\"🦸🏾‍♀️\",\"🦸🏾‍♂️\",\"🧕🏾\",\"👸🏾\",\"🤴🏾\",\"🐣\"];\nfunction meta(ch){ return CH_META[ch] || {e:\"📗\",cat:\"Bases\",c:\"navy\",figs:[\"💊\",\"📘\",\"🧪\"]}; }\n\n/* ---------- progression étendue ---------- */\n(function ensure(){\n  const p = progress;\n  p.xp = p.xp||0; p.daily = p.daily||{}; p.seen = p.seen||{}; p.bookmarks = p.bookmarks||{};\n  p.chBookmarks = p.chBookmarks||{}; p.badges = p.badges||{}; p.name = p.name||\"Étudiant(e) INFAS\";\n  p.avatar = p.avatar||\"👩🏾‍⚕️\"; p.openDone = p.openDone||0; p.flashDone = p.flashDone||0;\n  Object.keys(p.mastery).forEach(id=> p.seen[id]=true);\n  saveProgress();\n})();\nconst _oldDefault = defaultProgress;\ndefaultProgress = function(){ return Object.assign(_oldDefault(), {xp:0,daily:{},seen:{},bookmarks:{},chBookmarks:{},badges:{},name:progress.name,avatar:progress.avatar,openDone:0,flashDone:0}); };\n\nconst pad = n=> String(n).padStart(2,\"0\");\nfunction dkey(d){ d=d||new Date(); return d.getFullYear()+\"-\"+pad(d.getMonth()+1)+\"-\"+pad(d.getDate()); }\nlet lastAct = null;\nfunction logActivity(correct){\n  const k = dkey(); const day = progress.daily[k] || (progress.daily[k]={n:0,c:0,s:0});\n  const now = Date.now(); const dt = lastAct ? Math.min(90,(now-lastAct)/1000) : 20; lastAct = now;\n  day.n++; if(correct) day.c++; day.s += Math.round(dt);\n}\nfunction streak(){\n  let s=0; const d=new Date();\n  if(!progress.daily[dkey(d)]) d.setDate(d.getDate()-1);\n  while(progress.daily[dkey(d)] && progress.daily[dkey(d)].n>0){ s++; d.setDate(d.getDate()-1); }\n  return s;\n}\nconst level = ()=> 1+Math.floor(progress.xp/200);\nconst xpInLevel = ()=> progress.xp%200;\nfunction isSeen(id){ return !!(progress.seen[id] || id in progress.mastery); }\nfunction chapterStats(ch){\n  const items = Q.filter(q=>q.chapter===ch);\n  const seen = items.filter(q=>isSeen(q.id)).length;\n  let sum=0; items.forEach(q=> sum+=getMastery(q.id)/4);\n  const mastery = items.length? Math.round(100*sum/items.length):0;\n  const done = items.length>0 && seen===items.length && mastery>=50;\n  return {items, total:items.length, seen, mastery, done, open:items.filter(q=>q.type===\"ouverte\").length, seenPct: items.length?Math.round(100*seen/items.length):0};\n}\n\n/* ---------- effets : toast, confettis, figurine ---------- */\nlet pendingFx = null;\nlet toastQ=[], toastBusy=false;\nfunction toast(msg){ toastQ.push(msg); if(!toastBusy) nextToast(); }\nfunction nextToast(){ const m=toastQ.shift(); if(!m){toastBusy=false;return;} toastBusy=true; const t=document.createElement(\"div\"); t.className=\"toast\"; t.textContent=m; document.body.appendChild(t); setTimeout(()=>{t.remove(); nextToast();},1650); }\nfunction confetti(){\n  if(window.matchMedia && matchMedia(\"(prefers-reduced-motion: reduce)\").matches) return;\n  const box=document.createElement(\"div\"); box.className=\"confetti\";\n  const cols=[\"#5B3FF0\",\"#F6B81A\",\"#2FA84F\",\"#2F7BF6\",\"#F0566A\",\"#7C62FF\"];\n  for(let i=0;i<34;i++){ const c=document.createElement(\"i\"); c.style.left=Math.random()*100+\"%\"; c.style.background=cols[i%cols.length]; c.style.animationDelay=(Math.random()*.35)+\"s\"; c.style.transform=\"rotate(\"+Math.random()*180+\"deg)\"; box.appendChild(c); }\n  document.body.appendChild(box); setTimeout(()=>box.remove(),1900);\n}\nfunction mascot(mood){\n  // \"Pilou\", la gélule-mascotte\n  const eyes = mood===\"happy\" ? `<path d=\"M23 35q4-5 8 0M37 35q4-5 8 0\" stroke=\"#151A33\" stroke-width=\"2.6\" fill=\"none\" stroke-linecap=\"round\"/>`\n    : mood===\"star\" ? `<text x=\"21\" y=\"39\" font-size=\"11\">⭐</text><text x=\"36\" y=\"39\" font-size=\"11\">⭐</text>`\n    : `<circle cx=\"27\" cy=\"35\" r=\"2.8\" fill=\"#151A33\"/><circle cx=\"41\" cy=\"35\" r=\"2.8\" fill=\"#151A33\"/>`;\n  const mouth = mood===\"happy\"||mood===\"star\" ? `<path d=\"M27 43q7 8 14 0\" stroke=\"#151A33\" stroke-width=\"2.6\" fill=\"#F0566A\" stroke-linecap=\"round\"/>`\n    : mood===\"sad\" ? `<path d=\"M28 47q6-6 12 0\" stroke=\"#151A33\" stroke-width=\"2.6\" fill=\"none\" stroke-linecap=\"round\"/>`\n    : `<path d=\"M29 45h10\" stroke=\"#151A33\" stroke-width=\"2.6\" stroke-linecap=\"round\"/>`;\n  const extra = mood===\"sad\" ? `<path d=\"M50 24q3 5 0 7q-3-2 0-7z\" fill=\"#7CC4FF\"/>` : mood===\"think\" ? `<text x=\"50\" y=\"16\" font-size=\"14\" font-weight=\"700\" fill=\"#5B3FF0\">?</text>` : `<circle cx=\"20\" cy=\"42\" r=\"3\" fill=\"#FFB3C1\" opacity=\".8\"/><circle cx=\"48\" cy=\"42\" r=\"3\" fill=\"#FFB3C1\" opacity=\".8\"/>`;\n  return `<svg viewBox=\"0 0 68 80\" aria-hidden=\"true\">\n    <ellipse cx=\"34\" cy=\"76\" rx=\"16\" ry=\"3\" fill=\"#151A33\" opacity=\".12\"/>\n    <path d=\"M14 30a20 20 0 0 1 40 0v4H14z\" fill=\"#7C62FF\"/>\n    <path d=\"M14 34h40v14a20 20 0 0 1-40 0z\" fill=\"#fff\" stroke=\"#E3E5F3\" stroke-width=\"1.5\"/>\n    <path d=\"M14 34h40\" stroke=\"#5B3FF0\" stroke-width=\"2\"/>\n    <ellipse cx=\"25\" cy=\"20\" rx=\"4\" ry=\"2.4\" fill=\"#fff\" opacity=\".55\"/>\n    <path d=\"M14 46l-7 6M54 46l7 6\" stroke=\"#5B3FF0\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n    <path d=\"M27 67v6M41 67v6\" stroke=\"#5B3FF0\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n    ${eyes}${mouth}${extra}</svg>`;\n}\nconst ROCKET = `<svg class=\"rocket\" viewBox=\"0 0 200 200\" aria-hidden=\"true\">\n  <defs><linearGradient id=\"rk\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#FFFFFF\"/><stop offset=\"1\" stop-color=\"#D9D2FF\"/></linearGradient>\n  <linearGradient id=\"fl\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#FFD54A\"/><stop offset=\"1\" stop-color=\"#FF7A1A\" stop-opacity=\"0\"/></linearGradient></defs>\n  <g transform=\"rotate(35 110 100)\">\n    <path d=\"M110 30c26 18 34 60 22 98h-44c-12-38-4-80 22-98z\" fill=\"url(#rk)\"/>\n    <path d=\"M88 110l-24 26 30-4zM132 110l24 26-30-4z\" fill=\"#6B4CF6\"/>\n    <circle cx=\"110\" cy=\"78\" r=\"15\" fill=\"#3B23C9\"/><circle cx=\"110\" cy=\"78\" r=\"10\" fill=\"#6FB6FF\"/><circle cx=\"106\" cy=\"74\" r=\"3\" fill=\"#fff\"/>\n    <path d=\"M96 128h28l-6 10h-16z\" fill=\"#6B4CF6\"/>\n    <path d=\"M100 140q10 46 10 52q0-6 10-52z\" fill=\"url(#fl)\"/>\n  </g></svg>`;\n\n/* ---------- XP & badges ---------- */\nconst BADGES = [\n  {id:\"first\",e:\"🚀\",t:\"Décollage\",test:()=>progress.totalSeen>=1},\n  {id:\"s3\",e:\"🔥\",t:\"Série 3 jours\",test:()=>streak()>=3},\n  {id:\"s7\",e:\"⭐\",t:\"Série 7 jours\",test:()=>streak()>=7},\n  {id:\"q100\",e:\"💯\",t:\"100 réponses\",test:()=>progress.totalSeen>=100},\n  {id:\"q500\",e:\"🏅\",t:\"500 réponses\",test:()=>progress.totalSeen>=500},\n  {id:\"ch1\",e:\"🎓\",t:\"1er chapitre\",test:()=>CHAPTERS.some(c=>chapterStats(c).done)},\n  {id:\"chAll\",e:\"🏆\",t:\"Cours maîtrisé\",test:()=>CHAPTERS.every(c=>chapterStats(c).done)},\n  {id:\"open20\",e:\"✍️\",t:\"20 ouvertes\",test:()=>progress.openDone>=20},\n  {id:\"flash50\",e:\"🗂️\",t:\"50 flashcards\",test:()=>progress.flashDone>=50},\n  {id:\"exam80\",e:\"🎯\",t:\"Examen ≥ 80%\",test:()=>(progress.history||[]).some(h=>h.label===\"Examen blanc\"&&h.score>=80&&h.total>=20)},\n  {id:\"lvl5\",e:\"👑\",t:\"Niveau 5\",test:()=>level()>=5},\n  {id:\"fav\",e:\"🔖\",t:\"Collectionneur\",test:()=>Object.keys(progress.bookmarks).length>=10}\n];\nfunction addXP(n){\n  const before = level(); progress.xp += n;\n  if(level()>before) setTimeout(()=>levelUp(level()),700);\n}\nfunction checkBadges(){\n  BADGES.forEach(b=>{ if(!progress.badges[b.id] && b.test()){ progress.badges[b.id]=dkey(); setTimeout(()=>toast(b.e+\" Badge débloqué : \"+b.t),900); } });\n}\nfunction levelUp(n){\n  const o = el(`<div class=\"overlay center\"><div class=\"sheet centered\">\n     <div style=\"width:110px;margin:0 auto\">${mascot(\"star\")}</div>\n     <h2 style=\"margin:6px 0 4px;font-size:22px\">Niveau ${n} débloqué ! 🎉</h2>\n     <p style=\"color:var(--ink2);font-size:13.5px;margin:0 0 16px\">Tu progresses comme une fusée 🚀. Continue sur ta lancée.</p>\n     <button class=\"btn primary full\">Continuer</button></div></div>`);\n  o.querySelector(\"button\").onclick=()=>o.remove(); o.onclick=(e)=>{ if(e.target===o) o.remove(); }; document.body.appendChild(o); confetti();\n}\n\n/* ---------- réponse : XP + suivi ---------- */\nfunction markAnswered(q, correct, given, partial){\n  answersGiven[q.id] = { given, correct, revealed:true, partial:!!partial };\n  progress.seen[q.id] = true;\n  if(partial){ progress.totalSeen++; saveProgress(); } else bumpMastery(q.id, correct);\n  let xp = correct ? (q.difficulty===\"difficile\"?15:q.difficulty===\"moyen\"?12:10) : partial ? 6 : 2;\n  if(q.type===\"ouverte\"){ progress.openDone++; if(correct) xp+=5; }\n  addXP(xp); logActivity(correct);\n  pendingFx = {correct, xp};\n  checkBadges(); saveProgress();\n}\nrecordFlashResult = (function(orig){ return function(card,res){ orig(card,res); progress.flashDone++; addXP(res===\"again\"?1:res===\"good\"?3:5); logActivity(res!==\"again\"); checkBadges(); saveProgress(); }; })(recordFlashResult);\n\n/* ---------- sessions ---------- */\nfunction startOrdered(list,label){ queue=list.slice(); qIndex=0; answersGiven={}; selectedOptions={}; sessionLabel=label; view=\"quiz\"; render(); }\nfunction nextChapter(){ return CHAPTERS.find(c=>!chapterStats(c).done) || CHAPTERS[0]; }\nlet openChapter = null, parcoursCat = \"Tous\", statsMode = \"week\";\n\n/* ---------- coque : barre du haut + navigation ---------- */\nconst ICONS = {\n  home:`<svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M12 3l9 7.5V20a1 1 0 0 1-1 1h-5v-6h-6v6H4a1 1 0 0 1-1-1v-9.5z\"/></svg>`,\n  grid:`<svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><rect x=\"3\" y=\"3\" width=\"8\" height=\"8\" rx=\"2.5\"/><rect x=\"13\" y=\"3\" width=\"8\" height=\"8\" rx=\"2.5\"/><rect x=\"3\" y=\"13\" width=\"8\" height=\"8\" rx=\"2.5\"/><rect x=\"13\" y=\"13\" width=\"8\" height=\"8\" rx=\"2.5\"/></svg>`,\n  target:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"currentColor\"/></svg>`,\n  bars:`<svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><rect x=\"4\" y=\"11\" width=\"3.4\" height=\"9\" rx=\"1.7\"/><rect x=\"10.3\" y=\"5\" width=\"3.4\" height=\"15\" rx=\"1.7\"/><rect x=\"16.6\" y=\"8\" width=\"3.4\" height=\"12\" rx=\"1.7\"/></svg>`,\n  user:`<svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><circle cx=\"12\" cy=\"8\" r=\"4.2\"/><path d=\"M4 20.5c0-4.2 3.6-7 8-7s8 2.8 8 7z\"/></svg>`,\n  bell:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#151A33\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M6 16V11a6 6 0 1 1 12 0v5l1.5 2h-15z\"/><path d=\"M10 20.5a2 2 0 0 0 4 0\"/></svg>`\n};\nconst NAV = [[\"home\",\"home\",\"Accueil\"],[\"parcours\",\"grid\",\"Parcours\"],[\"flash\",\"target\",\"Cartes\"],[\"stats\",\"bars\",\"Stats\"],[\"profile\",\"user\",\"Profil\"]];\nfunction renderShell(){\n  const top = document.getElementById(\"topbar\");\n  const fs = flashStats();\n  const hasNotif = fs.dueCount>0 || !progress.daily[dkey()];\n  top.innerHTML = `\n    <div class=\"avatar\" id=\"avBtn\" role=\"button\" aria-label=\"Profil\">${progress.avatar}</div>\n    <div class=\"who\"><div class=\"nm\">${esc(progress.name)}</div><div class=\"lv\"><i>⚡</i> Niveau ${level()} · ${progress.xp} XP · 🔥 ${streak()} j</div></div>\n    <button class=\"bell\" id=\"bellBtn\" aria-label=\"Notifications\">${ICONS.bell}${hasNotif?'<span class=\"dot\"></span>':''}</button>`;\n  top.querySelector(\"#avBtn\").onclick=()=>{ view=\"profile\"; render(); };\n  top.querySelector(\"#bellBtn\").onclick=openNotifs;\n  const nav = document.getElementById(\"bottomnav\");\n  nav.classList.toggle(\"hide\", view===\"quiz\"||view===\"flashSession\");\n  const activeKey = ({chapter:\"parcours\",flashSession:\"flash\",dashboard:\"stats\"})[view] || view;\n  nav.innerHTML = NAV.map(([k,ic,l])=>`<button class=\"${activeKey===k?'on':''} ${k==='stats'?'stats':''}\" data-k=\"${k}\" aria-label=\"${l}\">${ICONS[ic]}<span class=\"lbl\">${l}</span></button>`).join(\"\");\n  nav.querySelectorAll(\"button\").forEach(b=> b.onclick=()=>{ view=b.dataset.k; searchQuery=\"\"; render(); });\n}\nfunction openNotifs(){\n  const fs = flashStats(); const nc = nextChapter(); const s = streak();\n  const items = [];\n  if(!progress.daily[dkey()]) items.push([\"🔥\", s? `Garde ta série de ${s} jour(s) !` : \"Commence ta série aujourd'hui\", \"Réponds à au moins une question aujourd'hui.\", ()=>startQuickRevision(5)]);\n  if(fs.dueCount>0) items.push([\"🗂️\", `${fs.dueCount} flashcards à réviser`, \"La méthode Leitner te les ramène au bon moment.\", ()=>startFlashSession(FLASHCARDS.filter(isFlashDue),\"Cartes dues\")]);\n  items.push([meta(nc).e, \"Chapitre conseillé : \"+shortChapterLabel(nc), \"Continue ton parcours là où tu t'es arrêté(e).\", ()=>{ openChapter=nc; view=\"chapter\"; render(); }]);\n  items.push([\"💊\",\"Médicament du jour\",\"4 questions ciblées pour aujourd'hui.\", startMedOfDay]);\n  const o = el(`<div class=\"overlay\"><div class=\"sheet\"><h2 class=\"section-title\" style=\"font-size:18px\">🔔 Notifications</h2><div id=\"nl\"></div><button class=\"btn full mt14\" id=\"cl\">Fermer</button></div></div>`);\n  const nl = o.querySelector(\"#nl\");\n  items.forEach(([e,t,s2,fn])=>{ const r=el(`<div class=\"notif\"><div class=\"e\">${e}</div><div style=\"flex:1\"><b>${esc(t)}</b><small>${esc(s2)}</small></div><span>›</span></div>`); r.onclick=()=>{o.remove(); fn();}; nl.appendChild(r); });\n  o.querySelector(\"#cl\").onclick=()=>o.remove(); o.onclick=(e)=>{ if(e.target===o) o.remove(); };\n  document.body.appendChild(o);\n}\n\n/* ---------- rendu principal ---------- */\nfunction render(){\n  const app = document.getElementById(\"app\");\n  app.innerHTML = \"\";\n  renderShell();\n  const V = {home:renderHome, quiz:renderQuiz, dashboard:renderStats, stats:renderStats, resume:renderResume, meds:renderMeds,\n    flash:renderFlashHub, flashSession:renderFlashSession, parcours:renderParcours, chapter:renderChapter, profile:renderProfile,\n    custom:renderCustom, summary:renderSummary};\n  if([\"resume\",\"meds\"].includes(view)) app.appendChild(renderSearchBar());\n  app.appendChild((V[view]||renderHome)());\n  if(view!==previousView){ window.scrollTo({top:0,behavior:\"instant\"}); previousView=view; }\n  if(pendingFx){ const f=pendingFx; pendingFx=null; toast((f.correct?\"🎉 \":\"💪 \")+\"+\"+f.xp+\" XP\"); if(f.correct) confetti(); }\n}\n\n/* ---------- ACCUEIL ---------- */\nfunction renderHome(){\n  const w = el(`<div></div>`);\n  const nc = nextChapter();\n  const mastered = Q.filter(q=>getMastery(q.id)>=3).length;\n  w.appendChild(el(`<div class=\"hero\">\n      <span class=\"spark\" style=\"right:44%;top:18px\">★</span><span class=\"spark\" style=\"right:10%;top:46%;font-size:12px\">★</span><span class=\"spark\" style=\"right:36%;bottom:26px;font-size:12px\">★</span>\n      <h2>Continue d'apprendre, continue de grandir !</h2>\n      <p>Prochaine étape : ${meta(nc).e} ${esc(shortChapterLabel(nc))}. Parcours les ${CHAPTERS.length} chapitres pour maîtriser tout le cours.</p>\n      <button class=\"go\" id=\"heroGo\" aria-label=\"Ouvrir le chapitre conseillé\">→</button>${ROCKET}</div>`));\n  w.querySelector(\"#heroGo\").onclick=()=>{ openChapter=nc; view=\"chapter\"; render(); };\n  w.appendChild(renderSearchBar());\n\n  w.appendChild(el(`<div class=\"duo\">\n     <div class=\"mini lav\"><div class=\"top\"><div class=\"ic\">❓</div><div class=\"t\">Questions</div></div><div class=\"v\" style=\"margin-top:6px\">${Q.length}</div></div>\n     <div class=\"mini sky\"><div class=\"top\"><div class=\"ic\">✓</div><div class=\"t\">Maîtrisées</div></div><div class=\"v\" style=\"margin-top:6px\">${mastered}</div></div></div>`));\n\n  // progression sur 3 mois\n  const now = new Date(); const months=[]; \n  for(let i=2;i>=0;i--){ const d=new Date(now.getFullYear(),now.getMonth()-i,1); months.push({y:d.getFullYear(),m:d.getMonth(),n:0,lbl:d.toLocaleDateString(\"fr-FR\",{month:\"short\"})}); }\n  Object.entries(progress.daily).forEach(([k,v])=>{ const [y,m]=k.split(\"-\").map(Number); const mo=months.find(x=>x.y===y&&x.m===m-1); if(mo) mo.n+=v.n; });\n  const tot = months.reduce((a,b)=>a+b.n,0); const cols=[\"#5B3FF0\",\"#2F7BF6\",\"#C9CDE3\"];\n  const segs = tot ? months.map((mo,i)=>`<span style=\"flex:${Math.max(mo.n,0.0001)};background:${cols[i]}\"></span>`).join(\"\") : `<span style=\"flex:1;background:#E3E5F3\"></span>`;\n  const pc = el(`<div class=\"card\"><div class=\"h-row\" style=\"margin:0\"><h2 class=\"section-title\" style=\"margin:0\">Ma progression</h2><a id=\"toStats\">Détails ›</a></div>\n     <div class=\"segbar\">${segs}</div>\n     <div class=\"seglegend\">${months.map((mo,i)=>`<div><b>${mo.lbl}</b><small><i style=\"background:${cols[i]}\"></i>${mo.n} réponses</small></div>`).join(\"\")}</div></div>`);\n  pc.querySelector(\"#toStats\").onclick=()=>{ view=\"stats\"; render(); };\n  w.appendChild(pc);\n\n  const quick = el(`<div class=\"card\"><h2 class=\"section-title\">⚡ Révision express</h2><div class=\"scroller\">\n     ${[5,10,20,30].map(m=>`<div class=\"chip\" data-min=\"${m}\">⏱️ ${m} min</div>`).join(\"\")}</div>\n     <p class=\"hint\">Les notions que tu maîtrises le moins passent en premier.</p></div>`);\n  quick.querySelectorAll(\"[data-min]\").forEach(b=> b.onclick=()=> startQuickRevision(parseInt(b.dataset.min)));\n  w.appendChild(quick);\n\n  const day = el(`<div class=\"cta y\"><div class=\"e\">💊</div><div class=\"t\"><b>Médicament du jour</b><small>4 questions ciblées, renouvelées chaque jour</small></div><div class=\"go\">→</div></div>`);\n  day.onclick=startMedOfDay; w.appendChild(day);\n\n  w.appendChild(el(`<div class=\"h-row\"><h3>Outils</h3></div>`));\n  const tiles = el(`<div class=\"tiles\"></div>`);\n  [[\"📖\",\"Résumé\",()=>{view=\"resume\";render();}],[\"💊\",\"Médicaments\",()=>{view=\"meds\";render();}],[\"📝\",\"Examen blanc\",startExamBlanc],\n   [\"✍️\",\"Ouvertes\",()=>startSession(Q.filter(q=>q.type===\"ouverte\"&&filters.chapters.has(q.chapter)).sort((a,b)=>getMastery(a.id)-getMastery(b.id)).slice(0,10),\"Questions ouvertes\")],\n   [\"🔖\",\"Favoris\",startFavorites],[\"🎛️\",\"Sur mesure\",()=>{view=\"custom\";render();}]].forEach(([e,l,fn])=>{\n     const t=el(`<div class=\"tile\" tabindex=\"0\" role=\"button\"><div class=\"e\">${e}</div><div class=\"l\">${l}</div></div>`); t.onclick=fn; tiles.appendChild(t); });\n  w.appendChild(tiles);\n  return w;\n}\nfunction startFavorites(){\n  const favs = Q.filter(q=>progress.bookmarks[q.id]);\n  if(!favs.length){ toast(\"🔖 Ajoute des questions en favori pendant tes quiz\"); return; }\n  startSession(favs,\"Mes favoris\");\n}\n\n/* ---------- SESSION SUR MESURE (anciens filtres) ---------- */\nfunction renderCustom(){\n  const w = el(`<div></div>`);\n  w.appendChild(el(`<div class=\"pheader\"><h1>Session<br>sur mesure</h1><div class=\"fig\">🎛️</div></div>`));\n  const chCard = el(`<div class=\"card\"><div class=\"h-row\" style=\"margin:0 0 10px\"><h2 class=\"section-title\" style=\"margin:0\">📚 Chapitres (${filters.chapters.size}/${CHAPTERS.length})</h2><a id=\"allC\">Tout</a></div><div class=\"row\" id=\"chs\"></div></div>`);\n  chCard.querySelector(\"#allC\").onclick=()=>{ filters.chapters = filters.chapters.size===CHAPTERS.length? new Set([CHAPTERS[0]]) : new Set(CHAPTERS); render(); };\n  CHAPTERS.forEach(ch=>{ const n=Q.filter(q=>q.chapter===ch).length; const c=el(`<div class=\"chip compact ${filters.chapters.has(ch)?'active':''}\">${meta(ch).e} ${esc(shortChapterLabel(ch))} <small>(${n})</small></div>`);\n    c.onclick=()=>{ filters.chapters.has(ch)?filters.chapters.delete(ch):filters.chapters.add(ch); if(!filters.chapters.size) filters.chapters.add(ch); render(); }; chCard.querySelector(\"#chs\").appendChild(c); });\n  w.appendChild(chCard);\n  const tl = {qcm:\"QCM\",qcd:\"QCD\",ouverte:\"✍️ Ouvertes\",libre:\"Libres\",association:\"Associations\"};\n  const tc = el(`<div class=\"card\"><h2 class=\"section-title\">Type de questions</h2><div class=\"row\" id=\"ty\"></div></div>`);\n  Object.keys(tl).forEach(t=>{ const c=el(`<div class=\"chip ${filters.types.has(t)?'active':''}\">${tl[t]} <small>(${Q.filter(q=>q.type===t).length})</small></div>`);\n    c.onclick=()=>{ filters.types.has(t)?filters.types.delete(t):filters.types.add(t); if(!filters.types.size) filters.types.add(t); render(); }; tc.querySelector(\"#ty\").appendChild(c); });\n  w.appendChild(tc);\n  const dl = {facile:\"🟢 Facile\",moyen:\"🟠 Moyen\",difficile:\"🔴 Difficile\"};\n  const dc = el(`<div class=\"card\"><h2 class=\"section-title\">Difficulté</h2><div class=\"row\" id=\"di\"></div></div>`);\n  Object.keys(dl).forEach(d=>{ const c=el(`<div class=\"chip ${filters.difficulties.has(d)?'active':''}\">${dl[d]}</div>`);\n    c.onclick=()=>{ filters.difficulties.has(d)?filters.difficulties.delete(d):filters.difficulties.add(d); if(!filters.difficulties.size) filters.difficulties.add(d); render(); }; dc.querySelector(\"#di\").appendChild(c); });\n  w.appendChild(dc);\n  const pool = buildFilteredPool();\n  const go = el(`<button class=\"btn primary full\" ${pool.length?'':'disabled'}>▶️ Démarrer (${pool.length} questions)</button>`);\n  go.onclick=()=>startSession(pool,\"Session sur mesure\"); w.appendChild(go);\n  return w;\n}\n\n/* ---------- PARCOURS ---------- */\nfunction renderParcours(){\n  const w = el(`<div></div>`);\n  const doneN = CHAPTERS.filter(c=>chapterStats(c).done).length;\n  w.appendChild(el(`<div class=\"pheader\"><h1>Mon<br>parcours</h1><div class=\"fig\">🎓📚</div></div>`));\n  w.appendChild(el(`<div class=\"row mb14\"><span class=\"pill navy\">📚 ${CHAPTERS.length} chapitres</span><span class=\"pill white\">✅ ${doneN} terminés</span></div>`));\n  const cats = el(`<div class=\"scroller mb14\"></div>`);\n  CATS.forEach(([c,e])=>{ const ch=el(`<div class=\"chip ${parcoursCat===c?'active':''}\">${e} ${c}</div>`); ch.onclick=()=>{parcoursCat=c; render();}; cats.appendChild(ch); });\n  w.appendChild(cats);\n  const favCh = el(`<div class=\"chip ${parcoursCat==='Favoris'?'active':''}\" style=\"display:inline-block;margin-bottom:12px\">🔖 Chapitres favoris</div>`);\n  favCh.onclick=()=>{ parcoursCat = parcoursCat===\"Favoris\"?\"Tous\":\"Favoris\"; render(); }; w.appendChild(favCh);\n  CHAPTERS.forEach((ch,i)=>{\n    const m = meta(ch);\n    if(parcoursCat===\"Favoris\" ? !progress.chBookmarks[ch] : (parcoursCat!==\"Tous\" && m.cat!==parcoursCat)) return;\n    const s = chapterStats(ch);\n    const card = el(`<div class=\"ccard ${m.c}\" tabindex=\"0\" role=\"button\">\n      <div class=\"blob\"></div>\n      <div class=\"cat\">${String(i+1).padStart(2,\"0\")} · ${m.cat}${s.done?\" · ✅ terminé\":\"\"}</div>\n      <div class=\"ttl\">${esc(ch)}</div><div class=\"emo\">${m.e}</div>\n      <button class=\"bm ${progress.chBookmarks[ch]?'on':''}\" aria-label=\"Favori\">🔖</button>\n      <div class=\"foot\"><div class=\"stack\">${m.figs.map(f=>`<span>${f}</span>`).join(\"\")}<b>${s.total} questions</b></div><div class=\"arrow\">→</div></div>\n      <div class=\"cprog\"><span style=\"width:${s.seenPct}%\"></span></div></div>`);\n    card.querySelector(\".bm\").onclick=(e)=>{ e.stopPropagation(); progress.chBookmarks[ch]=!progress.chBookmarks[ch]; saveProgress(); render(); };\n    card.onclick=()=>{ openChapter=ch; view=\"chapter\"; render(); };\n    w.appendChild(card);\n  });\n  return w;\n}\n\nfunction renderChapter(){\n  const ch = openChapter || CHAPTERS[0]; const m = meta(ch); const s = chapterStats(ch);\n  const w = el(`<div></div>`);\n  const top = el(`<div class=\"qtop mb14\"><button class=\"rbtn\" id=\"bk\" aria-label=\"Retour\">←</button><div class=\"qlabel\">Chapitre ${CHAPTERS.indexOf(ch)+1} / ${CHAPTERS.length}</div><button class=\"rbtn ${progress.chBookmarks[ch]?'on':''}\" id=\"bm\" aria-label=\"Favori\">🔖</button></div>`);\n  top.querySelector(\"#bk\").onclick=()=>{ view=\"parcours\"; render(); };\n  top.querySelector(\"#bm\").onclick=()=>{ progress.chBookmarks[ch]=!progress.chBookmarks[ch]; saveProgress(); render(); };\n  w.appendChild(top);\n  w.appendChild(el(`<div class=\"ccard ${m.c}\" style=\"cursor:default\"><div class=\"blob\"></div><div class=\"cat\">${m.cat}</div>\n     <div class=\"ttl\" style=\"font-size:20px\">${esc(ch)}</div><div class=\"emo\" style=\"right:16px;font-size:40px\">${m.e}</div>\n     <div class=\"foot\"><div class=\"stack\">${m.figs.map(f=>`<span>${f}</span>`).join(\"\")}<b>${s.seen}/${s.total} vues · ${s.mastery}% maîtrise</b></div></div>\n     <div class=\"cprog\"><span style=\"width:${s.seenPct}%\"></span></div></div>`));\n  const closed = s.items.filter(q=>q.type!==\"ouverte\"); const opens = s.items.filter(q=>q.type===\"ouverte\");\n  const order = s.items.slice().sort((a,b)=> (a.type===\"ouverte\")-(b.type===\"ouverte\") || (a.page-b.page));\n  const acts = [\n    [\"🚀\",\"Parcours complet\",`${s.total} questions dans l'ordre du cours`,\"v\",()=>startOrdered(order,\"Parcours · \"+shortChapterLabel(ch))],\n    [\"🎯\",\"QCM & QCD\",`${closed.length} questions, ordre aléatoire`,\"b\",()=>startSession(closed,\"QCM · \"+shortChapterLabel(ch))],\n    [\"✍️\",\"Questions ouvertes\",`${opens.length} réponses à rédiger, puis à comparer`,\"y\",()=>opens.length?startSession(opens,\"Ouvertes · \"+shortChapterLabel(ch)):toast(\"Pas de question ouverte ici\")],\n    [\"🗂️\",\"Flashcards du chapitre\",`${FLASHCARDS.filter(c=>c.chapter===ch).length} cartes Leitner`,\"g\",()=>startFlashSession(FLASHCARDS.filter(c=>c.chapter===ch),\"Flashcards · \"+shortChapterLabel(ch))],\n    [\"🔁\",\"Mes erreurs\",`${s.items.filter(q=>isSeen(q.id)&&getMastery(q.id)<2).length} notions fragiles`,\"v\",()=>{ const l=s.items.filter(q=>isSeen(q.id)&&getMastery(q.id)<2); l.length?startSession(l,\"Erreurs · \"+shortChapterLabel(ch)):toast(\"Aucune erreur à revoir 👏\"); }]\n  ];\n  acts.forEach(([e,t,sub,c,fn])=>{ const r=el(`<div class=\"cta ${c}\"><div class=\"e\">${e}</div><div class=\"t\"><b>${t}</b><small>${sub}</small></div><div class=\"go\">→</div></div>`); r.onclick=fn; w.appendChild(r); });\n  const sum = SUMMARIES[ch];\n  if(sum){ w.appendChild(el(`<div class=\"card\"><h2 class=\"section-title\">📖 L'essentiel à retenir</h2>${sum.bullets.map(b=>`<div style=\"font-size:13.5px;line-height:1.6;margin-bottom:9px;padding-left:12px;border-left:3px solid var(--violet2)\">${esc(b)}</div>`).join(\"\")}<div class=\"q-page\">p. ${esc(sum.page)}</div></div>`)); }\n  return w;\n}\n\n/* ---------- STATISTIQUES ---------- */\nfunction renderStats(){\n  const w = el(`<div></div>`);\n  const head = el(`<div class=\"h-row\"><h3 style=\"font-size:24px\">Statistiques</h3><div class=\"toggle\"><span data-m=\"week\" class=\"${statsMode==='week'?'on':''}\">Semaine</span><span data-m=\"month\" class=\"${statsMode==='month'?'on':''}\">Mois</span></div></div>`);\n  head.querySelectorAll(\"[data-m]\").forEach(s=> s.onclick=()=>{ statsMode=s.dataset.m; render(); });\n  w.appendChild(head);\n  let bars=[];\n  if(statsMode===\"week\"){\n    const d=new Date(); const dow=(d.getDay()+6)%7; const mon=new Date(d); mon.setDate(d.getDate()-dow);\n    [\"Lun\",\"Mar\",\"Mer\",\"Jeu\",\"Ven\",\"Sam\",\"Dim\"].forEach((l,i)=>{ const x=new Date(mon); x.setDate(mon.getDate()+i); const r=progress.daily[dkey(x)]||{n:0,c:0,s:0}; bars.push({l,...r}); });\n  } else {\n    for(let wk=3;wk>=0;wk--){ let n=0,c=0,s=0; for(let i=0;i<7;i++){ const x=new Date(); x.setDate(x.getDate()-wk*7-i); const r=progress.daily[dkey(x)]; if(r){n+=r.n;c+=r.c;s+=r.s;} } bars.push({l:\"S-\"+wk,n,c,s}); }\n    bars[3].l=\"Cette sem.\";\n  }\n  const max = Math.max(1,...bars.map(b=>b.n)); const mins = Math.round(bars.reduce((a,b)=>a+b.s,0)/60); const good = bars.reduce((a,b)=>a+b.c,0);\n  w.appendChild(el(`<div class=\"card\">\n     <div style=\"display:flex;justify-content:space-between;align-items:center\"><div class=\"kpi\"><div class=\"ic\" style=\"width:40px;height:40px;font-size:18px;border-radius:14px\">📊</div><div><small>${statsMode==='week'?'Cette semaine':'4 dernières semaines'}</small><b>${bars.reduce((a,b)=>a+b.n,0)} réponses</b></div></div></div>\n     <div class=\"row\" style=\"justify-content:space-around;margin-top:14px\">\n       <div class=\"kpi\"><div class=\"ic\">⏱</div><div><div class=\"v\">${mins}</div><small>Minutes passées</small></div></div>\n       <div class=\"kpi\"><div class=\"ic\">✓</div><div><div class=\"v\">${good}</div><small>Bonnes réponses</small></div></div></div>\n     <div class=\"bars\">${bars.map(b=>`<div class=\"b ${b.n===max&&b.n>0?'max':''}\"><em>${b.n}</em><i style=\"height:${Math.round(110*b.n/max)}px\"></i><small>${b.l}</small></div>`).join(\"\")}</div></div>`));\n  const s = streak();\n  const c1 = el(`<div class=\"cta y\"><div class=\"e\">🏆</div><div class=\"t\"><b>Continue comme ça !</b><small>${progress.totalSeen? \"Tu es en feu 🔥 — \"+(progress.totalSeen? Math.round(100*progress.totalCorrect/progress.totalSeen):0)+\"% de réussite\" : \"Lance ta première révision\"}</small></div><div class=\"go\">→</div></div>`);\n  c1.onclick=()=>startQuickRevision(10); w.appendChild(c1);\n  const c2 = el(`<div class=\"cta b\"><div class=\"e\">⭐</div><div class=\"t\"><b>Série</b><small>${s} jour(s) d'affilée ⚡ · record : ${Math.max(s,progress.bestStreak||0)}</small></div><div class=\"go\">→</div></div>`);\n  progress.bestStreak = Math.max(s, progress.bestStreak||0); saveProgress(); c2.onclick=()=>startQuickRevision(5); w.appendChild(c2);\n  const list = el(`<div class=\"card\"><h2 class=\"section-title\">Maîtrise par chapitre</h2></div>`);\n  CHAPTERS.forEach(ch=>{ const st=chapterStats(ch); const r=el(`<div class=\"chapter-row\" style=\"cursor:pointer\"><span style=\"font-size:18px\">${meta(ch).e}</span><div class=\"cname\">${esc(shortChapterLabel(ch))}${st.done?\" ✅\":\"\"}</div><div class=\"cbar\"><span style=\"width:${st.mastery}%\"></span></div><div class=\"cpct\">${st.mastery}%</div></div>`);\n    r.onclick=()=>{ openChapter=ch; view=\"chapter\"; render(); }; list.appendChild(r); });\n  w.appendChild(list);\n  const weak = Q.filter(q=>isSeen(q.id)).sort((a,b)=>getMastery(a.id)-getMastery(b.id)).slice(0,6);\n  if(weak.length){ const wc = el(`<div class=\"card\"><h2 class=\"section-title\">🔁 Notions à revoir</h2>${weak.map(q=>`<div class=\"chapter-row\"><span class=\"mastery-dot m${getMastery(q.id)}\"></span><div class=\"cname\">${esc(q.question.slice(0,80))}${q.question.length>80?'…':''}</div></div>`).join(\"\")}<button class=\"btn primary full mt14\">Réviser ces notions</button></div>`);\n    wc.querySelector(\"button\").onclick=()=>startSession(weak,\"Notions à revoir\"); w.appendChild(wc); }\n  return w;\n}\n\n/* ---------- PROFIL ---------- */\nfunction renderProfile(){\n  const w = el(`<div></div>`);\n  w.appendChild(el(`<div class=\"card center\"><div class=\"avatar\" style=\"width:84px;height:84px;font-size:46px;margin:0 auto 10px\">${progress.avatar}</div>\n     <input class=\"inp\" id=\"nm\" type=\"text\" value=\"${esc(progress.name)}\" aria-label=\"Ton prénom\" style=\"text-align:center;font-weight:700;font-size:16px;padding:10px;width:100%;max-width:280px\">\n     <div style=\"margin-top:12px;font-size:13px;color:var(--ink2)\">⚡ Niveau ${level()} · ${progress.xp} XP</div>\n     <div class=\"lvlbar\"><span style=\"width:${Math.round(100*xpInLevel()/200)}%\"></span></div>\n     <div class=\"hint\">${200-xpInLevel()} XP avant le niveau ${level()+1}</div></div>`));\n  w.querySelector(\"#nm\").onchange=(e)=>{ progress.name=e.target.value.trim()||\"Étudiant(e) INFAS\"; saveProgress(); renderShell(); };\n  const av = el(`<div class=\"card\"><h2 class=\"section-title\">Choisis ta figurine</h2><div class=\"avgrid\"></div></div>`);\n  AVATARS.forEach(a=>{ const s=el(`<span class=\"${progress.avatar===a?'on':''}\" role=\"button\">${a}</span>`); s.onclick=()=>{ progress.avatar=a; saveProgress(); render(); }; av.querySelector(\".avgrid\").appendChild(s); });\n  w.appendChild(av);\n  const bd = el(`<div class=\"card\"><h2 class=\"section-title\">🏅 Mes badges (${Object.keys(progress.badges).length}/${BADGES.length})</h2><div class=\"badges\">${BADGES.map(b=>`<div class=\"bdg ${progress.badges[b.id]?'':'off'}\"><div class=\"e\">${b.e}</div><small>${b.t}</small></div>`).join(\"\")}</div></div>`);\n  w.appendChild(bd);\n  const tot = el(`<div class=\"card\"><h2 class=\"section-title\">Mon bilan</h2><div class=\"dash-grid\">\n     <div class=\"stat\"><div class=\"num\">${sumMasteryPct()}%</div><div class=\"lbl\">Maîtrise globale</div></div>\n     <div class=\"stat\"><div class=\"num\">${progress.totalSeen}</div><div class=\"lbl\">Réponses données</div></div>\n     <div class=\"stat\"><div class=\"num\">${progress.openDone}</div><div class=\"lbl\">Ouvertes rédigées</div></div>\n     <div class=\"stat\"><div class=\"num\">${progress.flashDone}</div><div class=\"lbl\">Flashcards revues</div></div></div>\n     <button class=\"btn ghost full mt14\" id=\"rs\">♻️ Réinitialiser ma progression</button></div>`);\n  tot.querySelector(\"#rs\").onclick=()=>{ if(confirm(\"Réinitialiser toute ta progression ? Cette action est définitive.\")){ progress=defaultProgress(); saveProgress(); render(); } };\n  w.appendChild(tot);\n  return w;\n}\n\n/* ---------- QUIZ ---------- */\nconst TYPE_LABEL = {qcm:\"QCM\",qcd:\"QCD\",libre:\"Question libre\",association:\"Association\",ouverte:\"✍️ Question ouverte\"};\nfunction renderQuiz(){\n  const w = el(`<div></div>`);\n  if(!queue.length){ w.appendChild(el(`<div class=\"card center\">${mascot(\"think\")}<p>Aucune question pour cette sélection.</p><button class=\"btn primary\" id=\"b\">← Accueil</button></div>`)); w.querySelector(\"#b\").onclick=()=>{view=\"home\";render();}; return w; }\n  const q = queue[qIndex]; const state = answersGiven[q.id];\n  const top = el(`<div class=\"qtop\"><button class=\"rbtn\" id=\"quit\" aria-label=\"Quitter\">✕</button><div class=\"qlabel\">${esc(sessionLabel)}</div><button class=\"rbtn ${progress.bookmarks[q.id]?'on':''}\" id=\"bm\" aria-label=\"Favori\">🔖</button></div>`);\n  w.appendChild(top);\n  w.appendChild(el(`<div class=\"progress-outer\"><div class=\"progress-inner\" style=\"width:${Math.round(100*qIndex/queue.length)}%\"></div></div>`));\n  const card = el(`<div class=\"card\" style=\"margin-top:12px\"></div>`);\n  card.appendChild(el(`<div class=\"q-meta\"><div class=\"tags\"><span class=\"badge chap\">${meta(q.chapter).e} ${esc(shortChapterLabel(q.chapter))}</span><span class=\"badge ${q.type}\">${TYPE_LABEL[q.type]}</span><span class=\"badge ${q.difficulty}\">${q.difficulty}</span></div><div class=\"q-page\">p.${q.page} · éd. ${q.source||\"2025\"}</div></div>`));\n  card.appendChild(el(`<div class=\"q-text\">${esc(q.question)}</div>`));\n  const body = el(`<div></div>`); card.appendChild(body);\n  if(q.type===\"qcm\") renderQCM(body,q,state);\n  else if(q.type===\"qcd\") renderQCD(body,q,state);\n  else if(q.type===\"libre\") renderLibre(body,q,state);\n  else if(q.type===\"association\") renderAssociation(body,q,state);\n  else if(q.type===\"ouverte\") renderOuverte(body,q,state);\n  if(state && state.revealed){\n    const mood = state.correct?\"happy\":state.partial?\"think\":\"sad\";\n    const msg = state.correct ? [\"Bravo, c'est juste ! 🎉\",\"Excellent, continue ! 🚀\",\"Parfait, tu maîtrises ! ⭐\"][qIndex%3] : state.partial ? \"Presque ! Complète avec la réponse modèle 💡\" : \"Pas grave : lis bien la correction 👇\";\n    card.appendChild(el(`<div class=\"react\">${mascot(mood)}<div class=\"bubble ${state.correct?'ok':state.partial?'mid':'ko'}\">${msg}</div></div>`));\n    const nb = el(qIndex<queue.length-1 ? `<button class=\"btn primary full mt14\">Suivant →</button>` : `<button class=\"btn green full mt14\">🏁 Terminer et voir mon score</button>`);\n    nb.onclick=()=>{ if(qIndex<queue.length-1){ qIndex++; render(); } else showSummary(); };\n    card.appendChild(nb);\n    card.appendChild(renderCorrection(q,state));\n  }\n  w.appendChild(card);\n  const nav = el(`<div class=\"navrow\"><button class=\"btn arrow-btn\" id=\"p\" ${qIndex===0?'disabled':''} aria-label=\"Précédente\">←</button><div class=\"qcounter\">Question ${qIndex+1} / ${queue.length}</div><button class=\"btn arrow-btn\" id=\"n\" ${qIndex===queue.length-1?'disabled':''} aria-label=\"Suivante\">→</button></div>`);\n  w.appendChild(nav);\n  w.querySelector(\"#quit\").onclick=()=>{ if(Object.keys(answersGiven).length) showSummary(); else { view=\"home\"; render(); } };\n  w.querySelector(\"#bm\").onclick=()=>{ progress.bookmarks[q.id]=!progress.bookmarks[q.id]; if(!progress.bookmarks[q.id]) delete progress.bookmarks[q.id]; checkBadges(); saveProgress(); render(); };\n  w.querySelector(\"#p\").onclick=()=>{ qIndex=Math.max(0,qIndex-1); render(); };\n  w.querySelector(\"#n\").onclick=()=>{ qIndex=Math.min(queue.length-1,qIndex+1); render(); };\n  return w;\n}\n\n/* ---------- QUESTIONS OUVERTES ---------- */\nfunction norm(s){ return (s||\"\").toLowerCase().normalize(\"NFD\").replace(/[\\u0300-\\u036f]/g,\"\"); }\nfunction kwHit(text,k){ const t=norm(text); const parts=norm(k).split(/[\\s,\\/]+/).filter(p=>p.length>2); return parts.length? parts.every(p=>t.includes(p.slice(0,Math.max(4,p.length-2)))) : t.includes(norm(k)); }\nfunction highlight(answer, kws, userText){\n  let html = esc(answer);\n  kws.forEach(k=>{ const re = new RegExp(\"(\"+k.replace(/[.*+?^${}()|[\\]\\\\]/g,\"\\\\$&\")+\")\",\"i\"); html = html.replace(re, `<mark class=\"${kwHit(userText,k)?'hit':'miss'}\">$1</mark>`); });\n  return html;\n}\nfunction renderOuverte(body,q,state){\n  const key=\"ouv_\"+q.id; const st = selectedOptions[key] || (selectedOptions[key]={text:\"\",revealed:false});\n  if(!st.revealed && !state){\n    body.appendChild(el(`<p class=\"hint\" style=\"margin-top:-6px\">✍️ Rédige ta réponse comme à l'examen, puis compare-la à la réponse modèle.</p>`));\n    const ta = el(`<textarea class=\"free\" placeholder=\"Ta réponse…\"></textarea>`); ta.value=st.text; ta.oninput=e=>st.text=e.target.value; body.appendChild(ta);\n    const b = el(`<button class=\"btn primary full mt14\">👀 Voir la réponse modèle</button>`);\n    b.onclick=()=>{ st.revealed=true; render(); }; body.appendChild(b);\n    return;\n  }\n  const userText = state ? state.given : st.text;\n  const hits = q.keywords.filter(k=>kwHit(userText,k)).length; const pct = Math.round(100*hits/q.keywords.length);\n  body.appendChild(el(`<div class=\"label\" style=\"font-size:12px;color:var(--ink2);font-weight:700;margin-bottom:6px\">📝 Ta réponse</div>`));\n  body.appendChild(el(`<div class=\"opt disabled\" style=\"white-space:pre-wrap\">${esc(userText||\"(aucune réponse rédigée)\")}</div>`));\n  body.appendChild(el(`<div class=\"label\" style=\"font-size:12px;color:var(--ink2);font-weight:700;margin:12px 0 6px\">✅ Réponse modèle</div>`));\n  body.appendChild(el(`<div class=\"model\">${highlight(q.answer,q.keywords,userText)}</div>`));\n  body.appendChild(el(`<div class=\"kwrow\">${q.keywords.map(k=>`<span class=\"kw ${kwHit(userText,k)?'hit':''}\">${kwHit(userText,k)?'✓ ':''}${esc(k)}</span>`).join(\"\")}</div>`));\n  body.appendChild(el(`<div class=\"hint\">🔑 Mots-clés retrouvés : <b>${hits}/${q.keywords.length}</b> (${pct}%)</div>`));\n  if(!state){\n    const se = el(`<div><p style=\"font-size:13.5px;font-weight:600;margin:14px 0 0\">Honnêtement, ta réponse était… ?</p><div class=\"selfeval\"><button class=\"k\">❌ À revoir</button><button class=\"m\">🟡 Partielle</button><button class=\"o\">✅ Je savais</button></div></div>`);\n    se.querySelector(\".k\").onclick=()=>{ markAnswered(q,false,userText); render(); };\n    se.querySelector(\".m\").onclick=()=>{ markAnswered(q,false,userText,true); render(); };\n    se.querySelector(\".o\").onclick=()=>{ markAnswered(q,true,userText); render(); };\n    body.appendChild(se);\n  }\n}\n\n/* ---------- correction ---------- */\nfunction explanationAnswerText(q){\n  if(q.type===\"qcm\") return \"Réponse : \"+q.correctAnswer;\n  if(q.type===\"qcd\") return \"Réponses : \"+q.correctAnswer.join(\" · \");\n  if(q.type===\"association\") return \"Bonnes associations : \"+q.pairs.map(p=>p[0]+\" → \"+p[1]).join(\" · \");\n  if(q.type===\"libre\") return \"Réponse attendue (mots-clés) : \"+(q.keywords||[]).join(\", \");\n  if(q.type===\"ouverte\") return \"Compare ta rédaction avec la réponse modèle ci-dessus.\";\n  return \"\";\n}\nfunction renderCorrection(q,state){\n  const box = el(`<div class=\"correction\"></div>`);\n  const head = state.correct?\"✅ Bonne réponse\":state.partial?\"🟡 Réponse partielle\":\"❌ Voici la correction\";\n  box.appendChild(el(`<div class=\"block\"><div class=\"label\">${head}</div><div class=\"content\"><b>${esc(explanationAnswerText(q))}</b></div></div>`));\n  if(q.type!==\"ouverte\") box.appendChild(el(`<div class=\"block\"><div class=\"label\">📖 Explication</div><div class=\"content\">${esc(q.explanation)}</div></div>`));\n  if(q.simpleExplanation) box.appendChild(el(`<div class=\"block\"><div class=\"label\">🧒 Comme à un enfant de 10 ans</div><div class=\"content kid\">${esc(q.simpleExplanation)}</div></div>`));\n  if(q.memoryTip) box.appendChild(el(`<div class=\"block\"><div class=\"label\">💡 Astuce mémoire</div><div class=\"content tip\">${esc(q.memoryTip)}</div></div>`));\n  if(q.examTrap) box.appendChild(el(`<div class=\"block\"><div class=\"label\">⚠️ Piège d'examen</div><div class=\"content trap\">${esc(q.examTrap)}</div></div>`));\n  box.appendChild(el(`<div class=\"q-page\">📄 Source : COURS PHARMACOLOGIE ${q.source===\"2022\"?\"INFAS 2022\":\"L2 INFAS 2025\"} — page ${q.page}</div>`));\n  return box;\n}\n\n/* ---------- résultat de session ---------- */\nlet lastResult = null;\nfunction showSummary(){\n  const answered = queue.filter(q=>answersGiven[q.id]);\n  const correct = answered.filter(q=>answersGiven[q.id].correct).length;\n  const score = answered.length? Math.round(100*correct/answered.length):0;\n  progress.history.push({date:new Date().toISOString(), label:sessionLabel, score, total:answered.length});\n  lastResult = {score, correct, total:answered.length, wrong:answered.filter(q=>!answersGiven[q.id].correct), label:sessionLabel};\n  checkBadges(); saveProgress();\n  view=\"summary\"; render();\n  if(score>=80 && answered.length>=3) confetti();\n}\nfunction renderSummary(){\n  const r = lastResult || {score:0,correct:0,total:0,wrong:[],label:\"\"};\n  const C = 2*Math.PI*62; const col = r.score>=80?\"#2FA84F\":r.score>=50?\"#F6B81A\":\"#F0566A\";\n  const mood = r.score>=80?\"happy\":r.score>=50?\"think\":\"sad\";\n  const msg = r.score>=80?\"Superbe session ! Tu décolles 🚀\":r.score>=50?\"Bon travail, encore un effort 💪\":\"On recommence ensemble, tu vas y arriver 🌱\";\n  const w = el(`<div><div class=\"card center\">\n     <div class=\"q-page\" style=\"margin-bottom:8px\">${esc(r.label)}</div>\n     <div class=\"ring\"><svg viewBox=\"0 0 150 150\"><circle cx=\"75\" cy=\"75\" r=\"62\" stroke=\"#EDEEF6\" stroke-width=\"14\" fill=\"none\"/><circle cx=\"75\" cy=\"75\" r=\"62\" stroke=\"${col}\" stroke-width=\"14\" fill=\"none\" stroke-linecap=\"round\" stroke-dasharray=\"${C}\" stroke-dashoffset=\"${C*(1-r.score/100)}\"/></svg><div class=\"val\">${r.score}%<small>${r.correct}/${r.total} justes</small></div></div>\n     <div class=\"react\" style=\"justify-content:center\">${mascot(mood)}<div class=\"bubble ${r.score>=80?'ok':r.score>=50?'mid':'ko'}\">${msg}</div></div>\n     <div class=\"hint\">⚡ Niveau ${level()} · ${progress.xp} XP · 🔥 Série ${streak()} j</div></div></div>`);\n  if(r.wrong.length){ const b=el(`<button class=\"btn primary full mb14\">🔁 Revoir mes ${r.wrong.length} erreur(s)</button>`); b.onclick=()=>startSession(r.wrong,\"Mes erreurs\"); w.appendChild(b); }\n  const h=el(`<button class=\"btn full\">🏠 Retour à l'accueil</button>`); h.onclick=()=>{view=\"home\";render();}; w.appendChild(h);\n  return w;\n}\n\nrender();\n<%/script>\n</body>\n</html>\n";
